window.KMAP_EXTRA.japan = {"JP-01":[{"k":"work","zh":"漫畫《黃金神威》描寫日俄戰爭退伍的士兵和愛努少女，在這裡尋找愛努人藏起來的黃金","en":"The manga Golden Kamuy follows a Russo-Japanese War veteran and an Ainu girl hunting for hidden Ainu gold here.","ja":"漫画『ゴールデンカムイ』は、日露戦争帰りの元兵士とアイヌの少女がここでアイヌの金塊を探す物語"},{"k":"symbol","zh":"官方代表花是長在海邊沙地上的玫瑰「濱梨」（ハマナス）","en":"Its official flower is the beach rose (hamanasu), which grows on seaside sands.","ja":"シンボルの花は、海辺の砂地に咲くハマナス"},{"k":"record","zh":"1902 年旭川測得 −41.0°C，是日本官方氣象觀測史上的最低氣溫","en":"Asahikawa recorded −41.0°C in 1902, the lowest temperature in Japan's official weather records.","ja":"1902年に旭川で観測された−41.0℃は、日本の気象観測史上の最低気温"},{"k":"sport","zh":"北見的冰壺隊 LS北見在 2018 平昌冬奧拿下銅牌，是日本第一面奧運冰壺獎牌","en":"Curling team Loco Solare from Kitami won bronze at PyeongChang 2018, Japan's first Olympic curling medal.","ja":"北見のロコ・ソラーレは2018年平昌五輪で銅メダル。日本カーリング初の五輪メダルだった"},{"k":"festival","zh":"「YOSAKOI索朗祭」是 1992 年一名大學生看了高知的夜來祭後，在這裡發起的","en":"The YOSAKOI Soran Festival was started here in 1992 by a university student inspired by Kōchi's Yosakoi festival.","ja":"YOSAKOIソーラン祭りは1992年、高知のよさこい祭りに感動した大学生がここで始めた"},{"k":"life","zh":"雪印的乳酸菌飲料「軟式カツゲン」幾乎只在這裡販售","en":"Snow Brand's lactic acid drink 'Soft Katsugen' is sold almost only here.","ja":"雪印メグミルクの乳酸菌飲料「ソフトカツゲン」は、ほぼここでしか売っていない"},{"k":"people","zh":"綽號「狼」、拿過 31 次優勝的橫綱千代之富士出身這裡","en":"Yokozuna Chiyonofuji, nicknamed 'the Wolf' and winner of 31 tournaments, came from here.","ja":"「ウルフ」の愛称で幕内優勝31回の横綱・千代の富士の出身地"},{"k":"nature","zh":"摩周湖 1930 年測得透明度 41.6 公尺，是當時世界最高紀錄","en":"Lake Mashū measured 41.6 m of water clarity in 1930, then the highest ever recorded in the world","ja":"摩周湖は1930年に透明度41.6mを記録し、当時の世界最高値だった"},{"k":"legend","zh":"摩周湖中的小島，傳說是等不到孫子的愛努老婆婆化成的","en":"An Ainu legend says the islet in Lake Mashū is an old woman who became it while waiting for her lost grandchild","ja":"摩周湖の小島カムイシュは、孫を待ち続けたアイヌの老婆が姿を変えたものと伝わる"},{"k":"life","zh":"1966 年暢銷歌〈霧の摩周湖〉的作曲者，寫歌時根本沒去過那座湖","en":"The composer of the 1966 hit 'Kiri no Mashūko' had never visited the lake when he wrote it","ja":"1966年のヒット曲『霧の摩周湖』の作曲者・平尾昌晃は、作曲時に湖を訪れたことがなかった"},{"k":"sport","zh":"駒大苫小牧高中在 2004、2005 年連續拿下夏季甲子園冠軍","en":"Komazawa Univ. Tomakomai High School here won the summer Koshien two years running, 2004 and 2005","ja":"駒大苫小牧高校は2004年・2005年に夏の甲子園を連覇した"},{"k":"brand","zh":"家具家飾連鎖「宜得利（NITORI）」1967 年在這裡最大的城市創業","en":"Furniture chain Nitori was founded in this prefecture's largest city in 1967","ja":"家具チェーンのニトリは1967年、○○最大の都市で創業した"},{"k":"brand","zh":"超商 Seicomart 1971 年開出第一家店，是日本現存最古老的便利商店連鎖","en":"Seicomart, which opened its first store in 1971, is Japan's oldest surviving convenience store chain","ja":"1971年に1号店を開いたセイコーマートは、現存する日本最古のコンビニチェーン"},{"k":"people","zh":"把愛努族神謠譯成日文的知里幸惠，19 歲就過世了","en":"Chiri Yukie, who translated Ainu sacred songs into Japanese, died at just 19","ja":"アイヌの神謡を日本語に訳した知里幸恵は、19歳の若さで亡くなった"},{"k":"legend","zh":"愛努傳說中住在蜂斗菜葉下的小人「克魯波克魯」，因受辱而渡海遠去","en":"Ainu legend tells of the Koropokkur, little people under butterbur leaves who left after being insulted","ja":"フキの葉の下に住む小人コロポックルは、無礼に怒り北の海の彼方へ去ったと伝わる"},{"k":"history","zh":"1954 年洞爺丸翻覆，1155 人罹難或失蹤，促成青函隧道計畫","en":"The 1954 Tōya Maru ferry sinking left 1,155 dead or missing and spurred the Seikan Tunnel plan","ja":"1954年の洞爺丸事故は死者・行方不明者1155人を出し、青函トンネル構想を加速させた"},{"k":"people","zh":"克拉克博士只在這裡的農學校待了約 9 個月，留下「少年們，要胸懷大志」","en":"William Clark taught at the farm school here for only about nine months, leaving 'Boys, be ambitious'","ja":"クラーク博士は○○の農学校に約9か月だけ滞在し「少年よ大志を抱け」と残した"},{"k":"work","zh":"岩井俊二的電影《情書》在小樽拍攝，「你好嗎？」的台詞紅遍韓國","en":"Iwai Shunji's film Love Letter was shot in Otaru; its line 'O-genki desu ka?' became a buzzword in Korea","ja":"岩井俊二の映画『Love Letter』は小樽で撮影され、「お元気ですか？」は韓国で流行語になった"},{"k":"work","zh":"荒川弘的漫畫《銀之匙》以農業高中為舞台，原型是帶廣農業高中","en":"Arakawa Hiromu's manga Silver Spoon is set at a farm school modeled on Obihiro Agricultural High","ja":"荒川弘『銀の匙』の舞台の農業高校は、帯広農業高校がモデル"},{"k":"nature","zh":"昭和新山是 1943～45 年從農地隆起的火山，至今仍是私人土地","en":"Shōwa-shinzan rose out of farmland in 1943–45 and is still privately owned","ja":"昭和新山は1943〜45年に畑地から隆起した火山で、今も私有地である"},{"k":"nature","zh":"鄂霍次克海沿岸是北半球流冰能抵達的最南端","en":"Its Okhotsk Sea coast marks the southern limit of drift ice in the Northern Hemisphere","ja":"オホーツク海沿岸は北半球で流氷が届く南限にあたる"},{"k":"history","zh":"函館在 1859 年與橫濱、長崎同時開港，是日本最早的貿易港之一","en":"Hakodate opened to foreign trade in 1859 along with Yokohama and Nagasaki","ja":"函館は1859年、横浜・長崎とともに日本初の貿易港として開港した"},{"k":"festival","zh":"愛努族把養大的小熊之靈送回神界的「熊送」儀式，曾被禁止半個世紀","en":"In the Ainu Iomante rite, a raised bear cub's spirit is sent back to the gods; it was banned 1955–2007","ja":"育てた子グマの魂を神の国へ送るアイヌのイオマンテは、1955〜2007年に事実上禁止された"},{"k":"symbol","zh":"日本只有這裡有棕熊，是日本現存最大的陸上哺乳類","en":"Brown bears live only here in Japan, the country's largest land mammal","ja":"日本でヒグマが生息するのは○○だけで、国内最大の陸生哺乳類である"},{"k":"food","zh":"這裡做紅豆飯常放甜納豆而不是紅豆，吃起來是甜的","en":"Locals often make sekihan festive rice with sweet amanattō beans instead of azuki","ja":"○○では赤飯に小豆ではなく甘納豆を入れることが多い"},{"k":"history","zh":"1874 年起派駐「屯田兵」，一邊開墾一邊守備北方","en":"From 1874, farmer-soldiers called tondenhei were stationed here to clear land and guard the north","ja":"1874年から屯田兵が置かれ、開拓と北辺の守りを担った"},{"k":"record","zh":"日高山脈襟裳十勝國立公園是日本面積最大的國立公園","en":"Hidaka-sanmyaku Erimo Tokachi is Japan's largest national park by area","ja":"日高山脈襟裳十勝国立公園は面積が日本最大の国立公園"},{"k":"history","zh":"1457 年愛努首領胡奢魔犬起兵，被武田信廣擊敗","en":"In 1457 the Ainu leader Koshamain rose in revolt and was defeated by Takeda Nobuhiro","ja":"1457年、アイヌの首長コシャマインが蜂起し、武田信広に討たれた"},{"k":"life","zh":"這裡的「町」除了森町之外，全都念作「ちょう」","en":"Every town here is read '-chō' except Mori-machi","ja":"○○の町は森町（もりまち）を除いてすべて「ちょう」と読む"},{"k":"nature","zh":"最高峰是海拔 2291 公尺的旭岳","en":"Its highest peak is Asahidake, 2,291 m","ja":"最高峰は標高2291mの旭岳"},{"k":"history","zh":"2018 年膽振東部地震，厚真町測得這裡史上首次的震度 7","en":"In the 2018 Iburi quake, Atsuma recorded shindo 7, the first ever measured here","ja":"2018年の胆振東部地震で厚真町が震度7を観測、○○で初めてだった"}],
"JP-02":[{"k":"festival","zh":"八戶三社大祭的華麗山車，2016 年登錄聯合國教科文組織無形文化遺產","en":"The ornate floats of Hachinohe's Sansha Taisai festival joined UNESCO's intangible heritage list in 2016.","ja":"八戸三社大祭の山車行事は、2016年にユネスコ無形文化遺産に登録された"},{"k":"symbol","zh":"縣樹是柏科的「羅漢柏」（ヒバ）","en":"Its prefectural tree is the hiba, a Japanese cypress relative.","ja":"県の木はヒバ"},{"k":"people","zh":"以畫大眼睛、表情叛逆的小女孩聞名的藝術家奈良美智出身弘前","en":"Artist Yoshitomo Nara, famous for his big-eyed, defiant little girls, was born in Hirosaki.","ja":"目つきの鋭い少女の絵で知られる美術家・奈良美智は弘前市出身"},{"k":"work","zh":"漫畫《飛翔的魔女》描寫一位見習魔女搬到弘前的親戚家生活","en":"In the manga Flying Witch, a trainee witch moves in with relatives in Hirosaki.","ja":"漫画『ふらいんぐうぃっち』は、見習い魔女が弘前の親戚の家で暮らす物語"},{"k":"origin","zh":"名字來自港邊一座長滿青翠樹木的小丘，漁船回港時把它當成目標","en":"Its name comes from a small wooded hill by the harbor that fishing boats used as a landmark when returning.","ja":"名の由来は、漁船が帰港の目印にしていた、木々の茂る海辺の小高い丘"},{"k":"record","zh":"用不同顏色稻子在田裡作畫的「稻田藝術」，1993 年起源於這裡的田舍館村","en":"'Rice paddy art', pictures made with different-colored rice plants, began in 1993 in Inakadate village here.","ja":"色の違う稲で田に絵を描く「田んぼアート」は1993年、ここの田舎館村で始まった"},{"k":"record","zh":"八甲田山的酸湯 2013 年積雪達 566 公分，刷新氣象廳全國觀測點的紀錄","en":"Sukayu on Mt. Hakkōda logged 566 cm of snow in 2013, a record for Japan's weather stations.","ja":"八甲田山の酸ヶ湯では2013年に積雪566cmを観測し、アメダスの記録を塗り替えた"},{"k":"sport","zh":"高中足球名門「○○山田高中」2016 年後已四度拿下全國高中足球冠軍","en":"High-school soccer powerhouse '○○ Yamada' has won the national high school championship four times since 2016.","ja":"高校サッカーの強豪「○○山田」は2016年度以降、全国選手権で4度優勝"},{"k":"legend","zh":"新鄉村有座「基督之墓」，傳說耶穌逃到日本並在這裡終老","en":"Shingō village has a 'Tomb of Christ', claiming Jesus fled to Japan and spent his last years here","ja":"新郷村には「キリストの墓」があり、イエスが日本へ逃れ晩年を過ごしたと伝わる"},{"k":"food","zh":"八戶的「草莓煮」其實是海膽鮑魚湯，因海膽看起來像野草莓而得名","en":"Hachinohe's 'ichigo-ni' is sea urchin and abalone soup, named because the urchin looks like wild strawberries","ja":"八戸のいちご煮はウニとアワビの吸い物で、ウニが野いちごに見えるのが名の由来"},{"k":"festival","zh":"五所川原的「立佞武多」山車高約 23 公尺，1996 年睽違約 80 年復活","en":"Goshogawara's Tachi-neputa floats stand about 23 m tall, revived in 1996 after some 80 years","ja":"五所川原立佞武多の山車は高さ約23mで、1996年に約80年ぶりに復活した"},{"k":"history","zh":"戊辰戰爭後，會津藩士被移到下北半島建立斗南藩，生活極為困苦","en":"After the Boshin War, Aizu samurai were moved to the Shimokita Peninsula as the Tonami domain","ja":"戊辰戦争後、会津藩士は下北半島へ移され斗南藩を立てたが、困窮を極めた"},{"k":"history","zh":"眼睛像雪鏡的「遮光器土偶」代表作，出土於津輕的龜岡遺跡","en":"The best-known goggle-eyed Shakōki dogū figurine was dug up at the Kamegaoka site in Tsugaru","ja":"遮光器土偶の代表作は、つがる市の亀ヶ岡遺跡から出土した"},{"k":"brand","zh":"全球產量最多的蘋果品種「富士」，是在藤崎町育成的","en":"Fuji, the world's most-produced apple variety, was bred in the town of Fujisaki here","ja":"世界で最も多く生産されるリンゴ品種「ふじ」は藤崎町で育成された"},{"k":"symbol","zh":"尻屋崎放牧的「寒立馬」，冬天就在雪地裡佇立過冬","en":"Kandachime horses graze at Cape Shiriya and spend the winter outdoors in the snow","ja":"尻屋崎の寒立馬は、冬も放牧されたまま雪の中で越冬する"},{"k":"life","zh":"津輕腔最短的對話：「どさ」（去哪？）「ゆさ」（去泡澡）","en":"Tsugaru dialect's shortest exchange: 'Dosa?' (Where to?) 'Yusa.' (To the bath.)","ja":"津軽弁の最短会話は「どさ」（どこへ）「ゆさ」（湯へ）"},{"k":"history","zh":"1931 年 Miss Veedol 號從三澤起飛，完成首次不著陸飛越太平洋","en":"In 1931 Miss Veedol took off from Misawa for the first nonstop flight across the Pacific","ja":"1931年、ミス・ビードル号が三沢から飛び立ち、初の太平洋無着陸横断を果たした"},{"k":"life","zh":"縣廳所在地是唯一全市被劃為「特別豪雪地帶」的縣廳所在地","en":"Its capital is the only prefectural capital designated entirely as a special heavy-snow zone","ja":"市全域が特別豪雪地帯の県庁所在地はここだけ"},{"k":"people","zh":"創立劇團「天井棧敷」的歌人兼劇作家寺山修司，出身弘前","en":"Poet and playwright Terayama Shūji, founder of the Tenjō Sajiki troupe, was born in Hirosaki","ja":"劇団「天井桟敷」を主宰した歌人・劇作家の寺山修司は弘前出身"},{"k":"history","zh":"日本第一艘核動力船「陸奧號」1974 年試航時發生輻射外洩，一度有港歸不得","en":"Japan's first nuclear ship Mutsu leaked radiation on a 1974 test run and was left adrift","ja":"日本初の原子力船「むつ」は1974年の試験航海で放射線漏れを起こし漂流した"},{"k":"nature","zh":"佛浦海岸綿延 2 公里以上的奇岩，被取名為「如來之首」「五百羅漢」","en":"At Hotokegaura, over 2 km of rock cliffs bear Buddhist names like 'Head of the Tathagata'","ja":"仏ヶ浦では2km以上続く奇岩に「如来の首」「五百羅漢」などの名が付く"},{"k":"legend","zh":"能召喚亡者說話的巫女「イタコ」，以恐山大祭最為人知","en":"Itako, female mediums who channel the dead, are best known at the Osorezan summer festival","ja":"死者の言葉を語る口寄せ巫女イタコは、恐山大祭で知られる"},{"k":"food","zh":"黑石的「湯汁炒麵」，是把炒麵泡在蕎麥湯汁或拉麵湯裡吃","en":"Kuroishi's tsuyu-yakisoba is fried noodles served in soba broth or ramen soup","ja":"黒石のつゆやきそばは、焼きそばにそばつゆやラーメンスープをかける"},{"k":"sport","zh":"1883 年起，大相撲幕內從未少過這裡出身的力士","en":"Since 1883, sumo's top division has never been without a wrestler from here","ja":"1883年以降、○○出身の幕内力士が途絶えたことがない"},{"k":"people","zh":"女子角力選手伊調馨在 2004～2016 年連續四屆奧運奪金","en":"Wrestler Ichō Kaori won Olympic gold at four Games in a row, 2004–2016","ja":"レスリングの伊調馨は2004〜2016年に五輪4連覇を達成した"},{"k":"brand","zh":"漆器「津輕塗」在 1975 年獲指定為國家傳統工藝品","en":"Tsugaru-nuri lacquerware was designated a national traditional craft in 1975","ja":"津軽塗は1975年に国の伝統的工芸品に指定された"},{"k":"food","zh":"縣廳所在地的關東煮，習慣沾薑味噌吃","en":"In the prefectural capital, oden is eaten with ginger miso","ja":"県庁所在地ではおでんに生姜味噌をつけて食べる"},{"k":"food","zh":"當地有一種把味噌、咖哩、牛奶混在一起的「味噌咖哩牛奶拉麵」","en":"A local ramen blends miso, curry and milk in one bowl","ja":"味噌・カレー・牛乳を合わせた「味噌カレー牛乳ラーメン」がご当地麺"},{"k":"sport","zh":"2003 年亞洲冬季運動會在這裡舉辦","en":"This prefecture hosted the 2003 Asian Winter Games","ja":"2003年にアジア冬季競技大会が開かれた"},{"k":"people","zh":"桌球名將福原愛、水谷隼都出自這裡的同一所私立高中","en":"Table tennis stars Fukuhara Ai and Mizutani Jun both came through the same private school here","ja":"卓球の福原愛と水谷隼は、ともに○○の同じ私立高校で腕を磨いた"},{"k":"history","zh":"西邊的弘前藩與東邊的盛岡藩長年不和，到 1869 年才和解","en":"The Hirosaki and Morioka domains here were long rivals, reconciling only in 1869","ja":"弘前藩と盛岡藩は長く対立し、1869年にようやく和解した"},{"k":"origin","zh":"愛努語稱這一帶為「Awunmosir」，意思是「鄰國」","en":"In Ainu, this area was called Awunmosir, meaning 'neighboring land'","ja":"アイヌ語でこの地は「アウンモシㇼ（隣の国）」と呼ばれた"}],
"JP-03":[{"k":"symbol","zh":"縣花是桐樹的花（キリ）","en":"Its prefectural flower is the paulownia blossom.","ja":"県の花はキリ（桐）"},{"k":"people","zh":"2022 年以 20 歲之齡投出完全比賽的佐佐木朗希，出身陸前高田","en":"Rōki Sasaki, who threw a perfect game at age 20 in 2022, is from Rikuzentakata.","ja":"2022年に20歳で完全試合を達成した佐々木朗希は陸前高田市出身"},{"k":"people","zh":"畢生研究愛努語的語言學家金田一京助出身縣廳所在地","en":"Linguist Kyōsuke Kindaichi, who devoted his life to studying the Ainu language, was born in the prefectural capital.","ja":"アイヌ語研究に生涯をささげた言語学者・金田一京助は県庁所在地の出身"},{"k":"festival","zh":"「チャグチャグ馬コ」祭中，掛滿鈴鐺、盛裝打扮的馬兒一路叮噹作響地遊行","en":"At the Chagu Chagu Umakko festival, horses in colorful costumes hung with bells parade with a jingling sound.","ja":"チャグチャグ馬コでは、鈴をたくさん付けて着飾った馬が音を鳴らして行進する"},{"k":"record","zh":"縣廳所在地的「さんさ舞」以 3 千多人同時打太鼓，獲金氏認證為世界最大和太鼓合奏","en":"The Sansa Odori festival in the capital holds a Guinness record for the largest Japanese drum ensemble: over 3,000 drummers.","ja":"県庁所在地のさんさ踊りは、3千人超の和太鼓同時演奏でギネス世界記録に認定"},{"k":"origin","zh":"傳說作惡的鬼被神懲罰，在大石上按下手印發誓不再作亂，成了名字由來","en":"Legend says a demon, punished by the gods, pressed its handprint into a big rock as a vow to behave, giving the name.","ja":"悪さをした鬼が神に懲らしめられ、大岩に手形を押して誓ったという伝説が名の由来"},{"k":"sport","zh":"「橄欖球之城」釜石：新日鐵釜石隊在 1980 年前後達成日本選手權 7 連霸","en":"Kamaishi is a rugby town: Nippon Steel Kamaishi won seven straight national championships around 1980.","ja":"ラグビーの街・釜石。新日鉄釜石は1980年前後に日本選手権7連覇を果たした"},{"k":"work","zh":"宮澤賢治筆下的理想鄉「伊哈托布（イーハトーブ）」以這裡為原型","en":"Kenji Miyazawa's dreamland 'Ihatov' was modeled on this place.","ja":"宮沢賢治が描いた理想郷「イーハトーブ」のモデル"},{"k":"history","zh":"蝦夷首領阿弖流為在 789 年大敗朝廷軍，後來向坂上田村麻呂投降","en":"Emishi leader Aterui routed a court army in 789, later surrendering to Sakanoue no Tamuramaro","ja":"蝦夷の族長アテルイは789年に朝廷軍を破り、のちに坂上田村麻呂に降った"},{"k":"history","zh":"陸前高田約 7 萬棵松樹中，唯一挺過 2011 年海嘯的「奇蹟一本松」","en":"Of some 70,000 pines in Rikuzentakata, one 'Miracle Pine' survived the 2011 tsunami","ja":"陸前高田の約7万本の松のうち、2011年の津波に耐えたのが「奇跡の一本松」"},{"k":"brand","zh":"小岩井農場的名字，取自三位創辦人小野、岩崎、井上的姓","en":"Koiwai Farm's name combines its three founders: Ono, Iwasaki and Inoue","ja":"小岩井農場の名は創業者の小野・岩崎・井上の頭文字から"},{"k":"work","zh":"NHK 晨間劇《小海女》以久慈為原型，台詞「じぇじぇじぇ」成為年度流行語","en":"NHK drama Amachan was modeled on Kuji; its 'jejeje!' won the 2013 buzzword award","ja":"朝ドラ『あまちゃん』は久慈がモデルで、「じぇじぇじぇ」が流行語大賞に"},{"k":"symbol","zh":"法院裡的「石割櫻」從花崗岩裂縫中長出，樹齡超過 360 年","en":"The 'Rock-splitting Cherry' grows from a cracked granite boulder at a courthouse, over 360 years old","ja":"地方裁判所構内の石割桜は花崗岩の割れ目から育ち、樹齢360年を超える"},{"k":"record","zh":"魹崎是本州最東端，也是本州四極中唯一沒有道路可達的","en":"Cape Todogasaki is Honshu's easternmost point and the only one of its four extremes with no road","ja":"魹ヶ崎は本州最東端で、本州四端で唯一車道が通じていない"},{"k":"record","zh":"二戶淨法寺產的漆約占國產漆七成，修復金閣寺與日光東照宮都用它","en":"Jōbōji in Ninohe makes most of Japan's domestic lacquer, used to restore Kinkaku-ji and Nikkō Tōshō-gū","ja":"二戸の浄法寺漆は国産漆の約7割を占め、金閣寺や日光東照宮の修復に使われた"},{"k":"legend","zh":"傳說家中住著孩童模樣的「座敷童子」就會興旺，它一離開家就衰敗","en":"Zashiki-warashi, a child spirit, brings a house fortune, and ruin when it leaves","ja":"座敷童子が住む家は栄え、去ると衰えると伝わる"},{"k":"festival","zh":"北上的「鬼劍舞」面具看似鬼，其實代表五大明王，所以沒有角","en":"Kitakami's Oni-kenbai masks look like demons but depict Buddhist wisdom kings, so they have no horns","ja":"北上の鬼剣舞の面は鬼に見えるが五大明王を表し、角がない"},{"k":"record","zh":"1984 年開通的三陸鐵道，是第一條接手廢線計畫路線的第三部門鐵路","en":"Sanriku Railway (1984) was Japan's first third-sector line made from lines slated for closure","ja":"1984年開業の三陸鉄道は、廃止予定線を引き継いだ初の第三セクター鉄道"},{"k":"life","zh":"「南部曲屋」是 L 形農舍，人和馬住在同一個屋頂下","en":"Nanbu magariya are L-shaped farmhouses where people and horses lived under one roof","ja":"南部曲り家はL字型の農家で、人と馬が一つ屋根の下で暮らした"},{"k":"nature","zh":"由蛇紋岩構成的早池峰山，長著特有種「早池峰薄雪草」","en":"Mt. Hayachine, made of serpentinite, is home to the endemic Hayachine-usuyukisō flower","ja":"蛇紋岩の早池峰山には、固有種ハヤチネウスユキソウが咲く"},{"k":"people","zh":"當過臺灣總督府民政長官、主導關東大地震後復興的後藤新平出身水澤","en":"Gotō Shinpei, Taiwan's civil administrator and planner of Tokyo's post-1923 rebuild, was from Mizusawa","ja":"台湾総督府民政長官や帝都復興を担った後藤新平は水沢出身"},{"k":"food","zh":"久慈的「まめぶ汁」，麵疙瘩裡包著核桃和黑糖，卻泡在鹹湯裡","en":"Kuji's mamebu soup has walnut and brown-sugar dumplings simmered in a savory broth","ja":"久慈のまめぶ汁は、クルミと黒砂糖入りの団子をだし汁で煮る"},{"k":"history","zh":"1189 年源義經在衣川館遭藤原泰衡圍攻後自盡","en":"In 1189 Minamoto no Yoshitsune took his own life at Koromogawa after Fujiwara no Yasuhira attacked","ja":"1189年、源義経は衣川館で藤原泰衡に攻められ自害した"},{"k":"legend","zh":"傳說武藏坊弁慶在這裡守護源義經，至死仍站著不倒","en":"Legend says Benkei died standing upright here while guarding Yoshitsune","ja":"弁慶は義経を守り、立ったまま息絶えた「立往生」の伝説が残る"},{"k":"life","zh":"縣廳所在地的車站，是新幹線「隼號」與「小町號」連結、分離的地方","en":"Its capital's station is where Hayabusa and Komachi shinkansen trains couple and split","ja":"県庁所在地の駅で、はやぶさとこまちが連結・切り離しを行う"},{"k":"nature","zh":"北上川是東北地方最大的河川","en":"The Kitakami is the largest river in the Tōhoku region","ja":"北上川は東北地方最大の河川"},{"k":"record","zh":"奧州的角塚古墳，是最北的前方後圓墳","en":"Tsunozuka Kofun in Ōshū is the northernmost keyhole-shaped burial mound","ja":"奥州市の角塚古墳は最北の前方後円墳"},{"k":"festival","zh":"早池峰神樂在 2009 年登錄聯合國教科文組織無形文化遺產","en":"Hayachine Kagura was inscribed as UNESCO Intangible Cultural Heritage in 2009","ja":"早池峰神楽は2009年にユネスコ無形文化遺産に登録された"},{"k":"sport","zh":"釜石的球場建在被海嘯沖毀的學校舊址，是 2019 世界盃橄欖球賽唯一新建場地","en":"Kamaishi's stadium, on a tsunami-destroyed school site, was the only new venue of the 2019 Rugby World Cup","ja":"釜石鵜住居復興スタジアムは津波で流された学校跡に建ち、2019年W杯唯一の新設会場"},{"k":"brand","zh":"以金箔雲紋為特色的漆器「秀衡塗」，名字來自奧州藤原氏的藤原秀衡","en":"Hidehira-nuri lacquerware with gold-leaf clouds is named for Fujiwara no Hidehira","ja":"金箔の源氏雲が特徴の秀衡塗は、奥州藤原氏の秀衡にちなむ"},{"k":"people","zh":"蘭學者高野長英出身水澤，越獄後據說用藥品燒臉來變裝","en":"Scholar Takano Chōei of Mizusawa escaped prison and reportedly burned his face with acid as a disguise","ja":"水沢出身の蘭学者・高野長英は脱獄後、薬品で顔を焼いて逃亡したと伝わる"},{"k":"people","zh":"《錢形平次捕物控》作者野村胡堂出身紫波，一共寫了 383 篇","en":"Nomura Kodō from Shiwa wrote 383 Zenigata Heiji detective stories","ja":"紫波出身の野村胡堂は『銭形平次捕物控』を383編書いた"},{"k":"record","zh":"2008 年地震時一關測得 4022 gal 的加速度，獲金氏世界紀錄認證","en":"During a 2008 quake, Ichinoseki recorded 4,022 gal of acceleration, a Guinness world record","ja":"2008年の地震で一関西観測点が4022ガルを記録し、ギネス認定された"}],
"JP-04":[{"k":"symbol","zh":"縣鳥是雁；伊豆沼清晨雁群齊飛的振翅聲，入選「日本音風景百選」","en":"Its prefectural bird is the goose; the sound of geese taking off at dawn over Izunuma is one of Japan's 100 Soundscapes.","ja":"県の鳥はガン。伊豆沼でマガンが一斉に飛び立つ音は「日本の音風景100選」"},{"k":"people","zh":"創作《假面騎士》《人造人009》的石之森章太郎出身登米","en":"Shōtarō Ishinomori, creator of Kamen Rider and Cyborg 009, was born in Tome.","ja":"『仮面ライダー』『サイボーグ009』の石ノ森章太郎は登米市出身"},{"k":"work","zh":"《JOJO的奇妙冒險》第四部的「杜王町」，以作者故鄉、這裡的縣廳所在地為原型","en":"Morioh, the town in JoJo's Bizarre Adventure Part 4, is modeled on the author's hometown, the prefectural capital.","ja":"『ジョジョ』第4部の杜王町は、作者の故郷であるここの県庁所在地がモデル"},{"k":"work","zh":"伊坂幸太郎的小說《Golden Slumber 宅配男與披頭四搖籃曲》以縣廳所在地為舞台","en":"Kōtarō Isaka's novel Golden Slumber is set in the prefectural capital.","ja":"伊坂幸太郎の小説『ゴールデンスランバー』の舞台は県庁所在地"},{"k":"festival","zh":"どんと祭的「裸參拜」，男人纏著白布、口咬白紙以免氣息碰到神明，走向神社","en":"At Donto-sai, men in white cloth make 'naked pilgrimages' to shrines, biting paper so their breath won't touch the gods.","ja":"どんと祭の裸参りでは、さらし姿の男たちが神に息がかからないよう紙をくわえて歩く"},{"k":"life","zh":"縣廳所在地的中華料理店「龍亭」1937 年推出夏季涼麵，被視為冷やし中華的發祥之一","en":"Ryūtei, a Chinese restaurant in the capital, launched a summer cold noodle in 1937, seen as one origin of hiyashi chūka.","ja":"県庁所在地の「龍亭」が1937年に出した夏の麺は、冷やし中華の元祖のひとつとされる"},{"k":"sport","zh":"達比修有高中就讀這裡的東北高中，曾在甲子園投出無安打比賽","en":"Yu Darvish attended Tōhoku High School here and threw a no-hitter at Kōshien.","ja":"ダルビッシュ有は東北高校出身で、甲子園でノーヒットノーランを達成した"},{"k":"people","zh":"搞笑組合「三明治人」兩人都出身這裡，2007 年拿下 M-1 大賽冠軍","en":"Comedy duo Sandwichman, both from here, won the M-1 Grand Prix in 2007.","ja":"お笑いコンビ・サンドウィッチマンは2人ともここの出身で、2007年のM-1王者"},{"k":"history","zh":"724 年建的多賀城，奈良時代設有陸奧國府和鎮守府","en":"Taga Castle, built in 724, housed the Mutsu provincial government and military HQ","ja":"724年創建の多賀城には、奈良時代に陸奥国府と鎮守府が置かれた"},{"k":"sport","zh":"2022 年這裡的一所高中成為首支奪得夏季甲子園冠軍的東北球隊","en":"In 2022 a school here became the first Tōhoku team to win the summer Koshien","ja":"2022年、○○の高校が東北勢として初めて夏の甲子園を制した"},{"k":"work","zh":"漫畫《排球少年!!》的烏野高中和對手青葉城西、白鳥澤都在這裡","en":"In Haikyu!!, Karasuno and rivals Aoba Johsai and Shiratorizawa are all schools here","ja":"『ハイキュー!!』の烏野・青葉城西・白鳥沢はすべて○○の高校"},{"k":"festival","zh":"「麻雀舞」傳說源自 1603 年遷入新城的慶典上，石匠們的即興舞蹈","en":"Legend says the Suzume Odori sparrow dance began with stonemasons dancing at a 1603 castle celebration","ja":"すずめ踊りは1603年の城移徙の宴で石工が即興で踊ったのが始まりと伝わる"},{"k":"life","zh":"縣廳所在地的新年「初賣」贈品太豪華，曾獲准放寬贈品上限","en":"Its capital's lavish New Year sales were once allowed a special exemption on giveaway limits","ja":"県庁所在地の初売りは景品が豪華で、景品上限の特例が認められていた"},{"k":"brand","zh":"銘菓「萩之月」的造型，取自胡枝子盛開的原野上空的明月","en":"The custard cake Hagi no Tsuki is shaped after the moon over a field of blooming bush clover","ja":"銘菓「萩の月」は、萩の咲き乱れる野の空に浮かぶ名月をかたどった"},{"k":"people","zh":"〈荒城之月〉作詞者土井晚翠出身這裡，是第一位獲頒文化勳章的詩人","en":"Doi Bansui, lyricist of 'Kōjō no Tsuki', was born here and was the first poet given the Order of Culture","ja":"『荒城の月』の作詞者・土井晩翠は○○出身で、詩人初の文化勲章受章者"},{"k":"life","zh":"《福星小子》拉姆的口頭禪「だっちゃ」，靈感來自這裡的方言","en":"Lum's catchphrase 'daccha' in Urusei Yatsura was inspired by the local dialect","ja":"『うる星やつら』ラムの「だっちゃ」は○○の方言がヒント"},{"k":"food","zh":"伊達政宗在城下設「御鹽噌藏」釀味噌，被視為當地紅色辛口味噌的起源","en":"Date Masamune set up a domain miso brewery, seen as the origin of the local red miso","ja":"伊達政宗が城下に御塩噌蔵を設けたのが、当地の辛口赤味噌の始まりとされる"},{"k":"food","zh":"登米的「油麩丼」用炸麵筋取代豬排，原本是為不吃肉的客人做的","en":"Tome's aburafu-don swaps pork cutlet for fried wheat gluten, first made for diners who avoided meat","ja":"登米の油麩丼はカツの代わりに油麩を使い、肉を食べられない客向けに生まれた"},{"k":"legend","zh":"鹽竈神社的起源，傳說是鹽土老翁神在此教人民製鹽","en":"Shiogama Shrine traces its origin to a god who taught locals to make salt","ja":"鹽竈神社は、塩土老翁神が人々に製塩を教えたことが起源とされる"},{"k":"people","zh":"提倡「民本主義」、大正民主的旗手吉野作造出身古川","en":"Yoshino Sakuzō, standard-bearer of Taishō Democracy and 'minpon-shugi', was from Furukawa","ja":"大正デモクラシーの旗手で民本主義を唱えた吉野作造は古川出身"},{"k":"nature","zh":"金華山其實是一座島，名列「奧州三靈場」","en":"Kinkasan is actually an island, one of the Three Sacred Sites of Ōshū","ja":"金華山は山ではなく島で、奥州三霊場の一つ"},{"k":"history","zh":"1978 年近海地震多人死於磚牆倒塌，促成 1981 年的耐震新基準","en":"In a 1978 offshore quake many died under collapsed block walls, prompting stricter 1981 building codes","ja":"1978年の沖合の地震はブロック塀倒壊の犠牲が多く、1981年の新耐震基準につながった"},{"k":"people","zh":"林子平寫書警告海防而遭處罰，自嘆「無親無妻無子無版木」","en":"Hayashi Shihei, punished for warning of coastal threats, lamented having no parents, wife, child or woodblocks","ja":"林子平は『海国兵談』で処罰され「親も無し妻無し子無し版木無し」と詠んだ"},{"k":"symbol","zh":"石卷外海的田代島是「貓島」，有貓神社，原則上禁止帶狗上島","en":"Tashirojima off Ishinomaki is 'Cat Island', with a cat shrine and a general ban on dogs","ja":"石巻の田代島は「猫の島」で猫神社があり、犬の持ち込みは原則禁止"},{"k":"food","zh":"白石溫麵長約 9 公分、不用油，傳說是孝子為胃弱的父親研發的","en":"Shiroishi's oil-free umen noodles, about 9 cm long, were reputedly made by a son for his weak-stomached father","ja":"白石温麺は長さ約9cmで油を使わず、胃の弱い父のため考案されたと伝わる"},{"k":"history","zh":"真田幸村之子在大坂之陣後被白石城主片倉家收留，後代成為伊達家臣","en":"After the Osaka campaigns, a son of Sanada Yukimura was sheltered by the Katakura clan; his line served the Date","ja":"真田信繁の子とされる守信は白石城主片倉家に匿われ、伊達家臣の真田家を興した"},{"k":"food","zh":"當地的芹菜鍋，連芹菜根都一起下鍋吃","en":"The local seri nabe hot pot uses Japanese parsley from leaves right down to the roots","ja":"○○のせり鍋は、セリを葉から根まで丸ごと使う"},{"k":"festival","zh":"鳴子的全國木芥子祭，是三大木芥子大賽中歷史最悠久的","en":"The National Kokeshi Festival in Naruko is the oldest of the three big kokeshi contests","ja":"鳴子の全国こけし祭りは、三大こけしコンクールで最も歴史が長い"},{"k":"legend","zh":"明治時代的「四郎」去過的店都會興隆，如今他的照片被當成招財符","en":"Shirō, a Meiji-era man whose visits made shops prosper, is now displayed in shops as a good-luck charm","ja":"訪れた店が繁盛した明治の実在人物「四郎」は、今も写真が商売繁盛の福の神として飾られる"},{"k":"brand","zh":"以硯台聞名的雄勝石，也用在東京車站丸之內站舍上","en":"Ogatsu stone, famed for inkstones, was also used on Tokyo Station's Marunouchi building","ja":"硯で知られる雄勝石は、東京駅丸の内駅舎にも使われた"},{"k":"life","zh":"七濱的高山是日本三大外國人避暑地之一，始於明治時代","en":"Takayama in Shichigahama is one of Japan's three big foreigners' summer resorts, dating to Meiji","ja":"七ヶ浜の高山は明治に始まる日本三大外国人避暑地の一つ"},{"k":"festival","zh":"1991 年起，每年九月縣廳所在地的街頭舉辦由市民志工運作的爵士音樂節","en":"Since 1991, a volunteer-run street jazz festival has filled its capital's streets each September","ja":"1991年から毎年9月、市民ボランティアが運営する定禅寺ストリートジャズフェスが開かれる"}],
"JP-05":[{"k":"symbol","zh":"縣花是早春從雪地冒出來的蜂斗菜花苞「ふきのとう」","en":"Its prefectural flower is fukinotō, the butterbur bud that pokes through the snow in early spring.","ja":"県の花は、雪解けとともに顔を出すふきのとう"},{"k":"symbol","zh":"縣魚是冬天打雷時成群靠岸的「鰰」（ハタハタ）","en":"Its prefectural fish is the sandfish (hatahata), which swarms the coast in winter when thunder rolls.","ja":"県の魚は、冬の雷の頃に押し寄せるハタハタ（鰰）"},{"k":"people","zh":"日本職棒史上唯一三度拿下打擊三冠王的落合博滿出身這裡","en":"Hiromitsu Ochiai, the only player in Japanese pro baseball to win the Triple Crown three times, is from here.","ja":"プロ野球史上唯一、3度の三冠王に輝いた落合博満の出身地"},{"k":"work","zh":"《灌籃高手》最強對手「山王工業」，原型被認為是這裡的能代工業高中","en":"Sannoh Kogyo, the toughest rival in Slam Dunk, is said to be modeled on Noshiro Technical High School here.","ja":"『SLAM DUNK』の最強校・山王工業のモデルとされるのは、ここの能代工業高校"},{"k":"sport","zh":"2018 年夏季甲子園，公立農業高中「金足農」一路打進決賽，掀起「金農旋風」","en":"In 2018, public agricultural school Kanaashi Nōgyō stormed to the summer Kōshien final, sparking a national craze.","ja":"2018年夏の甲子園で公立の金足農業が準優勝し、「金農旋風」を巻き起こした"},{"k":"festival","zh":"橫手的雪屋祭「かまくら」，是武士町的左義長和商人町的水神祭合而為一","en":"Yokote's kamakura snow-hut festival grew from merging a samurai district's fire rite with a merchants' water-god festival.","ja":"横手のかまくらは、武家町の左義長と町人町の水神祭りが合わさって生まれた"},{"k":"life","zh":"夏天路邊的「Babahera 冰淇淋」：大媽用鏟子把粉紅和黃色冰淇淋堆成玫瑰花","en":"In summer, roadside 'Babahera' ladies scoop pink and yellow ice cream into rose shapes with a spatula.","ja":"夏の道端で、おばちゃんがヘラでピンクと黄色のアイスをバラの形に盛る「ババヘラアイス」"},{"k":"record","zh":"國家指定的「重要無形民俗文化財」件數全國最多","en":"It has more nationally designated Important Intangible Folk Cultural Properties than any other prefecture.","ja":"国の重要無形民俗文化財の指定件数が全国最多"},{"k":"food","zh":"魚醬「しょっつる」是日本三大魚醬之一","en":"Shottsuru fish sauce is one of Japan's three great fish sauces","ja":"魚醤しょっつるは日本三大魚醤の一つ"},{"k":"food","zh":"橫手炒麵上面放荷包蛋，配的是福神漬而不是紅薑","en":"Yokote yakisoba is topped with a fried egg and served with fukujinzuke instead of red ginger","ja":"横手やきそばは目玉焼きをのせ、紅しょうがでなく福神漬を添える"},{"k":"food","zh":"掃帚草種子做的「とんぶり」號稱「田裡的魚子醬」，只在大館生產","en":"Tonburi, kochia seeds dubbed 'field caviar', is produced only in Ōdate","ja":"ホウキギの実「とんぶり」は畑のキャビアと呼ばれ、大館市だけで生産される"},{"k":"festival","zh":"西馬音內盆舞的舞者用只露出眼睛的頭巾遮臉，據說代表亡者","en":"Nishimonai Bon Odori dancers hide their faces in hoods showing only the eyes, said to represent the dead","ja":"西馬音内の盆踊は目だけ出す彦三頭巾で顔を隠し、亡者を表すという"},{"k":"legend","zh":"傳說少女辰子為求永保美貌而化身為龍，田澤湖因此冬天不結冰","en":"Legend says Tatsuko became a dragon seeking eternal beauty, which is why Lake Tazawa never freezes","ja":"永遠の美を願い龍になった辰子姫の伝説があり、田沢湖が凍らない理由とされる"},{"k":"work","zh":"漫畫《天才小釣手》作者矢口高雄出身橫手，家鄉有增田漫畫美術館","en":"Yaguchi Takao, creator of Tsurikichi Sanpei, was born in Yokote, home of the Masuda Manga Museum","ja":"『釣りキチ三平』の矢口高雄は横手出身で、故郷に増田まんが美術館がある"},{"k":"people","zh":"第一屆芥川獎得主石川達三出身橫手，得獎作描寫巴西移民","en":"Ishikawa Tatsuzō, first Akutagawa Prize winner for a novel of Brazil emigrants, was from Yokote","ja":"第1回芥川賞の石川達三は横手出身で、受賞作はブラジル移民を描いた"},{"k":"brand","zh":"大館城主鼓勵下級武士做「曲木盒」當副業，成了傳統工藝","en":"Ōdate's bentwood magewappa boxes began as a side job encouraged for poor low-ranking samurai","ja":"大館曲げわっぱは、城主が下級武士に内職として奨励したのが始まり"},{"k":"symbol","zh":"天然○○杉與木曾檜、青森羅漢柏並稱「日本三大美林」","en":"Its natural cedar forests rank with Kiso cypress and Aomori hiba as Japan's three most beautiful forests","ja":"天然○○杉は木曽ヒノキ・青森ヒバと並ぶ日本三大美林"},{"k":"history","zh":"鹿角的大湯環狀列石中，萬座環狀列石直徑 52 公尺，是日本最大","en":"At the Ōyu Stone Circles in Kazuno, the Manza circle, 52 m across, is Japan's largest","ja":"鹿角の大湯環状列石のうち万座環状列石は径52mで国内最大"},{"k":"sport","zh":"這裡的一所工業高中拿過 15 次全國高中橄欖球冠軍，全國最多","en":"A technical high school here has won the national high school rugby title 15 times, the most","ja":"県内の工業高校がラグビー全国大会で最多の15回優勝を誇る"},{"k":"record","zh":"小坂礦山 1910 年為礦工蓋的劇場「康樂館」，至今仍在演出","en":"Kōraku-kan, built in 1910 for Kosaka mine workers, still stages performances","ja":"小坂鉱山の厚生施設として1910年に建った康楽館は、今も公演を行う"},{"k":"people","zh":"國學四大人之一的平田篤胤，曾訪談自稱去過仙境的少年並寫成書","en":"Nativist scholar Hirata Atsutane interviewed a boy who claimed to have lived in an otherworld","ja":"国学四大人の平田篤胤は、仙界帰りの少年寅吉に聞き取り『仙境異聞』を著した"},{"k":"people","zh":"《蟹工船》作者小林多喜二出生在大館，4 歲才搬到小樽","en":"Kobayashi Takiji, author of The Crab Cannery Ship, was born in Ōdate and moved to Otaru at 4","ja":"『蟹工船』の小林多喜二は大館の生まれで、4歳で小樽へ移った"},{"k":"nature","zh":"芭蕉以「松島如笑、象潟如怨」形容的潟湖，在 1804 年地震後隆起成陸地","en":"Kisakata, a lagoon Bashō contrasted with Matsushima, rose into dry land in an 1804 earthquake","ja":"芭蕉が「松島は笑ふが如く、象潟は憾むが如し」と記した潟は、1804年の地震で陸地化した"},{"k":"symbol","zh":"田澤湖特有的國鱒在 1940 年滅絕，2010 年卻在山梨的西湖被找到","en":"The Kunimasu trout of Lake Tazawa died out in 1940 but was found alive in Yamanashi's Lake Sai in 2010","ja":"田沢湖固有のクニマスは1940年に絶滅したが、2010年に山梨の西湖で再発見された"},{"k":"people","zh":"暗黑舞踏的創始者土方巽，出身縣廳所在地","en":"Hijikata Tatsumi, founder of ankoku butoh dance, was born in the prefectural capital","ja":"暗黒舞踏の創始者・土方巽は県庁所在地の出身"},{"k":"history","zh":"1602 年佐竹義宣從常陸 54 萬石被減封移到這裡","en":"In 1602 Satake Yoshinobu was moved here from Hitachi, his 540,000-koku domain cut down","ja":"1602年、佐竹義宣は常陸54万石から減封のうえ転封された"},{"k":"people","zh":"1912 年率隊登上南極大陸的白瀨矗，出身現在的仁賀保","en":"Shirase Nobu, who led Japan's 1912 Antarctic expedition, was born in today's Nikaho","ja":"1912年に南極大陸へ上陸した探検隊長・白瀬矗は、現在のにかほ市出身"},{"k":"life","zh":"白瀨矗探險後因後援會亂花錢背上鉅債，花了約 20 年巡迴演講還債","en":"After the Antarctic trip, Shirase was left in debt by his backers and lectured for about 20 years to repay it","ja":"白瀬矗は後援会の浪費で巨額の借金を負い、約20年講演して返済した"},{"k":"sport","zh":"出身縣廳所在地的遠藤幸雄，在 1964 東京奧運成為首位體操個人全能金牌的日本人","en":"Endō Yukio, born in the capital here, was Japan's first gymnastics all-around Olympic champion, in 1964","ja":"県庁所在地出身の遠藤幸雄は、1964年東京五輪で日本人初の体操個人総合金メダル"},{"k":"history","zh":"朝廷所設最北的古代城柵遺址，挖出接近簡易沖水式的廁所","en":"The northernmost ancient court fortress, here, had a toilet close to a simple flush type","ja":"朝廷最北の城柵跡から、簡易水洗式に近い古代のトイレ跡が見つかった"},{"k":"history","zh":"院內銀山在江戶時代是日本最大的銀山，人口比藩主的城下町還多","en":"Innai Silver Mine was Japan's largest in the Edo era, once more populous than the domain's castle town","ja":"院内銀山は江戸時代日本最大の銀山で、城下町久保田より人口が多かった"},{"k":"history","zh":"1935 年八橋油田的油井大量噴出原油","en":"In 1935 a well at the Yabase oil field here struck a major gusher","ja":"1935年、八橋油田の油井が大噴油した"}],
"JP-06":[{"k":"symbol","zh":"縣花是紅花，江戶時代做成胭脂與染料，讓當地商人致富","en":"Its prefectural flower is the safflower, which in the Edo period made local merchants rich as a source of rouge and dye.","ja":"県の花は紅花。江戸時代には口紅や染料の原料として商人に富をもたらした"},{"k":"festival","zh":"夏日祭典中，大批舞者戴著綴有紅花的斗笠，邊喊「ヤッショ、マカショ」邊跳舞","en":"At a summer festival, crowds of dancers in safflower-decorated straw hats dance chanting 'Yassho, makasho!'","ja":"花笠をかぶった大勢の踊り手が「ヤッショ、マカショ」と掛け声をあげて踊る夏祭り"},{"k":"people","zh":"近代短歌巨匠、同時也是精神科醫師的齋藤茂吉出身上山","en":"Mokichi Saitō, a master of modern tanka poetry who was also a psychiatrist, was born in Kaminoyama.","ja":"近代短歌の巨匠で精神科医でもあった斎藤茂吉は上山市の出身"},{"k":"origin","zh":"名字源自平安時代辭書《和名類聚抄》記載的「山方鄉」","en":"Its name is said to derive from an ancient district written 山方 ('mountain side'), recorded in a Heian-era dictionary.","ja":"名の由来は『和名類聚抄』に載る「山方郷」とされる"},{"k":"life","zh":"縣廳所在地每戶外食吃拉麵的支出，常年是全國第一","en":"Households in the capital spend more on eating out at ramen shops than anywhere else in Japan, year after year.","ja":"県庁所在地は1世帯あたりの外食ラーメン支出が、長年全国1位"},{"k":"work","zh":"奧斯卡最佳外語片《送行者：禮儀師的樂章》主要在酒田拍攝","en":"Departures, the Oscar-winning film about an encoffiner, was mainly shot in Sakata.","ja":"アカデミー賞外国語映画賞の『おくりびと』の主なロケ地は酒田市"},{"k":"work","zh":"NHK 晨間劇《阿信》開頭，主角在最上川沿岸的貧農家庭度過童年","en":"NHK drama Oshin opens with its heroine's childhood in a poor farming family along the Mogami River here.","ja":"NHK朝ドラ『おしん』は、主人公が最上川流域の貧しい農家で過ごす少女時代から始まる"},{"k":"legend","zh":"湯殿山一帶的寺院保存著僧侶自我木乃伊化而成的「即身佛」","en":"Temples around Mt. Yudono preserve sokushinbutsu, monks who mummified themselves","ja":"湯殿山周辺の寺には、自ら即身仏となった僧が祀られている"},{"k":"people","zh":"頭盔上有個「愛」字的直江兼續，隨上杉家移封到米澤","en":"Naoe Kanetsugu, whose helmet bore the kanji for 'love', moved to Yonezawa with the Uesugi","ja":"兜の前立に「愛」を掲げた直江兼続は、上杉家とともに米沢へ移った"},{"k":"people","zh":"組織浪士組、間接催生新選組的清河八郎出身庄內","en":"Kiyokawa Hachirō, who formed the rōnin band that gave rise to the Shinsengumi, was from Shōnai","ja":"新選組の母体となる浪士組を組織した清河八郎は庄内出身"},{"k":"history","zh":"酒田本間家號稱日本最大地主，俗諺說當不成本間大人，至少當個藩主","en":"Sakata's Honma family, called Japan's biggest landowners, were said to be richer than a feudal lord","ja":"酒田の本間家は日本最大の地主と称され「本間様には及びもせぬが」と歌われた"},{"k":"food","zh":"1952 年縣廳所在地的拉麵店應熟客要求，做出冰涼的「冷拉麵」","en":"A ramen shop in the capital created chilled 'hiyashi ramen' in 1952 at a regular's request","ja":"県庁所在地の栄屋本店が1952年、常連の要望で冷やしラーメンを生んだ"},{"k":"work","zh":"電影《搖擺女孩》描寫鄉下女高中生組大樂團，主要在置賜地方拍攝","en":"The film Swing Girls, about rural schoolgirls forming a big band, was shot mainly in the Okitama area","ja":"映画『スウィングガールズ』は置賜地方を中心に撮影された"},{"k":"food","zh":"竹籤串起的醬油滷「玉蒟蒻」，傳說是缺糖缺米時茶屋拿來代替丸子的","en":"Skewered soy-simmered konjac balls reputedly replaced dango at teahouses when sugar was scarce","ja":"玉こんにゃくは砂糖や米粉が貴重な時代、茶屋が団子の代わりに出したと伝わる"},{"k":"festival","zh":"鶴岡黑川地區傳承約 500 年的「黑川能」，二月王祇祭時徹夜演出","en":"Kurokawa Noh in Tsuruoka, kept for about 500 years, is performed all night at a February festival","ja":"鶴岡の黒川能は約500年続き、2月の王祇祭で夜通し演じられる"},{"k":"record","zh":"1992 年開通的迷你新幹線，把在來線改成標準軌，與東京直通","en":"A 1992 'mini-shinkansen' converted local track to standard gauge for direct trains to Tokyo","ja":"1992年開業のミニ新幹線は在来線を標準軌に改め、東京と直通した"},{"k":"record","zh":"鶴岡的加茂水族館靠水母起死回生，展示種類獲金氏紀錄認證","en":"Tsuruoka's Kamo Aquarium was revived by jellyfish and holds a Guinness record for species shown","ja":"加茂水族館はクラゲで再生し、展示種数でギネス認定を受けた"},{"k":"people","zh":"貧農出身的探險家最上德內，曾約九度探查蝦夷地，還到過擇捉島","en":"Explorer Mogami Tokunai, a poor farmer's son, made about nine trips to Ezo and reached Etorofu","ja":"貧農出身の探検家・最上徳内は蝦夷地を約9回探査し、択捉島にも渡った"},{"k":"nature","zh":"唯一有人居住的離島飛島，傳說是鳥海山山頂被炸飛形成的","en":"Tobishima, the only inhabited island here, is said to be Mt. Chōkai's summit blown off in an eruption","ja":"県内唯一の有人島・飛島は、鳥海山の山頂が吹き飛んでできたと伝わる"},{"k":"people","zh":"攝影大師土門拳出身酒田，故鄉的紀念館收藏他的全部作品","en":"Photographer Domon Ken was born in Sakata, whose museum holds all his works","ja":"写真家・土門拳は酒田出身で、記念館が全作品を収蔵する"},{"k":"food","zh":"鶴岡毛豆「だだちゃ豆」的名字，來自庄內方言的「爸爸」","en":"Tsuruoka's dadacha-mame edamame is named from the Shōnai dialect word for 'father'","ja":"鶴岡のだだちゃ豆の「だだちゃ」は庄内弁で父親のこと"},{"k":"history","zh":"庄內藩在戊辰戰爭中沒讓敵軍入境，戰後感念西鄉隆盛而編了《南洲翁遺訓》","en":"Shōnai domain kept enemies out in the Boshin War, later compiling Saigō Takamori's sayings in gratitude","ja":"庄内藩は戊辰戦争で領内に敵を入れず、のち西郷への恩義から『南洲翁遺訓』を編んだ"},{"k":"festival","zh":"1989 年創辦的國際紀錄片影展，是亞洲第一個專門的紀錄片影展","en":"Its international documentary film festival, begun in 1989, was Asia's first devoted to documentaries","ja":"1989年創設の国際ドキュメンタリー映画祭は、アジア初のドキュメンタリー専門映画祭"},{"k":"people","zh":"57 萬石大名最上義光的妹妹義姬，是伊達政宗的母親","en":"Daimyo Mogami Yoshiaki's younger sister Yoshihime was the mother of Date Masamune","ja":"57万石の大名・最上義光の妹・義姫は伊達政宗の母"},{"k":"people","zh":"劇作家井上廈以寫稿慢出名，乾脆自號「遲筆堂」","en":"Playwright Inoue Hisashi was so slow with manuscripts that he called himself 'Chihitsu-dō' (Slow Pen Hall)","ja":"劇作家・井上ひさしは遅筆で知られ、自ら「遅筆堂」と号した"},{"k":"food","zh":"河北町的「冷肉蕎麥麵」用老母雞，湯在常溫下上桌","en":"Kahoku's tsumetai niku soba uses mature hen, with the broth served at room temperature","ja":"河北町の冷たい肉そばは親鶏を使い、常温のつゆで出す"},{"k":"nature","zh":"月山積雪豐厚，滑雪場可以一路滑到七月底","en":"Mt. Gassan's lingering snow lets its ski area run until about late July","ja":"月山スキー場は豊富な残雪で7月末ごろまで夏スキーができる"},{"k":"history","zh":"1976 年酒田大火從一家電影院燒起，燒毀約 22.5 公頃市中心","en":"The 1976 Sakata Great Fire began in a cinema and burned about 22.5 hectares of downtown","ja":"1976年の酒田大火は映画館から出火し、中心市街地約22.5haを焼いた"},{"k":"brand","zh":"鶴岡的新創公司 Spiber 開發出人工蜘蛛絲蛋白質材料","en":"Tsuruoka startup Spiber develops artificial spider-silk protein materials","ja":"鶴岡のスパイバーは人工クモ糸のタンパク質素材を開発した"},{"k":"record","zh":"鶴岡在 2014 年成為日本第一個聯合國教科文組織「美食創意城市」","en":"In 2014 Tsuruoka became Japan's first UNESCO Creative City of Gastronomy","ja":"鶴岡市は2014年、日本初のユネスコ食文化創造都市に認定された"},{"k":"legend","zh":"傳說最上川中游曾有一座湖，行基與圓仁開鑿河道後才消失","en":"Legend says a lake once lay on the Mogami's middle course until the monks Gyōki and Ennin cut a channel","ja":"最上川中流には藻が湖があり、行基・円仁の開削で消えたという伝承がある"}],
"JP-07":[{"k":"symbol","zh":"縣花是高山植物「根本石楠花」（ネモトシャクナゲ）","en":"Its prefectural flower is the Nemoto rhododendron, an alpine plant.","ja":"県の花は高山植物のネモトシャクナゲ"},{"k":"people","zh":"寫出阪神虎隊歌《六甲颪》的作曲家古關裕而出身這裡，晨間劇《Yell》以他為原型","en":"Composer Yūji Koseki, who wrote the Hanshin Tigers' anthem 'Rokkō Oroshi', was born here; NHK's drama Yell is based on him.","ja":"阪神の「六甲おろし」を作曲した古関裕而の出身地。朝ドラ『エール』のモデル"},{"k":"festival","zh":"「相馬野馬追」：數百名身穿盔甲的騎馬武士，爭奪射上天空的神旗","en":"At Sōma Nomaoi, hundreds of armored samurai on horseback race to catch sacred flags shot into the sky.","ja":"相馬野馬追では、甲冑姿の騎馬武者数百騎が打ち上げられた御神旗を奪い合う"},{"k":"work","zh":"大河劇《八重之櫻》的主角新島八重，是戊辰戰爭時拿槍守城的會津女子","en":"Niijima Yae, heroine of the NHK drama Yae's Sakura, was an Aizu woman who fought with a rifle in the Boshin War.","ja":"大河ドラマ『八重の桜』の主人公・新島八重は、戊辰戦争で銃を手に戦った会津の女性"},{"k":"origin","zh":"據《古事記》，兩位將軍父子在此相會，因此原寫作「相津」，後來成了「會津」","en":"Per the Kojiki, a general and his son met here, so the area was named 相津 ('meeting port'), later written Aizu.","ja":"『古事記』によれば、将軍の父子がここで出会ったことから「相津」と呼ばれ、のちの会津になった"},{"k":"record","zh":"全國新酒鑑評會的金賞數量，曾史上首度連續 9 屆全國第一","en":"It won the most gold medals at Japan's national new sake competition nine times in a row, a first in history.","ja":"全国新酒鑑評会の金賞受賞数で、史上初の9回連続日本一"},{"k":"life","zh":"會津藩武士子弟守則「什之掟」最後一句是：「不行的事就是不行」","en":"The Aizu domain's code for samurai children ends with: 'What must not be done, must not be done.'","ja":"会津藩の子弟の掟「什の掟」は「ならぬことはならぬものです」で結ばれる"},{"k":"sport","zh":"日本國家足球隊的訓練中心「J-Village」在這裡，核災後曾當作應變據點","en":"J-Village, Japan's national soccer training center, is here; after the 2011 nuclear accident it served as a response base.","ja":"サッカー日本代表の練習拠点「Jヴィレッジ」がある。原発事故後は対応拠点になった"},{"k":"history","zh":"1888 年磐梯山噴發，山體崩塌堵住河川，形成了檜原湖等湖泊","en":"In 1888 Mt. Bandai erupted; its collapse dammed rivers and created Lake Hibara and other lakes.","ja":"1888年の磐梯山噴火で山体が崩れ、川がせき止められて檜原湖などができた"},{"k":"history","zh":"1589 年伊達政宗在摺上原之戰擊敗蘆名氏，奪下會津","en":"In 1589 Date Masamune crushed the Ashina clan at the Battle of Suriagehara and seized Aizu.","ja":"1589年、伊達政宗が摺上原の戦いで蘆名氏を破り、会津を手に入れた"},{"k":"history","zh":"明治時期的國家工程「安積疏水」把豬苗代湖的水引到郡山，讓失業武士移墾荒原","en":"The Meiji-era Asaka Canal piped Lake Inawashiro water to Koriyama, where former samurai settled to farm.","ja":"明治の国営事業「安積疏水」で猪苗代湖の水を郡山に引き、士族が荒野を開拓した"},{"k":"life","zh":"因戊辰戰爭的舊恨，會津若松市曾在 1986 年拒絕與長州的萩市結為友好城市","en":"Still bitter over the Boshin War, Aizu-Wakamatsu turned down a 1986 friendship-city offer from Hagi in old Choshu.","ja":"戊辰戦争の恨みから、会津若松市は1986年に旧長州・萩市からの友好都市提携の申し入れを断った"},{"k":"people","zh":"1975 年成為全球第一位登上聖母峰的女性田部井淳子，出身這裡的三春町","en":"Junko Tabei, the first woman to summit Everest (1975), was born in Miharu here.","ja":"1975年に女性で世界初のエベレスト登頂を果たした田部井淳子は三春町の出身"},{"k":"people","zh":"二代將軍德川秀忠的私生子保科正之，成為會津藩的藩祖","en":"Hoshina Masayuki, an illegitimate son of shogun Tokugawa Hidetada, founded the ruling line of the Aizu domain.","ja":"2代将軍徳川秀忠の隠し子・保科正之が会津藩の藩祖となった"},{"k":"people","zh":"推動「寬政改革」的老中松平定信，原本是白河藩的藩主","en":"Matsudaira Sadanobu, architect of the Kansei Reforms, was the lord of the Shirakawa domain here.","ja":"寛政の改革を行った老中・松平定信は、白河藩の藩主だった"},{"k":"people","zh":"二本松出身的歷史學家朝河貫一，1937 年成為第一位日本人耶魯大學教授","en":"Historian Kan'ichi Asakawa from Nihonmatsu became Yale's first Japanese professor in 1937.","ja":"二本松出身の歴史学者・朝河貫一は、日本人初のイェール大学教授になった"},{"k":"sport","zh":"1964 年東京奧運馬拉松銅牌得主圓谷幸吉，出身須賀川","en":"Kokichi Tsuburaya, marathon bronze medalist at the 1964 Tokyo Olympics, came from Sukagawa.","ja":"1964年東京五輪マラソン銅メダリストの円谷幸吉は須賀川の出身"},{"k":"sport","zh":"東京奧運最早開賽的項目是壘球，揭幕戰在這裡的吾妻球場舉行","en":"The first event of the Tokyo 2020 Olympics, a softball game, was played at Azuma Stadium here.","ja":"東京2020五輪で最初に行われた競技はソフトボールで、会場は県営あづま球場だった"},{"k":"work","zh":"高村光太郎《智惠子抄》裡，智惠子說東京沒有天空，真正的天空在安達太良山上","en":"In Takamura Kotaro's Chieko-sho, Chieko says Tokyo has no sky; the real sky is above Mt. Adatara.","ja":"『智恵子抄』で智恵子は東京に空が無いと言い、安達太良山の上の空を「ほんとの空」と呼んだ"},{"k":"work","zh":"民謠〈會津磐梯山〉唱的小原庄助，因愛睡早覺、喝早酒、泡早澡而敗光家產","en":"The folk song Aizu Bandaisan teases Ohara Shosuke, who lost his fortune to sleeping in, morning sake and baths.","ja":"民謡「会津磐梯山」の小原庄助さんは、朝寝・朝酒・朝湯が大好きで身上を潰した"},{"k":"festival","zh":"二本松提燈祭中，掛滿三百多盞燈籠的太鼓台夜裡遊街，名列日本三大提燈祭","en":"Nihonmatsu's lantern festival parades floats hung with 300+ lanterns, one of Japan's three great lantern festivals.","ja":"二本松提灯祭りでは300個以上の提灯を灯した太鼓台が夜の町を練り歩く。日本三大提灯祭りの一つ"},{"k":"festival","zh":"須賀川的「松明あかし」點燃巨大火把，悼念 1589 年與伊達軍交戰而死的人","en":"Sukagawa's Taimatsu Akashi burns giant torches to mourn those killed fighting Date's army in 1589.","ja":"須賀川の「松明あかし」は巨大な松明を燃やし、1589年に伊達軍と戦った人々を弔う"},{"k":"life","zh":"會津十日市買不倒翁「起き上がり小法師」，習俗是要買比家裡人數多一個","en":"At Aizu's Toka-ichi fair, people buy tiny self-righting okiagari-koboshi dolls: one more than the family size.","ja":"会津の十日市では起き上がり小法師を「家族の人数より一つ多く」買うのが習わし"},{"k":"origin","zh":"據說城主木村吉清把「杉目城」改名為○○城，成了名字由來","en":"The name is said to date to lord Kimura Yoshikiyo renaming Sugime Castle with a lucky new name.","ja":"城主・木村吉清が杉目城を○○城と改名したのが名の由来とされる"},{"k":"symbol","zh":"樹齡超過千年的紅枝垂櫻「三春瀧櫻」，是日本三大櫻之一","en":"The Miharu Takizakura, a weeping cherry over 1,000 years old, is one of Japan's three great cherry trees.","ja":"樹齢千年を超えるベニシダレザクラ「三春滝桜」は日本三大桜の一つ"},{"k":"nature","zh":"縣界沿著飯豐山的登山步道延伸出細長一條，被稱為「臍帶縣界」","en":"A narrow strip of the border runs up a hiking trail on Mt. Iide, nicknamed the 'umbilical cord border'.","ja":"飯豊山の登山道に沿って県境が細長く延び、「へその緒県境」と呼ばれる"},{"k":"food","zh":"會津的喜宴湯品「こづゆ」用干貝熬湯，裝在淺漆碗裡，可以無限續碗","en":"Aizu's festive soup kozuyu, made with dried scallop stock in shallow lacquer bowls, may be refilled endlessly.","ja":"会津の祝い膳「こづゆ」は貝柱でだしを取り、浅い手塩皿で何杯おかわりしてもよい"},{"k":"food","zh":"縣廳所在地的「圓盤餃子」把餃子在平底鍋裡排成一大圈，整盤煎好端上桌","en":"In the capital city, 'disc gyoza' are fried in a big circle in the pan and served whole on a plate.","ja":"県庁所在地の「円盤餃子」は、フライパンに餃子を円形に並べて焼き、そのまま皿に返す"},{"k":"food","zh":"某宿場町的名物「高遠蕎麥」不用筷子，而是用一整根大蔥撈麵來吃","en":"At an old post town here, takato soba is eaten with a whole leek instead of chopsticks.","ja":"ある宿場町名物の「高遠そば」は、箸の代わりに長ネギ1本ですくって食べる"},{"k":"brand","zh":"大堀相馬燒的茶杯是雙層構造，倒進熱茶也不燙手，杯上畫著奔馬","en":"Obori Soma ware cups have double walls so hot tea won't burn your hand, and are painted with running horses.","ja":"大堀相馬焼の湯呑みは二重構造で熱いお茶でも持てる。走り駒の絵が描かれる"},{"k":"brand","zh":"木馬玩具「三春駒」是日本三駒之一，源自坂上田村麻呂的傳說","en":"The Miharu-goma wooden horse, one of Japan's three great folk horse toys, comes from a Sakanoue no Tamuramaro legend.","ja":"木馬の郷土玩具「三春駒」は日本三駒の一つで、坂上田村麻呂の伝説に由来する"},{"k":"legend","zh":"傳說安達原住著吃人的鬼婆，會殺害留宿的旅人","en":"Legend says a man-eating hag lived on the Adachigahara plain, killing travelers who stayed the night.","ja":"安達ヶ原には、泊めた旅人を殺して食べる鬼婆が住んでいたという伝説がある"}],
"JP-08":[{"k":"symbol","zh":"縣花是玫瑰（バラ）","en":"Its prefectural flower is the rose.","ja":"県の花はバラ"},{"k":"origin","zh":"據《常陸國風土記》，古代將軍用帶刺的荊棘築城抵禦盜賊，成了名字由來","en":"Per an ancient gazetteer, a general built a fort of thorny brambles to fend off bandits, which gave the place its name.","ja":"『常陸国風土記』によれば、黒坂命が賊を防ぐため茨で城を築いたのが名の由来"},{"k":"life","zh":"民間調查「都道府縣魅力度排行」中，曾連續 7 年排名最後一名","en":"It came dead last in a private 'prefecture attractiveness ranking' seven years in a row.","ja":"民間の「都道府県魅力度ランキング」で7年連続最下位だったことがある"},{"k":"festival","zh":"「日立風流物」是高約 15 公尺的巨大山車，上面的機關人偶會演出戲碼","en":"Hitachi Furyūmono is a giant 15 m float on which mechanical puppets act out plays.","ja":"日立風流物は高さ約15mの巨大な山車で、からくり人形が芝居を演じる"},{"k":"work","zh":"動畫《少女與戰車》以大洗町為舞台，掀起聖地巡禮熱潮","en":"The anime Girls und Panzer is set in Ōarai, sparking a wave of fan pilgrimages.","ja":"アニメ『ガールズ&パンツァー』の舞台は大洗町。聖地巡礼ブームを呼んだ"},{"k":"people","zh":"近代日本畫巨匠橫山大觀出身縣廳所在地","en":"Yokoyama Taikan, a giant of modern Japanese-style painting, was born in the prefectural capital.","ja":"近代日本画の巨匠・横山大観は県庁所在地の出身"},{"k":"sport","zh":"2017 年成為睽違 19 年的日本出身橫綱稀勢之里，在這裡的牛久長大","en":"Kisenosato, who in 2017 became the first Japan-born yokozuna in 19 years, grew up in Ushiku here.","ja":"2017年に19年ぶりの日本出身横綱となった稀勢の里は牛久市育ち"},{"k":"record","zh":"給人京都蔬菜印象的水菜，收穫量全國第一其實在這裡","en":"Mizuna, a green associated with Kyoto, is actually grown most here.","ja":"京野菜のイメージが強い水菜の収穫量は、実はここが全国1位"},{"k":"people","zh":"江戶幕府末代將軍德川慶喜，是水戶藩主德川齊昭之子，在水戶長大","en":"Tokugawa Yoshinobu, the last shogun, was a son of Mito lord Tokugawa Nariaki and grew up in Mito.","ja":"江戸幕府最後の将軍・徳川慶喜は水戸藩主徳川斉昭の子で、水戸で育った"},{"k":"people","zh":"以這裡為根據地起兵、自稱「新皇」的平將門，被視為武士叛亂的先驅","en":"Taira no Masakado, who rebelled from his base here and called himself the 'New Emperor', was an early samurai rebel.","ja":"この地を拠点に挙兵し「新皇」を名乗った平将門は、武士の反乱の先駆けとされる"},{"k":"people","zh":"確認庫頁島是島嶼、留下「間宮海峽」之名的間宮林藏，出身這裡","en":"Mamiya Rinzo, who proved Sakhalin is an island and gave his name to the Strait of Mamiya, was born here.","ja":"樺太が島であることを確かめ「間宮海峡」に名を残した間宮林蔵はこの地の出身"},{"k":"people","zh":"寫下多首知名童謠的作詞家野口雨情，出身這裡北部的海邊","en":"Ujo Noguchi, lyricist of children's songs like 'Shabondama', was born on the northern coast here.","ja":"童謡『シャボン玉』『赤い靴』の作詞家・野口雨情は県北の海辺の出身"},{"k":"people","zh":"傳說真劍對決從未落敗的劍聖塚原卜傳，是鹿島神宮神官之子","en":"Tsukahara Bokuden, the sword saint said never to have lost a real duel, was born to a Kashima Shrine priest family.","ja":"真剣勝負で無敗と伝わる剣聖・塚原卜伝は鹿島神宮の神官の家に生まれた"},{"k":"history","zh":"1860 年刺殺大老井伊直弼的「櫻田門外之變」，主力是水戶藩的浪士","en":"Most of the assassins who killed chief minister Ii Naosuke at Sakuradamon in 1860 were Mito ronin.","ja":"1860年に大老井伊直弼を討った桜田門外の変は、主に水戸藩の浪士によるものだった"},{"k":"history","zh":"1864 年尊王攘夷派的「天狗黨」在筑波山起兵，後來三百五十多人被處死","en":"The 1864 Tengu Party rebellion of pro-emperor samurai began on Mt. Tsukuba; over 350 were later executed.","ja":"1864年、尊王攘夷派の天狗党が筑波山で挙兵し、のちに350人以上が処刑された"},{"k":"history","zh":"1929 年環球飛行的齊柏林伯爵號飛船，在日本降落於霞浦的海軍基地","en":"On its 1929 round-the-world flight, the airship Graf Zeppelin landed in Japan at Kasumigaura naval air base.","ja":"1929年、世界一周中の飛行船ツェッペリン伯号が霞ヶ浦の海軍飛行場に着陸した"},{"k":"festival","zh":"金砂神社的「磯出大祭禮」每 72 年才舉行一次，上次是 2003 年","en":"The Kanasa Shrine's Isode Grand Festival is held only once every 72 years; the last was in 2003.","ja":"金砂神社の磯出大祭礼は72年に一度だけ行われ、前回は2003年だった"},{"k":"festival","zh":"土浦全國煙火競技大會與大曲、長岡並列日本三大煙火大會","en":"The Tsuchiura fireworks competition is one of Japan's three great fireworks shows, with Omagari and Nagaoka.","ja":"土浦全国花火競技大会は、大曲・長岡と並ぶ日本三大花火大会の一つ"},{"k":"origin","zh":"舊國名「常陸」據說源自「直道」：不必翻山渡河，一路直通而來","en":"The old province name Hitachi is said to mean 'straight road', as it could be reached without crossing mountains.","ja":"旧国名「常陸」は、山や川を越えずに行ける「直道（ひたみち）」に由来するとされる"},{"k":"sport","zh":"名教頭木內幸男率取手二高、常總學院，三度奪下甲子園冠軍","en":"Coach Yukio Kiuchi led Toride Daini and Joso Gakuin to three Koshien national titles.","ja":"名将・木内幸男は取手二高と常総学院を率いて甲子園で3度優勝した"},{"k":"sport","zh":"J 聯盟水戶 HollyHock 的隊名意為「蜀葵」，取自德川家的葵紋","en":"J.League club Mito HollyHock is named after the hollyhock, echoing the Tokugawa family's aoi crest.","ja":"Jリーグ「水戸ホーリーホック」の名は、徳川家の葵の紋にちなむ「立葵」の英名"},{"k":"work","zh":"電影《下妻物語》描寫鄉下小鎮的蘿莉塔少女與不良少女之間的友情","en":"The film Kamikaze Girls follows a Lolita-fashion girl and a biker girl in the rural town of Shimotsuma.","ja":"映画『下妻物語』は、田舎町・下妻のロリータ少女とヤンキー少女の友情を描く"},{"k":"symbol","zh":"奈良春日大社的神明據說騎著白鹿從鹿島神宮前去，鹿因此被視為神使","en":"Nara's sacred deer trace to a legend that Kasuga Taisha's god rode a white deer from Kashima Shrine here.","ja":"春日大社の祭神は鹿島神宮から白鹿に乗って奈良へ来たとされ、鹿が神の使いとなった"},{"k":"legend","zh":"鹿島神宮的「要石」據說壓住了引發地震的大鯰魚的頭","en":"Kashima Shrine's Kaname-ishi stone is said to pin down the head of the giant catfish that causes earthquakes.","ja":"鹿島神宮の「要石」は、地震を起こす大鯰の頭を押さえているとされる"},{"k":"legend","zh":"傳說 1803 年有艘碗形怪船漂到常陸海岸，裡面坐著異國女子，被當成 UFO 傳說","en":"In 1803 a bowl-shaped 'hollow ship' carrying a foreign woman reportedly washed ashore here, now a UFO legend.","ja":"1803年、異国の女を乗せたお椀型の「うつろ舟」が常陸の浜に流れ着いたという伝説"},{"k":"life","zh":"筑波山「蟾蜍油」的叫賣口白：把蟾蜍放進鏡箱，牠會被自己的模樣嚇出油來","en":"Mt. Tsukuba's toad-oil sellers claim a toad in a mirror box sweats oil in fright at its own looks.","ja":"筑波山の「ガマの油売り」の口上では、鏡の箱に入れたガマが自分の姿に驚いて脂汗を流す"},{"k":"food","zh":"相傳德川光圀是第一個吃拉麵的日本人，水戶因此推出「水戶藩拉麵」","en":"Tokugawa Mitsukuni was long said to be the first Japanese to eat ramen, inspiring Mito's 'Mito-han ramen'.","ja":"徳川光圀が日本で初めてラーメンを食べたという説から「水戸藩ラーメン」が生まれた"},{"k":"food","zh":"「精力拉麵」在麵上淋滿南瓜、豬肝等勾芡的甜辣醬，冷熱都有","en":"Local 'stamina ramen' is topped with a sweet-spicy starchy sauce of pumpkin, liver and veggies, hot or cold.","ja":"「スタミナラーメン」は、カボチャやレバー入りの甘辛いあんを麺にかけた料理で、冷も温もある"},{"k":"nature","zh":"有「西富士、東筑波」之稱的筑波山，山頂分成男體山與女體山兩峰","en":"Mt. Tsukuba, paired with Fuji as 'Fuji in the west, Tsukuba in the east', has twin male and female peaks.","ja":"「西の富士、東の筑波」と並び称される筑波山は、男体山と女体山の二峰からなる"},{"k":"record","zh":"竜神大吊橋全長 375 公尺，1994 年完工時是日本最長的行人專用吊橋","en":"The 375 m Ryujin Suspension Bridge was Japan's longest pedestrian suspension bridge when completed in 1994.","ja":"竜神大吊橋は全長375mで、1994年の完成当時は歩行者専用吊橋として日本一だった"},{"k":"record","zh":"2019 年成為日本第一個實施性少數伴侶制度的都道府縣","en":"In 2019 it became the first Japanese prefecture to introduce a partnership system for sexual minorities.","ja":"2019年、都道府県で初めて性的少数者のパートナーシップ制度を導入した"},{"k":"life","zh":"東北新幹線穿過境內，卻一個新幹線車站也沒有","en":"The Tohoku Shinkansen runs through this prefecture, yet there is no Shinkansen station here.","ja":"東北新幹線が県内を通るのに、新幹線の駅が一つもない"},{"k":"brand","zh":"日立製作所起源於 1910 年小平浪平在日立礦山修理廠打造的馬達","en":"Hitachi began in 1910 when Namihei Odaira built electric motors at a copper mine's repair shop here.","ja":"日立製作所は1910年、小平浪平が日立鉱山の修理工場で作ったモーターから始まった"}],
"JP-09":[{"k":"symbol","zh":"縣花是杜鵑的一種「八汐躑躅」（やしおつつじ）","en":"Its prefectural flower is the yashio azalea.","ja":"県の花はやしおつつじ"},{"k":"festival","zh":"每年春秋，上千人扮成武士，重現德川家康遷葬的「千人武者行列」","en":"Each spring and autumn, a 'thousand-warrior procession' re-enacts the transfer of Tokugawa Ieyasu's remains.","ja":"春と秋、千人の武者姿で家康の改葬を再現する「百物揃千人武者行列」"},{"k":"people","zh":"前 WBC 世界拳王、以「OK 牧場」口頭禪聞名的 Guts 石松出身鹿沼","en":"Guts Ishimatsu, former WBC world boxing champion known for the catchphrase 'OK Bokujō', is from Kanuma.","ja":"元WBC世界王者で「OK牧場」でおなじみのガッツ石松は鹿沼市出身"},{"k":"origin","zh":"名字一說來自神社屋頂上 10 支交叉的「千木」，稱為「十千木」","en":"One theory says the name comes from the ten crossed roof beams (chigi) on a local shrine.","ja":"神明宮の社殿にあった10本の千木「十千木（とおちぎ）」が名の由来という説がある"},{"k":"sport","zh":"MotoGP 機車世界錦標賽的日本站，在這裡的茂木賽道舉行","en":"The MotoGP Japanese Grand Prix is held at the Motegi circuit here.","ja":"MotoGP日本グランプリの会場は、ここの茂木町にあるサーキット"},{"k":"life","zh":"以這裡為中心的鄉土菜「しもつかれ」，把鮭魚頭、蘿蔔泥、酒粕煮成一鍋，外觀嚇人","en":"Shimotsukare, a local dish of salmon heads, grated radish and sake lees stewed together, is notoriously scary-looking.","ja":"郷土料理しもつかれは鮭の頭・大根おろし・酒粕を煮込んだもので、見た目が強烈"},{"k":"record","zh":"伊呂波坂山路共有 48 個彎道，每個彎都標上一個「いろは」假名","en":"The Irohazaka road has 48 hairpin turns, each marked with one kana of the old 'iroha' poem.","ja":"いろは坂には48のカーブがあり、それぞれに「い」「ろ」「は」…の文字が付く"},{"k":"record","zh":"縣廳所在地夏季打雷的日數全國最多，被稱為「雷都」","en":"The capital has the most thunderstorm days in Japan from spring to autumn and is called the 'Thunder City'.","ja":"県庁所在地は4〜9月の雷発生日数が全国最多で、「雷都」と呼ばれる"},{"k":"people","zh":"在屋島之戰一箭射中船上扇靶的弓箭手那須與一，出身這裡","en":"Nasu no Yoichi, the archer who shot a fan off a boat at the Battle of Yashima, came from here.","ja":"屋島の戦いで扇の的を射抜いた那須与一はこの地の出身"},{"k":"people","zh":"勝道上人於 782 年首度登上男體山頂，開創了日光山的信仰","en":"The monk Shodo first reached the top of Mt. Nantai in 782 and founded the Nikko mountain faith.","ja":"勝道上人は782年に男体山の登頂を果たし、日光山を開いた"},{"k":"history","zh":"建立室町幕府的足利氏，以這裡的「足利莊」為根據地並以此為姓","en":"The Ashikaga clan, founders of the Muromachi shogunate, took their name from the Ashikaga estate here.","ja":"室町幕府を開いた足利氏は、この地の足利荘を本拠としその名を名乗った"},{"k":"people","zh":"二宮尊德在這裡的櫻町重建荒廢農村，晚年也在日光過世","en":"Ninomiya Sontoku rebuilt ruined villages at Sakuramachi here and died in Nikko.","ja":"二宮尊徳は桜町で荒れた農村を復興させ、晩年は日光で没した"},{"k":"people","zh":"日本爵士樂薩克斯風巨匠渡邊貞夫，出身縣廳所在地","en":"Sadao Watanabe, the giant of Japanese jazz saxophone, was born in this prefecture's capital.","ja":"日本ジャズを代表するサックス奏者・渡辺貞夫は県庁所在地の出身"},{"k":"sport","zh":"B 聯盟 2016–17 首屆總冠軍，是以縣廳所在地為主場的布雷克斯隊","en":"The Brex, based in the prefectural capital, won the first-ever B.League title in 2016–17.","ja":"Bリーグ初代王者（2016-17）は県庁所在地を本拠地とするブレックスだった"},{"k":"sport","zh":"縣廳所在地每年秋天舉辦亞洲最高等級的單日自行車公路賽「日本盃」","en":"The capital hosts the Japan Cup each autumn, Asia's top-ranked one-day pro cycling road race.","ja":"県庁所在地では毎秋、アジア最高位のワンデーロードレース「ジャパンカップ」が開かれる"},{"k":"festival","zh":"日光輪王寺的「強飯式」中，山伏會逼參拜者吃下堆得像山一樣高的白飯","en":"At Nikko's Rinnoji temple, the Gohan-shiki ritual has mountain monks force towering bowls of rice on guests.","ja":"日光輪王寺の「強飯式」では、山伏が山盛りのご飯を参拝者に無理やり勧める"},{"k":"festival","zh":"烏山「山上祭」在街上立起巨大山景布景演出歌舞伎舞蹈，列入聯合國無形遺產","en":"Karasuyama's Yamaage festival sets up giant mountain backdrops on the street for kabuki dance; UNESCO-listed.","ja":"烏山の山あげ祭は道路に巨大な山の書き割りを立てて歌舞伎舞踊を演じる。ユネスコ無形文化遺産"},{"k":"festival","zh":"鹿沼秋祭中，雕刻華麗的屋台面對面奏樂較勁，稱為「ぶっつけ」","en":"In Kanuma's autumn festival, ornately carved floats face off and battle with music, called 'buttsuke'.","ja":"鹿沼秋まつりでは、彫刻屋台が向かい合ってお囃子を競う「ぶっつけ」が見どころ"},{"k":"origin","zh":"「日光」一說源自「二荒（ふたら）」，音讀成 Nikō 後改寫成吉祥的字","en":"Nikko is said to come from 'Futara', read as 'Niko' and rewritten with characters meaning sunlight.","ja":"「日光」は「二荒（ふたら）」を音読みした「にこう」に好字を当てたものとされる"},{"k":"origin","zh":"古代的「毛野國」分成上下兩國，這裡是離京城較遠的那一半","en":"Ancient Keno province was split in two; this was the 'lower' half, farther from the capital.","ja":"古代の毛野国が上下に分かれ、都から遠い方がこの地の「下毛野」となった"},{"k":"legend","zh":"傳說男體山神化身大蛇、赤城山神化身大蜈蚣爭奪湖泊，交戰之處就是戰場之原","en":"Legend says Senjogahara is where Mt. Nantai's god as a serpent fought Mt. Akagi's god as a centipede.","ja":"男体山の神（大蛇）と赤城山の神（大ムカデ）が湖を巡って戦った場所が戦場ヶ原とされる"},{"k":"legend","zh":"那須的「殺生石」傳說是九尾狐化成的毒石，2022 年被發現裂成兩半","en":"Nasu's Sessho-seki is said to be the nine-tailed fox turned to poison stone; it was found split in two in 2022.","ja":"那須の殺生石は九尾の狐が化した毒石とされ、2022年に真っ二つに割れているのが見つかった"},{"k":"legend","zh":"日光憾滿之淵的一排地藏，傳說每次數的數量都不同，被叫做「化地藏」","en":"The row of Jizo statues at Nikko's Kanmangafuchi are 'ghost Jizo': the count is said to differ every time.","ja":"日光・憾満ヶ淵の並び地蔵は、数えるたびに数が変わるとされ「化け地蔵」と呼ばれる"},{"k":"record","zh":"國寶「那須國造碑」建於 700 年，是日本三大古碑之一","en":"The Nasu Kuni-no-miyatsuko stele, a National Treasure erected in 700, is one of Japan's three great ancient steles.","ja":"国宝「那須国造碑」は700年の建立で、日本三古碑の一つ"},{"k":"record","zh":"大谷寺的大谷觀音直接刻在岩壁上，被稱為日本最古老的磨崖佛","en":"Oya Kannon at Oyaji temple, carved into a rock face, is called Japan's oldest cliff-carved Buddha.","ja":"大谷寺の大谷観音は岩壁に彫られ、日本最古の磨崖仏とされる"},{"k":"record","zh":"1873 年開業的日光金谷飯店，是現存日本最古老的度假飯店","en":"Nikko Kanaya Hotel, opened in 1873, is Japan's oldest surviving resort hotel.","ja":"1873年開業の日光金谷ホテルは、現存する日本最古のリゾートホテル"},{"k":"life","zh":"日本俗諺說：「沒看過日光，別說『結構』（了不起）」","en":"A Japanese saying goes: 'Don't say kekko (splendid) until you've seen Nikko.'","ja":"「日光を見ずして結構と言うなかれ」ということわざがある"},{"k":"life","zh":"明治以後，義大利、英國等國大使館在中禪寺湖畔建了避暑別墅","en":"Embassies such as Italy's and Britain's built summer villas on Lake Chuzenji from the Meiji era on.","ja":"明治以降、イタリアや英国などの大使館が中禅寺湖畔に避暑の別荘を構えた"},{"k":"nature","zh":"中禪寺湖是男體山噴發的熔岩堵住河谷而形成的堰塞湖","en":"Lake Chuzenji formed when lava from Mt. Nantai's eruption dammed a valley.","ja":"中禅寺湖は男体山の噴火で溶岩が谷をせき止めてできた堰止湖"},{"k":"food","zh":"日光的豆皮寫成「湯波」，跟京都的「湯葉」不同，捲成厚厚一卷","en":"Nikko's yuba tofu skin is written 湯波, not Kyoto's 湯葉, and is rolled up thick.","ja":"日光のゆばは京都の「湯葉」と違い「湯波」と書き、厚く巻き上げるのが特徴"},{"k":"food","zh":"佐野的「炸馬鈴薯串」把蒸好的馬鈴薯裹粉油炸，淋上濃醬汁吃","en":"Sano's imo-fry are skewers of steamed potato, battered, deep-fried and doused in thick sauce.","ja":"佐野の「いもフライ」は、蒸したジャガイモを串に刺して揚げ、ソースをかけて食べる"},{"k":"brand","zh":"黃色包裝的在地乳飲「檸檬牛奶」其實不含檸檬汁，成了鄉土象徵","en":"Yellow 'lemon milk', a local dairy drink with no lemon juice in it, became a regional icon.","ja":"黄色い「レモン牛乳」はレモン果汁を使っていないご当地の乳飲料"}],
"JP-10":[{"k":"symbol","zh":"縣吉祥物是一匹小馬，2014 年拿下全國吉祥物大賽冠軍","en":"Its mascot, a little pony, won Japan's Yuru-chara Grand Prix in 2014.","ja":"県のマスコットは子馬のキャラクターで、2014年のゆるキャラグランプリで優勝"},{"k":"work","zh":"《頭文字D》主角拓海送豆腐的「秋名山」，原型是這裡的榛名山","en":"Mt. Akina, where Initial D's Takumi delivers tofu, is modeled on Mt. Haruna here.","ja":"『頭文字D』で拓海が豆腐を配達する「秋名」のモデルは榛名山"},{"k":"people","zh":"遊戲《MOTHER》的創作者、知名文案人糸井重里出身縣廳所在地","en":"Shigesato Itoi, creator of the game Mother and a famed copywriter, was born in the prefectural capital.","ja":"ゲーム『MOTHER』の生みの親でコピーライターの糸井重里は県庁所在地の出身"},{"k":"people","zh":"被譽為「日本近代詩之父」的萩原朔太郎出身縣廳所在地","en":"Sakutarō Hagiwara, called the father of modern Japanese poetry, was born in the prefectural capital.","ja":"「日本近代詩の父」と呼ばれる萩原朔太郎は県庁所在地の出身"},{"k":"origin","zh":"名字源自古代的「車郡」，後來改寫成兩個吉祥的漢字","en":"The name derives from the ancient 'Kuruma' (cart) district, later rewritten with auspicious characters.","ja":"古代の「車（くるま）」の郡が由来で、のちに縁起のよい2文字に改められた"},{"k":"record","zh":"草津溫泉的自然湧出量是日本第一","en":"Kusatsu Onsen has the largest natural flow of hot spring water in Japan.","ja":"草津温泉は自然湧出量が日本一"},{"k":"life","zh":"大泉町約五分之一居民是外國人，巴西人尤其多，被稱為「小巴西」","en":"About one in five residents of Ōizumi town is foreign, many of them Brazilian; it's nicknamed 'Little Brazil'.","ja":"大泉町は住民の約2割が外国人でブラジル人が多く、「リトルブラジル」と呼ばれる"},{"k":"life","zh":"持有駕照的人口比例全國最高","en":"It has the highest share of driver's-license holders in Japan.","ja":"運転免許保有率が全国1位"},{"k":"history","zh":"1333 年新田義貞在生品神社舉兵，一路南下攻滅鎌倉幕府","en":"In 1333 Nitta Yoshisada raised his army at Ikushina Shrine here and marched on to destroy the Kamakura shogunate.","ja":"1333年、新田義貞は生品神社で挙兵し、鎌倉幕府を滅ぼした"},{"k":"history","zh":"1783 年淺間山大噴發，鎌原村被土石流吞沒，被稱為「日本的龐貝」","en":"In 1783 Mt. Asama's eruption buried Kanbara village under debris; it's called 'Japan's Pompeii'.","ja":"1783年の浅間山大噴火で鎌原村が土石なだれに埋もれ、「日本のポンペイ」と呼ばれる"},{"k":"history","zh":"高崎的「上野三碑」是 7～8 世紀的石碑，2017 年列入世界記憶","en":"The Kozuke Sanpi, three 7th–8th century steles in Takasaki, joined UNESCO's Memory of the World in 2017.","ja":"高崎の「上野三碑」は7〜8世紀の石碑で、2017年にユネスコ「世界の記憶」に登録"},{"k":"history","zh":"碓冰峠鐵路曾用齒軌爬上 66.7‰ 陡坡，紅磚拱橋「眼鏡橋」留存至今","en":"The Usui Pass railway climbed a 66.7‰ grade by rack rail; its brick 'Megane Bridge' still stands.","ja":"碓氷峠の鉄道は66.7‰の急勾配をアプト式で登った。レンガの「めがね橋」が残る"},{"k":"people","zh":"江戶末期的俠客國定忠治據說救濟饑民，被處刑後成了戲劇裡的英雄","en":"Kunisada Chuji, a late-Edo gambler-outlaw said to have fed famine victims, became a stage hero after his execution.","ja":"江戸末期の侠客・国定忠治は飢饉で農民を救ったとされ、処刑後は芝居の英雄になった"},{"k":"people","zh":"日本首位女性太空人向井千秋出身館林","en":"Chiaki Mukai, Japan's first female astronaut, was born in Tatebayashi.","ja":"日本人女性初の宇宙飛行士・向井千秋は館林市の出身"},{"k":"people","zh":"吉田松陰的妹婿楫取素彥擔任首任縣令，大力推動養蠶與教育","en":"Katori Motohiko, brother-in-law of Yoshida Shoin, served as the first governor and promoted silk and schools.","ja":"吉田松陰の義弟・楫取素彦は初代県令として養蚕と教育に力を注いだ"},{"k":"sport","zh":"元旦舉行的企業接力賽「新年驛傳」，自 1988 年起都在這裡的道路上開跑","en":"Since 1988 the New Year Ekiden, Japan's corporate relay championship on Jan. 1, has been run on roads here.","ja":"元日の全日本実業団対抗駅伝（ニューイヤー駅伝）は1988年から県内の公道で行われている"},{"k":"sport","zh":"1999 年桐生第一高校奪下夏季甲子園冠軍，是本縣首座夏季冠軍","en":"In 1999 Kiryu Daiichi won the summer Koshien, the prefecture's first title in that tournament.","ja":"1999年、桐生第一高校が夏の甲子園で優勝し、県勢初の夏の全国制覇を果たした"},{"k":"festival","zh":"桐生八木節祭上，民眾隨著輕快的民謠「八木節」圍成圈跳舞","en":"At Kiryu's Yagibushi Festival, crowds dance in circles to the lively Yagibushi folk song.","ja":"桐生八木節まつりでは、民謡「八木節」に合わせて大勢が輪になって踊る"},{"k":"festival","zh":"沼田祭中，由女性抬著放有巨大天狗面具的神轎遊街","en":"At the Numata Festival, women carry a mikoshi bearing a giant tengu mask through the streets.","ja":"沼田まつりでは、巨大な天狗の面をのせた神輿を女性たちが担ぐ"},{"k":"origin","zh":"草津的地名一說來自硫磺味刺鼻的「臭水（くさうず）」","en":"Kusatsu's name is said to come from 'kusouzu', smelly water, because of its sulfur.","ja":"草津の地名は硫黄のにおいの「くさうず（臭水）」に由来するという説がある"},{"k":"record","zh":"土合車站的下行月台深埋隧道中，要走近五百級階梯，人稱「日本第一鼴鼠車站」","en":"Doai Station's downbound platform lies deep in a tunnel, nearly 500 steps down: 'Japan's top mole station'.","ja":"土合駅の下りホームはトンネル内の地下深くにあり、約500段の階段を下りる「日本一のモグラ駅」"},{"k":"nature","zh":"流域面積日本最大的利根川，源頭就在這裡的大水上山","en":"The Tone River, Japan's largest by basin area, rises on Mt. Ominakami here.","ja":"流域面積日本一の利根川の水源は、県北の大水上山にある"},{"k":"nature","zh":"吹割瀑布的河水從三面落進岩床裂開的深溝，人稱「東洋尼加拉」","en":"Fukiware Falls pours into a rift in a wide rock bed from three sides, dubbed the 'Niagara of the Orient'.","ja":"吹割の滝は岩床の割れ目に川が三方から流れ落ち、「東洋のナイアガラ」と呼ばれる"},{"k":"food","zh":"「烤饅頭」把蒸好的饅頭串起來，塗上甜味噌醬烤，很多是沒有餡的","en":"Yaki-manju are steamed buns skewered, brushed with sweet miso and grilled; many have no filling.","ja":"「焼きまんじゅう」は蒸したまんじゅうを串に刺し、甘い味噌だれを塗って焼く。餡なしが多い"},{"k":"food","zh":"鄉土料理「おっきりこみ」把寬麵條不先燙過，直接和蔬菜一起燉煮","en":"Okkirikomi is a local stew of broad noodles simmered straight into the pot with vegetables, no pre-boiling.","ja":"郷土料理「おっきりこみ」は幅広の麺を下茹でせず、野菜と一緒に煮込む"},{"k":"food","zh":"橫川車站的「峠之釜飯」1958 年問世，裝在益子燒的陶鍋裡販售","en":"Yokokawa Station's Toge no Kamameshi, sold since 1958, comes in a Mashiko-ware clay pot.","ja":"横川駅の「峠の釜めし」は1958年発売で、益子焼の土釜に入っている"},{"k":"brand","zh":"絲織之都桐生，自古有「西有西陣、東有桐生」之稱","en":"Silk-weaving Kiryu was long praised: 'Nishijin in the west, Kiryu in the east.'","ja":"織物の町・桐生は「西の西陣、東の桐生」と並び称された"},{"k":"brand","zh":"眼鏡連鎖品牌 JINS 創立於縣廳所在地","en":"The eyewear chain JINS was founded in this prefecture's capital.","ja":"眼鏡チェーン「JINS」は県庁所在地で創業した"},{"k":"brand","zh":"家電量販店山田電機，起源於縣廳所在地的一家小電器行","en":"Electronics retailer Yamada Denki began as a small appliance shop in the capital city.","ja":"家電量販店ヤマダ電機は、県庁所在地の小さな電器店から始まった"},{"k":"legend","zh":"童話「分福茶釜」裡狸貓變成的茶釜，據說就收藏在館林的茂林寺","en":"The tanuki-turned-tea-kettle of the tale Bunbuku Chagama is said to be kept at Morinji temple in Tatebayashi.","ja":"狸が化けた茶釜の昔話「分福茶釜」の茶釜は、館林の茂林寺に伝わるとされる"},{"k":"legend","zh":"傳說幕臣小栗忠順把幕府的黃金埋在赤城山，長年有人挖掘尋寶","en":"Legend says shogunate gold was buried on Mt. Akagi, possibly by official Oguri Tadamasa; many have dug for it.","ja":"赤城山には小栗忠順が幕府の御用金を埋めたという「徳川埋蔵金」伝説がある"}],
"JP-11":[{"k":"symbol","zh":"縣吉祥物「コバトン」的原型，是縣鳥灰斑鳩（シラコバト）","en":"Its mascot Kobaton is based on the prefectural bird, the Eurasian collared dove.","ja":"県のマスコット「コバトン」は、県民の鳥シラコバトがモデル"},{"k":"work","zh":"動畫《幸運☆星》讓鷲宮神社成了動漫聖地巡禮的先驅","en":"The anime Lucky Star made Washinomiya Shrine one of the first anime pilgrimage sites.","ja":"アニメ『らき☆すた』で鷲宮神社は聖地巡礼の先駆けになった"},{"k":"work","zh":"動畫《我們仍未知道那天所看見的花名。》以秩父為舞台","en":"The anime Anohana: The Flower We Saw That Day is set in Chichibu.","ja":"アニメ『あの日見た花の名前を僕達はまだ知らない。』の舞台は秩父市"},{"k":"people","zh":"第一位擔任國際太空站站長的日本太空人若田光一出身這裡","en":"Kōichi Wakata, the first Japanese commander of the International Space Station, was born here.","ja":"日本人初の国際宇宙ステーション船長・若田光一の出身地"},{"k":"festival","zh":"鴻巢的「驚奇女兒節」把人偶擺上 31 層、高 7 公尺的金字塔台，號稱日本最高","en":"Kōnosu's 'Surprise Doll Festival' stacks hina dolls on a 31-tier, 7 m pyramid, said to be Japan's tallest.","ja":"鴻巣の「びっくりひな祭り」には31段・高さ7mの日本一高いピラミッドひな壇が登場"},{"k":"sport","zh":"職棒西武獅的主場在這裡的所澤","en":"The Seibu Lions baseball team plays its home games in Tokorozawa here.","ja":"プロ野球・西武ライオンズの本拠地は所沢市"},{"k":"record","zh":"大量居民到外縣通勤通學，「晝夜間人口比率」全國最低","en":"So many residents commute out of the prefecture that its daytime-to-nighttime population ratio is the lowest in Japan.","ja":"県外への通勤・通学者が多く、昼夜間人口比率は全国最低"},{"k":"people","zh":"七歲失明的國學家塙保己一編纂巨著《群書類從》，海倫凱勒視他為榜樣","en":"Hanawa Hokiichi, blind from age 7, compiled the huge Gunsho Ruiju; Helen Keller looked up to him.","ja":"7歳で失明した国学者・塙保己一は『群書類従』を編み、ヘレン・ケラーの心の支えとなった"},{"k":"people","zh":"日本第一位國家認證的女醫師荻野吟子出身這裡","en":"Ginko Ogino, Japan's first government-licensed female doctor, was born here.","ja":"日本初の公許女性医師・荻野吟子はこの地の出身"},{"k":"people","zh":"被稱為「日本公園之父」、設計日比谷公園的本多靜六出身這裡","en":"Honda Seiroku, the 'father of Japanese parks' who designed Hibiya Park, was born here.","ja":"「日本の公園の父」と呼ばれ日比谷公園を設計した本多静六はこの地の出身"},{"k":"people","zh":"被譽為「坂東武士典範」的鎌倉武將畠山重忠，出身深谷一帶","en":"Hatakeyama Shigetada, the Kamakura warrior hailed as the model of eastern samurai, came from the Fukaya area.","ja":"「坂東武士の鑑」と称えられた鎌倉武将・畠山重忠は深谷周辺の出身"},{"k":"history","zh":"708 年秩父發現天然銅並獻給朝廷，年號因此改為和銅，鑄造「和同開珎」","en":"Natural copper found in Chichibu was presented to the court in 708, leading to the Wado Kaichin coin.","ja":"708年に秩父で自然銅が献上され、元号が和銅となり和同開珎が造られた"},{"k":"history","zh":"716 年朝廷把高句麗移民遷到這裡設立「高麗郡」，高麗神社祭祀其首領","en":"In 716 the court resettled Goguryeo migrants here as Koma District; Koma Shrine honors their leader.","ja":"716年、高句麗からの渡来人を移して高麗郡が置かれ、その長を祀る高麗神社がある"},{"k":"history","zh":"1590 年石田三成築起約 28 公里長堤水攻忍城，城卻沒被攻下","en":"In 1590 Ishida Mitsunari built a 28 km dike to flood Oshi Castle, yet failed to take it.","ja":"1590年、石田三成は約28kmの堤を築いて忍城を水攻めしたが、城は落ちなかった"},{"k":"history","zh":"1884 年秩父的農民因負債困苦起義，史稱「秩父事件」","en":"In 1884 debt-ridden farmers rose in revolt in Chichibu, known as the Chichibu Incident.","ja":"1884年、借金に苦しむ秩父の農民が蜂起した「秩父事件」が起きた"},{"k":"sport","zh":"2002 年世界盃四強賽巴西對土耳其，在這裡的足球專用球場舉行","en":"The 2002 World Cup semifinal between Brazil and Turkey was played at the football stadium here.","ja":"2002年W杯準決勝ブラジル対トルコは、この地のサッカー専用スタジアムで行われた"},{"k":"sport","zh":"1964 年東京奧運的划船比賽在戶田漕艇場舉行","en":"Rowing at the 1964 Tokyo Olympics was held at the Toda rowing course here.","ja":"1964年東京五輪のボート競技は戸田漕艇場で行われた"},{"k":"work","zh":"宮崎駿《龍貓》裡的森林，原型之一是所澤一帶的狹山丘陵","en":"The forest in My Neighbor Totoro is partly modeled on the Sayama Hills around Tokorozawa.","ja":"『となりのトトロ』の舞台のモデルの一つは所沢周辺の狭山丘陵とされる"},{"k":"work","zh":"動畫《前進吧！登山少女》以飯能為舞台","en":"The anime Encouragement of Climb is set in Hanno.","ja":"アニメ『ヤマノススメ』は飯能市が舞台"},{"k":"work","zh":"日劇《陸王》描寫足袋之城行田的老店轉型做跑鞋","en":"TV drama Rikuoh, about an old tabi maker turning to running shoes, is set in the tabi town of Gyoda.","ja":"ドラマ『陸王』は足袋の町・行田の老舗がランニングシューズに挑む物語"},{"k":"festival","zh":"春日部的大風箏祭會放飛約一百張榻榻米大的巨型風箏","en":"At Kasukabe's giant kite festival, a kite the size of about 100 tatami mats is flown.","ja":"春日部の大凧あげ祭りでは、約100畳もの巨大な凧を揚げる"},{"k":"festival","zh":"熊谷團扇祭號稱「關東第一祇園」，名字來自商家發團扇給客人","en":"Kumagaya's Uchiwa Festival, billed as the Kanto's top Gion festival, is named for shops handing out fans.","ja":"熊谷うちわ祭は「関東一の祇園」と称され、商家が団扇を配ったことが名の由来"},{"k":"origin","zh":"名字源自古代郡名，再往上追溯是當地神社名，一說意為「幸魂」","en":"The name comes from an ancient district, traced further to a local shrine name possibly meaning 'blessed spirit'.","ja":"名は古代の郡名に由来し、さらに地元の神社名や「幸魂（さきみたま）」にさかのぼるという説がある"},{"k":"symbol","zh":"縣魚ムサシトミヨ是一種小型刺魚，野生族群只剩熊谷的元荒川源頭","en":"The prefectural fish, the Musashi stickleback, survives in the wild only at a spring-fed stream in Kumagaya.","ja":"県の魚ムサシトミヨは、野生では熊谷市の元荒川源流域にしか生息していない"},{"k":"symbol","zh":"秩父三峯神社把狼當作神使，信眾求「御犬」神符來防火防盜","en":"Mitsumine Shrine in Chichibu treats wolves as divine messengers; its wolf charms guard against fire and theft.","ja":"秩父の三峯神社は狼を神の使いとし、「お犬様」のお札が火難・盗難よけになる"},{"k":"record","zh":"荒川在鴻巢與吉見之間的兩岸堤防相距 2537 公尺，是日本最寬的河幅","en":"Between Konosu and Yoshimi, the Arakawa's levees are 2,537 m apart, Japan's widest river span.","ja":"鴻巣市と吉見町の間の荒川は堤防間が2537mあり、川幅日本一"},{"k":"nature","zh":"秩父的武甲山因開採石灰石，山頂被削掉，海拔低了約 30 公尺","en":"Chichibu's Mt. Buko has been quarried so much for limestone that its summit is about 30 m lower.","ja":"秩父の武甲山は石灰石の採掘で山頂が削られ、標高が約30m低くなった"},{"k":"food","zh":"行田的「ゼリーフライ」不是果凍，而是炸豆渣馬鈴薯餅，名字來自錢幣形狀","en":"Gyoda's 'jelly fry' isn't jelly but a fried okara-potato patty, named for its coin (zeni) shape.","ja":"行田の「ゼリーフライ」はおからとジャガイモの揚げ物で、銭形から「ぜにフライ」が転じた"},{"k":"food","zh":"東松山的「烤雞串」其實是烤豬頭肉，要沾辣味噌醬吃","en":"Higashimatsuyama's 'yakitori' is actually grilled pork cheek, eaten with spicy miso sauce.","ja":"東松山の「やきとり」は豚のかしら肉で、辛味噌だれを付けて食べる"},{"k":"brand","zh":"國民冰棒「ガリガリ君」出自總部在深谷的赤城乳業","en":"The popular Garigari-kun ice pop is made by Akagi Nyugyo, headquartered in Fukaya here.","ja":"アイス「ガリガリ君」の赤城乳業は深谷市に本社を置く"},{"k":"brand","zh":"服飾連鎖「思夢樂」起源於小川町的一家吳服店","en":"Clothing chain Shimamura began as a kimono shop in the town of Ogawa here.","ja":"衣料品チェーン「しまむら」は小川町の呉服店から始まった"}],
"JP-12":[{"k":"symbol","zh":"縣吉祥物是一隻紅色的狗，側面輪廓剛好就是縣的形狀","en":"Its mascot is a red dog whose side profile is exactly the shape of the prefecture.","ja":"県のマスコットは赤い犬で、横から見た姿が県の形そのもの"},{"k":"life","zh":"船橋市的非官方吉祥物「船梨精」是一顆會尖叫、亂跳的梨子","en":"Funabashi's unofficial mascot Funassyi is a pear fairy that shrieks and jumps around wildly.","ja":"船橋市の非公認キャラ「ふなっしー」は、奇声を上げて跳ね回る梨の妖精"},{"k":"record","zh":"日本梨的產量全國第一","en":"It grows more Japanese pears than any other prefecture.","ja":"日本梨の収穫量が全国1位"},{"k":"work","zh":"自行車漫畫《飆速宅男》的主角就讀這裡的總北高中","en":"In the cycling manga Yowamushi Pedal, the hero attends Sōhoku High School here.","ja":"自転車漫画『弱虫ペダル』の主人公は、ここの総北高校に通う"},{"k":"sport","zh":"職棒羅德海洋隊的主場在這裡，球場以強勁海風出名","en":"The Lotte Marines baseball team plays here, at a stadium famous for strong sea winds.","ja":"プロ野球ロッテの本拠地があり、球場は海風が強いことで有名"},{"k":"festival","zh":"佐原大祭的山車上有巨大人偶，2016 年登錄聯合國教科文組織無形文化遺產","en":"Sawara's grand festival features floats topped with giant figures; it joined UNESCO's intangible heritage list in 2016.","ja":"佐原の大祭は巨大な人形を載せた山車が特徴で、2016年にユネスコ無形文化遺産に"},{"k":"origin","zh":"名字的意思是「許多葉子茂盛生長」，寄託土地與子孫繁榮的願望","en":"The name means 'a thousand leaves', expressing wishes for a thriving land and descendants.","ja":"名は「多くの葉が茂る」の意で、土地と子孫の繁栄を願ったものとされる"},{"k":"people","zh":"日蓮宗的開山祖師日蓮出身這裡的安房小湊","en":"Nichiren, founder of Nichiren Buddhism, was born in Awa-Kominato here.","ja":"日蓮宗の開祖・日蓮は安房小湊の出身"},{"k":"work","zh":"曲亭馬琴的長篇小說《南總里見八犬傳》，以里見氏統治的房總為舞台","en":"Kyokutei Bakin's epic Nanso Satomi Hakkenden is set in the Boso lands ruled by the Satomi clan.","ja":"曲亭馬琴の『南総里見八犬伝』は里見氏が治めた房総を舞台にした長編"},{"k":"work","zh":"輕小說《我的妹妹哪有這麼可愛！》以縣廳所在地為舞台","en":"The light novel Oreimo is set in this prefecture's capital city.","ja":"ライトノベル『俺の妹がこんなに可愛いわけがない』は県庁所在地が舞台"},{"k":"history","zh":"1180 年源賴朝在石橋山戰敗後渡海逃到安房，在這裡重整旗鼓","en":"After losing at Ishibashiyama in 1180, Minamoto no Yoritomo fled by sea to Awa here and regrouped.","ja":"1180年、石橋山の戦いに敗れた源頼朝は海を渡って安房に逃れ、再起を図った"},{"k":"history","zh":"1843 年蘭醫佐藤泰然在佐倉開設「順天堂」，有「西有長崎、東有佐倉」之稱","en":"In 1843 Dutch-trained doctor Sato Taizen opened Juntendo in Sakura: 'Nagasaki in the west, Sakura in the east.'","ja":"1843年、佐藤泰然が佐倉に順天堂を開き「西の長崎、東の佐倉」と称された"},{"k":"history","zh":"成田機場興建時爆發「三里塚抗爭」，農民與學生長年反對徵收土地","en":"Building Narita Airport sparked the long Sanrizuka Struggle, with farmers and students resisting land seizure.","ja":"成田空港の建設をめぐり、農民や学生が土地収用に抵抗する「三里塚闘争」が起きた"},{"k":"people","zh":"以《回眸美人圖》聞名的浮世繪之祖菱川師宣，出身房總的保田","en":"Hishikawa Moronobu, father of ukiyo-e famed for 'Beauty Looking Back', was born in Hota here.","ja":"『見返り美人図』で知られる浮世絵の祖・菱川師宣は保田の出身"},{"k":"people","zh":"傳說名主佐倉惣五郎為減輕年貢直接向將軍上訴，被處死後奉為義民","en":"Legend says village head Sakura Sogoro appealed to the shogun over taxes, was executed, and became a martyr.","ja":"名主・佐倉惣五郎は重い年貢を将軍に直訴して処刑され、義民として祀られた"},{"k":"sport","zh":"年末賽馬大賽「有馬紀念」在這裡的中山賽馬場舉行","en":"The Arima Kinen, Japan's big year-end horse race, is held at Nakayama Racecourse here.","ja":"年末の大一番「有馬記念」は県内の中山競馬場で行われる"},{"k":"sport","zh":"衝浪首度成為奧運項目的東京奧運，比賽在一宮町的釣崎海岸舉行","en":"When surfing debuted at the Tokyo 2020 Olympics, the contest was held at Tsurigasaki Beach in Ichinomiya.","ja":"サーフィンが初採用された東京2020五輪の会場は一宮町の釣ヶ崎海岸だった"},{"k":"festival","zh":"大原裸祭中，十幾座神轎直接衝進海裡互相推擠","en":"At the Ohara Hadaka Festival, over a dozen mikoshi are carried charging straight into the sea.","ja":"大原はだか祭りでは、十数基の神輿が一斉に海へ駆け込んでもみ合う"},{"k":"origin","zh":"南部舊國名「安房」，據說源自從四國阿波渡海來開墾的忌部氏","en":"The old province name Awa is said to come from the Inbe clan, who crossed from Awa in Shikoku to settle.","ja":"旧国名「安房」は、四国の阿波から渡ってきた忌部氏に由来するとされる"},{"k":"origin","zh":"古代稱這一帶為「總國」，一說因當地盛產麻（古語「ふさ」）","en":"The old name Fusa-no-kuni is said to come from 'fusa', an old word for the hemp that grew well here.","ja":"古くは「総（ふさ）の国」と呼ばれ、麻（ふさ）がよく育ったことに由来するとされる"},{"k":"symbol","zh":"外來種山羌從觀光樂園逃出後在房總野外大量繁殖","en":"Reeves's muntjac escaped from a former theme park and multiplied wildly in the Boso region.","ja":"観光施設から逃げ出した外来種キョンが房総で大繁殖した"},{"k":"symbol","zh":"鯛之浦的野生真鯛會成群浮到海面，被列為國家特別天然紀念物","en":"At Tainoura, wild red sea bream swarm near the surface; the site is a Special Natural Monument.","ja":"鯛の浦では野生のマダイが海面近くに群れ、国の特別天然記念物に指定されている"},{"k":"record","zh":"地球磁場最後一次反轉的地層在養老川沿岸，地質年代因此以本縣命名","en":"Rocks on the Yoro River record Earth's last magnetic reversal, so a geologic age is named after this prefecture.","ja":"地磁気逆転の地層が養老川沿いにあり、地質時代の名前に県名が使われた"},{"k":"record","zh":"加曾利貝塚是日本最大級的貝塚，2017 年列為特別史蹟","en":"Kasori shell mound, one of Japan's largest, was designated a Special Historic Site in 2017.","ja":"加曽利貝塚は日本最大級の貝塚で、2017年に特別史跡に指定された"},{"k":"life","zh":"經營困難的銚子電鐵靠賣「濕仙貝」撐了下來","en":"The struggling Choshi Electric Railway survived by selling wet rice crackers.","ja":"経営難の銚子電鉄は「ぬれ煎餅」を売って存続した"},{"k":"food","zh":"鄉土料理「太卷祭壽司」切開後，斷面會出現花朵或文字圖案","en":"Futomaki matsuri-zushi are thick sushi rolls that reveal flowers or characters when sliced.","ja":"郷土料理「太巻き祭りずし」は、切ると断面に花や文字の模様が現れる"},{"k":"food","zh":"勝浦擔擔麵加了辣油和洋蔥，是為了讓海女和漁夫暖身而誕生","en":"Katsuura tantanmen, made with chili oil and onions, was born to warm up ama divers and fishermen.","ja":"勝浦タンタンメンはラー油と玉ねぎが特徴で、海女や漁師の体を温めるために生まれた"},{"k":"food","zh":"野田的「White 餃子」用大量油煎到像炸的一樣，厚皮又香又脆","en":"Noda's White Gyoza are pan-fried in lots of oil until the thick skins turn crisp.","ja":"野田の「ホワイト餃子」はたっぷりの油で揚げ焼きにし、厚い皮がカリッとなる"},{"k":"nature","zh":"屏風浦的斷崖綿延約 10 公里，被稱為「東洋多佛」","en":"The Byobugaura cliffs stretch about 10 km and are called the 'Dover of the Orient'.","ja":"屏風ヶ浦は約10kmにわたる断崖で、「東洋のドーバー」と呼ばれる"},{"k":"brand","zh":"用一根細竹劈開做骨架的「房州團扇」，是日本三大團扇之一","en":"Boshu uchiwa fans, made from a single split bamboo, are one of Japan's three great fan styles.","ja":"細い竹を割いて骨にする「房州うちわ」は日本三大うちわの一つ"},{"k":"legend","zh":"市川的「八幡不知藪」是一片竹林，傳說進去的人就再也出不來","en":"Legend says anyone who enters the Yawata no Yabushirazu grove in Ichikawa can never come out.","ja":"市川の「八幡の藪知らず」は、入ると二度と出られないという禁足地の竹やぶ"}],
"JP-13":[{"k":"symbol","zh":"代表鳥是紅嘴鷗，就是《伊勢物語》裡被稱為「都鳥」的那種鳥","en":"Its official bird is the black-headed gull, the 'miyakodori' of the classic Tales of Ise.","ja":"シンボルの鳥はユリカモメ。『伊勢物語』に詠まれた「都鳥」とされる"},{"k":"work","zh":"吉卜力動畫《心之谷》以多摩地區的聖蹟櫻丘一帶為舞台","en":"Studio Ghibli's Whisper of the Heart is set around Seiseki-Sakuragaoka in the Tama area.","ja":"ジブリ『耳をすませば』の舞台は多摩市の聖蹟桜ヶ丘周辺"},{"k":"people","zh":"曾印在千圓鈔票上的文豪夏目漱石出身這裡的牛込","en":"Natsume Sōseki, the novelist once on the 1,000-yen note, was born in Ushigome here.","ja":"千円札の肖像だった夏目漱石は牛込の出身"},{"k":"festival","zh":"神田祭和山王祭是獲准讓遊行隊伍進入江戶城的「天下祭」","en":"The Kanda and Sannō festivals were 'festivals of the realm' whose processions were allowed into Edo Castle.","ja":"神田祭と山王祭は、行列が江戸城に入ることを許された「天下祭」"},{"k":"origin","zh":"銀座這個地名，來自江戶時代在此鑄造銀幣的「銀座」","en":"The Ginza district is named after the Edo-period silver mint that stood there.","ja":"銀座の地名は、江戸時代に銀貨を鋳造した「銀座」があったことに由来"},{"k":"record","zh":"2007 年米其林首次在這裡評鑑，星星總數就是全球城市之冠","en":"In its first Michelin guide in 2007, its restaurants earned the most stars of any city.","ja":"2007年のミシュラン初版で、星の総数が世界の都市で最多になった"},{"k":"sport","zh":"職棒巨人隊與養樂多燕子隊兩支球隊的主場都在這裡","en":"Both the Yomiuri Giants and the Yakult Swallows play their home games here.","ja":"プロ野球の巨人とヤクルト、2球団の本拠地がある"},{"k":"life","zh":"伊豆群島名產「くさや」魚乾，用代代相傳的醃汁浸漬，臭味驚人","en":"The Izu Islands' kusaya, fish cured in brine passed down for generations, is famous for its overpowering smell.","ja":"伊豆諸島名物のくさやは、代々受け継ぐ漬け汁に漬けた干物で、強烈な臭いがする"},{"k":"people","zh":"幕末促成將軍居城「無血開城」的勝海舟，出生在這裡的本所","en":"Katsu Kaishū, who negotiated the bloodless surrender of the shogun's castle, was born in Honjo here.","ja":"将軍の城の無血開城を実現した勝海舟は、○○の本所の生まれ"},{"k":"people","zh":"印在 2004～2024 年五千圓鈔票上的女作家樋口一葉生於這裡，24 歲就病逝","en":"Higuchi Ichiyō, the writer on the ¥5,000 note from 2004 to 2024, was born here and died at just 24.","ja":"2004～2024年の五千円札の肖像・樋口一葉はここの生まれで、24歳で世を去った"},{"k":"sport","zh":"1909 年這裡落成的相撲館，因開館文寫著「角力乃日本國技」而取名「國技館」","en":"Its sumo arena, opened in 1909, was named Kokugikan after a line calling sumo 'Japan's national sport'.","ja":"1909年開館の相撲場は、披露文の「角力は日本の國技なり」から「國技館」と名付けられた"},{"k":"work","zh":"漫畫《烏龍派出所》從 1976 年連載到 2016 年從未休刊，舞台在葛飾區龜有","en":"Kochikame, serialized 1976–2016 without a single break, is set in Kameari, Katsushika, here.","ja":"1976年から2016年まで一度も休載しなかった『こち亀』の舞台は葛飾区亀有"},{"k":"record","zh":"以這裡為舞台的《烏龍派出所》，曾以「單一漫畫系列最多卷」獲金氏世界紀錄","en":"Kochikame, set here, held the Guinness record for most volumes of a single manga series until 2021.","ja":"ここが舞台の『こち亀』は、2021年まで「最も巻数が多い単一漫画シリーズ」のギネス記録だった"},{"k":"work","zh":"電影《男人真命苦》的寅次郎，老家是柴又帝釋天參道上的糰子店","en":"In the Tora-san films, Torajirō's family runs a dango shop by Shibamata Taishakuten temple here.","ja":"映画『男はつらいよ』の寅さんの実家は、柴又帝釈天の門前の団子屋"},{"k":"work","zh":"《你的名字。》結尾男女主角重逢的階梯，在四谷的須賀神社","en":"The stairway where the leads reunite at the end of 'Your Name.' is at Suga Shrine in Yotsuya here.","ja":"『君の名は。』のラストで二人が再会する階段は、四谷の須賀神社にある"},{"k":"festival","zh":"淺草神社的「三社祭」，名稱來自供奉的三位人物，每年五月第三個週末舉行","en":"Asakusa Shrine's Sanja Matsuri, named for the three men it enshrines, fills the third weekend of May.","ja":"浅草神社の「三社祭」は三人の祭神にちなむ名で、毎年5月第3週の金～日曜に行われる"},{"k":"origin","zh":"秋葉原的地名，來自人們把明治初年蓋的「鎮火社」誤當成供奉火神秋葉權現","en":"Akihabara's name comes from locals mistaking a Meiji-era fire-prevention shrine for one to the fire god Akiba.","ja":"秋葉原の名は、明治初年の「鎮火社」を人々が火防の神・秋葉権現と誤解したことから"},{"k":"origin","zh":"日比谷原是海灣，地名可能來自淺灘裡捕魚、採海苔用的竹竿「ひび」","en":"Hibiya was once an inlet; its name may come from 'hibi', stakes set in the shallows to catch fish and seaweed.","ja":"日比谷はかつて入江で、地名は海苔や魚を採るため浅瀬に立てた「ひび」に由来するとも"},{"k":"record","zh":"1903 年開放的日比谷公園，是日本第一座西式公園","en":"Hibiya Park, opened in 1903, was Japan's first Western-style park.","ja":"1903年開園の日比谷公園は、日本初の洋風公園"},{"k":"symbol","zh":"日本最常見的櫻花「染井吉野」，是幕末到明治初在這裡的染井村培育出來的","en":"Somei-yoshino, Japan's most common cherry, was bred by gardeners in Somei village here in the 1800s.","ja":"日本で最もおなじみの桜ソメイヨシノは、幕末から明治初めにここの染井村で育成された"},{"k":"record","zh":"1882 年開園的上野動物園，是日本最古老的動物園","en":"Ueno Zoo, opened in 1882, is the oldest zoo in Japan.","ja":"1882年開園の上野動物園は、日本で最も古い動物園"},{"k":"record","zh":"1927 年在上野到淺草之間通車的地下鐵，被稱為「東洋第一條地下鐵」","en":"The subway that opened between Ueno and Asakusa in 1927 was billed as the first in the Orient.","ja":"1927年に上野～浅草間で開業した地下鉄は「東洋初の地下鉄」だった"},{"k":"history","zh":"1657 年明曆大火燒毀了將軍居城的天守，此後再也沒有重建","en":"The Great Fire of Meireki in 1657 destroyed the shogun's castle keep, which was never rebuilt.","ja":"1657年の明暦の大火で将軍の城の天守が焼け落ち、以後再建されることはなかった"},{"k":"legend","zh":"明曆大火別名「振袖火事」：傳說為超度亡故少女而焚燒的振袖被風捲起，引燃寺院","en":"The 1657 blaze is nicknamed the 'Long-Sleeves Fire', after a tale of a mourning kimono that flew up in flames.","ja":"明暦の大火の別名「振袖火事」は、供養で焼いた振袖が舞い上がり火事になった伝承から"},{"k":"history","zh":"1860 年大老井伊直弼在櫻田門外遭水戶浪士刺殺，當天下著不合時節的雪","en":"In 1860 chief minister Ii Naosuke was assassinated outside Sakurada Gate here on an unseasonably snowy day.","ja":"1860年、大老井伊直弼が桜田門外で水戸浪士らに暗殺された。その日は季節外れの雪だった"},{"k":"nature","zh":"南方的小笠原群島生物獨自演化，有「東洋加拉巴哥」之稱，2011 年列世界自然遺產","en":"Its Ogasawara Islands, the 'Galápagos of the Orient', became a World Natural Heritage site in 2011.","ja":"小笠原諸島は独自の進化から「東洋のガラパゴス」と呼ばれ、2011年に世界自然遺産になった"},{"k":"nature","zh":"2013 年起西之島噴發長出新陸地，熔岩最後把原本的舊島整個吞沒","en":"Since 2013, eruptions at Nishinoshima built new land whose lava eventually buried the original island.","ja":"2013年からの噴火で西之島は拡大し、溶岩がもとの島をすっかり覆ってしまった"},{"k":"nature","zh":"最高峰雲取山標高 2017 公尺，2017 年因數字和年份相同掀起紀念登山熱","en":"Its highest peak, Mt. Kumotori, is 2,017 m tall, so 2017 brought a rush of commemorative climbs.","ja":"最高峰の雲取山は標高2017m。2017年は西暦と同じ数字で記念登山が人気に"},{"k":"brand","zh":"索尼的前身 1946 年創業時，借用日本橋百貨公司白木屋三樓的一個房間","en":"Sony's predecessor started in 1946 in a single room on the third floor of the Shirokiya store in Nihonbashi.","ja":"ソニーの前身は1946年、日本橋のデパート白木屋の3階の一室で創業した"},{"k":"food","zh":"親子丼的發祥店是人形町的雞肉料理老店「玉ひで」，明治中期由老闆娘想出來","en":"Oyakodon was born at Tamahide, an old chicken restaurant in Ningyōchō, in the 1890s.","ja":"親子丼の発祥は人形町の鶏料理店「玉ひで」で、明治中期に5代目の妻が考案した"},{"k":"food","zh":"佃煮的名稱來自佃島，那裡的漁民是德川家康從大阪佃村找來的","en":"Tsukudani is named after Tsukudajima, settled by fishermen Tokugawa Ieyasu brought from Tsukuda near Osaka.","ja":"佃煮の名は佃島から。そこの漁民は徳川家康が摂津国佃村から呼び寄せた人々"},{"k":"legend","zh":"大手町有平將門的首塚，傳說他的首級從京城飛回來，因此曾有人供奉青蛙（諧音「回來」）","en":"Ōtemachi holds the mound of Taira no Masakado's head, said to have flown back here from Kyoto.","ja":"大手町の将門塚には、京から飛んで帰ったという平将門の首が祀られ、「帰る」にかけた蛙が供えられた"},{"k":"legend","zh":"《東海道四谷怪談》的女鬼阿岩，在四谷左門町有兩座「於岩稻荷」隔著馬路相對","en":"Oiwa, the ghost of Yotsuya Kaidan, is honored by two Oiwa Inari shrines facing each other in Yotsuya.","ja":"『東海道四谷怪談』のお岩を祀る於岩稲荷が、四谷左門町に道を挟んで二つ並ぶ"}],
"JP-14":[{"k":"symbol","zh":"縣花是花朵碩大、香氣濃郁的山百合","en":"Its prefectural flower is the golden-rayed lily, with large, fragrant blooms.","ja":"県の花は、大きな花と強い香りのヤマユリ"},{"k":"work","zh":"《新世紀福音戰士》裡的「第3新東京市」，設定在這裡的箱根","en":"Tokyo-3, the city in Neon Genesis Evangelion, is set in Hakone here.","ja":"『エヴァンゲリオン』の第3新東京市は、箱根にある設定"},{"k":"work","zh":"《灌籃高手》片頭出現的平交道，就在江之電鎌倉高校前站旁","en":"The railroad crossing in Slam Dunk's opening is next to Kamakura-Kōkōmae Station on the Enoden line.","ja":"『SLAM DUNK』のOPに出る踏切は、江ノ電・鎌倉高校前駅のそば"},{"k":"sport","zh":"職棒 DeNA 海灣之星和 J 聯盟川崎前鋒都以這裡為主場","en":"Pro baseball's DeNA BayStars and soccer's Kawasaki Frontale are both based here.","ja":"プロ野球DeNAとJリーグ川崎フロンターレの本拠地"},{"k":"festival","zh":"鶴岡八幡宮的「流鏑馬」：身穿武士裝束的射手在疾馳的馬上射靶","en":"At Tsurugaoka Hachimangū's yabusame, archers in samurai dress shoot targets from galloping horses.","ja":"鶴岡八幡宮の流鏑馬では、武士装束の射手が疾走する馬上から的を射る"},{"k":"people","zh":"南方之星主唱桑田佳祐出身茅崎，常在歌裡唱湘南的海","en":"Southern All Stars frontman Keisuke Kuwata is from Chigasaki and often sings about the Shōnan coast.","ja":"サザンオールスターズの桑田佳祐は茅ヶ崎市出身で、湘南の海をよく歌う"},{"k":"record","zh":"全國唯一擁有三座政令指定都市的縣","en":"It is the only prefecture with three government-designated major cities.","ja":"政令指定都市が3つある唯一の県"},{"k":"record","zh":"1869 年，日本第一支冰淇淋「あいすくりん」在這裡的馬車道開賣","en":"Japan's first ice cream, 'aisukurin', went on sale on Bashamichi street here in 1869.","ja":"1869年、ここの馬車道で日本初のアイスクリーム「あいすくりん」が売られた"},{"k":"people","zh":"許多小學裡背柴邊走邊讀書銅像的主角二宮尊德，出生在小田原的栢山","en":"Ninomiya Sontoku, the boy reading while hauling firewood in countless school statues, was born in Odawara.","ja":"薪を背負って本を読む像で知られる二宮尊徳は、小田原の栢山の生まれ"},{"k":"people","zh":"「歌謠界女王」美空雲雀出身這裡的磯子，死後成為首位獲國民榮譽賞的女性","en":"Hibari Misora, queen of Japanese pop, was born in Isogo here and was the first woman given the People's Honour Award.","ja":"「歌謡界の女王」美空ひばりは磯子区の出身で、没後に女性初の国民栄誉賞を受けた"},{"k":"sport","zh":"2002 年世界盃足球賽冠軍戰在這裡的日產體育場舉行","en":"The 2002 FIFA World Cup final was played at Nissan Stadium here.","ja":"2002年サッカーW杯の決勝戦は、ここの日産スタジアムで行われた"},{"k":"sport","zh":"箱根驛傳第 5 區爬山路段落差 864 公尺，在這裡跑出壓倒性成績的人被稱為「山之神」","en":"Leg 5 of the Hakone Ekiden climbs 864 m here; its dominant runners earn the nickname 'God of the Mountain'.","ja":"箱根駅伝5区は標高差864mの山上り。ここで圧倒的に速い選手は「山の神」と呼ばれる"},{"k":"work","zh":"吉卜力《來自紅花坂》的舞台是 1963 年的這座港都，女主角每天早上升起信號旗","en":"Ghibli's 'From Up on Poppy Hill' is set in a port city here in 1963; the heroine raises signal flags every morning.","ja":"ジブリ『コクリコ坂から』は1963年のこの港町が舞台で、主人公は毎朝信号旗を揚げる"},{"k":"work","zh":"是枝裕和電影《海街日記》裡，三姊妹接來同父異母的妹妹，一起住在鎌倉","en":"In Kore-eda's 'Our Little Sister', three sisters take in their half-sister to live with them in Kamakura.","ja":"是枝裕和監督の映画『海街diary』では、三姉妹が異母妹を迎えて鎌倉で暮らす"},{"k":"festival","zh":"川崎的「かなまら祭」抬著陽具造型的神轎，據說源自江戶時代遊女祈求遠離性病","en":"Kawasaki's Kanamara Matsuri parades phallic shrines, said to stem from courtesans' prayers against disease.","ja":"川崎の「かなまら祭」は、江戸時代の遊女が性病除けを願った祭りが起源とされる"},{"k":"life","zh":"江戶時代的百姓流行組團參拜大山，落語裡也有描寫這趟旅程鬧劇的段子","en":"Edo commoners loved group pilgrimages to Mt. Ōyama here; a classic rakugo tale pokes fun at one such trip.","ja":"江戸の庶民は講を組んで大山へ参った。落語『大山詣り』はその道中の騒動を描く"},{"k":"origin","zh":"「湘南」一名據說是借中國湘江以南的勝景，來比喻這一帶海岸","en":"The name Shōnan is said to borrow the scenic land south of China's Xiang River to praise this coast.","ja":"「湘南」の名は、中国・湘江の南の景勝地になぞらえたものとされる"},{"k":"legend","zh":"傳說藤原鎌足在這裡埋下一把鐮刀，「鎌倉」因此得名","en":"Legend says Kamakura was named after Fujiwara no Kamatari buried his sickle (kama) there.","ja":"藤原鎌足が鎌を埋めた地だから「鎌倉」と名付いた、という伝説がある"},{"k":"brand","zh":"1870 年美國人科普蘭在山手開設的春谷啤酒廠，是麒麟啤酒的源頭","en":"Spring Valley Brewery, opened in 1870 by American William Copeland, is the origin of Kirin beer.","ja":"1870年にコープランドが山手に開いたスプリング・バレー・ブルワリーは、キリンビールの源流"},{"k":"food","zh":"日式番茄醬炒麵「拿坡里義大利麵」、焗飯和布丁百匯，都誕生於這裡的新格蘭飯店","en":"Spaghetti Napolitan, doria and pudding à la mode all came out of the Hotel New Grand's kitchen here.","ja":"ナポリタン、ドリア、プリン・ア・ラ・モードは、ホテルニューグランドの厨房から生まれた"},{"k":"food","zh":"豚骨醬油湯配三片大海苔的「家系拉麵」，源頭是 1974 年在磯子開業的吉村家","en":"Iekei ramen—pork-bone soy broth with three big sheets of nori—traces back to Yoshimuraya, opened here in 1974.","ja":"豚骨醤油に大判の海苔3枚が定番の「家系ラーメン」は、1974年開業の吉村家が源流"},{"k":"food","zh":"大涌谷用溫泉蒸氣煮的「黑蛋」，號稱吃一顆能延壽七年","en":"Ōwakudani's hot-spring 'black eggs' are said to add seven years to your life.","ja":"大涌谷の「黒たまご」は、1個食べると寿命が7年延びるといわれる"},{"k":"origin","zh":"大涌谷原本叫「地獄谷」，1873 年明治天皇來訪時才改成現名","en":"Ōwakudani was called 'Hell Valley' until it was renamed for Emperor Meiji's visit in 1873.","ja":"大涌谷はかつて「地獄谷」と呼ばれ、1873年の明治天皇の行幸に際して改名された"},{"k":"history","zh":"1862 年薩摩藩行列砍殺英國人的「生麥事件」，引爆了隔年的薩英戰爭","en":"In the 1862 Namamugi Incident, Satsuma retainers killed a British merchant, sparking the Anglo-Satsuma War.","ja":"1862年、薩摩藩の行列が英国人を殺傷した生麦事件は、翌年の薩英戦争の引き金となった"},{"k":"history","zh":"1854 年《日美和親條約》在這裡的小漁村簽訂，地點就在今天的縣廳附近","en":"Japan and the US signed their 1854 treaty of amity in a fishing village here, near today's prefectural office.","ja":"1854年の日米和親条約は、現在の県庁付近にあった応接所で調印された"},{"k":"nature","zh":"蘆之湖約在 3100 年前形成：神山崩塌的土石堵住了破火山口裡的早川","en":"Lake Ashi formed about 3,100 years ago when a collapse of Mt. Kami dammed a river inside the Hakone caldera.","ja":"芦ノ湖は約3100年前、神山の山体崩壊がカルデラ内の早川をせき止めてできた"},{"k":"legend","zh":"傳說蘆之湖的九頭龍作亂害人，被僧人萬卷降伏後反成守護神","en":"Legend says a nine-headed dragon terrorized Lake Ashi until the monk Mangan tamed it into a guardian god.","ja":"芦ノ湖で人々を苦しめた九頭龍は、万巻上人に調伏されて守護神として祀られた"},{"k":"history","zh":"鶴岡八幡宮的大銀杏相傳是公曉埋伏暗殺源實朝之處，2010 年被強風吹倒","en":"Tsurugaoka Hachimangū's great ginkgo, where legend says Sanetomo's assassin hid, was blown down in 2010.","ja":"鶴岡八幡宮の大銀杏は公暁が隠れて実朝を襲ったと伝わる木で、2010年に強風で倒れた"}],
"JP-15":[{"k":"symbol","zh":"縣樹是在大雪中也能開花的「雪椿」","en":"Its prefectural tree is the snow camellia, which blooms despite heavy snow.","ja":"県の木は、雪に耐えて咲くユキツバキ"},{"k":"people","zh":"策劃偷襲珍珠港的聯合艦隊司令長官山本五十六出身長岡","en":"Admiral Isoroku Yamamoto, who planned the Pearl Harbor attack, was born in Nagaoka.","ja":"真珠湾攻撃を立案した連合艦隊司令長官・山本五十六は長岡出身"},{"k":"work","zh":"川端康成《雪國》開頭「穿過縣界長長的隧道」，舞台就在湯澤","en":"Kawabata's Snow Country, which opens with a train leaving a long tunnel into snow, is set in Yuzawa here.","ja":"川端康成『雪国』の「国境の長いトンネルを抜けると」の舞台は湯沢町"},{"k":"festival","zh":"長岡煙火大會的「鳳凰」煙火，是為祈求 2004 年地震後的復興而開始施放","en":"Nagaoka's fireworks feature 'Phoenix', launched to pray for recovery after the 2004 earthquake.","ja":"長岡まつり大花火大会の「フェニックス」は、中越地震からの復興を願って始まった"},{"k":"festival","zh":"名字裡有「富士」的富士搖滾音樂祭，1999 年起其實都在這裡的苗場舉辦","en":"Despite its name, the Fuji Rock Festival has been held at Naeba here since 1999.","ja":"名前に「富士」とつくフジロックは、1999年からここの苗場で開かれている"},{"k":"record","zh":"1888 年人口約 166 萬，是當時全國人口最多的縣，東京只排第 4","en":"In 1888, with about 1.66 million people, it was Japan's most populous prefecture; Tokyo ranked only fourth.","ja":"1888年には人口約166万人で全国最多。東京は4位だった"},{"k":"life","zh":"在地速食「義大利麵（イタリアン）」其實是淋上番茄肉醬的炒麵","en":"The local fast food called 'Italian' is actually yakisoba topped with tomato meat sauce.","ja":"ご当地ファストフード「イタリアン」の正体は、ミートソースをかけた焼きそば"},{"k":"people","zh":"和村童拍手毬玩到天黑的禪僧良寬，出生在出雲崎","en":"Ryōkan, the Zen monk famed for playing temari ball with village kids, was born in Izumozaki here.","ja":"子どもたちと手毬をついて遊んだ禅僧・良寛は、出雲崎の生まれ"},{"k":"people","zh":"寫下《墮落論》的無賴派作家坂口安吾，出生在縣廳所在地","en":"Sakaguchi Ango, the Buraiha author of 'Discourse on Decadence', was born in the prefectural capital.","ja":"『堕落論』で知られる無頼派作家・坂口安吾は、県庁所在地の生まれ"},{"k":"history","zh":"戰敗的長岡藩把救濟來的一百俵米賣掉辦學校，留下「米百俵」的故事","en":"Defeated Nagaoka domain sold 100 bales of relief rice to found a school: the famed 'Kome Hyappyō' story.","ja":"敗戦後の長岡藩は救援の米百俵を食べずに売り、学校を建てた。「米百俵」の逸話である"},{"k":"history","zh":"長岡藩家老河井繼之助在戊辰戰爭時，擁有全日本僅 3 挺加特林機槍中的 2 挺","en":"Nagaoka's Kawai Tsugunosuke held two of the only three Gatling guns in Japan during the Boshin War.","ja":"長岡藩家老・河井継之助は、当時日本に3門しかないガトリング砲のうち2門を持っていた"},{"k":"festival","zh":"1950 年開辦的十日町雪祭被視為現代雪祭的發祥，比札幌雪祭還早兩週","en":"Tōkamachi's Snow Festival, first held in 1950, is called the birthplace of modern snow festivals.","ja":"1950年に始まった十日町雪まつりは「現代雪まつり発祥の地」といわれる"},{"k":"festival","zh":"佐渡的「鬼太鼓」挨家挨戶表演祈福驅邪，約 120 個聚落各有不同的跳法","en":"Sado's Ondeko demon-drum dance goes house to house; about 120 villages each have their own style.","ja":"佐渡の鬼太鼓は家々を回って舞い、約120の集落ごとに形が違う"},{"k":"festival","zh":"小千谷片貝祭施放直徑約 120 公分、重 420 公斤的「正四尺玉」煙火","en":"Katakai Festival in Ojiya fires the 'Shō-yonshakudama', a shell about 120 cm wide weighing 420 kg.","ja":"小千谷の片貝まつりでは、直径約120cm・重さ420kgの「正四尺玉」が打ち上がる"},{"k":"life","zh":"片貝的居民在出生、結婚、成年等人生大事時，會奉納煙火給淺原神社","en":"In Katakai, locals offer fireworks to Asahara Shrine to mark births, weddings and other life milestones.","ja":"片貝では誕生・結婚・成人など人生の節目ごとに、浅原神社へ花火を奉納する"},{"k":"life","zh":"上越高田商店街屋簷延伸成防雪走廊「雁木」，總長度號稱日本第一","en":"Takada in Jōetsu has Japan's longest 'gangi', roofed walkways that keep shopping streets clear of snow.","ja":"上越市高田の雪よけのひさし「雁木」は、総延長が日本一とされる"},{"k":"work","zh":"鈴木牧之的《北越雪譜》介紹雪國生活，江戶後期賣出 700 部以上成為暢銷書","en":"Suzuki Bokushi's 1837 'Hokuetsu Seppu', a guide to snow-country life, became a bestseller.","ja":"鈴木牧之の『北越雪譜』は雪国の暮らしを描き、700部を超えるベストセラーになった"},{"k":"origin","zh":"海岸絕壁「親不知」，名字來自路太險，連父母都顧不了孩子","en":"The Oyashirazu cliffs were named because the path was so perilous parents couldn't look after their children.","ja":"断崖の難所「親不知」は、親も子を顧みられないほど険しい道だったことが名の由来"},{"k":"legend","zh":"傳說平賴盛的妻子帶著兩歲孩子從京都來尋夫，孩子在親不知被浪捲走","en":"Legend says Taira no Yorimori's wife, travelling from Kyoto to find him, lost her toddler to the waves at Oyashirazu.","ja":"平頼盛を慕って都から来た妻が、親不知で2歳の子を波にさらわれたという伝説がある"},{"k":"legend","zh":"傳說鬼王酒吞童子生在這裡，原是國上寺的美少年，因燒掉情書被怨念化為鬼","en":"Legend says the oni king Shuten-dōji was born here, a handsome temple boy turned demon after burning love letters.","ja":"酒呑童子は国上寺の美少年で、恋文を焼いたため女たちの怨念で鬼になったと伝わる"},{"k":"legend","zh":"成語「送鹽給敵人」，出自上杉謙信送鹽救濟宿敵武田領民的故事","en":"The idiom 'sending salt to your enemy' comes from a tale of Uesugi Kenshin sending salt to rival Takeda's people.","ja":"「敵に塩を送る」は、上杉謙信が武田領の民に塩を送ったという逸話に由来する"},{"k":"food","zh":"把炸豬排浸過甜鹹醬油汁再鋪上飯的「醬汁豬排丼」，1945 年在縣廳所在地誕生","en":"Tare-katsudon—cutlets dipped in sweet soy sauce over rice—was devised in the prefectural capital in 1945.","ja":"醤油ダレにくぐらせたカツをのせる「タレカツ丼」は、1945年に県庁所在地で考案された"},{"k":"food","zh":"用竹葉包住的「笹糰子」，據說原本是戰國時代的攜帶式保存食","en":"Sasa-dango, dumplings wrapped in bamboo leaves, reportedly began as a portable ration in the Warring States era.","ja":"笹の葉で包んだ「笹団子」は、戦国時代の携行保存食として生まれたとされる"},{"k":"brand","zh":"零食大廠 Bourbon 1924 年在柏崎創立，起因是關東大地震讓地方買不到點心","en":"Snack maker Bourbon was founded in Kashiwazaki in 1924 after the Great Kantō quake cut off sweets supplies.","ja":"菓子メーカーのブルボンは、関東大震災で菓子が届かなくなったのを機に1924年柏崎で創業"},{"k":"symbol","zh":"阿賀野市瓢湖每年冬天湧入數千隻天鵝，1954 年這裡首度在日本成功餵食野生天鵝","en":"Lake Hyōko, where thousands of swans winter, saw Japan's first successful feeding of wild swans in 1954.","ja":"白鳥が数千羽飛来する瓢湖では、1954年に日本で初めて野生の白鳥の餌付けに成功した"},{"k":"nature","zh":"清津峽有壯觀的柱狀節理岩壁，與黑部峽谷、大杉峽谷並稱日本三大峽谷","en":"Kiyotsu Gorge, walled by columnar-jointed cliffs, is one of Japan's three great gorges.","ja":"柱状節理の断崖が続く清津峡は、日本三大峡谷の一つ"},{"k":"work","zh":"清津峽的步道隧道 2018 年被建築師馬岩松改造成倒映峽谷的藝術作品","en":"In 2018 architect Ma Yansong turned the Kiyotsu Gorge tunnel into an artwork that mirrors the gorge.","ja":"清津峡渓谷トンネルは2018年、建築家マ・ヤンソンの手で峡谷を映すアート作品になった"}],
"JP-16":[{"k":"symbol","zh":"縣樹是立山山區的杉樹「立山杉」","en":"Its prefectural tree is the Tateyama cedar.","ja":"県の木はタテヤマスギ"},{"k":"work","zh":"細田守動畫《狼的孩子雨和雪》的鄉間場景，以他的故鄉上市町為原型","en":"The countryside in Mamoru Hosoda's Wolf Children is modeled on his hometown, Kamiichi.","ja":"細田守監督『おおかみこどもの雨と雪』の田舎は、監督の故郷・上市町がモデル"},{"k":"work","zh":"電影《劍岳：點之記》描寫明治時代的測量隊挑戰攀登劍岳","en":"The film Tsurugidake chronicles a Meiji-era survey team's climb of Mt. Tsurugi here.","ja":"映画『劔岳 点の記』は、明治の測量隊が劔岳に挑む姿を描く"},{"k":"festival","zh":"越中八尾的「風之盆」：人們在胡弓聲中，三天三夜靜靜跳舞穿過街巷","en":"During Owara Kaze-no-Bon in Yatsuo, dancers weave through the streets to the kokyū fiddle for three days and nights.","ja":"越中八尾の「おわら風の盆」では、胡弓の音色にのせて三日三晩踊り歩く"},{"k":"people","zh":"《忍者哈特利》的作者藤子不二雄Ⓐ出身冰見","en":"Fujiko Fujio Ⓐ, creator of Ninja Hattori-kun, was born in Himi.","ja":"『忍者ハットリくん』の藤子不二雄Ⓐは氷見市出身"},{"k":"people","zh":"讀賣新聞社主、被稱為「職棒之父」的正力松太郎出身這裡","en":"Matsutarō Shōriki, the Yomiuri newspaper owner called the father of Japanese pro baseball, was born here.","ja":"読売新聞社主で「プロ野球の父」と呼ばれる正力松太郎の出身地"},{"k":"record","zh":"稱名瀑布落差約 350 公尺，是日本落差最大的瀑布","en":"Shōmyō Falls drops about 350 m, the tallest waterfall in Japan.","ja":"称名滝は落差約350mで日本一"},{"k":"life","zh":"春天在魚津海岸可以看到海市蜃樓，對岸的景物彷彿浮在海上","en":"In spring, mirages can appear off the Uozu coast, with distant shores seeming to float above the sea.","ja":"春の魚津の海岸では蜃気楼が現れ、対岸の景色が海上に浮かんで見える"},{"k":"people","zh":"世界首位萃取出荷爾蒙「腎上腺素」結晶的高峰讓吉，出生在高岡","en":"Takamine Jōkichi, the first to crystallize adrenaline, was born in Takaoka here.","ja":"世界で初めてアドレナリンの結晶化に成功した高峰譲吉は、高岡の生まれ"},{"k":"history","zh":"1912 年送給華盛頓波多馬克河畔的櫻花，這裡出身的高峰讓吉也出力促成","en":"Takamine Jōkichi, a native here, helped make Japan's 1912 gift of cherry trees to Washington's Potomac happen.","ja":"1912年にワシントンのポトマック河畔へ贈られた桜は、ここ出身の高峰譲吉も実現に尽力した"},{"k":"people","zh":"匿名捐建東京大學安田講堂的財閥創始人安田善次郎，出身這裡的下級武士家庭","en":"Yasuda Zenjirō, the anonymous donor behind the University of Tokyo's Yasuda Auditorium, was born here.","ja":"東大安田講堂を匿名で寄付した安田善次郎は、ここの下級武士の家の出身"},{"k":"people","zh":"「水泥大王」淺野總一郎出身冰見，鶴見線的淺野站就是以他命名","en":"'Cement King' Asano Sōichirō, namesake of Asano Station, was born in Himi here.","ja":"「セメント王」浅野総一郎は氷見の出身で、鶴見線の浅野駅は彼にちなむ"},{"k":"people","zh":"以上班族身分拿下 2002 年諾貝爾化學獎的田中耕一，生於縣廳所在地","en":"Tanaka Kōichi, a company engineer who won the 2002 Nobel Prize in Chemistry, was born in the prefectural capital.","ja":"会社員のまま2002年ノーベル化学賞を受けた田中耕一は、県庁所在地の生まれ"},{"k":"festival","zh":"高岡御車山祭的花車，相傳源自豐臣秀吉迎接天皇時使用的御所車","en":"Takaoka's Mikurumayama floats are said to descend from an imperial carriage Toyotomi Hideyoshi used.","ja":"高岡御車山祭の山車は、豊臣秀吉が天皇を迎えた際の御所車が起源と伝わる"},{"k":"festival","zh":"魚津「たてもん祭」把燈籠掛成高約 16 公尺的三角帆船狀山車，祈求大漁","en":"At Uozu's Tatemon Festival, sail-shaped lantern towers about 16 m tall are hauled to pray for big catches.","ja":"魚津の「たてもん祭り」では、提灯を三角に吊るした高さ約16mの万燈を曳き大漁を祈る"},{"k":"festival","zh":"縣廳所在地從 1955 年起每年春天舉辦全日本チンドン（街頭廣告樂隊）大賽","en":"Since 1955 the prefectural capital has hosted the All-Japan Chindon Contest for street-advertising bands each spring.","ja":"県庁所在地では1955年から毎春、全日本チンドンコンクールが開かれている"},{"k":"symbol","zh":"立山高處住著冰河時期遺留下來的雷鳥，夏天褐色、冬天變成全白","en":"Tateyama's heights are home to the rock ptarmigan, an Ice Age relic that turns from brown to pure white in winter.","ja":"立山の高山に住むライチョウは氷河期の生き残りで、夏は褐色、冬は純白になる"},{"k":"symbol","zh":"砺波的鬱金香試驗場 1951 年差點被裁撤，據說盟軍總部官員看到花海後撤回決定","en":"Tonami's tulip station nearly closed in 1951, until GHQ officials saw the blooms and reversed the plan.","ja":"砺波のチューリップ試験場は1951年に廃止されかけたが、咲く花を見たGHQ関係者が撤回させたという"},{"k":"food","zh":"縣廳所在地有種湯頭漆黑的醬油拉麵，戰後是為了替重建工人補充鹽分而生","en":"A jet-black, very salty soy ramen was born in the capital here after the war to replenish rebuilding workers' salt.","ja":"県庁所在地の真っ黒な醤油ラーメンは、戦後復興の労働者の塩分補給のため生まれた"},{"k":"history","zh":"1584 年佐佐成政據說在寒冬翻山越嶺去找德川家康，史稱「さらさら越」","en":"In 1584 Sassa Narimasa reportedly crossed snowbound mountains in midwinter to urge Tokugawa Ieyasu to fight on.","ja":"1584年、佐々成政は厳冬の山を越えて家康に再挙を促しに行ったとされる。「さらさら越え」である"},{"k":"history","zh":"萬葉歌人大伴家持曾在這裡當了五年國守，期間詠出 223 首和歌","en":"Poet Ōtomo no Yakamochi served five years as governor here and wrote 223 waka during his stay.","ja":"大伴家持は国守としてここに5年赴任し、在任中に223首の歌を詠んだ"},{"k":"legend","zh":"傳說 701 年少年佐伯有賴追著一隻白鷹進山，遇見阿彌陀如來，開啟了立山信仰","en":"Legend says in 701 Saeki Arifuyu chased a white hawk into the mountains, met Amida Buddha and founded Tateyama worship.","ja":"701年、佐伯有頼が白鷹を追って山に入り阿弥陀如来に出会い、立山を開いたと伝わる"},{"k":"legend","zh":"立山信仰把山上的地獄谷視為地獄；不能登山的女性改走鋪白布的橋祈求往生","en":"Tateyama faith saw its Jigokudani as hell; women, barred from the peak, crossed a cloth-draped bridge to be saved.","ja":"立山の地獄谷は地獄に見立てられ、登山できない女性は白布を敷いた布橋を渡り往生を願った"},{"k":"nature","zh":"這裡的海灣深處超過 1000 公尺，和 3000 公尺級的立山連峰高低落差約 4000 公尺","en":"Its bay plunges over 1,000 m; with the 3,000 m Tateyama peaks, the relief spans about 4,000 m.","ja":"湾の最深部は1000mを超え、3000m級の立山連峰との高低差は約4000mに及ぶ"},{"k":"nature","zh":"黑部峽谷是日本最深的 V 字峽谷，從宇奈月溫泉可搭小火車深入","en":"Kurobe Gorge is Japan's deepest V-shaped gorge, reached by a little trolley train from Unazuki Onsen.","ja":"黒部峡谷は日本一深いV字峡谷で、宇奈月温泉からトロッコ電車で入る"},{"k":"life","zh":"走遍全國的賣藥郎，會送客人紙氣球和錦繪版畫當贈品","en":"Travelling medicine peddlers from here handed out paper balloons and woodblock prints as freebies.","ja":"全国を回った売薬さんは、紙風船や売薬版画をおまけとして配った"},{"k":"life","zh":"砺波平原的農家零星散布，每戶都被稱為「カイニョ」的防風林包圍","en":"On the Tonami Plain, scattered farmhouses each sit inside their own windbreak grove called 'kainyo'.","ja":"砺波平野では、カイニョと呼ぶ屋敷林に囲まれた家々が点在する散居村が広がる"},{"k":"brand","zh":"做出《Angel Beats!》《SHIROBAKO》的動畫公司 P.A.WORKS，總部設在南砺","en":"Anime studio P.A.Works, maker of 'Angel Beats!' and 'Shirobako', is based in Nantō here.","ja":"『Angel Beats!』『SHIROBAKO』のアニメ会社P.A.WORKSは南砺市に本社を置く"},{"k":"history","zh":"高岡的國寶瑞龍寺，是前田利常為兄長前田利長蓋的菩提寺","en":"Zuiryū-ji, a National Treasure in Takaoka, was made by Maeda Toshitsune as the memorial temple of his brother Toshinaga.","ja":"国宝・瑞龍寺は、前田利常が兄・利長の菩提寺として高岡に整えた寺"},{"k":"life","zh":"銅造的高岡大佛，據說被與謝野晶子評為「比鎌倉大佛更俊美」","en":"Poet Yosano Akiko reputedly called Takaoka's bronze Great Buddha more handsome than Kamakura's.","ja":"高岡大仏は、与謝野晶子が「鎌倉の大仏より一段と美男」と評したと伝わる"}],
"JP-17":[{"k":"symbol","zh":"縣花是開在白山高處的黑百合","en":"Its prefectural flower is the black lily, an alpine bloom of Mt. Haku.","ja":"県の花は白山に咲く高山植物クロユリ"},{"k":"symbol","zh":"縣鳥是猛禽「金鵰」（イヌワシ）","en":"Its prefectural bird is the golden eagle.","ja":"県の鳥はイヌワシ"},{"k":"festival","zh":"能登的「切子祭」扛著點燈的巨大方形燈籠遊行，有的高超過 10 公尺","en":"In Noto's Kiriko festivals, people carry giant illuminated lantern towers, some over 10 m tall.","ja":"能登のキリコ祭りでは、高さ10mを超すものもある巨大な灯籠キリコを担ぐ"},{"k":"people","zh":"以怪奇幻想小說《高野聖》聞名的泉鏡花出身縣廳所在地","en":"Izumi Kyōka, author of the eerie fantasy The Holy Man of Mount Kōya, was born in the prefectural capital.","ja":"幻想小説『高野聖』の泉鏡花は県庁所在地の出身"},{"k":"work","zh":"湯涌溫泉的「燈籠祭」，是 2011 年把動畫《花開伊呂波》裡虛構的祭典搬到現實","en":"Yuwaku Onsen's Bonbori Festival brought a fictional festival from the anime Hanasaku Iroha to life in 2011.","ja":"湯涌温泉の「ぼんぼり祭り」は、アニメ『花咲くいろは』の架空の祭りを2011年に現実にしたもの"},{"k":"origin","zh":"縣廳所在地的名字，傳說來自農夫在泉水邊洗山芋時洗出了砂金","en":"Legend says the capital's name comes from a spring where a farmer washing yams found gold dust.","ja":"県庁所在地の名は、芋掘り藤五郎が芋を洗った泉から砂金が出た伝説に由来"},{"k":"sport","zh":"2025 年以入門 13 場所的史上最快速度晉升橫綱的大之里，出身津幡町","en":"Ōnosato, who became yokozuna in 2025 just 13 tournaments after his debut, a record, is from Tsubata.","ja":"初土俵から史上最速の13場所で2025年に横綱昇進した大の里は津幡町出身"},{"k":"life","zh":"縣廳所在地每戶買和菓子的支出，長年是全國第一","en":"Households in the capital spend more on Japanese sweets than anywhere else in Japan.","ja":"県庁所在地は1世帯あたりの和菓子支出が全国1位の常連"},{"k":"people","zh":"建造臺灣烏山頭水庫與嘉南大圳的八田與一，出身縣廳所在地","en":"Hatta Yoichi, builder of Taiwan's Wushantou Dam and Chianan irrigation canals, was born in the prefectural capital.","ja":"台湾の烏山頭ダムと嘉南大圳を築いた八田與一は、県庁所在地の出身"},{"k":"history","zh":"這裡出身的八田與一忌日 5 月 8 日，臺灣烏山頭水庫每年都為他舉行追思會","en":"Every May 8, a memorial for Hatta Yoichi, a native here, is held at Taiwan's Wushantou Dam.","ja":"この地出身の八田與一の命日5月8日には、台湾の烏山頭ダムで毎年慰霊祭が開かれる"},{"k":"people","zh":"詩人室生犀星生於縣廳所在地，1918 年的《抒情小曲集》為詩壇帶來新風","en":"Poet Murō Saisei, born in the prefectural capital, refreshed Japanese verse with his 1918 lyric collections.","ja":"県庁所在地生まれの室生犀星は、1918年の『抒情小曲集』で詩壇に新風を吹き込んだ"},{"k":"people","zh":"和島崎藤村、田山花袋並列自然主義大家的德田秋聲，生於縣廳所在地","en":"Tokuda Shūsei, a master of Japanese naturalist fiction, was born in the prefectural capital.","ja":"島崎藤村・田山花袋と並ぶ自然主義の大家・徳田秋声は、県庁所在地の生まれ"},{"k":"legend","zh":"藩主前田利常故意留長鼻毛裝傻，好讓幕府不起戒心","en":"Lord Maeda Toshitsune is said to have grown out his nose hair to look foolish and disarm the shogunate.","ja":"藩主・前田利常は幕府を油断させるため、わざと鼻毛を伸ばして愚か者を装ったという"},{"k":"sport","zh":"七尾出身的橫綱輪島，是第一位學生相撲出身的橫綱，也以本名當四股名","en":"Yokozuna Wajima from Nanao was the first college-sumo yokozuna and fought under his real name.","ja":"七尾出身の横綱・輪島は学生相撲出身初の横綱で、本名をしこ名にしていた"},{"k":"festival","zh":"名舟的「御陣乘太鼓」：1577 年村民戴樹皮面具、頂海草頭髮擊鼓，嚇退上杉軍","en":"Gojinjō Daiko recalls villagers in bark masks and seaweed hair drumming to drive off Uesugi's army in 1577.","ja":"御陣乗太鼓は1577年、樹皮の面と海藻の髪で仮装した村人が太鼓で上杉軍を退けた故事から"},{"k":"festival","zh":"能登宇出津的「暴祭」，夜裡把神轎丟進水中和熊熊火堆裡","en":"At Ushitsu's Abare Matsuri on Noto, portable shrines are flung into the water and into bonfires at night.","ja":"能登町宇出津の「あばれ祭」では、夜に神輿を水中や火の中へ放り込む"},{"k":"festival","zh":"奧能登的「あえのこと」把看不見的田神請回家，幫祂洗澡、端出大餐款待","en":"In Noto's Aenokoto rite, farmers welcome the blind rice-field god home with a bath and a feast.","ja":"奥能登の「あえのこと」では、目の不自由な田の神を家に迎え、風呂とごちそうでもてなす"},{"k":"origin","zh":"「兼六園」由松平定信命名，意思是兼具宏大、幽邃等名園的六種條件","en":"Kenroku-en means 'combining six', named by Matsudaira Sadanobu for six qualities of a perfect garden.","ja":"兼六園は松平定信の命名で、宏大・幽邃など庭園の六つの景観を兼ね備える意"},{"k":"life","zh":"每到冬天，兼六園的樹會用放射狀繩索吊住枝條防雪壓，稱為「雪吊」","en":"Each winter Kenroku-en's trees are braced with fans of rope, called yukitsuri, against heavy snow.","ja":"冬の兼六園では、雪の重みから枝を守る縄の「雪吊り」が風物詩"},{"k":"food","zh":"縣廳所在地的在地咖哩醬黑而濃，盛在不鏽鋼盤配豬排、高麗菜絲，用叉子吃","en":"The capital's local curry is thick and nearly black, served on a steel plate with a cutlet, cabbage and a fork.","ja":"県庁所在地のご当地カレーは黒く濃いルーをステンレス皿に盛り、カツとキャベツを添えフォークで食べる"},{"k":"food","zh":"蛋包飯上放炸魚的「ハントンライス」，名字取自匈牙利加上法語的鮪魚","en":"Hanton rice, omelette rice topped with fried fish, is named from 'Hungary' plus 'thon', French for tuna.","ja":"白身魚フライをのせたオムライス「ハントンライス」は、ハンガリーと仏語のマグロ（thon）から命名"},{"k":"food","zh":"能登的魚醬「いしる」用沙丁魚或魷魚內臟釀成，是日本三大魚醬之一","en":"Noto's ishiru fish sauce, made from sardines or squid guts, is one of Japan's three great fish sauces.","ja":"能登の魚醤「いしる」はイワシやイカの内臓で造り、日本三大魚醤の一つ"},{"k":"history","zh":"1488 年一向一揆推翻守護富樫政親，此後約 90 年被稱為「百姓擁有的國家」","en":"In 1488 Ikkō-ikki rebels toppled the governor here, beginning some 90 years as a 'country owned by peasants'.","ja":"1488年、一向一揆が守護富樫政親を倒し、約90年「百姓の持ちたる国」と呼ばれた"},{"k":"history","zh":"東京大學的「赤門」，原是這裡的藩主前田家為迎娶將軍之女而蓋的大門","en":"The University of Tokyo's Red Gate was built by this domain's Maeda lords to welcome a shogun's daughter.","ja":"東大の赤門は、ここの藩主前田家が将軍家の姫を迎えるために建てた御守殿門"},{"k":"brand","zh":"營建機械大廠小松製作所，起源是 1917 年為銅礦開設的小松鐵工所","en":"Construction-machinery giant Komatsu began in 1917 as an ironworks serving a copper mine in Komatsu here.","ja":"建機大手コマツは、1917年に遊泉寺銅山の機械を造る小松鉄工所として始まった"},{"k":"work","zh":"松本清張推理小說《零的焦點》以這裡和能登為舞台，電影高潮在能登金剛的斷崖","en":"Matsumoto Seichō's mystery 'Zero Focus' is set here and on Noto; the film climaxes on the Noto Kongō cliffs.","ja":"松本清張『ゼロの焦点』は県庁所在地と能登が舞台で、映画は能登金剛の断崖が山場"},{"k":"origin","zh":"珠洲的見附島，相傳是弘法大師從佐渡渡海而來時第一眼「看見」的島","en":"Suzu's Mitsukejima ('found island') is said to be the first thing Kūkai spotted when crossing over from Sado.","ja":"珠洲の見附島は、佐渡から渡った弘法大師が最初に見つけた島という伝説が名の由来"},{"k":"nature","zh":"外型像軍艦、被稱為「軍艦島」的見附島，在 2024 年地震中大片崩落","en":"Mitsukejima, nicknamed 'Battleship Island', lost much of its warship shape in the 2024 earthquake.","ja":"「軍艦島」とも呼ばれた見附島は、2024年の地震で大きく崩れ軍艦の姿を失った"},{"k":"record","zh":"尾山神社 1875 年完工的西洋風神門，屋頂上有日本現存最古老的避雷針","en":"Oyama Shrine's Western-style gate of 1875 carries Japan's oldest surviving lightning rod.","ja":"1875年完成の尾山神社神門の屋根には、現存する日本最古の避雷針がある"},{"k":"record","zh":"白山比咩神社是全日本 2000 多座白山神社的總本社","en":"Shirayama Hime Shrine is the head shrine of over 2,000 Hakusan shrines across Japan.","ja":"白山比咩神社は、全国2000社以上ある白山神社の総本社"},{"k":"life","zh":"輪島朝市據說從平安時代延續至今，與勝浦、宮川並列日本三大朝市","en":"Wajima's morning market, said to date back to the Heian era, is one of Japan's three great morning markets.","ja":"輪島朝市は平安時代から続くとされ、日本三大朝市の一つ"}],
"JP-18":[{"k":"symbol","zh":"縣花是寒冬時在越前海岸盛開的水仙","en":"Its prefectural flower is the narcissus, which blooms along the Echizen coast in winter.","ja":"県の花は、冬の越前海岸に咲くスイセン"},{"k":"symbol","zh":"縣鳥是冬天飛來過冬的斑點鶇（ツグミ）","en":"Its prefectural bird is the dusky thrush, a winter visitor.","ja":"県の鳥は冬鳥のツグミ"},{"k":"life","zh":"民間「都道府縣幸福度排行」中，連續多次拿下總合第一","en":"It has repeatedly ranked No. 1 overall in a private happiness ranking of Japan's prefectures.","ja":"民間の「都道府県幸福度ランキング」で、総合1位を何度も連続で獲得"},{"k":"people","zh":"演歌歌手五木宏出身美濱町","en":"Enka singer Hiroshi Itsuki was born in Mihama.","ja":"演歌歌手・五木ひろしは美浜町出身"},{"k":"work","zh":"漫畫《花牌情緣》中，主角的競技歌牌勁敵綿谷新來自這裡","en":"In the manga Chihayafuru, Arata Wataya, the heroine's karuta rival, is from here.","ja":"漫画『ちはやふる』で、千早のライバル・綿谷新はここの出身という設定"},{"k":"festival","zh":"勝山的「左義長祭」在街頭高台上敲「浮太鼓」，最後把松飾集中燒掉","en":"At Katsuyama's Sagichō festival, drummers play 'floating drums' on street towers, then the pine decorations are burned.","ja":"勝山左義長まつりでは櫓の上で浮き太鼓を打ち、最後に松飾りを集めて燃やす"},{"k":"origin","zh":"原本叫「北之庄」，江戶時代嫌「北」有敗北之意而改名","en":"Originally called Kitanoshō; it was renamed in the Edo period because 'kita' (north) evokes defeat.","ja":"もとは「北ノ庄」。「北」が敗北に通じるとして江戸時代に改名された"},{"k":"life","zh":"水羊羹在這裡是冬天窩在暖桌裡吃的點心","en":"Here, mizu-yōkan (soft red bean jelly) is a winter treat eaten under the kotatsu.","ja":"ここでは水ようかんは冬にこたつで食べるもの"},{"k":"people","zh":"繼體天皇即位前在這裡長大，被迎去繼承皇位時已經 58 歲","en":"Emperor Keitai grew up here and was 58 when he was summoned to take the throne in 507.","ja":"継体天皇はここで育ち、507年に58歳で迎えられて即位したと伝わる"},{"k":"people","zh":"幕末志士橋本左內 15 歲寫下自勉書《啟發錄》，25 歲死於安政大獄","en":"Hashimoto Sanai wrote his creed 'Keihatsuroku' at 15 and was executed at 25 in the Ansei Purge.","ja":"橋本左内は15歳で『啓発録』を著し、安政の大獄により25歳で刑死した"},{"k":"people","zh":"起草《五條御誓文》原案的由利公正是這裡的藩士，後來推動銀座磚造街","en":"Yuri Kimimasa, a samurai from here, drafted the Charter Oath and later pushed a brick rebuild of Ginza.","ja":"五箇条の御誓文の原案を書いた由利公正はここの藩士で、銀座煉瓦街も推進した"},{"k":"people","zh":"翻譯《解體新書》的杉田玄白，是若狹小濱藩的藩醫","en":"Sugita Genpaku, translator of the anatomy text 'Kaitai Shinsho', was physician to the Obama domain here.","ja":"『解体新書』の杉田玄白は、若狭小浜藩の藩医だった"},{"k":"people","zh":"以字典三部作《字統》《字訓》《字通》聞名的漢字學者白川靜，生於縣廳所在地","en":"Shirakawa Shizuka, the kanji scholar behind the dictionaries Jitō, Jikun and Jitsū, was born in the capital here.","ja":"字書三部作『字統』『字訓』『字通』の漢字学者・白川静は県庁所在地の生まれ"},{"k":"people","zh":"紫式部曾跟著擔任國司的父親，在這裡生活了約兩年","en":"Murasaki Shikibu spent about two years here when her father became provincial governor.","ja":"紫式部は国司となった父に従い、ここで約2年を過ごした"},{"k":"sport","zh":"1995 年世界體操錦標賽在這裡舉行，是首次在亞洲舉辦","en":"The 1995 World Gymnastics Championships were held here, the first ever staged in Asia.","ja":"1995年、アジア初となる世界体操選手権がここで開かれた"},{"k":"history","zh":"柴田勝家與妻子阿市戰敗後，1583 年在這裡的居城中一同自盡","en":"After defeat in 1583, Shibata Katsuie and his wife Oichi took their lives together in his castle here.","ja":"1583年、敗れた柴田勝家はお市の方とともにここの居城で自害した"},{"k":"history","zh":"1948 年這裡的大地震造成三千多人罹難，隔年日本因此新增「震度 7」","en":"A 1948 earthquake here killed over 3,700 people and led Japan to add the top 'shindo 7' intensity.","ja":"1948年にここで起きた大地震を受け、翌年気象台の震度階に「震度7」が加えられた"},{"k":"history","zh":"1471 年蓮如在吉崎建立道場，成為淨土真宗在北陸傳教的據點","en":"In 1471 Rennyo built Yoshizaki Gobō here, the base that spread Jōdo Shinshū across Hokuriku.","ja":"1471年、蓮如が吉崎御坊を建て、北陸の浄土真宗布教の拠点となった"},{"k":"festival","zh":"小濱的「送水」儀式，傳說水會在地下流到奈良東大寺二月堂的「取水」","en":"Obama's Omizu-okuri sends sacred water said to flow underground to Nara's Tōdai-ji for its Omizutori.","ja":"小浜の「お水送り」で鵜の瀬に流す水は、奈良東大寺二月堂の若狭井に届くとされる"},{"k":"festival","zh":"山車上載著巨大武者人偶的三國祭，與高岡御車山祭、七尾青柏祭並稱北陸三大祭","en":"The Mikuni Festival, its floats topped with giant warrior dolls, is one of Hokuriku's three great festivals.","ja":"武者人形の山車が練る三国祭は、高岡御車山祭・七尾青柏祭と並ぶ北陸三大祭"},{"k":"origin","zh":"敦賀古名「角鹿」，傳說來自一位額頭長角、乘船漂到這裡的異國王子","en":"Tsuruga was once 'Tsunuga', said to be named after a horned foreign prince who landed here by boat.","ja":"敦賀の古名「角鹿」は、額に角のある都怒我阿羅斯等が船で来着した伝説に由来"},{"k":"legend","zh":"小濱流傳「八百比丘尼」：少女吃了人魚肉後青春不老，活到八百歲","en":"Obama's legend tells of a girl who ate mermaid flesh, stopped aging and lived to 800.","ja":"小浜には、人魚の肉を食べて不老となり800歳まで生きた「八百比丘尼」の伝説がある"},{"k":"legend","zh":"九頭龍川的名字，傳說來自 889 年出現一條九頭龍頂著佛像順流而下","en":"The Kuzuryū River is named for a legend of a nine-headed dragon carrying a Buddhist image downstream in 889.","ja":"九頭竜川の名は、889年に九つの頭の竜が尊像を頂いて流れていった伝説から"},{"k":"legend","zh":"這裡的和紙之鄉把教村民造紙的女神「川上御前」奉為紙祖神","en":"Papermakers here revere Kawakami Gozen, a goddess said to have taught villagers to make washi.","ja":"ここの和紙の里では、紙漉きを伝えたという川上御前を紙祖神として祀る"},{"k":"brand","zh":"明治新政府 1868 年發行的紙幣「太政官札」，用的就是這裡產的和紙","en":"The Meiji government's 1868 Dajōkan paper money was printed on washi made here.","ja":"1868年に明治新政府が出した太政官札には、ここの和紙が使われた"},{"k":"record","zh":"水月湖底逐年沉積的「年縞」，成為碳-14 定年的世界標準","en":"The annual sediment layers at the bottom of Lake Suigetsu became the world standard for radiocarbon dating.","ja":"水月湖の湖底に一年ずつ積もった「年縞」は、放射性炭素年代測定の世界標準になった"},{"k":"brand","zh":"小濱生產日本國產塗漆筷子的八成以上，若狹塗的花紋源自描繪海底景色","en":"Obama makes over 80% of Japan's lacquered chopsticks; Wakasa-nuri patterns are based on the seabed.","ja":"小浜は国産塗箸の8割以上を生産し、若狭塗の模様は海底の様子を図案化したもの"},{"k":"food","zh":"軟Q的「羽二重餅」，是模仿這裡產量日本第一的高級絲綢「羽二重」做的","en":"Habutae-mochi imitates the feel of habutae silk, of which this area was Japan's top producer.","ja":"羽二重餅は、この地が日本一の産地だった絹織物「羽二重」の風合いをまねた菓子"},{"k":"food","zh":"1913 年發表醬汁豬排丼的老店「ヨーロッパ軒」，創辦人高畠增太郎出身這裡","en":"Takabatake Masutarō, who unveiled sauce katsudon at his Europe-ken in 1913, was a native of this prefecture.","ja":"1913年にソースカツ丼を披露した「ヨーロッパ軒」の高畠増太郎は、ここの出身"}],
"JP-19":[{"k":"symbol","zh":"縣花是富士山麓開的小花櫻花「富士櫻」","en":"Its prefectural flower is the Fuji cherry, a small-flowered cherry of Mt. Fuji's foothills.","ja":"県の花は富士山麓に咲くフジザクラ"},{"k":"festival","zh":"「信玄公祭」上千人穿盔甲重現武田軍出陣，獲金氏認證為世界最大武者行列","en":"At the Shingen-kō Festival, over a thousand armored people re-enact Takeda's army: a Guinness-record samurai parade.","ja":"信玄公祭りの甲州軍団出陣は「世界最大の武者行列」としてギネス認定"},{"k":"work","zh":"露營動畫《搖曳露營△》的主要舞台在本栖湖和身延町一帶","en":"The camping anime Laid-Back Camp is mainly set around Lake Motosu and Minobu here.","ja":"キャンプアニメ『ゆるキャン△』の主な舞台は本栖湖や身延町の周辺"},{"k":"people","zh":"阪急電鐵、寶塚歌劇團與東寶的創辦人小林一三出身韮崎","en":"Ichizō Kobayashi, founder of Hankyu Railway, the Takarazuka Revue and Toho, was born in Nirasaki.","ja":"阪急電鉄・宝塚歌劇団・東宝を築いた小林一三は韮崎市出身"},{"k":"people","zh":"直木獎作家、日本大學理事長林真理子出身這裡","en":"Novelist Mariko Hayashi, a Naoki Prize winner and chair of Nihon University, is from here.","ja":"直木賞作家で日本大学理事長の林真理子の出身地"},{"k":"record","zh":"富士急樂園的「高飛車」以 121 度落下角，曾獲金氏認證為世界最陡雲霄飛車","en":"Fuji-Q Highland's Takabisha, with a 121° drop, was certified by Guinness as the world's steepest roller coaster.","ja":"富士急ハイランドの「高飛車」は最大落下角121度で、世界一急なコースターとしてギネス認定された"},{"k":"life","zh":"明明不靠海，縣廳所在地每戶的蛤蜊支出卻是全國第一的常客","en":"Though landlocked, the capital is a regular No. 1 in household spending on asari clams.","ja":"海なし県なのに、県庁所在地のあさり支出額は全国1位の常連"},{"k":"life","zh":"「吉田烏龍麵」麵條極硬，上面放的是燙高麗菜和馬肉","en":"Yoshida udon has extremely firm noodles topped with boiled cabbage and horse meat.","ja":"「吉田のうどん」は麺がとても硬く、ゆでキャベツと馬肉をのせる"},{"k":"people","zh":"諾貝爾生醫獎得主大村智出身韮崎，還在故鄉蓋了美術館捐給市政府","en":"Nobel laureate Satoshi Omura was born in Nirasaki and built an art museum there, donating it to the city.","ja":"ノーベル生理学・医学賞の大村智は韮崎出身で、故郷に美術館を建てて市に寄贈した"},{"k":"people","zh":"作家山本周五郎出身大月，是直木獎史上唯一在得獎公布後辭退的人","en":"Novelist Shugoro Yamamoto, born in Otsuki, is the only person to decline the Naoki Prize after it was announced.","ja":"大月出身の作家・山本周五郎は、直木賞の受賞決定後に辞退した唯一の人物"},{"k":"people","zh":"寫出棄老故事《楢山節考》的作家深澤七郎，出身石和","en":"Shichiro Fukazawa, author of The Ballad of Narayama, was born in Isawa.","ja":"棄老伝説を描いた『楢山節考』の作家・深沢七郎は石和の出身"},{"k":"work","zh":"深澤七郎的小說《笛吹川》描寫戰國時代這裡的農民，1960年由木下惠介拍成電影","en":"Fukazawa's novel 'Fuefukigawa' about Sengoku-era farmers here was filmed by Keisuke Kinoshita in 1960.","ja":"戦国時代の当地の農民を描いた深沢七郎『笛吹川』は、1960年に木下惠介が映画化した"},{"k":"work","zh":"太宰治1938年住進御坂峠的天下茶屋，寫下以富士山為題的《富嶽百景》","en":"In 1938 Osamu Dazai stayed at a teahouse on Misaka Pass, which led to his story 'One Hundred Views of Mt. Fuji'.","ja":"太宰治は1938年に御坂峠の天下茶屋に滞在し、『富嶽百景』を書いた"},{"k":"history","zh":"東武鐵道的根津嘉一郎等同鄉企業家，明治時代被稱為「○○財閥」，掌握東京的鐵路與電力","en":"Tobu Railway's Kaichiro Nezu was one of a group of local-born tycoons who controlled Tokyo railways and power.","ja":"東武鉄道の根津嘉一郎ら同郷の実業家は「○○財閥」と呼ばれ、東京の鉄道や電力を握った"},{"k":"sport","zh":"1989年這裡的一所大學派出箱根驛傳史上第一位留學生跑者","en":"In 1989 a university here fielded the first foreign-student runner in Hakone Ekiden history.","ja":"1989年、○○の大学が箱根駅伝史上初の留学生ランナーを起用した"},{"k":"sport","zh":"本地足球隊2022年以J2身分在天皇盃決賽PK擊敗J1廣島，首度奪冠","en":"The local club won the 2022 Emperor's Cup as a J2 side, beating J1 Hiroshima on penalties in the final.","ja":"地元クラブは2022年、J2のまま天皇杯決勝でJ1広島をPK戦で破り初優勝した"},{"k":"sport","zh":"本地J聯盟球隊的隊名結合法文「風」與「森林」，取自武田信玄的「風林火山」","en":"The local J.League club's name blends French 'vent' and 'forêt', inspired by Takeda Shingen's 'Furin Kazan' banner.","ja":"地元Jクラブの名は仏語の「風」と「森」を合わせたもので、武田信玄の「風林火山」が由来"},{"k":"festival","zh":"每年8月26日沿街點燃約3公尺高的大火把，宣告富士山登山季結束","en":"Every August 26, 3 m-tall torches are lit along a street in Fujiyoshida to close the Mt. Fuji climbing season.","ja":"毎年8月26日、高さ約3mの大松明が通りに並んで燃え、富士山の山じまいを告げる"},{"k":"origin","zh":"舊國名一說源自指群山之間谷地的「峽」，另一說是交通要衝的「交ひ」","en":"Its old province name may come from a word for a gorge between mountains, or from one meaning a crossroads.","ja":"旧国名は山あいの谷を指す「峡」、または交通の要衝を意味する「交ひ」が由来との説がある"},{"k":"symbol","zh":"原產這裡山區的虎斑日本犬，用來獵山豬與羚羊，1934年列為天然紀念物","en":"A brindle native dog bred in these mountains to hunt boar and serow was made a natural monument in 1934.","ja":"山岳地帯で猪やカモシカ猟に使われた虎毛の日本犬は、1934年に天然記念物になった"},{"k":"symbol","zh":"實相寺的「神代櫻」樹齡傳說有1800～2000年，相傳是日本武尊親手種下","en":"A temple cherry tree here is said to be 1,800 to 2,000 years old and planted by Prince Yamato Takeru.","ja":"実相寺の神代桜は樹齢1800～2000年といわれ、日本武尊が植えたと伝わる"},{"k":"record","zh":"天皇出席的全國植樹祭，1950年第一屆就在這裡舉行","en":"Japan's National Tree Planting Festival, attended by the Emperor, was first held here in 1950.","ja":"天皇が臨席する全国植樹祭は、1950年の第1回がここで開かれた"},{"k":"food","zh":"因為沒有傳統的喜慶料理，這個內陸縣反而把壽司當成慶祝時的固定菜色","en":"Lacking a traditional celebration dish, this landlocked prefecture adopted sushi for festive occasions.","ja":"祝いの郷土料理がなかったため、海なし県なのに寿司が祝い事の定番になった"},{"k":"life","zh":"朋友定期湊錢聚餐的「無盡」至今盛行，有餐廳掛出承辦無盡的招牌","en":"Friends still hold 'mujin', regular money-pooling get-togethers, and some restaurants advertise for them.","ja":"仲間で積み立てて宴会をする「無尽」が今も盛んで、無尽を受け付ける看板を出す店もある"},{"k":"life","zh":"縣立美術館1978年花2億日圓買下米勒名畫《播種者》","en":"In 1978 the prefectural art museum bought Millet's 'The Sower' for 200 million yen.","ja":"県立美術館は1978年、ミレーの『種をまく人』を2億円で購入した"},{"k":"history","zh":"1868年近藤勇率領的新選組部隊在勝沼被板垣退助的新政府軍擊敗","en":"In 1868 Kondo Isami's Shinsengumi-led force was defeated at Katsunuma by Itagaki Taisuke's government troops.","ja":"1868年、近藤勇率いる新選組中心の部隊が勝沼で板垣退助の新政府軍に敗れた"},{"k":"history","zh":"1582年武田勝頼在天目山麓自盡，武田家就此滅亡","en":"In 1582 Takeda Katsuyori died at the foot of Mt. Tenmoku, ending the Takeda clan.","ja":"1582年、武田勝頼が天目山麓で自害し、武田氏は滅亡した"},{"k":"history","zh":"日本血吸蟲1904年在這裡被發現，這種地方病直到1996年才宣布根絕","en":"Schistosoma japonicum was identified here in 1904; the endemic disease was declared eradicated in 1996.","ja":"日本住血吸虫は1904年にここで発見され、この地方病は1996年にようやく終息宣言が出た"},{"k":"history","zh":"相傳武田信玄在釜無川修築的「信玄堤」，是戰國時代治水工程的代表","en":"Takeda Shingen's levee on the Kamanashi River is a landmark of Sengoku-era flood control.","ja":"武田信玄が釜無川に築いたとされる「信玄堤」は、戦国時代の治水の代表例"},{"k":"nature","zh":"千圓鈔票背面的「逆富士」，畫的就是從本栖湖看到的富士山倒影","en":"The reflected Mt. Fuji on the back of the 1,000-yen note is the view from Lake Motosu.","ja":"千円札の裏に描かれた「逆さ富士」は、本栖湖から見た富士山"},{"k":"brand","zh":"以黃色工業機器人聞名的發那科，總部設在富士山麓忍野村的森林裡","en":"Robot maker FANUC, famous for its yellow machines, is headquartered in a forest at Oshino at the foot of Mt. Fuji.","ja":"黄色いロボットで知られるファナックは、富士山麓・忍野村の森に本社を置く"},{"k":"brand","zh":"在鹿皮上用漆畫花紋的「印傳」只在這裡傳承至今，名稱據說來自「印度傳來」","en":"Inden, deerskin decorated with lacquer, survives only here; its name is said to mean 'brought from India'.","ja":"鹿革に漆で柄をつける「印伝」は当地だけに伝わり、名は「印度伝来」に由来するという"},{"k":"brand","zh":"甜點連鎖Chateraise總部在這裡，名字是法文「城堡」與「葡萄」的組合","en":"Confectionery chain Chateraise is based here; its name combines French words for 'castle' and 'grapes'.","ja":"菓子チェーンのシャトレーゼは本社をここに置き、名は仏語の「城」と「ぶどう」から"},{"k":"legend","zh":"傳說聖德太子騎著這裡進貢的神駿黑馬，一路飛越富士山","en":"Legend says Prince Shotoku rode a black horse sent from here and flew over Mt. Fuji.","ja":"聖徳太子はここから献上された黒駒に乗り、富士山を飛び越えたと伝わる"},{"k":"legend","zh":"日本武尊與燒火老人在酒折宮一問一答吟歌，被視為連歌的起源","en":"Yamato Takeru and a fire-tending old man traded verses at Sakaori Shrine, said to be the birth of renga.","ja":"酒折宮で日本武尊と御火焼の老人が歌を交わし、連歌発祥の地とされる"},{"k":"food","zh":"傳說駿河灣的鮑魚泡醬油後用馬馱進山，路上剛好入味，成了「煮貝」","en":"Legend says soy-soaked abalone carried by horse from Suruga Bay marinated on the way, creating 'nigai'.","ja":"駿河湾のアワビを醤油に漬けて馬で運ぶうちに味がしみ、「煮貝」になったと伝わる"}],
"JP-20":[{"k":"symbol","zh":"縣樹是高原上常見的白樺","en":"Its prefectural tree is the white birch, common in its highlands.","ja":"県の木は高原に多いシラカバ"},{"k":"people","zh":"以圓點南瓜聞名的前衛藝術家草間彌生出身松本","en":"Avant-garde artist Yayoi Kusama, famous for her polka-dot pumpkins, was born in Matsumoto.","ja":"水玉のカボチャで知られる前衛芸術家・草間彌生は松本市出身"},{"k":"people","zh":"大坂之陣被譽為「日本第一兵」的真田幸村，真田家的根據地在上田","en":"The Sanada clan of Yukimura, hailed as 'Japan's finest warrior' at the Siege of Osaka, was based in Ueda.","ja":"大坂の陣で「日本一の兵」と称された真田幸村の真田氏は、上田が本拠地"},{"k":"work","zh":"細田守動畫《夏日大作戰》以上田市一個大家族的老宅為舞台","en":"Mamoru Hosoda's Summer Wars is set at a big family's old house in Ueda.","ja":"細田守監督『サマーウォーズ』の舞台は上田市の旧家"},{"k":"festival","zh":"野澤溫泉的「道祖神火祭」：男人們守住高大的木造社殿，抵擋拿火把的村民猛攻","en":"At Nozawa Onsen's Dōsojin fire festival, men defend a tall wooden shrine from torch-wielding villagers.","ja":"野沢温泉の道祖神祭りでは、社殿を守る男たちと松明で火を放つ村人が激しくぶつかる"},{"k":"record","zh":"博物館與美術館的數量全國最多","en":"It has more museums and art galleries than any other prefecture.","ja":"博物館・美術館の数が全国最多"},{"k":"life","zh":"縣民幾乎人人都會唱縣歌《信濃之國》","en":"Almost everyone here can sing the prefectural song 'Shinano no Kuni'.","ja":"ほとんどの県民が県歌『信濃の国』を歌える"},{"k":"life","zh":"伊那地方有吃昆蟲的習慣：蜂之子、蝗蟲，甚至水生昆蟲「ざざむし」","en":"In the Ina area, people eat insects: bee larvae, locusts, even aquatic 'zazamushi'.","ja":"伊那地方には、蜂の子やイナゴ、ざざむしなど昆虫を食べる文化がある"},{"k":"people","zh":"一生寫下超過兩萬首俳句的小林一茶，故鄉在北部的柏原","en":"Haiku poet Kobayashi Issa, who wrote over 20,000 haiku, came from Kashiwabara in the north.","ja":"2万句以上を詠んだ俳人・小林一茶は、北部の柏原の出身"},{"k":"people","zh":"吉田松陰與勝海舟的老師佐久間象山出身松代，1849年做了日本首次電報實驗","en":"Sakuma Shozan, teacher of Yoshida Shoin and Katsu Kaishu, ran Japan's first telegraph test in Matsushiro in 1849.","ja":"吉田松陰や勝海舟の師・佐久間象山は松代出身で、1849年に日本初の電信実験を行った"},{"k":"sport","zh":"江戶相撲幕內勝率高達九成六的傳奇力士雷電為右衛門，出身東御","en":"Raiden Tameemon, an Edo-era sumo legend with a .962 winning rate, was born in what is now Tomi.","ja":"幕内勝率9割6分2厘の伝説の力士・雷電爲右エ門は、現在の東御の出身"},{"k":"sport","zh":"松本的J聯盟球隊「山雅」，隊名取自早期球員常去的咖啡店","en":"Matsumoto's J.League club 'Yamaga' is named after a coffee shop its early players frequented.","ja":"松本山雅FCの「山雅」は、初期の選手たちが通った喫茶店の名前に由来する"},{"k":"record","zh":"輕井澤辦過1964年東京奧運馬術與1998年冬奧冰壺，號稱世界首個夏冬奧都當過場地的町","en":"Karuizawa hosted equestrian in 1964 and curling in 1998, said to be the first town to host both Olympics.","ja":"軽井沢町は1964年夏季五輪の馬術と1998年冬季五輪のカーリング会場になった"},{"k":"history","zh":"1886年起加拿大傳教士蕭（A.C. Shaw）推廣，讓輕井澤成為避暑勝地","en":"Canadian missionary Alexander Croft Shaw promoted Karuizawa as a summer retreat from 1886.","ja":"1886年、カナダ人宣教師ショーが軽井沢を避暑地として広めた"},{"k":"work","zh":"宮崎駿《風起》女主角的原型之一，是在富士見高原療養所病逝的堀辰雄未婚妻","en":"A model for the heroine of Miyazaki's 'The Wind Rises' was Hori Tatsuo's fiancée, who died at the Fujimi sanatorium.","ja":"宮崎駿『風立ちぬ』の菜穂子のモデルの一人は、富士見高原療養所で亡くなった堀辰雄の婚約者"},{"k":"origin","zh":"古代國名寫作「科野」，一說是因為這裡長滿椴樹（シナノキ）","en":"The old province name was first written with the character for the linden tree, said to grow here abundantly.","ja":"古代の国名は「科野」と書き、シナノキが多く生えていたことが由来との説がある"},{"k":"record","zh":"海拔1345.67公尺的野邊山站，是JR全線最高的車站","en":"Nobeyama Station, 1,345.67 m above sea level, is the highest station on the JR network.","ja":"標高1345.67mの野辺山駅は、JRで最も高い所にある駅"},{"k":"record","zh":"1876年落成的擬洋風校舍舊開智學校，2019年成為第一座列為國寶的近代學校建築","en":"The Kaichi School (1876) became the first modern school building named a National Treasure, in 2019.","ja":"1876年完成の旧開智学校は、2019年に近代の学校建築として初めて国宝になった"},{"k":"record","zh":"海拔657.5公尺的松本機場，是日本海拔最高的機場","en":"Matsumoto Airport, at 657.5 m, is the highest-elevation airport in Japan.","ja":"標高657.5mの松本空港は、日本で最も標高の高い空港"},{"k":"nature","zh":"野尻湖湖底挖出諾氏古菱齒象與大角鹿的化石，還有舊石器時代的石器","en":"Naumann elephant and giant deer fossils, plus Paleolithic tools, have been dug from the bed of Lake Nojiri.","ja":"野尻湖の湖底からは、ナウマンゾウやオオツノジカの化石と旧石器が出土している"},{"k":"record","zh":"1934年完工、把水抽回野尻湖的池尻川發電廠，是日本第一座抽水蓄能電廠","en":"The Ikejirigawa plant (1934), which pumps water back up into Lake Nojiri, was Japan's first pumped-storage station.","ja":"1934年完成の池尻川発電所は、野尻湖へ水をくみ上げる日本初の揚水発電所"},{"k":"nature","zh":"全長213公里的天龍川，從諏訪湖的釜口水門流出，一路奔向太平洋","en":"The 213 km Tenryu River flows out of Lake Suwa through the Kamaguchi sluice gate toward the Pacific.","ja":"全長213kmの天竜川は、諏訪湖の釜口水門から流れ出て太平洋へ向かう"},{"k":"food","zh":"茅野一帶冬天把洋菜凍放在戶外夜凍日曬，製成角寒天","en":"Around Chino, bar agar is made in winter by freezing jelly outdoors at night and drying it in the sun by day.","ja":"茅野周辺では冬、ところてんを夜に凍らせ昼に干して角寒天をつくる"},{"k":"food","zh":"明治時代諏訪湖畔大量釀造味噌，供應製絲工廠女工的伙食","en":"In the Meiji era, miso was mass-produced around Lake Suwa to feed the workers of silk mills.","ja":"明治時代、諏訪湖周辺では製糸工場で働く工女の食事用に味噌が大量に造られた"},{"k":"history","zh":"二戰末期在松代山中挖了總長約10公里的地道，準備遷移大本營與皇居","en":"In 1944–45 about 10 km of tunnels were dug at Matsushiro to house the Imperial HQ and the palace.","ja":"太平洋戦争末期、大本営と皇居を移すため松代の山中に総延長約10kmの地下壕が掘られた"},{"k":"history","zh":"1972年淺間山莊人質事件，電視直播收視率最高達89.7%","en":"TV coverage of the 1972 Asama-Sanso hostage siege peaked at 89.7% household viewership.","ja":"1972年のあさま山荘事件では、テレビ中継の視聴率が最高89.7%に達した"},{"k":"life","zh":"淺間山莊事件中機動隊吃杯麵的畫面不斷播出，讓剛上市的日清杯麵爆紅","en":"Footage of riot police eating Cup Noodles during the 1972 siege turned the new product into a hit.","ja":"あさま山荘事件で機動隊員がカップヌードルを食べる映像が流れ、ヒット商品になった"},{"k":"history","zh":"戰前送往滿洲的開拓移民，以這裡出身的約3萬4千人最多","en":"More Manchurian settlers came from here than from any other prefecture, about 34,000 people.","ja":"満蒙開拓移民の送出数は都道府県で最も多く、約3万4千人にのぼった"},{"k":"brand","zh":"愛普生起家於諏訪，品牌名來自印表機EP-101，意思是「EP的兒子」","en":"Epson began in Suwa; its name comes from the EP-101 printer plus 'son'.","ja":"諏訪で生まれたエプソンの名は、プリンター「EP-101」の「子（SON）」から"},{"k":"brand","zh":"1969年世界第一支石英腕錶「Astron」，由諏訪的精工集團開發","en":"The world's first quartz wristwatch, Seiko's Astron (1969), was developed by the Seiko group in Suwa.","ja":"世界初のクオーツ腕時計アストロン（1969年）は、諏訪のセイコーグループが開発した"},{"k":"legend","zh":"傳說天手力雄命把天岩戶的石門一把扔到這裡，落地成了戶隱山","en":"Legend says the god Tajikarao hurled the door of the heavenly rock cave here, forming Mt. Togakushi.","ja":"天手力雄命が投げた天岩戸の扉が落ちて戸隠山になったと伝わる"},{"k":"legend","zh":"冠著山俗稱「姨捨山」，是平安時代《大和物語》就記載的棄老傳說舞台","en":"Mt. Kamuriki, nicknamed Obasute-yama, is the setting of an abandoned-elder legend recorded around 950.","ja":"冠着山は「姨捨山」とも呼ばれ、『大和物語』にも載る棄老伝説の舞台"},{"k":"legend","zh":"戶隱一帶流傳平維茂討伐鬼女紅葉的傳說，能劇《紅葉狩》即取材於此","en":"Togakushi legend tells of Taira no Koremochi slaying the demon woman Momiji, the basis of the Noh play Momijigari.","ja":"戸隠には平維茂が鬼女紅葉を退治した伝説があり、能『紅葉狩』の題材となった"}],
"JP-21":[{"k":"symbol","zh":"縣樹是「一位」（紅豆杉），飛驒的「一位一刀雕」就是用它刻的","en":"Its prefectural tree is the Japanese yew (ichii), the wood used for Hida's single-blade carvings.","ja":"県の木はイチイ。飛騨の一位一刀彫の材料になる"},{"k":"work","zh":"動畫電影《你的名字》中「系守町」的原型之一是飛驒市","en":"Hida City is one of the models for Itomori, the town in the film Your Name.","ja":"映画『君の名は。』の糸守町のモデルのひとつは飛騨市"},{"k":"work","zh":"動畫電影《聲之形》以大垣市為舞台","en":"The anime film A Silent Voice is set in Ōgaki.","ja":"映画『聲の形』の舞台は大垣市"},{"k":"people","zh":"二戰時發放「生命簽證」救了約六千名猶太人的外交官杉原千畝出身這裡","en":"Diplomat Chiune Sugihara, whose 'visas for life' saved some 6,000 Jews in WWII, was born here.","ja":"「命のビザ」で約6千人のユダヤ人を救った外交官・杉原千畝の出身地"},{"k":"festival","zh":"春秋兩季舉行的高山祭，名列日本三大美祭","en":"The Takayama Festival, held each spring and autumn, ranks among Japan's three most beautiful festivals.","ja":"春と秋の高山祭は日本三大美祭のひとつ"},{"k":"life","zh":"縣廳所在地每戶的咖啡廳消費，曾連續 4 年全國第一","en":"Households in the capital once ranked No. 1 in Japan for café spending four years running.","ja":"県庁所在地の1世帯あたり喫茶代は、4年連続全国1位になったことがある"},{"k":"record","zh":"郡上八幡被稱為食品模型的發祥地，業界龍頭岩崎瀧三就是這裡人","en":"Gujō Hachiman is called the birthplace of plastic food samples; industry pioneer Takizō Iwasaki came from there.","ja":"郡上八幡は食品サンプル発祥の地とされ、業界最大手を築いた岩崎瀧三の故郷"},{"k":"people","zh":"發動本能寺之變的明智光秀，據傳出身這裡的美濃地方","en":"Akechi Mitsuhide, who betrayed Oda Nobunaga at Honnō-ji, is said to have been born in the Mino area here.","ja":"本能寺の変を起こした明智光秀は、美濃の出身とされる"},{"k":"people","zh":"一生據說刻了12萬尊佛像的僧人圓空，出身這裡的南部","en":"The monk Enku, said to have carved some 120,000 Buddhist statues, was born in this prefecture's south.","ja":"生涯に12万体の仏像を彫ったとされる円空は、当地の美濃の出身"},{"k":"sport","zh":"雪梨奧運馬拉松金牌、首位跑進2小時20分的女子選手高橋尚子，出身縣廳所在地","en":"Naoko Takahashi, Sydney 2000 marathon champion and first woman under 2:20, was born in the prefectural capital.","ja":"シドニー五輪マラソン金メダルで女子初の2時間20分切りを果たした高橋尚子は、県庁所在地の出身"},{"k":"people","zh":"譯完莎士比亞全集的坪內逍遙，出身美濃加茂的太田宿","en":"Tsubouchi Shoyo, who translated Shakespeare's complete works, was born at Ota-juku in Minokamo.","ja":"シェイクスピア全集を翻訳した坪内逍遥は、太田宿（美濃加茂市）の出身"},{"k":"history","zh":"1564年竹中半兵衛發動奇襲，從主君齋藤龍興手中奪下稻葉山城","en":"In 1564 Takenaka Hanbei seized Inabayama Castle from his own lord, Saito Tatsuoki, in a surprise attack.","ja":"1564年、竹中半兵衛は主君・斎藤龍興の稲葉山城を奇襲で乗っ取った"},{"k":"work","zh":"京都動畫《冰菓》主要在原作者米澤穗信的家鄉高山取景","en":"Kyoto Animation's 'Hyouka' was mainly location-scouted in Takayama, home of author Honobu Yonezawa.","ja":"京アニ『氷菓』は、原作者・米澤穂信の地元である高山を中心にロケハンされた"},{"k":"work","zh":"《暮蟬悲鳴時》裡雛見澤村的風景，以白川鄉為原型","en":"The village of Hinamizawa in 'Higurashi When They Cry' was modeled on Shirakawa-go.","ja":"『ひぐらしのなく頃に』の雛見沢村の風景は、白川郷がモデル"},{"k":"festival","zh":"每年4月19日深夜古川祭的「起太鼓」，小太鼓隊輪番衝撞扛著的大鼓","en":"On the night of April 19, Furukawa's Okoshi Daiko sees small drum teams charge a giant shouldered drum.","ja":"毎年4月19日夜、古川祭の起し太鼓では担がれた大太鼓に付け太鼓が次々と突進する"},{"k":"origin","zh":"南部的舊國名一說源自青野、大野、各務野三片原野，古代也寫作「三野」","en":"The southern old province name may come from three plains, and in early records was written as 'three fields'.","ja":"南部の旧国名は青野・大野・各務野の三つの野に由来する説があり、古くは「三野」と書いた"},{"k":"history","zh":"古代北部山區免繳庸與調，改派木匠替朝廷蓋宮殿，稱為「○○之匠」","en":"In ancient times the northern province paid its taxes by sending skilled carpenters to build for the court.","ja":"律令時代、北部の国は庸・調を免除される代わりに大工を都へ送り、「○○の匠」と呼ばれた"},{"k":"symbol","zh":"1883年名和靖在這裡採集到新種蝴蝶，因此日文名叫「○○蝶」","en":"A butterfly first collected here by Nawa Yasushi in 1883 was named after this prefecture.","ja":"1883年に名和靖がここで採集した新種の蝶は、県名をとって「○○チョウ」と名付けられた"},{"k":"symbol","zh":"長良川的香魚與周邊漁業生活構成的系統，2015年獲認定為世界農業遺產","en":"The Nagara River's sweetfish fishery and way of life became a Globally Important Agricultural Heritage System in 2015.","ja":"長良川の鮎をめぐる営みは2015年、「清流長良川の鮎」として世界農業遺産に認定された"},{"k":"nature","zh":"1995年河口堰啟用前，長良川是本州主流上沒有堰的最大河川","en":"Until its estuary weir opened in 1995, the Nagara was Honshu's largest river with no weir on its main stream.","ja":"1995年に河口堰ができるまで、長良川は本流に堰のない本州最大の川だった"},{"k":"record","zh":"高山市面積2177.67平方公里，是日本面積最大的市町村","en":"Takayama, covering 2,177.67 km², is the largest municipality in Japan by area.","ja":"高山市は面積2177.67km²で、日本一広い市町村"},{"k":"nature","zh":"2007年8月多治見測得40.9°C，追平當時的日本最高氣溫紀錄","en":"In August 2007 Tajimi hit 40.9°C, tying Japan's national temperature record at the time.","ja":"2007年8月、多治見で40.9℃を記録し、当時の国内最高気温に並んだ"},{"k":"nature","zh":"明明是內陸縣，最低點卻在海津，低於海平面","en":"Though landlocked, the prefecture's lowest point, in Kaizu, lies below sea level.","ja":"海なし県なのに、最低地点の海津市は海面より低い"},{"k":"life","zh":"平成大合併後，大垣市成了日本唯一有「雙重飛地」的城市","en":"After the Heisei mergers, Ogaki became the only city in Japan with a double exclave.","ja":"平成の大合併で、大垣市は日本で唯一の「二重飛び地」を持つ市になった"},{"k":"life","zh":"高山的斐太高中畢業生，把帽子白線與水手服領巾綁在一起放進河裡漂流","en":"Graduates of Hida High School in Takayama tie their cap stripes and scarves together and float them down a river.","ja":"高山の斐太高校では、卒業生が帽子の白線とスカーフを結んで川に流す「白線流し」を行う"},{"k":"history","zh":"1891年規模8.0的濃尾地震造成7千多人死亡，根尾谷斷層出現約6公尺落差","en":"The 1891 Nobi earthquake (M8.0) killed over 7,000 and left a vertical offset of about 6 m on the Neodani Fault.","ja":"1891年のM8.0の濃尾地震で7千人以上が死亡し、根尾谷断層に約6mの段差ができた"},{"k":"history","zh":"1754年薩摩藩奉命整治木曾三川、犧牲慘重，促成日後與鹿兒島結為姊妹縣","en":"Satsuma samurai's costly 1754 flood control on three rivers here led to a later sister tie with Kagoshima.","ja":"1754年に薩摩藩が木曽三川の治水を命じられ多くの犠牲を出し、のちの鹿児島との姉妹県盟約につながった"},{"k":"legend","zh":"傳說孝子打的瀑布水變成美酒，元正天皇因此把年號改為「養老」","en":"Legend says a waterfall turned to sake for a devoted son, and an empress renamed the era 'Yoro' after it.","ja":"孝行息子のために滝の水が酒になったと伝わり、元正天皇は元号を「養老」に改めた"},{"k":"legend","zh":"《日本書紀》裡兩張臉、四隻手的叛賊「兩面宿儺」，在當地傳說中卻是英雄","en":"The two-faced, four-armed Ryomen Sukuna is an outlaw in the Nihon Shoki but a hero in local legend.","ja":"『日本書紀』で二つの顔と四本の腕を持つ賊とされる両面宿儺は、地元では英雄として伝わる"},{"k":"food","zh":"中津川的栗子點心「栗金飩」，據說源自江戶中期宿場招待旅人","en":"Nakatsugawa's chestnut sweet kuri-kinton is said to date to the mid-Edo period, when it was served to travelers.","ja":"中津川の栗きんとんは、江戸中期に宿場で旅人をもてなしたのが始まりとされる"},{"k":"brand","zh":"多治見的笠原町是馬賽克磁磚產地，還有藤森照信設計的磁磚博物館","en":"Kasahara in Tajimi is a mosaic-tile center, home to a tile museum designed by Terunobu Fujimori.","ja":"多治見市笠原町はモザイクタイルの産地で、藤森照信設計のミュージアムがある"},{"k":"brand","zh":"野口勇1952年受當地傳統紙燈籠啟發，創作出風靡全球的「AKARI」燈具","en":"Isamu Noguchi's world-famous Akari lamps (1952) were inspired by this area's traditional paper lanterns.","ja":"イサム・ノグチの照明「AKARI」（1952年）は、当地の提灯から着想を得た"}],
"JP-22":[{"k":"symbol","zh":"縣鳥是三光鳥，叫聲聽起來像日文的「月、日、星」","en":"Its prefectural bird is the paradise flycatcher, whose call sounds like 'moon, sun, star' in Japanese.","ja":"県の鳥サンコウチョウは「ツキヒーホシ」と聞こえる声で鳴く"},{"k":"work","zh":"動畫《Love Live! Sunshine!!》以沼津的內浦為舞台","en":"The anime Love Live! Sunshine!! is set in Uchiura, Numazu.","ja":"アニメ『ラブライブ!サンシャイン!!』の舞台は沼津市内浦"},{"k":"people","zh":"豐田集團的創始人豐田佐吉，其實出身這裡的湖西","en":"Toyota group founder Sakichi Toyoda was actually born in Kosai here.","ja":"トヨタグループの創始者・豊田佐吉は、実はここの湖西市出身"},{"k":"festival","zh":"濱松祭以巨大風箏互相割線的「風箏大戰」聞名，起源是慶祝長子誕生","en":"The Hamamatsu Festival is famous for kite battles, rooted in celebrating the birth of first sons.","ja":"浜松まつりの凧揚げ合戦は、長男の誕生を祝う初凧が起源"},{"k":"origin","zh":"縣廳所在地原名「府中」，明治時代因為音近「不忠」而改名","en":"The capital was once called Fuchū; in the Meiji era it was renamed because 'Fuchū' sounds like 'disloyal'.","ja":"県庁所在地の旧名「府中」は「不忠」に通じるとして、明治に改名された"},{"k":"sport","zh":"曾三度奪得 J 聯盟冠軍的磐田喜悅隊以這裡為主場","en":"Júbilo Iwata, three-time J.League champions, are based here.","ja":"Jリーグで3度優勝したジュビロ磐田の本拠地"},{"k":"life","zh":"濱松市年年和宇都宮市爭奪「每戶餃子消費額」全國第一","en":"Hamamatsu and Utsunomiya battle every year for Japan's top household spending on gyoza.","ja":"浜松市は宇都宮市と毎年「餃子の支出額日本一」を争う"},{"k":"record","zh":"大井川上的蓬萊橋長 897 公尺，獲金氏認證為世界最長木造步道橋","en":"Hōrai Bridge over the Ōi River, 897 m long, is Guinness-certified as the world's longest wooden footbridge.","ja":"大井川の蓬莱橋は全長897mで、世界一長い木造歩道橋としてギネス認定"},{"k":"people","zh":"出身濱松的高柳健次郎1926年用映像管顯示出「イ」字，被稱為日本電視之父","en":"Hamamatsu-born Kenjiro Takayanagi showed the katakana 'i' on a cathode-ray tube in 1926: Japan's father of TV.","ja":"浜松出身の高柳健次郎は1926年にブラウン管に「イ」の字を映し、日本のテレビの父と呼ばれる"},{"k":"people","zh":"幕末俠客清水次郎長晚年轉而致力於港口建設與富士山麓開墾","en":"Shimizu no Jirocho, a famed gambler-boss, later devoted himself to port development and farmland near Mt. Fuji.","ja":"侠客・清水次郎長は晩年、港の整備や富士山麓の開墾に力を注いだ"},{"k":"people","zh":"傳說以女性身分當上家主的井伊直虎，領地在濱松的井伊谷","en":"Ii Naotora, traditionally said to be a woman who headed her clan, ruled Iinoya in present-day Hamamatsu.","ja":"女城主として知られる井伊直虎の本拠は、浜松の井伊谷"},{"k":"sport","zh":"1976年日本第一場F1大賽，在富士山東麓的賽車場冒雨舉行","en":"Japan's first Formula One race was held in the rain in 1976 at a circuit on Mt. Fuji's eastern slope.","ja":"1976年、日本初のF1レースが富士山東麓のサーキットで雨の中行われた"},{"k":"work","zh":"川端康成1918年獨自旅行越過天城山口到下田，寫成《伊豆的舞孃》","en":"Kawabata's 'The Izu Dancer' grew from his 1918 solo trip over Amagi Pass to Shimoda.","ja":"川端康成は1918年の一人旅で天城峠を越えて下田へ向かい、『伊豆の踊子』を書いた"},{"k":"work","zh":"《足球小將翼》小學與國中篇的舞台「南葛市」，設定在這裡","en":"Nankatsu City, the hometown in 'Captain Tsubasa', is a fictional city set in this prefecture.","ja":"『キャプテン翼』小学生編・中学生編の舞台・南葛市は、ここにある架空の市"},{"k":"festival","zh":"下田每年5月的「黑船祭」從1934年開始，美國海軍也會派艦艇與樂隊參加","en":"Shimoda's Black Ship Festival each May, held since 1934, features US Navy ships and bands.","ja":"下田で毎年5月に開かれる黒船祭は1934年に始まり、米海軍も艦船や音楽隊を送る"},{"k":"origin","zh":"西部舊國名意思是「遙遠的淡水湖」，指濱名湖，與指琵琶湖的近江相對","en":"The western old province name means 'distant freshwater lake' (Lake Hamana), in contrast to Omi's Lake Biwa.","ja":"西部の旧国名は浜名湖を指す「遠淡海」が由来で、琵琶湖の「近淡海」（近江）と対になる"},{"k":"nature","zh":"濱名湖原本是淡水湖，1498年明應地震的海嘯沖破沙洲才變成半鹹水湖","en":"Lake Hamana was freshwater until the 1498 Meio quake and tsunami breached its sandbar, making it brackish.","ja":"浜名湖はもとは淡水湖で、1498年の明応地震の津波で砂州が切れて汽水湖になった"},{"k":"symbol","zh":"2月就盛開的河津櫻，源自1955年在河津川畔雜草中發現的一株小樹","en":"Kawazu cherry, blooming in February, descends from a sapling found among weeds by the Kawazu River in 1955.","ja":"2月に咲く河津桜は、1955年に河津川沿いの雑草の中で見つかった苗木が原木"},{"k":"record","zh":"韮山反射爐是世界上唯一實際熔過鑄鐵、且保存至今的反射爐","en":"The Nirayama furnace is the world's only surviving reverberatory furnace that actually melted cast iron.","ja":"韮山反射炉は、実際に鋳鉄を溶かした反射炉として世界で唯一現存する"},{"k":"record","zh":"長約1.2公里的柿田川全靠富士山湧泉，是日本最短的一級河川","en":"Fed by Mt. Fuji springs, the 1.2 km Kakita River is the shortest first-class river in Japan.","ja":"富士山の湧水で流れる柿田川は全長約1.2km、日本一短い一級河川"},{"k":"history","zh":"1855年俄國軍艦沉沒後，日俄工匠在戶田村合造西式帆船「戶田號」讓船員回國","en":"After a Russian frigate sank in 1855, Japanese and Russian builders made the schooner Heda at Heda village.","ja":"1855年、沈没したロシア艦の乗員を帰すため、戸田村で洋式帆船「ヘダ号」が建造された"},{"k":"history","zh":"彌生時代的登呂遺跡，是1943年二戰期間興建軍需工廠時發現的","en":"The Yayoi-era Toro site was discovered in 1943 during construction of a wartime munitions factory.","ja":"弥生時代の登呂遺跡は、1943年に軍需工場の建設中に発見された"},{"k":"history","zh":"江戶幕府禁止在大井川架橋和擺渡，旅人只能花錢請挑夫扛過河","en":"The shogunate banned bridges and ferries on the Oi River, so travelers paid porters to carry them across.","ja":"江戸幕府は大井川に橋も渡し船も認めず、旅人は川越人足に担がれて渡った"},{"k":"food","zh":"加豬油渣、撒沙丁魚粉的富士宮炒麵，奪下第一、二屆B-1大獎冠軍","en":"Fujinomiya yakisoba, with pork cracklings and sardine powder, won the first two B-1 Grand Prix contests.","ja":"肉かすとイワシの削り粉が特徴の富士宮やきそばは、B-1グランプリ第1回・第2回で優勝した"},{"k":"life","zh":"以拳頭漢堡排聞名的「さわやか」只在這裡開店，外縣市客人專程來排隊","en":"Sawayaka, famed for its fist-sized hamburg steaks, only operates in this prefecture, drawing long lines of visitors.","ja":"げんこつハンバーグで有名な「さわやか」は県内だけに出店し、県外客も行列をつくる"},{"k":"brand","zh":"加了鰻魚精華的「鰻魚派」標語是「夜晚的點心」，原意是晚上全家團聚享用","en":"Unagi Pie, made with eel extract, is billed as 'the evening snack', originally meant for family time at night.","ja":"うなぎエキス入りの「うなぎパイ」の「夜のお菓子」は、本来は一家団らんを意味していた"},{"k":"brand","zh":"濱松光子製造的大型光電倍增管，撐起神岡探測器帶來的兩座諾貝爾獎","en":"Hamamatsu Photonics made the giant photomultiplier tubes behind two Nobel Prizes from Kamiokande and Super-K.","ja":"浜松ホトニクスの大型光電子増倍管は、カミオカンデ由来の二つのノーベル賞を支えた"},{"k":"life","zh":"大村智獲諾貝爾獎的伊維菌素，來源的土壤細菌是1974年在這裡採集的","en":"The soil bacterium behind Satoshi Omura's Nobel-winning ivermectin was isolated from soil here in 1974.","ja":"大村智のノーベル賞につながったイベルメクチンの土壌菌は、1974年にここの土から見つかった"},{"k":"life","zh":"演出能劇《羽衣》的法國舞者朱格拉莉絲早逝，丈夫依遺願把她的頭髮送到三保","en":"French dancer Hélène Giuglaris, who performed Hagoromo, died young; her husband brought her hair to Miho.","ja":"能『羽衣』を演じた仏の舞踊家エレーヌ・ジュグラリスは早世し、夫が遺髪を三保に届けた"},{"k":"legend","zh":"東海道三大難關之一的小夜中山山口，流傳著遠州七大不可思議之一「夜泣石」","en":"Sayo no Nakayama, one of the Tokaido's three hardest passes, has the legend of the 'night-crying stone'.","ja":"東海道三大難所の小夜の中山には、遠州七不思議の「夜泣き石」の伝説が残る"}],
"JP-23":[{"k":"symbol","zh":"縣花是燕子花（カキツバタ），《伊勢物語》在八橋以它為題作歌","en":"Its prefectural flower is the rabbit-ear iris, the subject of a famous poem at Yatsuhashi in the Tales of Ise.","ja":"県の花はカキツバタ。『伊勢物語』の八橋の歌で知られる"},{"k":"people","zh":"美日職棒傳奇鈴木一朗出身這裡的豐山町","en":"Baseball legend Ichiro Suzuki is from Toyoyama here.","ja":"日米で活躍したイチローは豊山町出身"},{"k":"work","zh":"2022 年開幕的吉卜力公園，蓋在長久手的愛・地球博紀念公園裡","en":"Ghibli Park, opened in 2022, sits inside the Expo 2005 memorial park in Nagakute.","ja":"2022年開業のジブリパークは、長久手市の愛・地球博記念公園の中にある"},{"k":"festival","zh":"國府宮「裸祭」上，數千名裸男推擠著想摸到「神男」來消災","en":"At Kōnomiya's Naked Festival, thousands of nearly naked men scramble to touch the 'shin-otoko' to ward off bad luck.","ja":"国府宮はだか祭では、大勢の裸男が厄を落とそうと神男に触れようともみ合う"},{"k":"origin","zh":"名字源自《萬葉集》歌詠的海邊潮灘「年魚市潟（あゆちがた）」","en":"The name comes from 'Ayuchi-gata', a tidal flat sung of in the Man'yōshū.","ja":"名は『万葉集』に詠まれた「年魚市潟（あゆちがた）」に由来"},{"k":"sport","zh":"職棒中日龍的主場在這裡","en":"The Chunichi Dragons baseball team plays its home games here.","ja":"プロ野球・中日ドラゴンズの本拠地"},{"k":"life","zh":"點咖啡就附吐司和水煮蛋的「早餐服務」，據說起源於一宮市","en":"The 'morning service', free toast and egg with your coffee, is said to have started in Ichinomiya.","ja":"コーヒーにトーストやゆで卵がつく「モーニング」は一宮市発祥とされる"},{"k":"record","zh":"菊花產量全國第一，渥美半島夜裡點燈讓菊花延後開花","en":"It grows the most chrysanthemums in Japan; on the Atsumi Peninsula, lights at night delay their blooming.","ja":"菊の生産量全国1位。渥美半島では夜に電照して開花を遅らせる"},{"k":"people","zh":"《七龍珠》作者鳥山明堅持不搬到東京，一直在清須的家中工作","en":"Dragon Ball creator Akira Toriyama refused to move to Tokyo and worked from his home in Kiyosu.","ja":"『ドラゴンボール』の鳥山明は東京へ移らず、清須の自宅で仕事を続けた"},{"k":"people","zh":"築起熊本城的猛將加藤清正，出生於現在縣廳所在地的中村","en":"Kato Kiyomasa, the warlord who built Kumamoto Castle, was born in Nakamura, now part of the prefectural capital.","ja":"熊本城を築いた加藤清正は、現在の県庁所在地にある中村の生まれ"},{"k":"sport","zh":"這裡的女子馬拉松2012年獲金氏認證為世界最大的女子馬拉松","en":"A women's marathon here was certified by Guinness in 2012 as the world's largest.","ja":"ここの女子マラソンは2012年、世界最大の女子マラソンとしてギネス認定された"},{"k":"life","zh":"這場女子馬拉松的完賽獎，是穿燕尾服的男士親手遞上的Tiffany墜飾","en":"Finishers of the women's marathon here receive a Tiffany pendant handed over by men in tuxedos.","ja":"この女子マラソンの完走賞は、タキシード姿の男性が手渡すティファニーのペンダント"},{"k":"work","zh":"柳田國男在伊良湖岬看到漂來的椰子，島崎藤村聽說後寫成詩〈椰子の実〉","en":"Kunio Yanagita saw a coconut washed ashore at Cape Irago; Shimazaki Toson turned it into the poem 'Yashi no Mi'.","ja":"柳田國男が伊良湖岬で見た漂着した椰子の実の話から、島崎藤村が詩「椰子の実」を書いた"},{"k":"festival","zh":"抱著自製竹筒向上噴出火柱的「手筒煙火」，發祥於豐橋的吉田神社","en":"Tezutsu hanabi, hand-held bamboo fireworks built by the performers themselves, began at Yoshida Shrine in Toyohashi.","ja":"自ら作った竹筒を抱えて火柱を上げる手筒花火は、豊橋の吉田神社が発祥とされる"},{"k":"festival","zh":"尾張津島天王祭的卷藁船掛滿500多個燈籠，2016年登錄聯合國無形文化遺產","en":"At the Owari Tsushima Tenno Festival, boats hung with 500-plus lanterns float by; UNESCO-listed in 2016.","ja":"尾張津島天王祭では500余りの提灯をまとう巻藁舟が浮かび、2016年にユネスコ無形文化遺産となった"},{"k":"origin","zh":"東部舊國名古時寫作「三川」，一說源自境內三條大河","en":"The eastern old province name was first written 'three rivers', possibly after three large rivers there.","ja":"東部の旧国名は古くは「三川」と書き、三つの大河に由来するとの説がある"},{"k":"symbol","zh":"1935年鳳來寺山的廣播實況，讓人發現「佛法僧」叫聲的主人其實是縣鳥東方角鴞","en":"A 1935 radio broadcast from Mt. Horaiji revealed the scops owl, the prefectural bird, made the 'buppōsō' call.","ja":"1935年の鳳来寺山からのラジオ中継で、「ブッポウソウ」の声の主が県の鳥コノハズクと判明した"},{"k":"life","zh":"塔摩利開玩笑說這裡把炸蝦念成「ebi-furyaa」，讓炸蝦被誤認為當地名物","en":"Comedian Tamori joked locals say 'ebi-furyā' for fried shrimp, making many think it a local specialty.","ja":"タモリが「エビフリャー」とネタにしたことで、エビフライが名物だと思われるようになった"},{"k":"record","zh":"縣廳所在地的電視塔1954年完工，是日本第一座集約式電波塔","en":"The capital's TV tower, completed in 1954, was Japan's first centralized broadcasting tower.","ja":"県庁所在地のテレビ塔は、1954年に完成した日本初の集約電波塔"},{"k":"record","zh":"市立科學館的天象儀圓頂直徑35公尺，2011年獲金氏認證為世界最大","en":"The city science museum's 35 m planetarium dome was certified by Guinness as the world's largest in 2011.","ja":"市科学館のプラネタリウムはドーム径35mで、2011年に世界最大としてギネス認定された"},{"k":"food","zh":"在台灣吃不到的「台灣拉麵」，1971年由台籍老闆在縣廳所在地的「味仙」發明","en":"'Taiwan ramen', unknown in Taiwan, was created in 1971 by the Taiwanese owner of Misen in the prefectural capital.","ja":"台湾にはない「台湾ラーメン」は、1971年に県庁所在地の「味仙」で台湾出身の店主が考案した"},{"k":"food","zh":"吐司抹紅豆餡的「小倉吐司」，起源於1921年左右學生把吐司泡進紅豆湯","en":"Ogura toast, sweet bean paste on toast, began around 1921 when students dipped toast into zenzai.","ja":"小倉トーストは1921年頃、学生がトーストをぜんざいに浸して食べたのが始まり"},{"k":"history","zh":"1575年長篠之戰，織田德川聯軍以鐵砲大敗武田勝頼","en":"At the 1575 Battle of Nagashino, Oda-Tokugawa gunners crushed Takeda Katsuyori's army.","ja":"1575年の長篠の戦いで、織田・徳川連合軍が鉄砲を用いて武田勝頼を破った"},{"k":"people","zh":"長篠城的鳥居強右衛門被武田軍俘虜後仍大喊援軍將至，因而被處死","en":"Captured by the Takeda, Nagashino's messenger Torii Suneemon shouted that help was coming and was executed.","ja":"長篠城の鳥居強右衛門は武田軍に捕らわれても援軍が近いと叫び、処刑された"},{"k":"life","zh":"日本第一家獲得許可營業的柏青哥店，1930年開在縣廳所在地","en":"Japan's first licensed pachinko parlor opened in the prefectural capital in 1930.","ja":"日本初の許可を受けたパチンコ店は、1930年に県庁所在地で開業した"},{"k":"brand","zh":"客美多咖啡1968年創業，店名來自創辦人家開的米店「米屋的太郎」","en":"Komeda's Coffee, founded here in 1968, is named after the founder's family rice shop: 'Rice-shop Taro'.","ja":"1968年創業のコメダ珈琲店の名は、創業者の実家の米屋「米屋の太郎」から"},{"k":"brand","zh":"可果美創辦人蟹江一太郎1899年在東海市開始種番茄，1903年做出番茄醬汁","en":"Kagome founder Ichitaro Kanie began growing tomatoes here in 1899 and made tomato sauce in 1903.","ja":"カゴメ創業者の蟹江一太郎は1899年にトマト栽培を始め、1903年にトマトソースを作った"},{"k":"brand","zh":"餐瓷品牌Noritake的名字不是人名，而是創業地「則武」的地名","en":"Tableware brand Noritake is named not after a person but after Noritake, the place where it was founded.","ja":"ノリタケは人名ではなく、創業地の地名「則武」に由来する"},{"k":"origin","zh":"1959年挙母市為了配合汽車產業改名為豐田市","en":"In 1959 the city of Koromo renamed itself Toyota after the carmaker based there.","ja":"1959年、挙母市は自動車産業にちなんで豊田市へ改名した"},{"k":"history","zh":"《日本書紀》記載668年新羅僧人道行偷走了熱田的草薙劍","en":"The Nihon Shoki records that a Silla monk named Dogyo stole the Kusanagi sword from Atsuta in 668.","ja":"『日本書紀』には、668年に新羅の僧・道行が熱田の草薙剣を盗んだと記される"}],
"JP-24":[{"k":"symbol","zh":"縣樹是「神宮杉」","en":"Its prefectural tree is the 'Jingū cedar'.","ja":"県の木は神宮スギ"},{"k":"symbol","zh":"縣鳥是在海岸沙灘上築巢的白千鳥（シロチドリ）","en":"Its prefectural bird is the Kentish plover, which nests on sandy beaches.","ja":"県の鳥は砂浜に巣をつくるシロチドリ"},{"k":"people","zh":"奧運女子角力三連霸的吉田沙保里出身這裡","en":"Wrestler Saori Yoshida, three-time Olympic champion, is from here.","ja":"五輪3連覇の女子レスリング・吉田沙保里の出身地"},{"k":"people","zh":"電影導演小津安二郎的少年時期在松阪度過","en":"Film director Yasujirō Ozu spent his boyhood in Matsusaka.","ja":"映画監督・小津安二郎は少年時代を松阪で過ごした"},{"k":"festival","zh":"桑名的「石取祭」數十台祭車一起敲鉦打鼓，號稱「日本最吵的祭典」","en":"At Kuwana's Ishidori Festival, dozens of floats pound gongs and drums at once: 'Japan's noisiest festival'.","ja":"桑名の石取祭は祭車の鉦と太鼓を一斉に打ち鳴らし「日本一やかましい祭」と呼ばれる"},{"k":"origin","zh":"傳說日本武尊疲憊地說「我的腳像折了好幾層的年糕」，成了名字由來","en":"Legend says an exhausted Yamato Takeru complained his legs felt folded like layered rice cakes, giving the name.","ja":"ヤマトタケルが疲れ果て「足が幾重にも曲がった餅のようだ」と言った伝説が名の由来"},{"k":"record","zh":"長島溫泉樂園的「鋼龍2000」全長 2479 公尺，曾是世界最長的雲霄飛車","en":"Steel Dragon 2000 at Nagashima Spa Land, 2,479 m long, was once the world's longest roller coaster.","ja":"ナガシマスパーランドの「スチールドラゴン2000」は全長2479mで、かつて世界最長"},{"k":"work","zh":"描寫都市青年到深山當林業學徒的電影《哪啊哪啊～神去村》，在這裡的美杉拍攝","en":"The film Wood Job!, about a city youth apprenticed to foresters, was shot in the Misugi area here.","ja":"林業見習いを描く映画『WOOD JOB!』は、ここの美杉地区で撮影された"},{"k":"people","zh":"三井家始祖三井高利出身松阪，在江戶開「越後屋」，以不賒帳、照定價收現金大賣","en":"Mitsui founder Mitsui Takatoshi, from Matsusaka, opened Echigoya in Edo, selling at fixed cash prices.","ja":"三井家の祖・三井高利は松阪出身で、江戸に越後屋を開き「現金掛け値なし」で繁盛した"},{"k":"people","zh":"被稱為「海賊大名」的九鬼嘉隆，率領志摩水軍替織田信長作戰","en":"Kuki Yoshitaka, the 'pirate daimyo', led the Shima navy in Oda Nobunaga's service.","ja":"「海賊大名」と呼ばれた九鬼嘉隆は、志摩の水軍を率いて織田信長に仕えた"},{"k":"sport","zh":"四日市高中1955年第一次打進夏季甲子園就奪得冠軍","en":"Yokkaichi High School won the 1955 summer Koshien tournament in its very first appearance.","ja":"四日市高校は1955年、夏の甲子園に初出場で初優勝した"},{"k":"work","zh":"十返舍一九《東海道中膝栗毛》裡，彌次與喜多從江戶出發，目的地是這裡的神宮","en":"In Jippensha Ikku's 'Shank's Mare' (1802), Yaji and Kita walk from Edo to the great shrine here.","ja":"十返舎一九『東海道中膝栗毛』で、弥次さん喜多さんが江戸から目指したのは伊勢参り"},{"k":"festival","zh":"每年8月17日的熊野大煙火，有快艇在海上投放煙火的「海上自爆」","en":"The Kumano fireworks every August 17 feature 'sea self-detonation', with shells dropped from speeding boats.","ja":"毎年8月17日の熊野大花火大会では、疾走する船から花火を海に投げ込む「海上自爆」が見もの"},{"k":"festival","zh":"伊賀的上野天神祭以「鬼行列」聞名，2016年登錄聯合國無形文化遺產","en":"Iga's Ueno Tenjin Festival, known for its parade of demons, was UNESCO-listed in 2016.","ja":"伊賀の上野天神祭は鬼行列で知られ、2016年にユネスコ無形文化遺産となった"},{"k":"life","zh":"依照不同的分法，這裡既屬於近畿地方，也被算進東海地方","en":"Depending on the definition, this prefecture counts as part of both the Kinki and Tokai regions.","ja":"区分によって近畿地方にも東海地方にも含まれる県"},{"k":"life","zh":"伊勢志摩一帶常見掛著「蘇民將來子孫家門」木牌的注連繩","en":"Around Ise-Shima, shimenawa ropes bear wooden tags reading 'House of the descendants of Somin Shorai'.","ja":"伊勢志摩では「蘇民将来子孫家門」の木札がついたしめ縄が広く見られる"},{"k":"life","zh":"江戶時代無法親自前往的人，會讓狗代替主人去參拜神宮，稱為「御蔭犬」","en":"In the Edo period, people unable to make the pilgrimage sent their dogs instead, known as 'okage-inu'.","ja":"江戸時代、参拝に行けない人の代わりに犬が伊勢参りをし、「おかげ犬」と呼ばれた"},{"k":"history","zh":"大約每60年爆發一次的「御蔭參拜」，1830年那次估計湧進約427萬人","en":"Mass pilgrimages here erupted about every 60 years; the 1830 wave drew an estimated 4.27 million people.","ja":"約60年周期で起きた「おかげ参り」は、1830年に約427万人が押し寄せたとされる"},{"k":"history","zh":"1581年織田軍從多路攻入伊賀，大約兩週就平定了這片土地","en":"In 1581 Oda forces invaded Iga from several directions and subdued it in about two weeks.","ja":"1581年の天正伊賀の乱で、織田軍は伊賀に攻め込み約2週間で平定した"},{"k":"history","zh":"從古代到南北朝，侍奉神宮的未婚皇女住在明和町的「齋宮」","en":"Until the 14th century, unmarried imperial princesses serving the great shrine lived at Saiku in Meiwa.","ja":"古代から南北朝時代まで、伊勢神宮に仕える未婚の皇女は明和町の斎宮で暮らした"},{"k":"record","zh":"熊野的丸山千枚田約有1340塊梯田，最小的一塊只有0.5平方公尺","en":"Kumano's Maruyama Senmaida has about 1,340 terraced paddies; the smallest is just 0.5 m².","ja":"熊野の丸山千枚田には約1340枚の棚田があり、最も小さい田は0.5m²"},{"k":"nature","zh":"尾鷲年雨量約4000毫米，1954年更下了6174.5毫米","en":"Owase gets about 4,000 mm of rain a year, and recorded 6,174.5 mm in 1954.","ja":"尾鷲は年間降水量約4000mmの多雨地で、1954年には6174.5mmを記録した"},{"k":"nature","zh":"長約25公里的七里御濱是日本最長的礫石海岸，赤蠵龜會上岸產卵","en":"Shichiri-mihama, about 25 km long, is Japan's longest gravel beach, where loggerhead turtles nest.","ja":"約25kmの七里御浜は日本一長い砂礫海岸で、アカウミガメが産卵に来る"},{"k":"legend","zh":"傳說坂上田村麻呂在海蝕洞「鬼之城」討伐了海盜鬼王多娥丸","en":"Legend says Sakanoue no Tamuramaro defeated the pirate demon Tagamaru at the sea caves of Onigajo.","ja":"海食洞の「鬼ヶ城」は、坂上田村麻呂が海賊の鬼・多娥丸を退治した地と伝わる"},{"k":"legend","zh":"傳說倭姬命帶著天照大神巡遊伊賀、近江、美濃等地，最後在這裡建立內宮","en":"Legend says Princess Yamatohime carried Amaterasu through many provinces before founding the Inner Shrine here.","ja":"倭姫命は天照大神を奉じて伊賀・近江・美濃などを巡り、最後にこの地で内宮を創建したと伝わる"},{"k":"food","zh":"炸蝦飯糰「天むす」1950年代誕生於縣廳所在地的「千壽」，原本是員工餐","en":"Tenmusu, shrimp-tempura rice balls, began in the 1950s as a staff meal at Senju in the prefectural capital.","ja":"天むすは1950年代、県庁所在地の「千寿」でまかないとして生まれた"},{"k":"food","zh":"志摩漁夫在船上把醬油醃過的鰹魚用手拌進飯裡，就是「手捏壽司」","en":"Shima fishermen created tekone-zushi by hand-mixing soy-marinated bonito into rice on their boats.","ja":"志摩の漁師が船上でタレに漬けたカツオを手でご飯に混ぜたのが「てこね寿司」"},{"k":"brand","zh":"創業於松阪的井村屋1973年推出紅豆冰棒，硬到刀具廠商曾測不出硬度","en":"Imuraya's Azuki Bar (1973) is famously hard; a blade maker once failed to measure its hardness.","ja":"井村屋の「あずきバー」（1973年発売）は硬さで有名で、刃物メーカーが硬度を測れなかった"},{"k":"brand","zh":"四日市的萬古燒開發出耐直火的陶土，土鍋約占日本國產的八成","en":"Yokkaichi's Banko ware, made with heat-resistant clay, accounts for about 80% of Japan's donabe pots.","ja":"四日市の萬古焼は直火に強い土を開発し、土鍋の国内シェア約8割を占める"},{"k":"brand","zh":"飯糰形狀的醬油仙貝「おにぎりせんべい」1969年由伊勢的マスヤ推出，關西人特別愛吃","en":"Onigiri Senbei, rice-ball-shaped crackers launched in 1969 by Masuya of Ise, are a Kansai staple.","ja":"1969年に伊勢のマスヤが発売した「おにぎりせんべい」は、関西で定番の菓子"},{"k":"brand","zh":"2004年夏普龜山工廠投產，「世界的龜山」成了液晶電視的代名詞","en":"Sharp's Kameyama plant, opened in 2004, made 'Sekai no Kameyama' a byword for LCD TVs.","ja":"2004年稼働のシャープ亀山工場の「世界の亀山」は、液晶テレビの代名詞になった"}],
"JP-25":[{"k":"symbol","zh":"縣鳥是擅長潛水的小鸊鷉（カイツブリ）","en":"Its prefectural bird is the little grebe, a small diving waterbird.","ja":"県の鳥は潜水が得意なカイツブリ。"},{"k":"people","zh":"戰國武將石田三成出生在這裡的長濱一帶","en":"Sengoku warlord Ishida Mitsunari was born here, in today's Nagahama.","ja":"戦国武将・石田三成は現在の長浜市石田町の生まれ。"},{"k":"work","zh":"動畫《K-ON！輕音部》高中的原型是這裡的豐鄉小學舊校舍","en":"The old Toyosato Elementary School here was the model for the high school in the anime K-On!","ja":"アニメ『けいおん!』の高校のモデルは豊郷小学校旧校舎。"},{"k":"sport","zh":"電視節目「鳥人間大賽」的人力飛機比賽在這裡的彥根湖畔舉行","en":"The TV Birdman Rally, a human-powered flight contest, is held on the lakeshore in Hikone.","ja":"人力飛行機の「鳥人間コンテスト」は彦根市の湖岸が会場。"},{"k":"festival","zh":"長濱曳山祭由孩童在山車舞台上演歌舞伎，列入聯合國非遺","en":"At the Nagahama Hikiyama Festival, children perform kabuki on float stages; it is UNESCO-listed.","ja":"長浜曳山祭では曳山の舞台で子ども歌舞伎を演じる。ユネスコ無形文化遺産。"},{"k":"record","zh":"伊吹山 1927 年積雪 11.82 公尺，至今仍是世界最深積雪紀錄","en":"Mt. Ibuki recorded 11.82 m of snow in 1927, still the world's deepest snow on record.","ja":"伊吹山は1927年に積雪1182cmを記録、今も破られていない世界記録。"},{"k":"life","zh":"路邊「衝出男孩」交通安全看板 1973 年起源於這裡","en":"The 'jumping-out boy' child-safety signboards originated here in 1973.","ja":"交通安全の看板「飛び出し坊や」は1973年にここで生まれた。"},{"k":"record","zh":"2020 年男性平均壽命 82.73 歲，全國第一","en":"Men here had Japan's longest life expectancy in 2020: 82.73 years.","ja":"2020年の男性の平均寿命は82.73歳で全国1位。"},{"k":"people","zh":"幕末大老井伊直弼生於這裡的彥根，「一期一會」一詞就出自他的茶道著作","en":"Bakumatsu chief minister Ii Naosuke, born in Hikone here, wrote \"ichigo ichie\" in his tea-ceremony book.","ja":"幕末の大老・井伊直弼は○○の彦根生まれで、茶道書に「一期一会」の語を記した。"},{"k":"people","zh":"茶茶、初、江「淺井三姊妹」，是這裡的戰國大名淺井長政與阿市的女兒","en":"The three Azai sisters, Chacha, Hatsu and Gō, were daughters of Azai Nagamasa, a warlord here, and Oichi.","ja":"茶々・初・江の「浅井三姉妹」は、○○の戦国大名・浅井長政とお市の娘。"},{"k":"people","zh":"美國人沃里斯 1905 年來這裡當英文老師後留下傳教，還把曼秀雷敦引進日本","en":"American W. M. Vories came here to teach English in 1905, stayed as a missionary and brought Mentholatum to Japan.","ja":"1905年に英語教師として○○に来た米国人ヴォーリズは、伝道を続けメンソレータムを日本に広めた。"},{"k":"people","zh":"伊藤忠商事與丸紅共同的創始人伊藤忠兵衛，出身這裡的豐鄉","en":"Itō Chūbei, the founder behind both trading giants Itochu and Marubeni, was born in Toyosato here.","ja":"伊藤忠商事と丸紅に共通する創業者・初代伊藤忠兵衛は○○の豊郷出身。"},{"k":"brand","zh":"洋馬創辦人山岡孫吉出身這裡，1933 年研發出世界第一台小型柴油引擎","en":"Yanmar founder Yamaoka Magokichi, born here, built the world's first small diesel engine in 1933.","ja":"ヤンマー創業者の山岡孫吉は○○出身で、1933年に世界初の小型ディーゼルエンジンを開発した。"},{"k":"sport","zh":"競技歌牌的名人位、女王位決定戰，每年 1 月都在這裡祭祀天智天皇的神宮舉行","en":"Each January the top competitive karuta title matches are held at a shrine here to Emperor Tenji.","ja":"競技かるたの名人位・クイーン位決定戦は毎年1月、○○の天智天皇を祀る神宮で行われる。"},{"k":"work","zh":"漫畫《花牌情緣》裡的歌牌聖地，就是這裡祭祀天智天皇的神宮","en":"The karuta holy ground in the manga \"Chihayafuru\" is a shrine here dedicated to Emperor Tenji.","ja":"漫画『ちはやふる』でかるたの聖地として登場するのは、○○の天智天皇を祀る神宮。"},{"k":"festival","zh":"據說織田信長曾在這裡的左義長祭盛裝起舞，這個火祭至今每年 3 月舉行","en":"Oda Nobunaga is said to have danced in flamboyant dress at the Sagichō fire festival here, still held each March.","ja":"織田信長が派手な装いで踊ったと伝わる○○の左義長まつりは、今も毎年3月に行われる。"},{"k":"origin","zh":"豐臣秀吉把這裡的「今濱」改名「長濱」，「長」字取自主君織田信長","en":"Hideyoshi renamed Imahama here \"Nagahama,\" taking the \"naga\" from his lord Oda Nobunaga's name.","ja":"秀吉は○○の「今浜」を、主君・信長の名から一字もらって「長浜」と改めた。"},{"k":"origin","zh":"三井寺之名源自寺中靈泉，曾是天智、天武、持統三位天皇出生時的洗澡水","en":"Miidera's name comes from its sacred spring, used to bathe three emperors at birth: Tenji, Tenmu and Jitō.","ja":"三井寺の名は、霊泉が天智・天武・持統の三天皇の産湯に使われた「御井の寺」に由来する。"},{"k":"symbol","zh":"只分布在這裡大湖的鱒魚，會在大雨天成群溯溪產卵，古稱「雨之魚」","en":"A trout found only in the big lake here swims upriver in heavy rain, hence its old name \"rain fish.\"","ja":"○○の湖だけにすむマスは、大雨の日に群れで川を遡ることから「アメノウオ」と呼ばれる。"},{"k":"symbol","zh":"日本最大的鯰魚可長到 120 公分，只住在這裡的大湖與下游淀川水系","en":"Japan's largest catfish, up to 120 cm long, lives only in the big lake here and the Yodo River system.","ja":"体長120cmに達する日本最大のナマズは、○○の湖と淀川水系にしかいない。"},{"k":"symbol","zh":"吉祥物「ひこにゃん」戴著武士頭盔，原型是招手讓藩主井伊直孝躲過雷擊的白貓","en":"Mascot Hikonyan, a helmeted cat, recalls the white cat that beckoned lord Ii Naotaka away from lightning.","ja":"ゆるキャラ「ひこにゃん」は、井伊直孝を手招きして落雷から救った白猫がモデル。"},{"k":"record","zh":"湖中的沖島是日本唯一位在淡水湖、沒有橋相連的有人島，島上沒有汽車","en":"Okishima here is Japan's only inhabited island in a freshwater lake with no bridge, and it has no cars.","ja":"○○の沖島は、橋のない淡水湖の有人島として日本唯一で、島に自動車はない。"},{"k":"record","zh":"縣內大湖約 440 萬年前誕生，是世界屈指可數的古代湖，特有種多達 66 種","en":"The big lake here formed about 4.4 million years ago, one of the world's oldest lakes, with 66 endemic species.","ja":"○○の湖は約440万年前に生まれた世界有数の古代湖で、固有種は66種にのぼる。"},{"k":"life","zh":"縣內小學五年級生會搭學習船「海之子（うみのこ）」，在湖上航行並住一晚","en":"Fifth-graders here sail the lake aboard the school ship \"Uminoko\" and spend a night on board.","ja":"○○の小学5年生は学習船「うみのこ」に乗って湖を航海し、船内に一泊する。"},{"k":"life","zh":"明明不靠海，境內卻有 20 個漁港，全都開在湖邊","en":"Though landlocked, this prefecture has 20 fishing ports, all on its lake.","ja":"海のない○○だが、湖に面した漁港が20港もある。"},{"k":"food","zh":"這裡長濱的老麵包店賣「沙拉麵包」，夾的是醃蘿蔔拌美乃滋","en":"A bakery in Nagahama here sells \"salad bread\": a roll filled with chopped pickled radish in mayo.","ja":"○○長浜のつるやパンの「サラダパン」は、刻んだたくあんをマヨネーズで和えて挟む。"},{"k":"food","zh":"這裡的近江八幡吃紅色蒟蒻，鮮紅色來自加入的氧化鐵","en":"In Ōmihachiman here, konjac is dyed bright red with iron oxide.","ja":"○○の近江八幡では、三二酸化鉄で赤く染めた「赤こんにゃく」を食べる。"},{"k":"history","zh":"667 年天智天皇把都城從飛鳥遷到這裡，672 年壬申之亂後廢都","en":"In 667 Emperor Tenji moved the capital here from Asuka; it was abandoned after the Jinshin War of 672.","ja":"667年、天智天皇は都を飛鳥から○○へ移したが、壬申の乱後の672年に廃された。"},{"k":"history","zh":"1571 年織田信長以援助淺井、朝倉聯軍為由，火燒這裡的比叡山","en":"In 1571 Oda Nobunaga burned the temples on Mt. Hiei here for aiding the Azai-Asakura alliance.","ja":"1571年、織田信長は浅井・朝倉軍を助けたとして○○の比叡山を焼き討ちにした。"},{"k":"history","zh":"1570 年姊川之戰太過慘烈，戰場附近留下「血原」「血川」等地名","en":"The 1570 Battle of Anegawa here was so bloody that nearby places were named \"Blood Field\" and \"Blood River.\"","ja":"1570年の○○での姉川の戦いの激しさは、「血原」「血川」という地名に残る。"},{"k":"nature","zh":"約 450 條河流注入縣內大湖，自然流出的卻只有瀨田川，下游改名宇治川、淀川","en":"About 450 rivers feed the big lake here, but only the Seta drains it, later becoming the Uji and Yodo.","ja":"○○の湖には約450本の川が注ぐが、自然に流れ出るのは瀬田川だけで、宇治川・淀川となる。"},{"k":"nature","zh":"比良山地吹下的強風「比良颪」，3 月下旬那陣被視為春天到來的信號","en":"The Hira-oroshi wind sweeps down the Hira Mountains here; its late-March gusts herald spring.","ja":"○○の比良山地から吹く「比良おろし」は、3月下旬の荒れが春の訪れを告げる風物詩。"},{"k":"legend","zh":"傳說俵藤太除掉這裡三上山的大蜈蚣，作為謝禮從龍宮帶回一口大鐘","en":"Legend says Tawara Tōda slew the giant centipede of Mt. Mikami here and brought back a bell from the Dragon Palace.","ja":"俵藤太は○○の三上山の大ムカデを退治し、礼に竜宮から鐘を持ち帰ったと伝わる。"},{"k":"legend","zh":"傳說弁慶把三井寺的鐘拖上比叡山，鐘卻響著「想回家」，氣得他丟進山谷","en":"Legend says Benkei dragged Miidera's bell up Mt. Hiei, but it rang \"I want to go home,\" so he hurled it away.","ja":"弁慶が三井寺の鐘を比叡山へ引き摺り上げると「イノー（帰りたい）」と鳴り、谷へ投げ捨てたという。"},{"k":"legend","zh":"傳說伊吹山之神比高輸給姪女淺井岳，砍下她的頭，頭落進湖中成了竹生島","en":"Legend says Mt. Ibuki's god lost a height contest to Mt. Asai's goddess and cut off her head, forming Chikubu Island.","ja":"背比べに負けた伊吹山の神が浅井岳の神の首を切り、湖に落ちた首が竹生島になったという。"}],
"JP-26":[{"k":"work","zh":"動畫《吹響吧！上低音號》以作者故鄉、這裡的宇治為舞台","en":"The anime Sound! Euphonium is set in Uji here, the author's hometown.","ja":"アニメ『響け!ユーフォニアム』の舞台は作者の地元・宇治市。"},{"k":"life","zh":"市中心地址用「上ル（往北）、下ル（往南）」等方向詞標示","en":"Downtown addresses use direction words such as agaru (go north) and sagaru (go south) from street crossings.","ja":"中心部の住所は通り名に「上ル・下ル・西入ル」と方向を付けて表す。"},{"k":"origin","zh":"名字的兩個字都是「首都」的意思","en":"Both characters of its name mean 'capital'.","ja":"名前の2文字はどちらも「みやこ（首都）」を意味する。"},{"k":"record","zh":"1869 年居民自建 64 所「番組小學校」，比國家學制更早，是日本最早的學區制小學","en":"In 1869 locals founded 64 'bangumi' schools, Japan's first school-district elementary schools, before the national system.","ja":"1869年に64の番組小学校が開校。学制より早い日本初の学区制小学校。"},{"k":"record","zh":"1895 年日本第一條營業用電車（路面電車）在這裡通車","en":"Japan's first commercial electric streetcar began running here in 1895.","ja":"1895年、日本初の営業用電車（路面電車）がここで開業した。"},{"k":"sport","zh":"每年 12 月的全國高中驛傳（長跑接力）都在這裡的街道舉行","en":"Every December the national high school ekiden relay race is run through its streets.","ja":"毎年12月の全国高校駅伝は、この街の「都大路」が舞台。"},{"k":"festival","zh":"時代祭的遊行從明治維新開始，一路倒著走回八世紀","en":"The Jidai Matsuri parade runs history backward, from the Meiji Restoration to the 8th century.","ja":"時代祭の行列は明治維新から始まり、時代をさかのぼって延暦へ。"},{"k":"people","zh":"幕末的新選組在這裡的壬生設屯所，因池田屋事件成名","en":"The Shinsengumi were based in Mibu here and rose to fame through the Ikedaya Incident.","ja":"新選組は壬生に屯所を置き、池田屋事件で名を上げた。"},{"k":"people","zh":"以機智故事聞名的一休宗純晚年住在這裡的酬恩庵（一休寺），1481 年在此圓寂","en":"Zen monk Ikkyū spent his last years at Shūon-an, now called Ikkyū-ji, here and died there in 1481.","ja":"とんち話で知られる一休宗純は、○○の酬恩庵（一休寺）で晩年を過ごし、1481年に没した。"},{"k":"sport","zh":"江戶時代流行在三十三間堂長廊射「通矢」，1686 年和佐大八郎一晝夜射穿 8133 箭","en":"In 1686 archer Wasa Daihachirō shot 8,133 arrows the full length of Sanjūsangen-dō's veranda here.","ja":"○○の三十三間堂の軒下を射通す「通し矢」で、1686年に和佐大八郎が8133本を記録した。"},{"k":"sport","zh":"每年 1 月 4 日下鴨神社舉行「蹴鞠初」，重現平安貴族踢鞠的遊戲","en":"Every January 4, Shimogamo Shrine here holds Kemari Hajime, reviving the kickball game of Heian nobles.","ja":"○○の下鴨神社では毎年1月4日、平安貴族の遊び・蹴鞠を行う「蹴鞠はじめ」がある。"},{"k":"work","zh":"小說《四疊半宿舍，青春迷走》的主角，是住在這裡下鴨公寓的大學三年級男生","en":"The hero of \"The Tatami Galaxy\" is a third-year university student living in a boarding house in Shimogamo here.","ja":"森見登美彦『四畳半神話大系』の主人公は、○○下鴨の下宿に住む大学3年生。"},{"k":"festival","zh":"每年 5 月 15 日的葵祭，以葵葉裝飾的王朝行列遊行，由「齋王代」率領女官隊伍","en":"Each May 15 the Aoi Festival parades hollyhock-decked courtiers; the Saiō-dai leads its women's procession.","ja":"毎年5月15日の葵祭では葵の葉で飾った王朝行列が進み、斎王代が女人列を率いる。"},{"k":"festival","zh":"每年 10 月 22 日夜的鞍馬火祭，源自 940 年迎接由岐明神時沿路點起的篝火","en":"Kurama's Fire Festival on the night of Oct 22 recalls the bonfires lit to welcome a deity there in 940.","ja":"○○の鞍馬の火祭（10月22日夜）は、940年に由岐明神を迎えた際の篝火が起源とされる。"},{"k":"origin","zh":"花街「先斗町」讀作 ponto，一說源自葡萄牙語 ponta（尖端）","en":"The geisha district Pontochō here may take its name from the Portuguese \"ponta\" (point).","ja":"○○の花街・先斗町（ぽんとちょう）の名は、ポルトガル語のponta（先）に由来する説がある。"},{"k":"origin","zh":"地名「太秦」讀作うずまさ，源自渡來氏族秦氏把絹「堆得高高的」獻給天皇","en":"Uzumasa here is said to come from the Hata clan piling silk tribute \"uzutakaku,\" in tall heaps.","ja":"○○の太秦（うずまさ）は、秦酒公が絹をうず高く積んだ功で賜った号に由来するという。"},{"k":"origin","zh":"一條戾橋得名於 918 年淨藏在橋上為亡父祈禱，父親竟一度復活","en":"Modoribashi, \"return bridge,\" is named for a monk whose prayers on it in 918 briefly revived his dead father.","ja":"一条戻橋の名は、918年に浄蔵が橋で祈ると亡き父が一時生き返った話に由来する。"},{"k":"symbol","zh":"舞鶴外海的無人島冠島全島是天然紀念物，也是西日本最大的大水薙鳥繁殖地","en":"Uninhabited Kanmurijima off Maizuru, a natural monument, is western Japan's largest streaked shearwater colony.","ja":"舞鶴沖の無人島・冠島は島全体が天然記念物で、西日本最大のオオミズナギドリ繁殖地。"},{"k":"record","zh":"1891 年啟用的蹴上發電廠，是日本第一座商業用水力發電廠","en":"The Keage plant here, opened in 1891, was Japan's first commercial hydroelectric power station.","ja":"1891年に運転を始めた○○の蹴上発電所は、日本初の営業用水力発電所。"},{"k":"record","zh":"東寺五重塔高 54.8 公尺，是日本最高的木造塔","en":"Tō-ji's five-story pagoda here, at 54.8 m, is the tallest wooden tower in Japan.","ja":"○○の東寺五重塔は高さ54.8mで、木造の塔として日本一高い。"},{"k":"record","zh":"三十三間堂（蓮華王院）內一字排開 1001 尊千手觀音立像","en":"Sanjūsangen-dō here houses 1,001 standing statues of the thousand-armed Kannon.","ja":"○○の三十三間堂（蓮華王院）には、千手観音立像が1001体並ぶ。"},{"k":"life","zh":"鴨川岸邊的情侶總是隔著差不多的距離坐，被稱為「鴨川等間隔法則」","en":"Couples on the Kamo River banks here sit at strikingly equal spacing, dubbed the \"equal-interval law.\"","ja":"○○の鴨川の河原でカップルが等間隔に並ぶ現象は「鴨川等間隔の法則」と呼ばれる。"},{"k":"life","zh":"傳說這裡的人問客人「要不要吃碗茶泡飯」是在暗示該回家了，這說法主要來自落語","en":"The idea that offering guests rice in tea here means \"please leave\" mostly comes from a rakugo story.","ja":"○○で「ぶぶ漬けでもどうどす」が帰れの合図という話は、主に落語の小噺から広まった。"},{"k":"food","zh":"生命力強的海鰻能活著運到這座內陸城市，因此祇園祭又被稱為「海鰻祭」","en":"Hardy pike conger could reach this inland city alive, so the Gion Festival is also called the \"Hamo Festival.\"","ja":"生命力の強いハモは生きたまま運べたため○○で好まれ、祇園祭は「ハモ祭り」とも呼ばれる。"},{"k":"food","zh":"若狹的鯖魚抹鹽後步行一整天運到這裡，抵達時鹹度剛好，這條路稱為「鯖街道」","en":"Salted mackerel walked a full day from Wakasa arrived here perfectly seasoned, giving the \"Mackerel Road\" its name.","ja":"若狭で塩をした鯖は丸一日かけて○○へ運ばれ、着く頃ちょうどよい塩加減になった（鯖街道）。"},{"k":"food","zh":"加上鯡魚乾的「鯡魚蕎麥麵」，1882 年由南座旁的老店「松葉」發明","en":"Nishin soba, noodles with dried herring, was created in 1882 at Matsuba beside the Minamiza theater here.","ja":"身欠きにしんをのせる「にしんそば」は、1882年に○○の南座そばの「松葉」で考案された。"},{"k":"food","zh":"御手洗糰子據說是模仿下鴨神社御手洗池湧出的水泡做成的","en":"Mitarashi dango are said to imitate the bubbles rising in the Mitarashi pond at Shimogamo Shrine here.","ja":"みたらし団子は、○○の下鴨神社の御手洗池に湧く水泡をかたどったのが発祥とされる。"},{"k":"brand","zh":"連鎖餐廳「餃子的王將」1967 年在這裡的四條大宮開出第一家店","en":"The Gyoza no Ohsho chain opened its first restaurant at Shijō-Ōmiya here in 1967.","ja":"「餃子の王将」は1967年、○○の四条大宮に1号店を開いた。"},{"k":"brand","zh":"這裡的島津製作所 1909 年做出日本第一台醫療用 X 光機，員工田中耕一後來獲諾貝爾獎","en":"Shimadzu here built Japan's first medical X-ray unit in 1909; its engineer Tanaka Kōichi won a 2002 Nobel Prize.","ja":"○○の島津製作所は1909年に日本初の医療用X線装置を完成させ、社員の田中耕一はノーベル化学賞を受けた。"},{"k":"history","zh":"1867 年將軍德川慶喜在二條城宣布大政奉還，把政權交還天皇","en":"In 1867 shogun Tokugawa Yoshinobu returned political power to the emperor at Nijō Castle here.","ja":"1867年、徳川慶喜は○○の二条城で大政奉還を表明し、政権を天皇に返上した。"},{"k":"history","zh":"1864 年長州藩進攻皇宮的蛤御門之變，引發「咚咚燒」大火，燒毀約 3 萬戶","en":"The 1864 Hamaguri Gate Rebellion here sparked the \"Dondon-yake\" fire, which burned about 30,000 homes.","ja":"1864年の蛤御門の変で起きた「どんどん焼け」は、○○の市街約3万戸を焼いた。"},{"k":"history","zh":"1867 年坂本龍馬與中岡慎太郎在這裡河原町一家醬油商的宅邸遇刺","en":"Sakamoto Ryōma and Nakaoka Shintarō were assassinated at a soy-sauce merchant's house in Kawaramachi here in 1867.","ja":"1867年、坂本龍馬と中岡慎太郎は○○河原町の醤油商の家で暗殺された。"},{"k":"nature","zh":"1606 年角倉了以只花 5 個月整治保津川急流，讓船能從丹波直通嵐山","en":"In 1606 Suminokura Ryōi tamed the Hozu River rapids in five months, opening a boat route from Tanba to Arashiyama.","ja":"角倉了以は1606年、わずか5か月で保津川を開削し、丹波から○○の嵐山へ舟が通えるようにした。"},{"k":"legend","zh":"傳說陰陽師安倍晴明的妻子害怕式神，他便把十二神將藏在一條戾橋下","en":"Legend says Abe no Seimei hid his twelve spirit servants under Ichijō Modoribashi because his wife feared them.","ja":"安倍晴明は妻が怖がるので、式神の十二神将を○○の一条戻橋の下に隠したという。"},{"k":"legend","zh":"鬼王酒吞童子住在這裡的大江山，被假扮山伏的源賴光一行用毒酒灌醉後斬首","en":"Demon king Shuten-dōji lived on Mt. Ōe here until Minamoto no Raikō's band got him drunk on poisoned sake.","ja":"鬼の頭領・酒呑童子は○○の大江山に住み、山伏に化けた源頼光らに毒酒で酔わされ討たれた。"},{"k":"legend","zh":"猴臉、狸身、虎腳、蛇尾的妖怪「鵺」，據說在皇宮清涼殿上空被源賴政射落","en":"The nue, with monkey face, tanuki body, tiger legs and snake tail, was shot down over the imperial palace here.","ja":"猿の顔、狸の胴、虎の手足、蛇の尾の鵺は、○○の内裏・清涼殿の上で源頼政に射落とされた。"},{"k":"legend","zh":"丹後半島伊根的浦嶋神社，主祭神就是浦島太郎（浦嶋子），相傳 825 年創建","en":"A shrine in Ine on the Tango Peninsula here enshrines Urashima Tarō himself; tradition dates it to 825.","ja":"○○伊根町の浦嶋神社は浦島太郎（浦嶋子）を主祭神とし、825年の創建と伝わる。"},{"k":"legend","zh":"舞鶴外海的冠島，傳說是遠古大地震時沉入海中的「凡海鄉」山頂","en":"Kanmurijima off Maizuru is said to be the peak of Ōshiama, a land sunk by an ancient earthquake.","ja":"舞鶴沖の冠島は、大地震で海に沈んだ「凡海郷」の山の頂だと伝えられる。"}],
"JP-27":[{"k":"symbol","zh":"宣傳吉祥物是一隻伯勞鳥，叫「もずやん」","en":"Its PR mascot is a shrike character named Mozuyan.","ja":"PRキャラクターはモズがモチーフの「もずやん」。"},{"k":"sport","zh":"全國高中橄欖球大賽的會場「花園」被稱為橄欖球聖地","en":"Hanazono, home of the national high school rugby tournament, is called the sacred ground of rugby.","ja":"全国高校ラグビーの会場「花園」はラグビーの聖地と呼ばれる。"},{"k":"people","zh":"《龍馬行》作者司馬遼太郎在這裡出生，晚年也住在這裡","en":"Novelist Ryotaro Shiba, author of Ryoma ga Yuku, was born here and spent his later life here.","ja":"『竜馬がゆく』の司馬遼太郎はここで生まれ、晩年もここで暮らした。"},{"k":"life","zh":"關西搭電扶梯「站右邊、左邊讓人走」的習慣，1967 年起於這裡的阪急梅田站","en":"Kansai's habit of standing on the right of escalators began at Hankyu Umeda Station here in 1967.","ja":"エスカレーターで左を空ける関西の習慣は、1967年の阪急梅田駅から。"},{"k":"record","zh":"迴轉壽司 1958 年誕生於這裡的布施，靈感來自啤酒工廠輸送帶","en":"Conveyor-belt sushi was born here in Fuse in 1958, inspired by beer factory conveyors.","ja":"回転寿司は1958年に布施で誕生。ビール工場のベルトコンベアが発想源。"},{"k":"festival","zh":"岸和田地車祭的看點是拉著沉重山車全速甩過街角的「やりまわし」","en":"Kishiwada's Danjiri Festival is famed for yarimawashi, swinging heavy floats around corners at full speed.","ja":"岸和田だんじり祭の見せ場は、勢いのまま角を曲がる「やりまわし」。"},{"k":"origin","zh":"地名原本的「坂」字可拆成「土」「反」，被嫌像歸於塵土不吉而改字","en":"The 'slope' character in its name was changed because it could be read as 'return to earth', a bad omen.","ja":"地名の「坂」は「土に反る」と読めて縁起が悪いとされ、字が改められた。"},{"k":"people","zh":"歌人與謝野晶子出生在這裡的堺，家裡是和菓子老舖「駿河屋」","en":"Poet Yosano Akiko was born in Sakai here, daughter of the old Suruga-ya confectionery.","ja":"歌人・与謝野晶子は○○の堺で、老舗和菓子屋「駿河屋」の娘として生まれた。"},{"k":"people","zh":"漫畫之神手塚治虫出生在這裡的豐中，5 歲才隨家人搬走","en":"Tezuka Osamu, the \"god of manga,\" was born in Toyonaka here and moved away at age five.","ja":"漫画の神様・手塚治虫は○○の豊中で生まれ、5歳で一家とともに転居した。"},{"k":"people","zh":"緒方洪庵 1838 年在這裡的船場開設蘭學塾「適塾」，福澤諭吉曾任塾頭","en":"Ogata Kōan opened the Tekijuku school of Dutch learning here in 1838; Fukuzawa Yukichi became its head pupil.","ja":"緒方洪庵は1838年、○○の船場に蘭学塾「適塾」を開き、福澤諭吉も塾頭を務めた。"},{"k":"sport","zh":"夏季甲子園的前身，1915 年第一屆全國中等學校棒球大賽在這裡的豐中舉行","en":"The first national middle-school baseball tournament, forerunner of summer Kōshien, was held in Toyonaka here in 1915.","ja":"夏の甲子園の前身、第1回全国中等学校優勝野球大会は1915年に○○の豊中で開かれた。"},{"k":"work","zh":"近松門左衛門的《曾根崎心中》，取材自 1703 年在這裡露天神社森林發生的殉情","en":"Chikamatsu's \"The Love Suicides at Sonezaki\" retells a real 1703 double suicide in a shrine grove here.","ja":"近松門左衛門『曽根崎心中』は、1703年に○○の露天神社の森で起きた心中事件が題材。"},{"k":"work","zh":"《名偵探柯南》中與工藤新一齊名的高中生偵探服部平次，住在這裡的寢屋川","en":"In \"Detective Conan,\" rival teen detective Heiji Hattori is from here and lives in Neyagawa.","ja":"『名探偵コナン』の「西の高校生探偵」服部平次は○○出身で、寝屋川市に住む。"},{"k":"festival","zh":"今宮戎神社每年 1 月 9 至 11 日的「十日戎」，由公開招募選出的「福娘」服務參拜者","en":"Imamiya Ebisu Shrine's Tōka Ebisu, Jan 9 to 11, is served by publicly chosen \"fuku-musume\" maidens.","ja":"○○の今宮戎神社の十日戎（1月9〜11日）では、公募で選ばれた「福むすめ」が奉仕する。"},{"k":"festival","zh":"住吉大社每年 6 月 14 日在神田舉行插秧神事，是國家重要無形民俗文化財","en":"Sumiyoshi Taisha here holds a rice-planting rite every June 14, a designated intangible folk cultural property.","ja":"○○の住吉大社では毎年6月14日、境内の御田で御田植神事が行われる。"},{"k":"origin","zh":"露天神社俗稱「阿初天神」，名字來自《曾根崎心中》女主角阿初","en":"Tsuyu no Tenjin Shrine here is nicknamed \"Ohatsu Tenjin\" after the heroine of a famous love-suicide play.","ja":"○○の露天神社は、『曽根崎心中』のヒロインの名から「お初天神」と呼ばれる。"},{"k":"record","zh":"住吉大社是全國住吉神社的總本社，正殿的「住吉造」是最古老的神社樣式之一","en":"Sumiyoshi Taisha here heads all Sumiyoshi shrines; its main halls show one of the oldest shrine styles.","ja":"○○の住吉大社は全国の住吉神社の総本社で、本殿の住吉造は最古の神社建築様式の一つ。"},{"k":"life","zh":"這裡號稱「八百八橋」，但官方蓋的橋只有 12 座，其餘都是町人自掏腰包架的","en":"Called the city of \"808 bridges,\" it had only 12 official ones; merchants paid for the rest themselves.","ja":"「八百八橋」と呼ばれた○○だが公儀橋は12だけで、残りは町人が自費で架けた。"},{"k":"food","zh":"甜煮豆皮放在烏龍麵上的「豆皮烏龍麵」，據說 1893 年由這裡船場的松葉家發明","en":"Kitsune udon, topped with sweet fried tofu, is said to have been invented at Matsubaya here in 1893.","ja":"甘く煮た油揚げをのせるきつねうどんは、1893年創業の○○船場「松葉家」が考案したとされる。"},{"k":"food","zh":"這裡誕生的押壽司「バッテラ」名稱源自葡萄牙語「小船」，最初用的是窩斑鰶而非鯖魚","en":"Battera pressed sushi from here is named for Portuguese \"bateira\" (boat) and first used gizzard shad, not mackerel.","ja":"○○生まれの押し寿司バッテラはポルトガル語の小舟が語源で、元はサバでなくコノシロを使った。"},{"k":"food","zh":"這裡的箕面把鹽漬一年以上的楓葉裹上甜麵衣油炸，當成點心販賣","en":"In Minoh here, maple leaves salted for over a year are coated in sweet batter and deep-fried as a snack.","ja":"○○の箕面では、1年以上塩漬けにしたもみじの葉に甘い衣をつけて揚げた天ぷらを売る。"},{"k":"brand","zh":"三得利 1899 年在這裡創業，社名結合「赤玉」的太陽（sun）與創辦人鳥井的姓","en":"Suntory was founded here in 1899; its name joins the \"sun\" of Akadama wine with founder Torii's surname.","ja":"サントリーは1899年に○○で創業し、社名は「赤玉」の太陽（sun）と鳥井の姓を合わせたもの。"},{"k":"brand","zh":"自行車零件巨頭島野 1921 年在這裡的堺創業，堺自古就是菜刀與鐵砲之城","en":"Bike-parts giant Shimano was founded in 1921 in Sakai here, a city long famed for its knives and guns.","ja":"自転車部品のシマノは1921年に○○の堺で創業。堺は16世紀から包丁と鉄砲の町だった。"},{"k":"brand","zh":"固力果糖 1922 年在這裡的三越百貨首賣，名字來自從牡蠣煮汁萃取的肝醣","en":"Glico caramels debuted at Mitsukoshi here in 1922; the name comes from glycogen taken from oyster broth.","ja":"グリコは1922年に○○の三越で発売され、名は牡蠣の煮汁から採ったグリコーゲンに由来する。"},{"k":"history","zh":"1615 年德川大軍攻陷這裡的城，豐臣秀賴自盡，豐臣家就此滅亡","en":"In 1615 Tokugawa forces took the castle here; Toyotomi Hideyori took his own life, ending his clan.","ja":"1615年、徳川軍が○○城を落とし、豊臣秀頼が自害して豊臣家は滅んだ。"},{"k":"history","zh":"1614 年真田幸村在城南築起出城「真田丸」，擊退了德川軍","en":"In 1614 Sanada Yukimura built the Sanadamaru outwork south of the castle here and repelled Tokugawa troops.","ja":"1614年、真田信繁（幸村）は○○城の南に出城「真田丸」を築き、徳川軍を撃退した。"},{"k":"history","zh":"1837 年前與力大塩平八郎為救飢民起兵，半天就被鎮壓，大火卻燒掉市街五分之一","en":"In 1837 ex-official Ōshio Heihachirō rose up for famine victims; crushed in half a day, it burned a fifth of the city.","ja":"1837年、元与力・大塩平八郎が飢饉の民のため挙兵し、半日で鎮圧されたが市中の5分の1が焼けた。"},{"k":"history","zh":"645 年乙巳之變後，孝德天皇把都城遷到這裡的難波","en":"After the coup of 645, Emperor Kōtoku moved the capital here to Naniwa.","ja":"645年の乙巳の変の後、孝徳天皇は都を○○の難波へ移した。"},{"k":"history","zh":"1925 年這裡的首府在面積、人口和工業產值上都成為日本第一大城","en":"In 1925 the capital city here became Japan's largest in area, population and industrial output.","ja":"1925年、○○市は面積・人口・工業生産額のいずれでも日本最大の都市になった。"},{"k":"nature","zh":"這裡的最高點在金剛山的山腰（1056 公尺），山頂其實屬於鄰縣","en":"This prefecture's highest point is on the slope of Mt. Kongō (1,056 m); the summit lies in the next prefecture.","ja":"○○の最高地点は金剛山の山腹（1056m）で、山頂は隣の県にある。"},{"k":"nature","zh":"中之島是夾在堂島川與土佐堀川之間、長約 3 公里的沙洲，江戶時代各藩倉庫林立","en":"Nakanoshima, a 3-km sandbar between the Dōjima and Tosabori rivers, was lined with domain warehouses in Edo times.","ja":"○○の中之島は堂島川と土佐堀川に挟まれた長さ約3kmの中洲で、江戸時代は諸藩の蔵屋敷が並んだ。"},{"k":"legend","zh":"傳說安倍晴明的母親，是住在這裡信太森林的白狐「葛葉」","en":"Legend says Abe no Seimei's mother was Kuzunoha, a white fox from the Shinoda forest here.","ja":"安倍晴明の母は、○○の信太の森に住む白狐「葛の葉」だという伝説がある。"}],
"JP-28":[{"k":"symbol","zh":"縣花是野生的菊花「野路菊（ノジギク）」","en":"Its prefectural flower is the nojigiku, a wild chrysanthemum.","ja":"県の花は野生の菊・ノジギク。"},{"k":"record","zh":"日本最古老的高爾夫球場 1903 年由英國商人建在六甲山上","en":"Japan's oldest golf course was built on Mt. Rokko by a British merchant in 1903.","ja":"日本最古のゴルフ場は1903年に英国人グルームが六甲山上に開いた。"},{"k":"people","zh":"漫畫之神手塚治虫在這裡的寶塚住了約 20 年，當地有他的紀念館","en":"Manga legend Osamu Tezuka spent about 20 years in Takarazuka here, home to his memorial museum.","ja":"手塚治虫は宝塚で約20年を過ごし、記念館がある。"},{"k":"work","zh":"動畫電影《螢火蟲之墓》中，兄妹住進西宮池畔的防空洞","en":"In Grave of the Fireflies, the siblings move into a shelter by a pond in Nishinomiya.","ja":"『火垂るの墓』の兄妹は西宮の池のほとりの防空壕で暮らした。"},{"k":"festival","zh":"姬路的「灘之喧嘩祭」把三座神轎互相猛撞","en":"At the Nada Fighting Festival in Himeji, three portable shrines are smashed into each other.","ja":"姫路の「灘のけんか祭り」は3基の神輿を激しくぶつけ合う。"},{"k":"life","zh":"姬路一家公司生產全日本約七成的國產火柴","en":"One company in Himeji makes about 70% of Japan's domestically produced matches.","ja":"姫路市の日東社が国産マッチの約7割を製造している。"},{"k":"record","zh":"古墳數量 18,351 座，全國最多","en":"It has 18,351 ancient burial mounds, the most of any prefecture.","ja":"古墳の数は18,351か所で全国1位。"},{"k":"people","zh":"柔道創始人嘉納治五郎出生在這裡的御影，也是亞洲第一位 IOC 委員","en":"Kanō Jigorō, founder of judo and Asia's first IOC member, was born in Mikage here.","ja":"柔道の創始者で、アジア初のIOC委員となった嘉納治五郎は○○の御影生まれ。"},{"k":"people","zh":"1970 年成為世界第一位登頂五大洲最高峰的植村直己，出身這裡的豐岡","en":"Uemura Naomi, the first to climb the highest peaks of five continents (1970), was from Toyooka here.","ja":"1970年に世界初の五大陸最高峰登頂を果たした植村直己は○○の豊岡出身。"},{"k":"people","zh":"民俗學之父柳田國男出身這裡的福崎，他說老家是「日本最小的房子」","en":"Folklorist Yanagita Kunio, born in Fukusaki here, called his family home \"the smallest house in Japan.\"","ja":"民俗学の父・柳田國男は○○の福崎出身で、生家を「日本一小さい家」と呼んだ。"},{"k":"sport","zh":"1995 年大地震那年，以這裡為主場的歐力士藍浪隊在鈴木一朗帶領下拿下聯盟冠軍","en":"In 1995, the year of the great quake, the Orix BlueWave, based here, won the Pacific League led by Ichiro.","ja":"震災の1995年、○○を本拠地とするオリックス・ブルーウェーブはイチローの活躍でリーグ優勝した。"},{"k":"festival","zh":"西宮神社每年 1 月 10 日清晨 6 點開門，參拜者衝刺約 230 公尺搶當「福男」","en":"At 6 a.m. each Jan 10, runners dash about 230 m to Nishinomiya Shrine's main hall to become \"lucky men.\"","ja":"○○の西宮神社では1月10日朝6時に門が開き、本殿まで約230mを走る「福男選び」がある。"},{"k":"festival","zh":"光之祭典「Luminarie」始於 1995 年，為悼念阪神淡路大地震的罹難者","en":"The Luminarie light festival here began in 1995 to mourn the victims of the Great Hanshin earthquake.","ja":"○○の光の祭典「ルミナリエ」は、阪神・淡路大震災の犠牲者を追悼するため1995年に始まった。"},{"k":"work","zh":"《涼宮春日的憂鬱》中的「縣立北高」，原型是作者母校、這裡的西宮北高中","en":"North High in \"The Melancholy of Haruhi Suzumiya\" is modeled on the author's old school in Nishinomiya here.","ja":"『涼宮ハルヒの憂鬱』の「県立北高」のモデルは、作者の母校・○○県立西宮北高校。"},{"k":"work","zh":"谷崎潤一郎《細雪》描寫蒔岡家四姊妹，故事多發生在她們位於這裡蘆屋的家","en":"Tanizaki's \"The Makioka Sisters\" follows four sisters whose lives mostly unfold at their Ashiya home here.","ja":"谷崎潤一郎『細雪』の蒔岡家四姉妹の物語は、主に○○の芦屋の分家で展開する。"},{"k":"work","zh":"志賀直哉被電車撞傷後到這裡的城崎溫泉療養，寫下看著蜂、鼠、蠑螈死去的名作短篇","en":"After being hit by a train, Shiga Naoya recovered at Kinosaki Onsen here, inspiring a famous short story.","ja":"電車にはねられた志賀直哉は○○の城崎温泉で養生し、短編『城の崎にて』を書いた。"},{"k":"origin","zh":"六甲山古時讀作「むこ」、寫作「武庫」，一說意思是從京畿看過去的「對面」","en":"Mt. Rokkō was once called \"Muko,\" possibly meaning \"over there\" as seen from the old capital region.","ja":"○○の六甲山は古く「むこ（武庫）」と呼ばれ、畿内から見た「向こう」が語源という説が有力。"},{"k":"origin","zh":"「百萬美元夜景」一詞源自六甲山，1950 年左右山下燈火一個月電費約 100 萬美元","en":"The phrase \"million-dollar night view\" began on Mt. Rokkō: around 1950 the lights below cost $1M a month.","ja":"「100万ドルの夜景」は○○の六甲山が発祥で、1950年頃に見える電灯の電気代が月約100万ドルだった。"},{"k":"symbol","zh":"全日本的黑毛和牛母牛，幾乎全是 1939 年在這裡美方郡出生的公牛「田尻號」的後代","en":"Almost all of Japan's Kuroge Wagyu cows descend from Tajiri, a Tajima bull born in Mikata here in 1939.","ja":"全国の黒毛和種の母牛のほぼすべては、1939年に○○の美方郡で生まれた但馬牛「田尻号」の子孫。"},{"k":"record","zh":"岩石名稱「玄武岩」是 1884 年取自這裡豐岡的玄武洞","en":"The Japanese word for basalt, \"genbugan,\" was coined in 1884 after the Genbudō caves here.","ja":"岩石名「玄武岩」は、1884年に○○豊岡の玄武洞にちなんで名付けられた。"},{"k":"record","zh":"1896 年日本首次公開放映電影就在這裡，用的是愛迪生的電影視鏡，12 月 1 日電影日由此而來","en":"Japan's first public film showing, on Edison's Kinetoscope, took place here in 1896, the origin of Movie Day.","ja":"1896年、エジソンのキネトスコープによる日本初の映画一般公開が○○で行われ、「映画の日」の由来に。"},{"k":"life","zh":"這裡由攝津、播磨、但馬、丹波、淡路五個舊國組成，還自稱「五國聯邦」","en":"This prefecture unites five old provinces, Settsu, Harima, Tajima, Tanba and Awaji, promoted as a \"federation.\"","ja":"○○は摂津・播磨・但馬・丹波・淡路の5つの旧国からなり、「五国連邦」とPRしている。"},{"k":"food","zh":"炒麵加白飯一起炒的「蕎麥飯」，起源於這裡長田區的工人帶冷飯請什錦燒店幫忙炒","en":"Sobameshi, noodles fried with rice, began when Nagata factory workers here brought cold rice to an okonomiyaki shop.","ja":"焼きそばとご飯を炒める「そばめし」は、○○長田区で工員が冷や飯を持ち込み頼んだのが始まり。"},{"k":"food","zh":"這裡沿海每年春天把玉筋魚煮成「釘煮」，因成品像彎曲生鏽的釘子而得名","en":"Each spring locals simmer sand lance into \"kugini,\" named for looking like bent, rusty nails.","ja":"○○沿岸の春の味「いかなごのくぎ煮」は、曲がって錆びた釘に見えることが名の由来。"},{"k":"food","zh":"這裡的姬路吃關東煮要沾薑汁醬油","en":"In Himeji here, oden is eaten dipped in ginger soy sauce.","ja":"○○の姫路では、おでんを生姜醤油につけて食べる。"},{"k":"history","zh":"1180 年平清盛把都城遷到這裡的福原，但只維持約半年就遷回","en":"In 1180 Taira no Kiyomori moved the capital to Fukuhara here, but it lasted only about half a year.","ja":"1180年、平清盛は○○の福原に都を移したが、約半年で都は戻された。"},{"k":"history","zh":"1184 年一之谷之戰，傳說源義經騎馬衝下鵯越的陡崖奇襲平家","en":"In the 1184 Battle of Ichi-no-Tani here, Minamoto no Yoshitsune reportedly charged on horseback down a cliff.","ja":"1184年の一ノ谷の戦いで、源義経は○○の鵯越の急崖を馬で駆け下りたと伝わる。"},{"k":"history","zh":"1336 年楠木正成在湊川之戰敗給足利尊氏，與弟弟正季互刺自盡","en":"In 1336 Kusunoki Masashige lost to Ashikaga Takauji at Minatogawa here and died with his brother.","ja":"1336年、○○での湊川の戦いで足利尊氏に敗れた楠木正成は、弟正季と刺し違えて自害した。"},{"k":"nature","zh":"竹田城遺跡常被河霧包圍，彷彿浮在雲海之上，被稱為「天空之城」","en":"The ruins of Takeda Castle often seem to float on a sea of clouds, earning the name \"castle in the sky.\"","ja":"○○の竹田城跡は川霧で雲海に浮かぶように見え、「天空の城」と呼ばれる。"},{"k":"nature","zh":"1926 年松山基範在這裡玄武洞的岩層中，發現地球磁場曾經倒轉","en":"At the Genbudō caves here in 1926, Matuyama Motonori found evidence that Earth's magnetic field had reversed.","ja":"松山基範は1926年、○○の玄武洞の玄武岩から地球磁場の逆転を発見した。"},{"k":"brand","zh":"亞瑟士 1949 年在這裡創業，ASICS 取自拉丁文「健全的身體寓有健全的精神」字首","en":"ASICS, founded here in 1949, takes its name from the Latin \"Anima Sana In Corpore Sano.\"","ja":"アシックスは1949年に○○で創業し、社名はラテン語「健全な身体に健全な精神を」の頭文字。"},{"k":"brand","zh":"總部在這裡的 UCC 上島咖啡，1969 年推出世界第一款加牛奶的罐裝咖啡","en":"UCC Ueshima Coffee, based here, launched the world's first canned coffee with milk in 1969.","ja":"○○に本社を置くUCC上島珈琲は、1969年に世界初のミルク入り缶コーヒーを発売した。"},{"k":"brand","zh":"逃離俄國革命的莫洛索夫一家在這裡開巧克力店，1932 年推出「情人節送巧克力」商品","en":"Morozoff, started here by Russian émigrés, sold Valentine's Day chocolate in 1932, claimed as a first in Japan.","ja":"白系ロシア人が○○で始めたモロゾフは、1932年に「バレンタインにチョコを贈る」商品を出した。"},{"k":"legend","zh":"怪談《播州皿屋敷》中，女僕阿菊在姬路城被冤殺丟進井裡，夜夜數著盤子","en":"In a ghost tale set at Himeji Castle, the murdered maid Okiku counts plates from a well every night.","ja":"怪談『播州皿屋敷』では、姫路城で殺され井戸に捨てられたお菊が夜ごと皿を数える。"},{"k":"legend","zh":"傳說姬路城天守頂層住著妖怪「長壁姬」，一年只以老婆婆模樣與城主見一次","en":"Legend says the yōkai Osakabe-hime lives atop Himeji Castle's keep, meeting the lord once a year as an old woman.","ja":"姫路城の天守には妖怪「長壁姫」が住み、年に一度だけ老婆の姿で城主に会うという。"}],
"JP-29":[{"k":"symbol","zh":"吉祥物是長著鹿角的童子「遷都君（せんとくん）」","en":"Its mascot Sento-kun is a child with deer antlers.","ja":"マスコットは鹿の角が生えた童子「せんとくん」。"},{"k":"people","zh":"傳說獨眼的劍豪柳生十兵衛出生在這裡的柳生庄","en":"Yagyu Jubei, the swordsman of one-eyed legend, was born in Yagyu village here.","ja":"隻眼の剣豪伝説で知られる柳生十兵衛は柳生庄の生まれ。"},{"k":"work","zh":"小說《鹿男》：到這裡女校代課的老師，被公園的鹿開口交付使命","en":"In the novel Shikaotoko Aoniyoshi, a substitute teacher at a girls' school here gets orders from a talking deer.","ja":"小説『鹿男あをによし』は女子高に赴任した教師が鹿に使命を託される話。"},{"k":"festival","zh":"東大寺二月堂的「汲水」法會自 752 年起從未中斷","en":"Todaiji's Omizutori rite at Nigatsudo has been held every year without a break since 752.","ja":"東大寺二月堂のお水取りは752年から一度も途絶えていない。"},{"k":"origin","zh":"地名一說來自日語「把土地整平」的動詞","en":"One theory derives the name from a Japanese verb meaning 'to level the ground'.","ja":"地名は「土地を平らにする」という意味の言葉が由来という説がある。"},{"k":"record","zh":"這裡的天理市是 21 世紀日本唯一以宗教命名的市","en":"Tenri here is the only city in 21st-century Japan named after a religion.","ja":"天理市は宗教名を市名にした21世紀の日本で唯一の市。"},{"k":"life","zh":"公園裡的野生鹿是國家天然紀念物，會鞠躬討鹿仙貝","en":"The park's wild deer are a national natural monument and bow to beg for deer crackers.","ja":"公園の鹿は国の天然記念物で、おじぎして鹿せんべいをねだる。"},{"k":"sport","zh":"《日本書紀》裡當麻蹴速與野見宿禰的角力，被視為相撲起源","en":"The Nihon Shoki bout between Taima no Kehaya and Nomi no Sukune, seen as sumo's origin, is linked to here.","ja":"相撲の起源とされる當麻蹴速と野見宿禰の力比べの伝承地。"},{"k":"people","zh":"修驗道開山祖師役小角出生在這裡的葛城，傳說能役使前鬼、後鬼兩個鬼神","en":"En no Ozunu, founder of Shugendō mountain asceticism, was born in Katsuragi here and said to command two demons.","ja":"修験道の開祖・役小角は○○の葛城の生まれで、前鬼・後鬼を従えたと伝わる。"},{"k":"work","zh":"河瀨直美的電影《殯之森》在這裡的山間拍攝，2007 年獲坎城影展評審團大獎","en":"Kawase Naomi's \"The Mourning Forest,\" shot in the hills here, won the Grand Prix at Cannes in 2007.","ja":"河瀨直美監督『殯の森』は○○の山間部で撮影され、2007年カンヌ国際映画祭グランプリを受賞。"},{"k":"festival","zh":"每年 1 月點火燒整座若草山，一說是為了安撫山頂鶯塚古墳的亡靈","en":"Each January Mt. Wakakusa is set ablaze, said to console the spirit of the ancient tomb on its summit.","ja":"毎年1月の○○の若草山焼きは、山頂の鶯塚古墳の霊を鎮めるためという説が有力。"},{"k":"festival","zh":"春日若宮御祭始於 1136 年，在 12 月 17 日深夜子時把神明迎到御旅所","en":"Kasuga Wakamiya's On-matsuri, begun in 1136, peaks on Dec 17, when the deity is carried out at midnight.","ja":"1136年に始まった○○の春日若宮おん祭は、12月17日午前0時に若宮神を御旅所へ迎える。"},{"k":"festival","zh":"每年 10 月左右的「切鹿角」，由勢子把發情期公鹿扳倒，鋸下鹿角獻給神明","en":"Each October, handlers wrestle down rutting stags here and saw off their antlers as an offering to the gods.","ja":"○○で毎年10月頃に行う「鹿の角きり」では、勢子が雄鹿を引き倒して角を切り、神前に供える。"},{"k":"origin","zh":"這裡的古國名寫法從「大倭」改成「大養德」又改回，最後才定為「大和」","en":"The old province here was written \"Great Wa,\" then \"Great Nourishing Virtue,\" and finally \"Yamato\" (大和).","ja":"○○の旧国名は「大倭」から「大養徳」、再び「大倭」と変わり、のちに「大和」と書くようになった。"},{"k":"symbol","zh":"這裡公園的糞金龜是罕見的琉璃色，被稱為「琉璃糞金龜」，可能與鹿有關","en":"Dung beetles in the deer park here are a rare lapis blue, a color some link to the deer and people.","ja":"○○の公園には瑠璃色のオオセンチコガネ「ルリセンチコガネ」がすみ、シカの関与も指摘される。"},{"k":"symbol","zh":"日本狼最後的確實紀錄，是 1905 年在這裡的東吉野村捕獲的年輕公狼","en":"The last known Japanese wolf was a young male caught in Higashiyoshino here in 1905.","ja":"ニホンオオカミの最後の確実な記録は、1905年に○○の東吉野村で捕獲された若い雄。"},{"k":"record","zh":"談山神社的十三重塔，是世界上現存唯一的木造十三重塔","en":"Tanzan Shrine here has the world's only surviving wooden thirteen-story pagoda.","ja":"○○の談山神社の十三重塔は、現存する世界唯一の木造十三重塔。"},{"k":"record","zh":"蘇我馬子建的飛鳥寺 596 年完工，是日本第一座具備完整伽藍的佛寺","en":"Asuka-dera, completed by Soga no Umako in 596, was Japan's first full-scale Buddhist temple.","ja":"蘇我馬子が建て596年に完成した○○の飛鳥寺は、本格的伽藍を備えた日本最初の寺院。"},{"k":"record","zh":"1999 年在這裡出土的「富本錢」約鑄於 683 年，比和同開珎更早","en":"Fuhonsen coins dug up here in 1999 date to around 683, older than the Wadō Kaichin.","ja":"1999年に○○の飛鳥池遺跡で出土した富本銭は683年頃の鋳造で、和同開珎より古い。"},{"k":"record","zh":"694 年遷都的藤原京是日本第一座棋盤式都城，面積比平城京、平安京還大","en":"Fujiwara-kyō, capital from 694, was Japan's first grid-planned capital and larger than Heijō or Heian.","ja":"694年に遷都した○○の藤原京は日本初の条坊制の都で、平城京や平安京より大きかった。"},{"k":"life","zh":"明日香村是日本唯一全村都受古都保存法規範的地方，開發與建築管制嚴格","en":"Asuka village here is the only municipality in Japan wholly covered by the ancient capitals preservation law.","ja":"○○の明日香村は、全域が古都保存法の対象となる日本唯一の自治体。"},{"k":"life","zh":"山上岳至今仍禁止女性登山，這項禁制據說延續了約 1300 年","en":"Mt. Sanjō here still bars women from climbing, a ban said to date back some 1,300 years.","ja":"○○の山上ヶ岳は今も女人禁制を守り、その歴史は約1300年とされる。"},{"k":"life","zh":"大神神社沒有正殿，直接把整座三輪山當作神體參拜","en":"Ōmiwa Shrine here has no main hall; worshippers pray to Mt. Miwa itself as the deity.","ja":"○○の大神神社には本殿がなく、三輪山そのものを御神体として拝む。"},{"k":"food","zh":"1341 年隨禪僧來日的林淨因在這裡改用紅豆餡做饅頭，成為日本饅頭的起源","en":"Lin Jingyin, who came from China in 1341, created bean-paste manjū here, swapping meat for azuki.","ja":"1341年に来日した林浄因は、肉の代わりに小豆餡を包む饅頭を○○で考案した。"},{"k":"food","zh":"有句話說「大和的茶粥、京都的白粥」，這裡的人習慣用焙茶煮稀飯","en":"Locals here cook rice porridge in roasted tea; a saying pairs \"Yamato's tea porridge\" with Kyoto's white one.","ja":"「大和の茶粥、京の白粥」と言われ、○○では焙じ茶で炊く茶粥が親しまれる。"},{"k":"food","zh":"正曆寺被稱為日本清酒發祥地，室町時代在此確立了菩提酛等釀酒法","en":"Shōryaku-ji temple here is called the birthplace of clear sake, where the bodaimoto method took shape.","ja":"○○の正暦寺は「日本清酒発祥の地」とされ、室町時代に菩提酛などの製法が確立した。"},{"k":"food","zh":"酒廠屋簷掛的杉球源自大神神社，每年 11 月 14 日的釀造祈願祭會換上新的","en":"Sake breweries' cedar balls trace to Ōmiwa Shrine here, which hangs new ones every November 14.","ja":"酒蔵の杉玉は○○の大神神社に由来し、毎年11月14日の醸造安全祈願祭で掛け替えられる。"},{"k":"history","zh":"645 年中大兄皇子與中臣鎌足在飛鳥的宮中刺殺蘇我入鹿","en":"In 645 Prince Naka no Ōe and Nakatomi no Kamatari killed Soga no Iruka at the palace in Asuka here.","ja":"645年、中大兄皇子と中臣鎌足は○○の飛鳥の宮で蘇我入鹿を討った（乙巳の変）。"},{"k":"history","zh":"1336 年後醍醐天皇逃到這裡的吉野另立朝廷，開啟約 56 年的南北朝","en":"In 1336 Emperor Go-Daigo fled to Yoshino here and set up the Southern Court, splitting Japan for 56 years.","ja":"1336年、後醍醐天皇は○○の吉野に逃れて南朝を開き、約56年の南北朝時代が始まった。"},{"k":"history","zh":"1972 年發現的高松塚古墳壁畫中，色彩鮮豔的女子群像被稱為「飛鳥美人」","en":"Murals found in the Takamatsuzuka tomb in 1972 include vivid court ladies nicknamed \"Asuka beauties.\"","ja":"1972年に見つかった○○の高松塚古墳壁画の女子群像は「飛鳥美人」と呼ばれる。"},{"k":"nature","zh":"谷瀨吊橋長約 297 公尺、高 54 公尺，1954 年由村民每戶出 20～30 萬日圓蓋成","en":"The 297-m Tanize suspension bridge here, 54 m high, was built in 1954 largely with villagers' own money.","ja":"長さ約297m、高さ54mの○○の谷瀬の吊り橋は、1954年に住民が1戸20〜30万円を出し合って架けた。"},{"k":"nature","zh":"大台原是與屋久島齊名的多雨地，1920 年曾記錄年雨量 8214 毫米","en":"Ōdaigahara here rivals Yakushima for rainfall; it once logged 8,214 mm of rain in 1920.","ja":"○○の大台ヶ原は屋久島に並ぶ多雨地帯で、1920年には年間8214mmを記録した。"},{"k":"brand","zh":"日本國產的抹茶茶筅，大多出自這裡生駒市的高山地區","en":"Most of Japan's bamboo tea whisks are made in Takayama, in Ikoma here.","ja":"○○生駒市の高山は、国産の茶筅の大半を生産している。"},{"k":"legend","zh":"雄略天皇在葛城山打獵時，遇見一位和自己長得一模一樣的神「一言主」","en":"Hunting on Mt. Katsuragi here, Emperor Yūryaku met Hitokotonushi, a god who looked exactly like him.","ja":"○○の葛城山で狩りをする雄略天皇の前に、天皇と同じ姿の一言主神が現れたという。"},{"k":"legend","zh":"傳說春日大社的神明騎著白鹿從鹿島來到這裡，所以鹿被視為神的使者","en":"Kasuga's god is said to have ridden a white deer here from Kashima, so local deer are sacred messengers.","ja":"春日大社の祭神タケミカヅチが白い鹿に乗って鹿島から来たため、○○の鹿は神の使いとされる。"},{"k":"legend","zh":"傳說小僧三作失手打死神鹿，被處以石子活埋之刑，母親每天敲鐘弔念他","en":"Legend says the boy Sansaku, who accidentally killed a sacred deer here, was executed by burial under stones.","ja":"神鹿を誤って殺した小僧・三作は石子詰めの刑にされ、母は毎日鐘をついて弔ったと○○に伝わる。"},{"k":"legend","zh":"傳說中將姬在當麻寺出家，用蓮花的絲一夜織成「當麻曼荼羅」","en":"Legend says Princess Chūjō became a nun at Taima-dera here and wove its mandala from lotus threads in one night.","ja":"○○の當麻寺で尼となった中将姫は、蓮の糸で一夜のうちに「当麻曼荼羅」を織ったという。"}],
"JP-30":[{"k":"symbol","zh":"縣樹是烏岡櫟（ウバメガシ），也是備長炭的原料","en":"Its prefectural tree is the ubame oak, the raw material of binchotan charcoal.","ja":"県の木はウバメガシ、備長炭の原料。"},{"k":"people","zh":"江戶幕府八代將軍德川吉宗，原本是這裡的紀州藩主","en":"Tokugawa Yoshimune, the 8th shogun, was lord of the Kishu domain here before taking power.","ja":"8代将軍・徳川吉宗はもともと紀州藩主だった。"},{"k":"sport","zh":"日本足協標誌上的三足烏「八咫烏」，是這裡熊野本宮大社的神使","en":"The three-legged crow on the Japan Football Association emblem is the messenger of the Kumano deity here.","ja":"日本サッカー協会のシンボル・八咫烏は熊野の神の使い。"},{"k":"work","zh":"動畫《夏日重現》的日都島，原型是這裡的無人島友島","en":"Hitogashima in Summer Time Rendering is modeled on Tomogashima, an uninhabited island here.","ja":"『サマータイムレンダ』の日都ヶ島のモデルは無人島の友ヶ島。"},{"k":"festival","zh":"那智火祭中，12 支大火把繞著石階，把火星灑向扇神轎","en":"At the Nachi Fire Festival, 12 huge torches circle the stone steps, showering sparks on fan-shaped mikoshi.","ja":"那智の火祭では大松明12本が石段を回り、扇神輿に火の粉を浴びせる。"},{"k":"record","zh":"那智勝浦的「ぶつぶつ川」全長 13.5 公尺，是日本最短的法定河川","en":"The Butsubutsu River in Nachikatsuura is just 13.5 m long, Japan's shortest official river.","ja":"那智勝浦町のぶつぶつ川は全長13.5m、日本一短い法定河川。"},{"k":"record","zh":"北山村是被奈良、三重包圍的飛地，全日本唯一","en":"Kitayama village is an exclave surrounded by Nara and Mie, the only such municipality in Japan.","ja":"北山村は奈良・三重に囲まれた飛び地で、日本で唯一。"},{"k":"life","zh":"這裡的拉麵店桌上擺著鯖魚押壽司，吃幾個自己報數結帳","en":"Ramen shops here leave mackerel pressed sushi on the table; you report how many you ate when paying.","ja":"ラーメン店の卓上に早ずしがあり、食べた数を自己申告で払う。"},{"k":"people","zh":"醫師華岡青洲 1804 年在這裡完成世界首例有紀錄的全身麻醉乳癌手術","en":"In 1804 local doctor Hanaoka Seishū performed the first recorded breast-cancer surgery under general anesthesia.","ja":"○○の医師・華岡青洲は1804年、記録に残る世界初の全身麻酔による乳がん手術に成功した。"},{"k":"people","zh":"人稱「剃刀大臣」的外相陸奧宗光出身這裡的紀州藩，1894 年廢除了領事裁判權","en":"\"Razor minister\" Mutsu Munemitsu, from the Kishū domain here, ended consular jurisdiction in Japan in 1894.","ja":"○○出身の外相・陸奥宗光は「カミソリ大臣」と呼ばれ、1894年に領事裁判権の撤廃を実現した。"},{"k":"sport","zh":"1979 年夏季甲子園，這裡的箕島高中與星稜鏖戰延長 18 局，被譽為史上最佳比賽","en":"The 1979 Kōshien game between Minoshima from here and Seiryō went 18 innings, hailed as the greatest ever.","ja":"1979年夏の甲子園、○○の箕島が星稜に延長18回でサヨナラ勝ちし「史上最高の試合」と呼ばれる。"},{"k":"work","zh":"道成寺流傳安珍與清姬的故事，成為能劇與歌舞伎《京鹿子娘道成寺》的題材","en":"Dōjō-ji temple here is the source of the Anchin and Kiyohime legend, retold in Noh and kabuki.","ja":"○○の道成寺に伝わる安珍・清姫の伝説は、能「道成寺」や歌舞伎『京鹿子娘道成寺』の題材。"},{"k":"festival","zh":"每年 2 月 6 日的御燈祭，白衣男子手持火把衝下神倉神社 538 級石階","en":"At the Otō Festival every Feb 6, white-clad men with torches race down Kamikura Shrine's 538 stone steps.","ja":"○○の御燈祭（2月6日）では、白装束の男たちが松明を手に神倉神社の538段の石段を駆け下りる。"},{"k":"festival","zh":"紀州東照宮的例祭始於 1622 年，是江戶時代當地首屈一指的華麗大祭","en":"The festival of Kishū Tōshōgū here, begun in 1622, was the province's grandest in the Edo period.","ja":"○○の紀州東照宮の例祭は1622年に始まり、江戸時代は国中第一の大祭とされた。"},{"k":"origin","zh":"這裡的古國名原本是雨多林茂的「木之國」，713 年起才改寫成兩字的「紀伊」","en":"The old province here was first \"Ki no kuni,\" Land of Trees, for its forests; in 713 it became \"Kii.\"","ja":"○○の旧国名は森林が茂る「木国」で、713年に二字の「紀伊」と書くようになった。"},{"k":"origin","zh":"備長炭的名字來自元祿年間把這裡的炭推廣到江戶的炭商「備中屋長左衛門」","en":"Binchōtan charcoal is named after Bitchūya Chōzaemon, a charcoal dealer here who popularized it in Edo.","ja":"備長炭の名は、元禄年間に江戸で広めた○○の炭問屋・備中屋長左衛門に由来する。"},{"k":"record","zh":"湯之峰溫泉的「壺湯」，是世界上唯一被列為世界遺產的溫泉","en":"Tsuboyu at Yunomine Onsen here is the world's only hot spring that is part of a World Heritage Site.","ja":"○○の湯の峰温泉「つぼ湯」は、温泉として世界で唯一の世界遺産。"},{"k":"record","zh":"日本三古湯之一的白濱溫泉，海邊的「崎之湯」相傳 658 年齊明天皇曾來泡過","en":"Seaside Saki-no-yu at Shirahama here, one of Japan's three oldest spas, hosted Empress Saimei in 658.","ja":"日本三古湯の一つ○○の白浜温泉。海辺の「崎の湯」には658年に斉明天皇が入ったと伝わる。"},{"k":"record","zh":"串本外海是日本第一座海中公園","en":"The sea off Kushimoto here became Japan's first marine park.","ja":"○○串本の沿岸は、日本初の海中公園として整備された。"},{"k":"life","zh":"這裡的方言常把ザ行念成ダ行，例如「全然（ぜんぜん）」說成「でんでん」","en":"The local dialect turns z-sounds into d-sounds, so \"zenzen\" (not at all) becomes \"denden.\"","ja":"○○の方言はザ行がダ行になりやすく、「全然」を「でんでん」と言う。"},{"k":"life","zh":"司馬遼太郎說這裡的紀州方言「沒有敬語」，對長輩不用敬語也被視為慣習","en":"Shiba Ryōtarō wrote that the Kishū dialect here \"has no honorifics\"; skipping them with elders is customary.","ja":"司馬遼太郎が「紀州方言には敬語がない」と書いたように、○○には目上にも敬語を使わない習慣がある。"},{"k":"food","zh":"柑橘「じゃばら」過去只有這裡的北山村種植","en":"The jabara citrus was once grown only in Kitayama village here.","ja":"柑橘「じゃばら」は、かつて○○の北山村だけで生産されていた。"},{"k":"history","zh":"擁有數千支火繩槍的傭兵集團雜賀眾，在石山合戰中站在本願寺一方對抗織田信長","en":"The Saika, a mercenary band with thousands of guns, fought Oda Nobunaga on the side of the Honganji.","ja":"数千挺の鉄砲で武装した○○の傭兵集団・雑賀衆は、石山合戦で本願寺方として信長と戦った。"},{"k":"history","zh":"平安末期上皇盛行參拜熊野，後白河上皇去了 34 次，人潮被形容為「螞蟻的熊野詣」","en":"Retired emperors flocked to Kumano; Go-Shirakawa went 34 times, and the crowds were likened to marching ants.","ja":"院政期には上皇の熊野詣が盛んで、後白河院は34回参詣し、人の列は「蟻の熊野詣」と呼ばれた。"},{"k":"nature","zh":"串本海邊約 40 塊岩石排成 850 公尺長的一列，像橋墩，是 1500 萬年前岩漿侵入形成","en":"About 40 rocks stand in an 850-m line off Kushimoto like bridge piers, formed by magma 15 million years ago.","ja":"○○串本の橋杭岩は、約40の岩が850mにわたり橋脚のように並び、約1500万年前のマグマが起源。"},{"k":"nature","zh":"白濱的圓月島中央有直徑約 9 公尺的海蝕洞，春分、秋分時可看見夕陽穿過洞口","en":"Engetsu Island off Shirahama has a 9-m sea arch; around the equinoxes the sunset shows through it.","ja":"○○白浜の円月島（正式名・高嶋）には直径約9mの穴があり、春分・秋分の頃は穴越しに夕日が見える。"},{"k":"nature","zh":"古座川的一枚岩高約 150 公尺、寬約 800 公尺，是日本最大級的單一巨岩","en":"Ichimaiiwa on the Koza River here is a single rock about 150 m tall and 800 m wide.","ja":"○○古座川の一枚岩は高さ約150m・幅約800mで、日本最大級の一枚岩。"},{"k":"brand","zh":"金鳥創辦人上山英一郎出身這裡的有田，1902 年依妻子的點子推出漩渦狀蚊香","en":"Kincho founder Ueyama Eiichirō, from Arida here, launched the spiral mosquito coil in 1902, his wife's idea.","ja":"金鳥の創業者・上山英一郎は○○の有田出身で、妻の発案で1902年に渦巻型蚊取り線香を発売した。"},{"k":"legend","zh":"傳說化成餓鬼模樣的小栗判官，在湯之峰溫泉泡湯後恢復了原形","en":"Legend says the hero Oguri Hangan, turned ghoulish, regained his true form by bathing at Yunomine here.","ja":"餓鬼阿弥となった小栗判官は、○○の湯の峰温泉に浸かって元の姿に戻ったと伝わる。"},{"k":"legend","zh":"傳說弘法大師與天邪鬼打賭一夜造橋，天邪鬼學雞啼騙他天亮，只留下橋墩般的岩石","en":"Legend says Kōbō Daishi was building a bridge overnight until a demon faked a rooster's crow; only piers remain.","ja":"弘法大師が一夜で橋を架けようとしたが、天邪鬼の鶏の鳴きまねで中断し、○○の橋杭岩だけが残ったという。"},{"k":"legend","zh":"傳說吃岩石的妖魔咬了古座川的一枚岩，被狗趕跑，岩上的縱向凹痕就是牠的齒痕","en":"Legend says a rock-eating monster bit Ichimaiiwa before a dog chased it off, leaving the groove on its face.","ja":"岩を食う魔物が○○古座川の一枚岩にかみついたが犬に追われ、中央の凹みはその歯形だという。"},{"k":"legend","zh":"傳說為秦始皇尋找長生藥的徐福抵達這裡的新宮並定居，當地有他的墓","en":"Legend says Xu Fu, sent by Qin Shi Huang to seek the elixir of life, settled in Shingū here; his grave remains.","ja":"不老不死の霊薬を求めた徐福は○○の新宮に住み着いたと伝わり、「秦徐福之墓」がある。"}],
"JP-31":[{"k":"symbol","zh":"縣鳥是鴛鴦","en":"Its prefectural bird is the mandarin duck.","ja":"県の鳥はオシドリ。"},{"k":"people","zh":"2024 年就任首相的石破茂在這裡長大，選區也在這裡","en":"Shigeru Ishiba, who became prime minister in 2024, grew up here and represents a district here.","ja":"2024年に首相となった石破茂はここで育ち、選挙区もここ。"},{"k":"work","zh":"游泳動畫《Free!》的岩鳶町，原型是這裡的岩美町","en":"Iwatobi in the swimming anime Free! is based on the town of Iwami here.","ja":"水泳アニメ『Free!』の岩鳶町のモデルは岩美町。"},{"k":"festival","zh":"傘舞祭 2014 年以 1688 人同跳，獲金氏認證為「世界最大傘舞」","en":"Its Shan Shan Festival set a Guinness record in 2014 for the largest umbrella dance, with 1,688 dancers.","ja":"しゃんしゃん祭は2014年、1688人で「世界最大の傘踊り」とギネス認定。"},{"k":"origin","zh":"名字源自古代替朝廷捕捉水鳥納貢的部民","en":"The name comes from an ancient guild that caught waterbirds as tribute for the imperial court.","ja":"名前は朝廷のために鳥を捕らえて納めた古代の部民に由来する。"},{"k":"record","zh":"2013 年全國第一個通過把手語當作語言的條例","en":"In 2013 it passed Japan's first ordinance recognizing sign language as a language.","ja":"2013年、手話を言語とする条例を全国で初めて可決した。"},{"k":"life","zh":"還沒有星巴克時，知事說「沒有Sutaba但有Sunaba（沙丘）」，催生了「沙場咖啡」","en":"With no Starbucks yet, the governor joked 'no Sutaba, but we have the Sunaba (sand dunes)', inspiring Sunaba Coffee.","ja":"スタバがない頃、知事の「スナバはある」発言から「すなば珈琲」が誕生。"},{"k":"life","zh":"每年秋冬螃蟹季，縣政府會把縣名的一個字換成「蟹」來宣傳","en":"Every autumn-to-winter crab season, the prefecture rebrands itself by swapping a character of its name for 'crab'.","ja":"秋冬のカニの季節には県名の一字を「蟹」に替える改名キャンペーンを行う。"},{"k":"history","zh":"1581 年羽柴秀吉斷糧圍城三個多月，城將吉川經家切腹換取城兵性命","en":"In 1581 Hideyoshi starved the castle here into surrender; commander Kikkawa Tsuneie died by seppuku to spare his men.","ja":"1581年、羽柴秀吉の兵糧攻めで城内が飢え、城将吉川経家が切腹して城兵を助けた"},{"k":"history","zh":"1943 年戰時發生 M7.2 大地震，死者逾千人，縣的災害紀錄被列為機密","en":"A 1943 M7.2 quake killed over 1,000 here; amid wartime censorship, the prefecture's records were marked secret.","ja":"1943年のM7.2の地震で千人以上が死亡、戦時中で県の震災記録は「マル秘」扱いだった"},{"k":"history","zh":"從隱岐脫逃的後醍醐天皇，由名和長年迎到這裡的船上山建立行宮","en":"Emperor Go-Daigo, escaping exile on Oki, set up a temporary palace on Mt. Senjō here with Nawa Nagatoshi's help.","ja":"隠岐を脱出した後醍醐天皇は、名和長年に迎えられ船上山に行宮を置いた"},{"k":"record","zh":"1899 年宇倍神社拜殿印上五圓紙鈔，是第一座登上日本紙幣的神社","en":"In 1899 Ube Shrine here became the first shrine pictured on a Japanese banknote, the five-yen note.","ja":"宇倍神社の拝殿は1899年、神社として初めて日本の紙幣（五円札）の図柄になった"},{"k":"sport","zh":"夏季甲子園前身大會 1915 年的第一場比賽，由這裡的中學以 14 比 7 勝出","en":"A school from here won the very first game of Japan's national high-school baseball tournament in 1915, 14–7.","ja":"夏の甲子園の前身、1915年の第1回大会の開幕試合で、この県の中学が14-7で勝った"},{"k":"sport","zh":"本地 J 聯盟球隊的隊名，結合方言「がいな」（大）與義大利文「願望」","en":"Its J.League club's name blends local dialect 'gaina' (big) with Italian 'sperare' (to hope).","ja":"Jリーグのクラブ名は、方言で「大きい」の「がいな」とイタリア語の「願う」を合わせたもの"},{"k":"people","zh":"攝影家植田正治出身境港，以在沙丘上把人物當擺件排列的「植田調」聞名","en":"Photographer Shoji Ueda of Sakaiminato staged people like objects on the sand dunes in his famed 'Ueda-cho' style.","ja":"写真家植田正治は境港の出身で、砂丘で人物をオブジェのように配した「植田調」で知られる"},{"k":"people","zh":"描寫日本終戰前一天的經典電影，導演岡本喜八出身米子","en":"Film director Kihachi Okamoto, maker of 'Japan's Longest Day' (1967), was born in Yonago.","ja":"『日本のいちばん長い日』（1967年）の映画監督岡本喜八は米子の出身"},{"k":"work","zh":"谷口治郎的漫畫裡，48 歲上班族回到故鄉倉吉，竟變回 14 歲的自己","en":"In Jiro Taniguchi's manga 'A Distant Neighborhood', a 48-year-old wakes up as his 14-year-old self in Kurayoshi.","ja":"谷口ジロー『遥かな町へ』は、48歳の男が故郷倉吉で14歳の自分に戻ってしまう物語"},{"k":"legend","zh":"「因幡白兔」神話裡，兔子被剝皮後由大國主用香蒲花粉治好的白兔海岸就在這裡","en":"The Hakuto coast, where Ōkuninushi healed the skinned 'White Hare of Inaba' with cattail pollen, is here.","ja":"皮をはがれた「因幡の白兎」を大国主が蒲の穂で治した白兎海岸がある"},{"k":"legend","zh":"倉吉的打吹山傳說，天女留下的孩子在山頂打鼓吹笛思念母親","en":"Legend says a celestial maiden's children played drum and flute atop Mt. Utsubuki in Kurayoshi, missing their mother.","ja":"倉吉の打吹山には、天女が残した子らが山頂で太鼓や笛を鳴らし母をしのんだ伝説がある"},{"k":"legend","zh":"傳說富豪用扇子把夕陽招回來趕完插秧，隔天田地全變成了湖山池","en":"A rich man fanned the setting sun back to finish planting rice; next morning his paddies had become Lake Koyama.","ja":"長者が扇で夕日を招き返して田植えを終えたが、翌朝田はすべて湖山池になったという"},{"k":"nature","zh":"湖山池面積約 7 平方公里，是日本名稱帶「池」的湖沼中最大的","en":"Koyama-ike, about 7 km², is the largest body of water in Japan that is called a 'pond' (ike).","ja":"湖山池は面積約7平方キロで、「池」と名のつく湖沼として日本最大とされる"},{"k":"food","zh":"藩主池田光仲因魚貴豆多而提倡吃豆腐，催生了東部的豆腐竹輪","en":"A lord urged tofu over scarce fish, giving rise to tofu chikuwa, the tofu-and-fish cake of the east.","ja":"魚が貴重だった藩で池田光仲が豆腐食を勧め、東部名物の豆腐ちくわが生まれた"},{"k":"food","zh":"中西部流行用牛骨熬湯的拉麵，源頭被認為是 1951 年米子的一家店","en":"Its central and western areas love ramen in beef-bone broth, traced to a Yonago shop advertised in 1951.","ja":"中西部では牛骨スープのラーメンが親しまれ、1951年の米子の店が発祥とされる"},{"k":"festival","zh":"用瀨每逢舊曆三月三日把雛人偶放流到千代川，祈求洗去一年罪穢","en":"On the 3rd day of the 3rd lunar month, Mochigase floats hina dolls down the Sendai River to cast off impurities.","ja":"用瀬では旧暦3月3日に流しびなを行い、千代川に雛を流して一年の罪や穢れを祓う"},{"k":"life","zh":"日吉津村自 1889 年成立以來從未合併，是縣內唯一的例子","en":"Hiezu Village has never merged with anyone since its founding in 1889, the only such municipality here.","ja":"日吉津村は1889年の発足以来一度も合併していない、県内唯一の市町村"},{"k":"record","zh":"直到 2004 年，這裡是全國唯一縣廳所在地市內沒有高速公路的縣","en":"Until 2004 its capital was the only prefectural capital in Japan without an expressway.","ja":"2004年まで、県庁所在地に高速道路がない全国唯一の県だった"},{"k":"life","zh":"2022 年全國出生數下滑，這裡是唯一出生數不減反增的縣","en":"In 2022, as births fell nationwide, this was the only prefecture where births rose.","ja":"2022年、全国で出生数が減る中、出生数が増えた唯一の県だった"},{"k":"history","zh":"1632 年池田光仲與池田光政互換領地，這裡和岡山的藩主對調","en":"In 1632 the Ikeda lords of this domain and Okayama swapped territories, an exchange called the 'okunigae'.","ja":"1632年、池田光仲と光政が領地を入れ替え、岡山藩と藩主が交代した（お国替え）"},{"k":"history","zh":"2000 年西部發生 M7.3 強震、最大震度 6 強，卻沒有任何人死亡","en":"A magnitude-7.3 quake struck its west in 2000 with intensity 6+, yet killed no one.","ja":"2000年の西部地震はM7.3、最大震度6強だったが死者は出なかった"},{"k":"life","zh":"沙丘上的美術館每年換主題，邀請各國雕刻家用沙子雕出巨大作品","en":"A museum on the dunes shows giant sand sculptures by artists from around the world, with a new theme each year.","ja":"砂丘の「砂の美術館」は毎年テーマを変え、各国の彫刻家が砂像を制作する"},{"k":"history","zh":"1873 年西部的會見郡爆發反對徵兵制的農民起義","en":"In 1873 farmers in Aimi District here rose up against the new conscription system.","ja":"1873年、会見郡で徴兵制に反対する一揆が起きた"}],
"JP-32":[{"k":"symbol","zh":"縣魚是飛魚","en":"Its prefectural fish is the flying fish.","ja":"県の魚はトビウオ。"},{"k":"people","zh":"歌手竹內瑪莉亞出生在出雲大社旁的老字號旅館","en":"Singer Mariya Takeuchi was born into the family running an old inn near Izumo Taisha.","ja":"歌手の竹内まりやは出雲大社近くの老舗旅館・竹野屋の生まれ。"},{"k":"sport","zh":"網球名將錦織圭的故鄉","en":"Hometown of tennis star Kei Nishikori.","ja":"テニスの錦織圭の出身地。"},{"k":"work","zh":"松本清張《砂之器》的破案關鍵，是這裡的方言竟像東北腔","en":"In Seicho Matsumoto's Castle of Sand, the key clue is that a local dialect here sounds like Tohoku speech.","ja":"松本清張『砂の器』は、東北弁に似た出雲の方言と「亀嵩」が鍵。"},{"k":"festival","zh":"船祭「ホーランエンヤ」每 10 年才辦一次，是日本三大船神事之一","en":"Horan Enya, held only once every 10 years, is one of Japan's three great boat rituals.","ja":"ホーランエンヤは10年に一度、日本三大船神事のひとつ。"},{"k":"record","zh":"《出雲國風土記》是唯一幾乎完整流傳至今的風土記","en":"The Izumo Fudoki is the only ancient provincial gazetteer surviving almost complete.","ja":"『出雲国風土記』は唯一ほぼ完本で残る風土記。"},{"k":"record","zh":"每 10 萬人中的百歲人瑞人數連續多年全國第一","en":"It has had Japan's most centenarians per 100,000 people for many years running.","ja":"人口10万人あたりの100歳以上の人数が長年全国1位。"},{"k":"origin","zh":"縣名據說是《出雲國風土記》中把土地拉來造國的神明所取","en":"The name was reportedly given by the god who 'pulled land' to build the province in the Izumo Fudoki.","ja":"県名は『出雲国風土記』で国引きの神・八束水臣津野命が名付けたと伝わる。"},{"k":"history","zh":"1868 年隱岐島民趕走藩派來的代官，一度自行治理（隱岐騷動）","en":"In the 1868 Oki Incident, islanders expelled the domain's governor and briefly ran their own affairs.","ja":"1868年の隠岐騒動で、島民が藩の代官を追い出し一時自治を行った"},{"k":"history","zh":"隱岐曾是後鳥羽上皇（1221 年）與後醍醐天皇（1332 年）的流放地","en":"The Oki Islands here were the place of exile for Emperor Go-Toba in 1221 and Emperor Go-Daigo in 1332.","ja":"隠岐は承久の乱後の後鳥羽上皇、1332年の後醍醐天皇の配流先となった"},{"k":"people","zh":"兩度出任首相、1930 年率團出席倫敦海軍裁軍會議的若槻禮次郎出身這裡","en":"Reijirō Wakatsuki, twice prime minister and chief delegate to the 1930 London Naval Conference, was born here.","ja":"首相を2度務め、1930年ロンドン海軍軍縮会議の首席全権だった若槻礼次郎の出身地"},{"k":"people","zh":"導入消費稅、發給全國市町村各一億日圓的首相竹下登是這裡人","en":"PM Noboru Takeshita, who introduced Japan's consumption tax and gave every town ¥100 million, was born here.","ja":"消費税を導入し、全市町村に1億円を配った首相竹下登はこの県の出身"},{"k":"people","zh":"飛鳥時代歌人柿本人麻呂的傳說，大多集中在西部的石見地方","en":"Many legends of Asuka-era poet Kakinomoto no Hitomaro are concentrated in the Iwami area here.","ja":"飛鳥時代の歌人柿本人麻呂の伝承は、県西部の石見地方に多く残る"},{"k":"people","zh":"戰國大名尼子經久以月山富田城為據點，勢力擴及整個中國地方","en":"Warlord Amago Tsunehisa built his power from Gassan-Toda Castle here, spreading across the Chūgoku region.","ja":"尼子経久は月山富田城を拠点に、中国地方に勢力を広げた"},{"k":"legend","zh":"伊奘諾從黃泉逃回時用巨石堵住的「黃泉比良坂」，傳說地就在這裡","en":"Yomotsu Hirasaka, the slope Izanagi sealed with a boulder after fleeing the land of the dead, is said to be here.","ja":"イザナギが千引の岩で塞いだ黄泉比良坂の伝承地が、東出雲町揖屋にある"},{"k":"life","zh":"八重垣神社的鏡池占卜，把放了硬幣的紙浮在池上，沉得越快越早結良緣","en":"At Yaegaki Shrine you float paper with a coin on its pond; the sooner it sinks, the sooner you'll find love.","ja":"八重垣神社の鏡の池では、硬貨を載せた紙を浮かべ、早く沈むほど早く良縁に恵まれるという"},{"k":"sport","zh":"隱岐的鬥牛「牛突」，據說是為了安慰被流放的後鳥羽上皇而開始","en":"Oki's bullfighting, 'ushi-zuki', is said to have begun to comfort the exiled Emperor Go-Toba.","ja":"隠岐の牛突きは、配流された後鳥羽上皇を慰めるために始まったとされる"},{"k":"record","zh":"荒神谷遺跡一次出土 358 把銅劍，超過當時全日本出土的總數","en":"The Kōjindani site yielded 358 bronze swords, more than had been found in all of Japan until then.","ja":"荒神谷遺跡では銅剣358本が出土し、それまでの全国出土総数を上回った"},{"k":"record","zh":"仁摩沙博物館裡有一座世界最大的沙漏","en":"The Nima Sand Museum here houses the world's largest hourglass.","ja":"仁摩サンドミュージアムには世界最大の砂時計がある"},{"k":"work","zh":"中井貴一主演、49 歲上班族轉行當電車司機的電影，舞台是一畑電車","en":"The 2010 film 'Railways', about a 49-year-old who quits to drive trains, is set on the Ichibata line here.","ja":"49歳で電車の運転士になる男を描く映画『RAILWAYS』の舞台は一畑電車"},{"k":"work","zh":"搞笑動畫裡老把家鄉掛嘴邊的吉田君設定出身這裡，還當上縣的宣傳大使","en":"Yoshida-kun of the anime 'Eagle Talon' keeps bringing up his home prefecture here and became its PR ambassador.","ja":"『秘密結社 鷹の爪』の吉田くんはこの県の出身という設定で、県のPR大使にも任命された"},{"k":"work","zh":"水木茂的妻子武良布枝出身安來，她的自傳 2010 年拍成 NHK 晨間劇","en":"Mizuki Shigeru's wife Nunoe Mura was born in Yasugi; her memoir became a 2010 NHK morning drama.","ja":"水木しげるの妻武良布枝は安来出身で、自伝『ゲゲゲの女房』は2010年に朝ドラ化された"},{"k":"brand","zh":"西部產的紅褐色石州瓦耐寒，是日本三大瓦之一","en":"Sekishū roof tiles, red-brown and frost-proof, are one of Japan's three great tile types.","ja":"赤褐色の石州瓦は寒さに強く、日本三大瓦の一つ"},{"k":"food","zh":"出雲的「ぼてぼて茶」把番茶打出泡，加入飯菜後不用筷子一口灌下","en":"Izumo's 'botebote-cha' is frothed bancha with bits of rice and food, gulped down without chopsticks.","ja":"出雲のぼてぼて茶は泡立てた番茶に具を入れ、箸を使わず一気に流し込む"},{"k":"festival","zh":"佐太神社的神樂「佐陀神能」，2011 年列入聯合國非物質文化遺產","en":"Sada Shinnō, the sacred dance of Sada Shrine, was inscribed as UNESCO Intangible Cultural Heritage in 2011.","ja":"佐太神社の佐陀神能は2011年、ユネスコ無形文化遺産に登録された"},{"k":"festival","zh":"津和野在 7 月 20、27 日跳鷺舞，這支舞源自京都祇園祭","en":"On July 20 and 27, Tsuwano performs the Heron Dance, which came from Kyoto's Gion Festival.","ja":"津和野の鷺舞は京都祇園祭から伝わり、7月20日と27日に舞われる"},{"k":"nature","zh":"三瓶山噴發的火山噴出物，被認為塑造了出雲平原的骨架","en":"Material from eruptions of Mt. Sanbe is thought to have shaped the framework of the Izumo Plain.","ja":"三瓶山の噴火による噴出物が、出雲平野の骨格をつくったとされる"},{"k":"history","zh":"神原神社古墳出土刻有景初三年（239 年）銘文的銅鏡，俗稱「卑彌呼之鏡」","en":"Kanbara Shrine tomb yielded a bronze mirror dated 239 AD, nicknamed 'Himiko's mirror'.","ja":"神原神社古墳から景初3年（239年）銘の三角縁神獣鏡、通称「卑弥呼の鏡」が出土"},{"k":"life","zh":"縣內的「町」都讀作「ちょう」，只有川本町讀「まち」","en":"Every town here reads 町 as 'chō' except Kawamoto, the only one read 'machi'.","ja":"県内の町はすべて「ちょう」と読み、「まち」と読むのは川本町だけ"},{"k":"history","zh":"1876 年吞併鄰縣，一度管轄五個舊國，直到 1881 年鄰縣才再分出去","en":"In 1876 it absorbed its neighbor and briefly governed five old provinces, until the neighbor split off in 1881.","ja":"1876年に隣県を編入して旧5国を管轄したが、1881年に隣県が再び分立した"},{"k":"origin","zh":"1871 年先以城下町名設縣，4 個月後與周邊縣合併才改成現在的縣名","en":"Created in 1871 under its castle town's name, it took its current name just four months later after a merger.","ja":"1871年に城下町の名で置かれた県は、4か月後に周辺県と合併して現在の県名に改称"},{"k":"life","zh":"2005 年首屆日本生蛋拌飯研討會在雲南市舉辦，10 月 30 日因而成為生蛋拌飯日","en":"Japan's first egg-on-rice symposium was held in Unnan on Oct 30, 2005, now 'Tamago Kake Gohan Day'.","ja":"2005年10月30日に雲南市で第1回日本たまごかけごはんシンポジウムが開かれ、記念日になった"}],
"JP-33":[{"k":"people","zh":"B'z 主唱稻葉浩志的故鄉是這裡的津山","en":"B'z vocalist Koshi Inaba comes from Tsuyama here.","ja":"B'zの稲葉浩志は津山市出身。"},{"k":"work","zh":"橫溝正史《八墓村》的發想來自這裡 1938 年的真實事件","en":"Seishi Yokomizo's The Village of Eight Graves was inspired by a real 1938 incident here.","ja":"横溝正史『八つ墓村』は1938年にここで起きた事件が発想源。"},{"k":"festival","zh":"西大寺會陽中，裸男爭搶從窗口投下的「寶木」，搶到的就是福男","en":"At Saidaiji Eyo, nearly naked men fight for sacred sticks thrown from a window; the winner is the year's lucky man.","ja":"西大寺会陽では裸の男たちが窓から投下される宝木を奪い合う。"},{"k":"origin","zh":"名字來自旭川河口的一座小丘，宇喜多直家在丘上築城","en":"Its name comes from a small hill at the Asahi River mouth where Ukita Naoie built his castle.","ja":"名前は旭川河口の丘の名で、宇喜多直家がそこに城を築いた。"},{"k":"record","zh":"2020 年女性平均壽命 88.29 歲，全國第一","en":"Women here had Japan's longest life expectancy in 2020: 88.29 years.","ja":"2020年の女性の平均寿命は88.29歳で全国1位。"},{"k":"record","zh":"吉備津神社本殿有前後並排的兩個屋頂，是全國唯一的「吉備津造」","en":"Kibitsu Shrine's main hall, with two roofs joined front to back, is the only one of its style in Japan.","ja":"吉備津神社の本殿は全国唯一の比翼入母屋造（吉備津造）。"},{"k":"sport","zh":"職棒名投手、名教頭星野仙一出身這裡的倉敷","en":"Baseball star and manager Senichi Hoshino came from today's Kurashiki here.","ja":"野球の星野仙一は現在の倉敷市の出身。"},{"k":"work","zh":"動畫電影《午睡公主》以瀨戶大橋旁的下津井為舞台","en":"The anime film Napping Princess is set in Shimotsui at the foot of the Seto Ohashi Bridge.","ja":"映画『ひるね姫』の舞台は瀬戸大橋のたもとの下津井。"},{"k":"people","zh":"畫僧雪舟幼時在寶福寺被綁在柱上，傳說用腳趾沾眼淚畫出老鼠","en":"Tied to a pillar at Hōfuku-ji as a boy, painter Sesshū is said to have drawn a mouse with his toe in his tears.","ja":"雪舟は幼少期、宝福寺で柱に縛られ、涙を足の指につけて鼠を描いたと伝わる"},{"k":"history","zh":"1183 年水島之戰中發生日蝕，有一說是懂曆法的平家趁機擊敗源義仲軍","en":"An eclipse occurred during the 1183 Battle of Mizushima; the Taira, who may have predicted it, beat Yoshinaka.","ja":"1183年の水島の戦いの最中に日食が起き、予測していた平家が義仲軍を破ったという説がある"},{"k":"sport","zh":"本地 J 聯盟球隊名是義大利文「雉雞」，來自桃太郎的隨從與縣鳥","en":"Its J.League club 'Fagiano' means pheasant in Italian, after Momotarō's companion and the prefectural bird.","ja":"Jリーグのファジアーノはイタリア語で「キジ」。桃太郎のお供と県鳥にちなむ"},{"k":"legend","zh":"吉備津神社以釜鳴聲占卜吉凶，上田秋成《雨月物語》把它寫成鬼故事","en":"Kibitsu Shrine divines fortunes from a cauldron's hum, a rite turned into a ghost tale in 'Tales of Moonlight and Rain'.","ja":"吉備津神社の鳴釜神事は釜の音で吉凶を占い、『雨月物語』「吉備津の釜」の題材になった"},{"k":"legend","zh":"傳說鬼神溫羅被吉備津彥射中眼睛，流出的血形成了「血吸川」","en":"Legend says blood from the ogre Ura's eye, shot by Prince Kibitsuhiko, formed the Chisui ('blood-sucking') River.","ja":"鬼の温羅が吉備津彦命に目を射られ、流れた血が「血吸川」になったと伝わる"},{"k":"work","zh":"橫溝正史《獄門島》的孤島，設定在笠岡諸島的最南端","en":"Seishi Yokomizo's 'Death on Gokumon Island' is set on a fictional isle at the southern tip of the Kasaoka Islands.","ja":"横溝正史『獄門島』の舞台は、笠岡諸島の最南端にあるという設定の架空の島"},{"k":"people","zh":"畫出「夢二式美人」、作詞〈宵待草〉的竹久夢二生於邑久","en":"Yumeji Takehisa, painter of dreamy 'Yumeji-style beauties' and lyricist of 'Yoimachigusa', was born here.","ja":"「夢二式美人」で知られ「宵待草」を作詞した竹久夢二は邑久の生まれ"},{"k":"food","zh":"出身美咲町的岸田吟香，被視為日本第一位留下吃生蛋拌飯紀錄的人","en":"Ginkō Kishida, born in Misaki, is the first person on record in Japan to eat raw egg on rice.","ja":"美咲町出身の岸田吟香は、卵かけご飯を食べた記録が残る日本初の人物とされる"},{"k":"brand","zh":"三宅精一發明的導盲磚，1967 年首次鋪設在這裡的盲校附近","en":"Tactile paving, invented by Seiichi Miyake, was first laid in 1967 near a school for the blind here.","ja":"三宅精一が考案した点字ブロックは、1967年に県内の盲学校近くで初めて敷設された"},{"k":"brand","zh":"據說卡拉 OK 包廂就是在這裡誕生的","en":"The karaoke box is said to have originated here.","ja":"カラオケボックスはこの県が発祥とされる"},{"k":"brand","zh":"教育集團倍樂生的前身福武書店，1955 年在縣廳所在地創業","en":"Education giant Benesse began here in 1955 as the publisher Fukutake Shoten.","ja":"ベネッセは1955年、県庁所在地で福武書店として創業した"},{"k":"nature","zh":"湯原溫泉位在河中的混浴露天池「砂湯」，曾被評為露天風呂番付的西橫綱","en":"Yubara's free riverside 'Sunayu' bath was ranked a West Yokozuna in a 1977 open-air bath ranking.","ja":"湯原温泉の川の中の露天風呂「砂湯」は、1977年の露天風呂番付で西の横綱とされた"},{"k":"life","zh":"方言說「很厲害」是「でーれー」或「もんげー」，後者在《妖怪手錶》裡常出現","en":"Local dialect says 'dēre' or 'monge' for 'awesome'; 'monge' is a familiar word in Yo-kai Watch.","ja":"方言で「すごい」は「でーれー」「もんげー」。もんげーは『妖怪ウォッチ』でもおなじみ"},{"k":"record","zh":"造山古墳規模全國第 4，在一般人可以進入的古墳中是全國最大","en":"Tsukuriyama Kofun is Japan's 4th-largest burial mound and the largest one the public may enter.","ja":"造山古墳は全国4位の大きさで、一般人が立ち入れる古墳としては全国1位"},{"k":"record","zh":"1669 年池田光政時期開設的花畠教場，被視為全國最早的藩校","en":"Hanabatake Kyōjō, opened under lord Ikeda Mitsumasa in 1669, is considered Japan's first domain school.","ja":"池田光政の時代の1669年に開かれた花畠教場は、全国初の藩校とされる"},{"k":"record","zh":"笠岡 Fureai 機場是全國第一座「農道機場」","en":"Kasaoka Fureai Airport opened as Japan's first farm-road airport.","ja":"笠岡ふれあい空港は全国初の農道空港として開港した"},{"k":"history","zh":"關原之戰後，西軍大將宇喜多秀家被沒收領地、流放到八丈島","en":"After Sekigahara, local lord Ukita Hideie lost his domain and was exiled to Hachijō Island.","ja":"関ヶ原の戦い後、宇喜多秀家は所領を没収され八丈島へ流された"},{"k":"food","zh":"日生的「Kakioko」是加入大量牡蠣的大阪燒","en":"Hinase's 'kaki-oko' is okonomiyaki made with oysters.","ja":"日生の「カキオコ」は牡蠣を入れたお好み焼き"},{"k":"food","zh":"直接淋醬汁吃的「ぶっかけ烏龍麵」，一般認為發源於這裡","en":"Bukkake udon, noodles with sauce poured right over them, is said to have originated here.","ja":"ぶっかけうどんはこの県が発祥とされる"},{"k":"people","zh":"奈良時代的吉備真備與和氣清麻呂，都出身古代吉備國的這一帶","en":"Nara-period statesmen Kibi no Makibi and Wake no Kiyomaro both came from the ancient Kibi province here.","ja":"奈良時代の吉備真備と和気清麻呂は、ともに旧吉備国の出身"},{"k":"legend","zh":"龜石神社供奉神武東征時，載著嚮導珍彥的大烏龜","en":"Kameishi Shrine honors the giant turtle that carried Uzuhiko, sea guide for Emperor Jinmu's eastern campaign.","ja":"亀石神社は、神武東征で水先案内をした珍彦が乗った大亀を祀る"},{"k":"sport","zh":"創志學園 2011 年以棒球部創部第一年打進甲子園，創下史上首例","en":"In 2011 Sōshi Gakuen reached Kōshien in its baseball team's first year, a first in tournament history.","ja":"創志学園は2011年、創部1年目で甲子園に出場し、春夏通じて史上初となった"},{"k":"people","zh":"馬拉松選手有森裕子出身這裡，在 1992、1996 年奧運連續奪牌","en":"Marathoner Yuko Arimori, from here, won medals at both the 1992 and 1996 Olympics.","ja":"マラソンの有森裕子はこの県出身で、1992年と1996年の五輪でメダルを獲得"},{"k":"brand","zh":"陶藝家金重陶陽以備前燒獲認定為人間國寶","en":"Potter Tōyō Kaneshige was named a Living National Treasure for Bizen ware.","ja":"金重陶陽は備前焼で人間国宝に認定された"},{"k":"record","zh":"江戶時代私塾數量多達 144 所，居全國第一","en":"In the Edo period it had more private academies than anywhere else in Japan: 144.","ja":"江戸時代の私塾数は144か所で全国1位だった"},{"k":"nature","zh":"兒島湖不是天然湖，而是築堤封住兒島灣後形成的人工湖","en":"Lake Kojima is man-made, formed by damming off Kojima Bay.","ja":"児島湖は児島湾を締切堤防で仕切ってできた人造湖"}],
"JP-34":[{"k":"sport","zh":"J聯盟「Sanfrecce」隊名是日文「三」加義大利文「箭」，取自毛利元就三支箭","en":"J.League club Sanfrecce blends Japanese 'san' (three) and Italian 'frecce' (arrows), after Mori Motonari.","ja":"サンフレッチェは「三」と伊語の「矢」の合成、毛利元就の三本の矢から。"},{"k":"sport","zh":"職棒鯉魚隊沒有母公司，草創期靠球迷把錢投進酒桶撐過危機","en":"The Carp began as a citizens' team with no parent company and survived on fans' 'barrel donations'.","ja":"カープは親会社のない市民球団が源流で、樽募金で危機を乗り越えた。"},{"k":"people","zh":"電音女團 Perfume 三位成員都是這裡出身","en":"All three members of the techno-pop group Perfume are from here.","ja":"テクノポップユニットPerfumeは3人とも県出身。"},{"k":"work","zh":"動畫電影《謝謝你，在世界的角落找到我》主角從江波嫁到軍港吳","en":"In the film In This Corner of the World, the heroine marries from Eba into a family in the naval port of Kure.","ja":"『この世界の片隅に』の主人公すずは江波から軍港・呉へ嫁ぐ。"},{"k":"life","zh":"盂蘭盆節會在墓前供上彩色紙糊、牽牛花形的「盆燈籠」","en":"At Obon, families here set colorful paper lanterns shaped like morning glories at graves.","ja":"お盆には色紙で作った朝顔形の盆灯籠を墓に供える。"},{"k":"origin","zh":"一說地名是從毛利氏祖先與協助選城址的武將名字中各取一字","en":"One theory says the name takes one character each from a Mori ancestor and the officer who chose the castle site.","ja":"地名は毛利氏の祖先と城地を選んだ武将の名から一字ずつ取ったという説がある。"},{"k":"festival","zh":"6 月的「とうかさん」祭是當地人一年中第一次穿浴衣的日子","en":"The Tokasan festival in June marks the day locals put on yukata for the first time each year.","ja":"6月の「とうかさん」は、その年の浴衣の着始めの祭り。"},{"k":"life","zh":"宮島整座島是神域，島上至今連一座墳墓都沒有","en":"Miyajima is considered sacred, and to this day there is not a single grave on the island.","ja":"宮島は島全体が神域で、今も墓が1基もない。"},{"k":"legend","zh":"1749 年三次的 16 歲少年稻生平太郎，連續一個月遭妖怪騷擾的怪談舞台","en":"In 1749, 16-year-old Inō Heitarō of Miyoshi was haunted by yokai for a month, as told in 'Inō Mononoke Roku'.","ja":"1749年、三次の16歳稲生平太郎が一か月妖怪に悩まされた『稲生物怪録』の舞台"},{"k":"work","zh":"深作欣二 1973 年的經典黑道電影，以戰後的吳市一帶為舞台","en":"Kinji Fukasaku's 1973 yakuza film 'Battles Without Honor and Humanity' is set in postwar Kure.","ja":"深作欣二監督『仁義なき戦い』（1973年）は戦後の呉などが舞台"},{"k":"work","zh":"小津安二郎《東京物語》裡的老夫婦住在尾道","en":"In Ozu's 'Tokyo Story' (1953), the elderly couple live in Onomichi.","ja":"小津安二郎『東京物語』の老夫婦は尾道に暮らしている"},{"k":"people","zh":"導演大林宣彥以故鄉尾道為舞台拍了三部片，合稱「尾道三部曲」","en":"Director Nobuhiko Obayashi shot his 'Onomichi Trilogy', starting with 'I Are You, You Am Me', in his hometown.","ja":"大林宣彦監督は故郷尾道を舞台に『転校生』など「尾道三部作」を撮った"},{"k":"festival","zh":"尾道 11 月的 Becchā 祭，鬼神追著人打，被打到就一整年不生病","en":"At Onomichi's Becchā Festival in November, demons chase and whack people, bringing a year of good health.","ja":"尾道のベッチャー祭りでは鬼が人を叩いて回り、叩かれると一年病気をしないという"},{"k":"food","zh":"2001 年興起的無湯擔擔麵以花椒麻味為主角，要拌 30 次左右再吃","en":"Its soupless dandan noodles, born in 2001, star numbing Sichuan pepper and should be mixed about 30 times.","ja":"2001年に始まった汁なし担担麺は花椒のしびれが主役で、30回ほど混ぜて食べる"},{"k":"brand","zh":"百圓商店大創總部在這裡，起點是 1980 年左右在停車場擺的流動攤","en":"Daiso, the ¥100 shop chain, is headquartered here; it began around 1980 as a pop-up stall in parking lots.","ja":"ダイソーの大創産業は本社をこの県に置き、1980年頃の駐車場での移動販売が始まり"},{"k":"history","zh":"1894 年甲午戰爭時大本營設在這裡，明治天皇移駐，一時成為臨時首都","en":"During the 1894 Sino-Japanese War, Imperial HQ and Emperor Meiji moved here, making it a temporary capital.","ja":"日清戦争の1894年、大本営が置かれ明治天皇が移り、臨時の首都となった"},{"k":"history","zh":"1888 年舊日本海軍兵學校遷到江田島","en":"In 1888 the Imperial Japanese Naval Academy moved to Etajima here.","ja":"1888年、海軍兵学校が江田島に移転した"},{"k":"festival","zh":"插秧儀式「壬生花田植」在 2011 年列入聯合國非物質文化遺產","en":"Mibu no Hana-taue, a rice-planting rite, was inscribed on UNESCO's intangible heritage list in 2011.","ja":"壬生の花田植は2011年にユネスコ無形文化遺産に記載された"},{"k":"people","zh":"1928 年拿下三級跳金牌、成為日本首位奧運金牌得主的織田幹雄是這裡人","en":"Mikio Oda, Japan's first Olympic gold medalist (triple jump, 1928), was from here.","ja":"1928年三段跳で日本初の五輪金メダルを取った織田幹雄はこの県の出身"},{"k":"brand","zh":"世界級運動球品牌 Mikasa 與 Molten 都誕生於這裡","en":"Ball makers Mikasa and Molten, used in world sports, were both born here.","ja":"世界的なボールメーカー、ミカサとモルテンはともにこの地で生まれた"},{"k":"brand","zh":"宮島從寬政年間（1789～1801）開始生產飯勺","en":"Miyajima began producing wooden rice paddles (shamoji) in the Kansei era (1789–1801).","ja":"宮島では寛政年間にしゃもじの生産が始まった"},{"k":"people","zh":"史家賴山陽的《日本外史》大暢銷，影響了幕末的尊王攘夷運動","en":"Historian Rai San'yō's best-selling 'Nihon Gaishi' inspired the late-Edo movement to revere the emperor.","ja":"頼山陽の『日本外史』は大ベストセラーとなり、幕末の尊王攘夷運動に影響した"},{"k":"people","zh":"福山藩主阿部正弘任老中首座，參與簽訂日美和親條約","en":"Abe Masahiro, lord of Fukuyama, headed the shogunate council and helped conclude the 1854 US–Japan treaty.","ja":"福山藩主阿部正弘は老中首座として日米和親条約の締結に関わった"},{"k":"history","zh":"1619 年福島正則擅自修築城牆石垣，因而被沒收領地","en":"In 1619 lord Fukushima Masanori lost his domain for repairing castle walls without permission.","ja":"1619年、福島正則は無断で城の石垣を修築したとして改易された"},{"k":"history","zh":"1576 年被逐出京都的將軍足利義昭移居鞆，史稱「鞆幕府」","en":"In 1576 ousted shogun Ashikaga Yoshiaki set up at Tomo, a comeback attempt called the 'Tomo shogunate'.","ja":"1576年、足利義昭が鞆に拠点を移し再起を図った「鞆幕府」"},{"k":"legend","zh":"傳說神武天皇東征途中，在府中町的多祁理宮停留了約 7 年","en":"Legend says Emperor Jinmu stayed about seven years at Takeri Palace in Fuchū during his eastern campaign.","ja":"神武天皇は東征の途中、府中町の多祁理宮に約7年滞在したと伝わる"},{"k":"life","zh":"移民夏威夷的人太多，這裡的方言成了當地日裔社群共通語的基礎","en":"So many emigrants went to Hawaii that this dialect became the base of the local Japanese community's speech.","ja":"ハワイの日系社会では、移民が多かったこの地の方言が共通語の基盤となった"},{"k":"nature","zh":"帝釋峽有河水侵蝕石灰岩形成的天然石橋「雄橋」","en":"Taishakukyō Gorge features Ondoribashi, a natural limestone bridge carved by the river.","ja":"帝釈峡には川の侵食で石灰岩にできた天然橋「雄橋」がある"},{"k":"record","zh":"1872 年人口超過 90 萬，是全國第一（只有這一年）","en":"In 1872 its population topped 900,000, the largest of any prefecture that year.","ja":"1872年の統計では人口90万人を超え全国1位だった（この年のみ）"},{"k":"legend","zh":"傳說音戶瀨戶這道海峽是平清盛下令開鑿的","en":"Legend credits Taira no Kiyomori with cutting the Ondo Strait.","ja":"音戸の瀬戸は平清盛が開削したという伝承がある"},{"k":"brand","zh":"縫衣針產業在江戶時代淺野家治理時普及，成為在地名產","en":"Sewing-needle making took root here under the Asano lords in the Edo period.","ja":"縫い針づくりは江戸時代の浅野藩時代に普及し、地場産業となった"},{"k":"food","zh":"府中燒和三原燒，是有別於一般御好燒的在地版本","en":"Fuchū-yaki and Mihara-yaki are local dishes distinct from the standard okonomiyaki.","ja":"府中焼きや三原焼きは、お好み焼きとは別のご当地料理"}],
"JP-35":[{"k":"symbol","zh":"縣花是夏蜜柑的花","en":"Its prefectural flower is the natsumikan (summer orange) blossom.","ja":"県の花は夏みかんの花。"},{"k":"people","zh":"詩人中原中也出生在這裡的湯田溫泉","en":"Poet Chuya Nakahara was born at Yuda Onsen here.","ja":"詩人・中原中也は湯田温泉の生まれ。"},{"k":"people","zh":"UNIQLO 的母公司迅銷集團總部設在這裡","en":"Fast Retailing, the company behind Uniqlo, has its head office here.","ja":"ユニクロを展開するファーストリテイリングの本社がある。"},{"k":"festival","zh":"先帝祭裡扮成花魁的太夫踩外八字遊行，追悼沉海的安德天皇","en":"At the Sentei Festival, women dressed as courtesans parade in memory of Emperor Antoku, who drowned at sea.","ja":"先帝祭では花魁姿の太夫が外八文字で練り歩き、安徳天皇をしのぶ。"},{"k":"record","zh":"全國獨有的牛品種「無角和牛」是這裡培育出來的","en":"Mukaku Wagyu, a hornless cattle breed found nowhere else in Japan, was developed here.","ja":"全国唯一の無角和牛は県が誕生させた品種。"},{"k":"life","zh":"當地為了討吉利，把河豚叫「ふく」（福）","en":"Locals call pufferfish 'fuku' (luck) instead of 'fugu' for good fortune.","ja":"フグは縁起をかついで「ふく」と呼ばれる。"},{"k":"life","zh":"路邊護欄漆成黃色，取自特產夏蜜柑的顏色","en":"Guardrails here are painted yellow after the local natsumikan orange.","ja":"ガードレールは特産の夏みかんにちなんだ黄色。"},{"k":"record","zh":"有紀錄可查的日本第一個聖誕節，1552 年在這裡舉行","en":"Japan's earliest recorded Christmas celebration was held here in 1552.","ja":"記録に残る日本初のクリスマスは1552年にここで行われた。"},{"k":"symbol","zh":"縣鳥白頭鶴在八代越冬，1887 年成為日本第一個禁獵保護的對象","en":"Hooded cranes winter in Yashiro here; in 1887 they became Japan's first creatures protected from hunting.","ja":"県鳥ナベヅルが越冬する八代では、1887年に日本初の禁猟対象に指定された"},{"k":"symbol","zh":"見島牛被認為是和牛的原種，被指定為國家天然紀念物","en":"Mishima cattle, said to be the original Wagyu breed, are a national natural monument.","ja":"見島牛は和牛の原種といわれ、国の天然記念物に指定されている"},{"k":"legend","zh":"長門的油谷流傳楊貴妃漂流到此上岸的傳說","en":"Legend says Yang Guifei drifted ashore at Yuya in Nagato.","ja":"長門市油谷には楊貴妃が流れ着いたという伝説がある"},{"k":"brand","zh":"全國近七成的神社籤詩，出自周南市鹿野的女子道社","en":"Nearly 70% of Japan's omikuji fortune slips are made by Joshidōsha in Kano, Shūnan.","ja":"全国のおみくじの7割近くは周南市鹿野の女子道社が奉製している"},{"k":"sport","zh":"橫濱 DeNA 海灣之星的源頭，是下關起家的大洋漁業企業隊","en":"The Yokohama DeNA BayStars trace back to the company team of Taiyō Gyogyō, a Shimonoseki fishery.","ja":"横浜DeNAベイスターズは、下関発祥の大洋漁業の実業団が起源"},{"k":"brand","zh":"糖果廠商 Kanro 發源於光市","en":"Candy maker Kanro was founded in Hikari.","ja":"菓子メーカーのカンロは光市が発祥"},{"k":"brand","zh":"水產大廠日本水產（Nissui）發跡於下關","en":"Seafood giant Nissui got its start in Shimonoseki.","ja":"水産大手ニッスイは下関が発祥"},{"k":"people","zh":"日產財閥的創辦人鮎川義介出身這裡","en":"Yoshisuke Aikawa, founder of the Nissan conglomerate, was from here.","ja":"日産コンツェルンの創始者鮎川義介はこの県の出身"},{"k":"people","zh":"被稱為日本陸軍之父的大村益次郎，生於鑄錢司村","en":"Ōmura Masujirō, founder of Japan's modern army, was born in Suzenji village here.","ja":"日本陸軍の創始者とされる大村益次郎は、鋳銭司村の生まれ"},{"k":"work","zh":"2015 年 NHK 大河劇以吉田松陰之妹杉文為主角，主要舞台在萩","en":"NHK's 2015 taiga drama about Yoshida Shōin's sister Fumi is set mainly in Hagi.","ja":"2015年の大河ドラマ『花燃ゆ』は吉田松陰の妹・文が主人公で、萩が主な舞台"},{"k":"record","zh":"防府天滿宮建於 904 年，自稱日本最早創建的天神社","en":"Hōfu Tenmangū, founded in 904, claims to be the very first shrine built to Sugawara no Michizane.","ja":"防府天満宮は904年創建で、「日本最初に創建された天神様」を名乗る"},{"k":"festival","zh":"防府天滿宮 11 月的裸坊祭，要拖著約 1 噸重的御網代上下大石階","en":"At Hōfu's November Hadakabō Festival, crowds haul a one-ton float down and back up the shrine's great stairs.","ja":"防府天満宮の裸坊祭では、約1トンの御網代を引いて大石段を上り下りする"},{"k":"history","zh":"1876 年前原一誠等人在萩起兵反抗政府，史稱萩之亂","en":"In 1876 Maebara Issei led the Hagi Rebellion against the Meiji government.","ja":"1876年、前原一誠らが萩の乱を起こした"},{"k":"history","zh":"1831 年爆發據說參與者超過 10 萬人的防長大一揆","en":"The Bōchō uprising of 1831 is said to have involved over 100,000 people.","ja":"1831年の防長大一揆は、参加者10万人以上に及んだとされる"},{"k":"history","zh":"奈良到平安初期，日本唯一的鑄錢所就設在這裡","en":"From the Nara to the early Heian period, Japan's only coin mint operated here.","ja":"奈良〜平安初期、日本で唯一の鋳銭所がこの地に置かれていた"},{"k":"history","zh":"大內氏的城下町繁榮到約 4 萬人，被稱為「西京」","en":"Under the Ōuchi clan its castle town grew to about 40,000 people and was nicknamed 'Western Capital'.","ja":"大内氏の城下町は人口4万人規模に栄え、「西京」の異名を得た"},{"k":"food","zh":"岩國蓮藕有 9 個孔，比一般蓮藕多一個","en":"Iwakuni lotus roots have nine holes, one more than ordinary ones.","ja":"岩国レンコンは穴が9個あり、普通のレンコンより1つ多い"},{"k":"food","zh":"這裡的外郎糕以使用蕨粉為特色","en":"The local uirō sweet is distinguished by its use of bracken starch.","ja":"この地の外郎はわらび粉を使うのが特徴"},{"k":"food","zh":"日本第一家辛子明太子業者誕生於下關","en":"Japan's very first spicy mentaiko maker was born in Shimonoseki.","ja":"日本最初の辛子明太子の業者は下関で生まれた"},{"k":"festival","zh":"下松每年 11 月舉行「狐狸娶親」的遊行","en":"Kudamatsu holds a 'fox's wedding' procession every November.","ja":"下松市では11月に「狐の嫁入り」が行われる"},{"k":"life","zh":"縣府宣傳單位曾介紹，本縣的形狀和澳洲很像","en":"The prefectural PR office once pointed out that its outline looks like Australia.","ja":"県の広報広聴課が、県の形がオーストラリアに似ていると紹介した"},{"k":"history","zh":"1864 年因砲擊外國船隻，遭到列強聯合艦隊報復攻擊","en":"In 1864, after firing on foreign ships, it was bombarded by an allied Western fleet in retaliation.","ja":"1864年、外国船砲撃の報復として連合艦隊の攻撃を受けた（下関戦争）"},{"k":"people","zh":"高杉晉作率領奇兵隊，擊退了幕府第二次征討的大軍","en":"Takasugi Shinsaku's Kiheitai militia repelled the shogunate's second punitive expedition.","ja":"高杉晋作らの奇兵隊は、第二次征伐で幕府軍を退けた"},{"k":"food","zh":"「Hanakkorii」是菜心與青花菜雜交出的在地蔬菜","en":"'Hanakkorī' is a local green vegetable bred by crossing Chinese saishin with broccoli.","ja":"はなっこりーは、サイシンとブロッコリーを掛け合わせたこの県生まれの野菜"},{"k":"origin","zh":"別稱「防長」，取自古代的周防國與長門國","en":"Its nickname 'Bōchō' combines the old provinces of Suō and Nagato.","ja":"別名「防長」は、令制国の周防と長門に由来する"}],
"JP-36":[{"k":"people","zh":"創作歌手米津玄師的故鄉","en":"Hometown of singer-songwriter Kenshi Yonezu.","ja":"米津玄師の出身地。"},{"k":"people","zh":"作家瀨戶內寂聽出生在這裡的一家佛壇店","en":"Novelist and nun Jakucho Setouchi was born into a Buddhist altar shop here.","ja":"作家・瀬戸内寂聴は仏壇店の娘として生まれた。"},{"k":"festival","zh":"動漫祭典「Machi★Asobi」在這裡舉辦，長年由 ufotable 策劃","en":"The anime festival Machi Asobi, long produced by studio ufotable, is held here.","ja":"アニメの祭典「マチ★アソビ」の開催地。長くufotableが企画した。"},{"k":"sport","zh":"池田高中 1982 年夏、1983 年春連霸甲子園","en":"Ikeda High School won Koshien in summer 1982 and spring 1983 back to back.","ja":"池田高校は1982年夏・83年春の甲子園を連覇した。"},{"k":"record","zh":"弁天山標高 6.1 公尺，號稱日本最低的天然山","en":"Mt. Benten, 6.1 m tall, is said to be Japan's lowest natural mountain.","ja":"標高6.1mの弁天山は、自然の山として日本一低いとされる。"},{"k":"record","zh":"全國唯一沒有電車、只跑柴油車的縣，當地人把火車叫「汽車」","en":"It's the only prefecture with no electric trains, only diesel railcars, which locals call 'kisha'.","ja":"電車が走らず気動車だけの全国唯一の県で、鉄道を「汽車」と呼ぶ。"},{"k":"symbol","zh":"吉祥物是綠色柑橘頭的「酢橘君（すだちくん）」","en":"Its mascot is Sudachi-kun, a green citrus character.","ja":"マスコットキャラクターは「すだちくん」。"},{"k":"origin","zh":"古國名「阿波」源自北部盛產小米（粟）","en":"Its old province name, Awa, comes from the millet (awa) grown widely in the north.","ja":"旧国名「阿波」は北部に粟が多い「粟国」から。"},{"k":"legend","zh":"有人深信劍山埋著所羅門王的秘寶，戰前戰後都有人上山挖掘","en":"Some believed King Solomon's treasure lay buried on Mt. Tsurugi, prompting digs before and after WWII.","ja":"剣山にはソロモンの秘宝が埋まるとの説があり、戦前戦後に発掘が行われた"},{"k":"nature","zh":"劍山標高約 1955 公尺，是近畿以西僅次於石鎚山的高峰","en":"Mt. Tsurugi, about 1,955 m, is the second-highest peak west of the Kinki region.","ja":"剣山は標高約1955メートルで、近畿以西では石鎚山に次ぐ高峰"},{"k":"legend","zh":"江戶末期狸貓金長與六右衛門大戰的「阿波狸合戰」傳說","en":"The 'Awa Tanuki War' legend tells of a great battle between the raccoon dogs Kinchō and Rokuemon.","ja":"金長狸と六右衛門狸が戦った「阿波狸合戦」の伝説の舞台"},{"k":"work","zh":"吉卜力《平成狸合戰》中登場的金長狸，在小松島有神社祭祀","en":"Kinchō, the tanuki who appears in Ghibli's 'Pom Poko', is enshrined at a shrine in Komatsushima.","ja":"ジブリ『平成狸合戦ぽんぽこ』にも登場する金長狸は、小松島の金長神社に祀られる"},{"k":"work","zh":"佐田雅志的小說《眉山》2007 年拍成電影，以縣廳所在地為舞台","en":"Masashi Sada's novel 'Bizan', filmed in 2007, is set in this prefecture's capital.","ja":"さだまさしの小説『眉山』は2007年に映画化され、県庁所在地が舞台"},{"k":"food","zh":"阿波市的「盆烏龍麵」盛在大木盆裡，原本沾河魚熬的湯汁吃","en":"Awa City's 'tarai udon' is served in a big tub and dipped in broth made from river fish.","ja":"阿波市のたらいうどんは、たらいに入れ、川魚でとったつけ汁で食べる"},{"k":"people","zh":"葡萄牙外交官作家莫拉埃斯，在亡妻おヨネ的故鄉度過晚年","en":"Portuguese diplomat-writer Wenceslau de Moraes spent his last years here, his late wife Oyone's hometown.","ja":"ポルトガルの外交官で作家のモラエスは、亡妻おヨネの故郷であるこの地で晩年を過ごした"},{"k":"legend","zh":"阿南的「お松大權現」傳說飼貓化成怪貓為主人報仇，是日本三大怪貓傳說之一","en":"At Omatsu Daigongen in Anan, a cat avenged its wronged mistress, one of Japan's three great ghost-cat tales.","ja":"阿南市のお松大権現は、飼い猫が化け猫となって仇を討った日本三大怪猫伝の舞台"},{"k":"brand","zh":"日文文書軟體「一太郎」與輸入法 ATOK 的開發商，1979 年在這裡創業","en":"JustSystems, maker of the Ichitarō word processor and ATOK input method, was founded here in 1979.","ja":"ワープロ「一太郎」やATOKのジャストシステムは1979年にこの地で創業した"},{"k":"history","zh":"在藩的保護下，這裡的藍染原料在 18 世紀稱霸全國市場","en":"Under the domain's protection, its indigo dye dominated Japan's market in the 1700s.","ja":"阿波藍は藩の保護で発展し、1700年代には全国市場を支配した"},{"k":"origin","zh":"拉麵上的「鳴門卷」，名稱來自這裡海峽的漩渦","en":"Naruto, the swirled fishcake on ramen, is named after the whirlpools of the strait here.","ja":"ラーメンの具「なると巻」の名は、この地の海峡の渦潮にちなむ"},{"k":"legend","zh":"秘境祖谷流傳屋島之戰後，平家殘兵逃到這裡落腳的傳說","en":"Legend says Taira clan survivors fled to the remote Iya valley after the Battle of Yashima.","ja":"祖谷には屋島の戦いで敗れた平家の落人が住み着いたという伝説がある"},{"k":"origin","zh":"廢藩置縣後一度叫「名東縣」，因城下町位在名東郡","en":"After 1871 it was briefly called Myōdō Prefecture, after the district holding its castle town.","ja":"廃藩置県後は一時「名東県」で、城下が名東郡にあったことに由来する"},{"k":"people","zh":"1974 年就任的首相三木武夫，是第一位出身這裡的首相","en":"Takeo Miki, who became prime minister in 1974, was the first PM from here.","ja":"1974年に首相となった三木武夫は、県出身初の内閣総理大臣"},{"k":"nature","zh":"縣內最長的河不是吉野川，而是全長 125 公里的那賀川","en":"Its longest river isn't the Yoshino but the 125 km Naka River.","ja":"県内最長の川は吉野川ではなく、延長125キロの那賀川"},{"k":"nature","zh":"吉野川中的善入寺島，被稱為日本最大的河中島","en":"Zennyūji Island in the Yoshino River is said to be Japan's largest river island.","ja":"吉野川の善入寺島は日本最大の川中島とされる"},{"k":"sport","zh":"J 聯盟球隊名結合義大利文「漩渦」，與土佐、伊予、讚岐的字首 TIS","en":"Its J.League club's name joins Italian 'vortice' (whirlpool) with TIS for Tosa, Iyo and Sanuki.","ja":"Jリーグのヴォルティスは、イタリア語の「渦」と土佐・伊予・讃岐の頭文字TISを合わせた名"},{"k":"food","zh":"祖谷地方的鄉土料理「蕎麥米湯」，用整粒蕎麥煮成","en":"Sobagome-jiru, a soup of whole buckwheat grains, is a traditional dish of the Iya area.","ja":"祖谷地方の郷土料理に、そばの実を使った「そば米汁」がある"},{"k":"history","zh":"1880 年才從高知縣分離出來，成為現在的縣","en":"It only became a separate prefecture in 1880, splitting off from Kōchi.","ja":"1880年、高知県から分離して現在の県が発足した"},{"k":"origin","zh":"大步危峽谷的名字，俗稱來自「大步走很危險」","en":"Ōboke Gorge's name is popularly read as 'dangerous to walk with big strides'.","ja":"大歩危の名は俗に「大股で歩くと危ない」ことに由来するといわれる"},{"k":"legend","zh":"妖怪「兒啼爺」據說就發源於大步危一帶","en":"The yokai Konaki-jijii is said to have originated in the Ōboke area.","ja":"妖怪「児啼爺」は大歩危の周辺が発祥とされる"},{"k":"history","zh":"2000 年吉野川第十堰改建可動堰的住民投票，反對票佔多數","en":"In a 2000 referendum, residents voted against replacing the Yoshino River's Daijū weir with a movable dam.","ja":"2000年、吉野川第十堰の可動堰化を問う住民投票で反対が多数を占めた"},{"k":"food","zh":"劍町的「半田素麵」是在地的鄉土料理","en":"Handa sōmen noodles are a traditional dish of the town of Tsurugi.","ja":"つるぎ町の半田そうめんは郷土料理として知られる"}],
"JP-37":[{"k":"people","zh":"創辦雜誌《文藝春秋》的作家菊池寬出身這裡","en":"Writer Kan Kikuchi, founder of the magazine Bungeishunju, was born here.","ja":"『文藝春秋』を創刊した作家・菊池寛の出身地。"},{"k":"people","zh":"首相大平正芳出身這裡，因說話常「啊、嗚」被叫「啊嗚宰相」","en":"PM Masayoshi Ohira came from here; his 'ah, uh' speaking habit earned him the nickname 'Ah-Uh Premier'.","ja":"首相・大平正芳の出身地。「アーウー宰相」と呼ばれた。"},{"k":"sport","zh":"J聯盟球隊名結合當地名物「釜玉烏龍麵」與義大利文的「海」","en":"Its J.League club's name blends kamatama udon with 'mare', Italian for sea.","ja":"Jリーグのカマタマーレは「釜玉うどん」と伊語の「海」の合成。"},{"k":"work","zh":"電影《二十四隻眼睛》把女老師與 12 個學生的故事放在小豆島","en":"The film Twenty-Four Eyes set its story of a young teacher and 12 pupils on Shodoshima.","ja":"映画『二十四の瞳』で小豆島が女性教師と12人の教え子の舞台に。"},{"k":"work","zh":"電影《在世界的中心呼喊愛》主要在這裡的庵治町取景","en":"The film Crying Out Love, in the Center of the World was mainly shot in Aji here.","ja":"映画『世界の中心で、愛をさけぶ』のメインロケ地は庵治町。"},{"k":"life","zh":"2020 年的條例建議 18 歲以下打電玩每天以 60 分鐘為限","en":"A 2020 ordinance recommends under-18s limit video games to 60 minutes a day.","ja":"2020年の条例で、18歳未満のゲームは1日60分が目安に。"},{"k":"life","zh":"新年雜煮用白味噌，裡面放包紅豆餡的年糕","en":"Its New Year zoni soup is made with white miso and mochi stuffed with sweet bean paste.","ja":"正月の雑煮は白味噌仕立てで、あんこ入りの餅を入れる。"},{"k":"festival","zh":"每 3 年一次的瀨戶內國際藝術祭，以直島、豐島等島嶼為會場","en":"The Setouchi Triennale art festival, held every three years, centers on islands such as Naoshima and Teshima.","ja":"3年に一度の瀬戸内国際芸術祭は直島・豊島などの島々が会場。"},{"k":"history","zh":"保元之亂落敗的崇德上皇被流放到這裡，1164 年死於當地，至死沒能回到京都","en":"Retired Emperor Sutoku, exiled here after losing the 1156 Hogen Rebellion, died here in 1164.","ja":"保元の乱に敗れた崇徳上皇はここへ流され、1164年に都へ戻れぬまま没した"},{"k":"legend","zh":"傳說崇德上皇抄的佛經被退回後，以血寫下詛咒、化為天狗，名列日本三大怨靈","en":"Legend says exiled Emperor Sutoku wrote a curse in blood and became one of Japan's three great vengeful spirits.","ja":"写経を送り返された崇徳上皇は血で呪いを書き天狗になったと伝わり、日本三大怨霊の一人とされる"},{"k":"people","zh":"修復靜電發生器「エレキテル」的江戶奇才平賀源內，出身這裡的志度","en":"Hiraga Gennai, the Edo-era polymath who restored the 'elekiter' static generator, was born in Shido here.","ja":"エレキテルを復元した江戸の奇才・平賀源内は、ここの志度の生まれ"},{"k":"legend","zh":"外海的女木島因桃太郎傳說被暱稱為「鬼島」，山頂附近有長約 400 公尺的大洞窟","en":"Megijima offshore is nicknamed 'Ogre Island' after the Momotaro tale, with a 400 m cave near its summit.","ja":"沖の女木島は桃太郎伝説にちなみ「鬼ヶ島」と呼ばれ、山頂近くに全長約400mの大洞窟がある"},{"k":"work","zh":"村上春樹《海邊的卡夫卡》中，15 歲少年離家出走後落腳這裡的一座私人圖書館","en":"In Haruki Murakami's Kafka on the Shore, the 15-year-old runaway takes refuge in a private library here.","ja":"村上春樹『海辺のカフカ』で、家出した15歳の少年はここの私設図書館に身を寄せる"},{"k":"record","zh":"丸龜城的石牆從山腳層層疊到山頂，總高度日本第一；天守則是現存天守中最小的","en":"Marugame Castle has Japan's tallest stone walls in total height, and the smallest of Japan's original keeps.","ja":"丸亀城の石垣は総高日本一で、天守は現存天守の中で最も小さい"},{"k":"sport","zh":"1924 年第一屆春季甲子園（選拔中等學校野球大會）由這裡的一所商業學校奪冠","en":"A commercial school from here won the very first spring national school baseball tournament in 1924.","ja":"1924年の第1回選抜中等学校野球大会は、ここの商業学校が初代王者となった"},{"k":"festival","zh":"傳說弘法大師教村中女子阿綾跳舞後降下大雨，這支「綾子踊」2022 年列入聯合國非物質文化遺產","en":"Ayako Odori, a rain dance said to be taught by Kobo Daishi to a woman named Aya, joined UNESCO's list in 2022.","ja":"弘法大師が綾という女性に教えると雨が降ったという「綾子踊」は、2022年にユネスコ無形文化遺産となった"},{"k":"nature","zh":"滿濃池是日本最大的灌溉用蓄水池，821 年由空海指揮修築，周長約 20 公里","en":"Mannoike, Japan's largest irrigation reservoir, was repaired under Kukai's direction in 821.","ja":"日本最大の灌漑用ため池・満濃池は、821年に空海の指揮で修築された"},{"k":"nature","zh":"三豐市的父母濱退潮後沙灘像鏡子一樣倒映天空，被稱為「日本的烏尤尼鹽湖」","en":"At low tide, Chichibugahama beach in Mitoyo mirrors the sky, earning the nickname 'Japan's Uyuni Salt Flat'.","ja":"三豊市の父母ヶ浜は干潮時に空を鏡のように映し、「日本のウユニ塩湖」と呼ばれる"},{"k":"food","zh":"外海伊吹島產的小魚乾「伊吹いりこ」，是許多烏龍麵店熬高湯的材料","en":"Dried anchovies from Ibukijima island are used for the soup stock in many of the local udon shops.","ja":"伊吹島の煮干し「伊吹いりこ」は、多くのうどん店でだしに使われている"},{"k":"life","zh":"伊吹島的方言據說保留了平安時代末期京都的聲調，在全國相當罕見","en":"The dialect of Ibukijima island is said to preserve the pitch accent of late Heian-period Kyoto.","ja":"伊吹島の方言は平安時代末期の京都のアクセントを残すとされ、全国でも珍しい"},{"k":"people","zh":"設計三越百貨紅白包裝紙「華ひらく」的畫家豬熊弦一郎在這裡出生長大","en":"Painter Genichiro Inokuma, who designed Mitsukoshi's red-and-white wrapping paper, was born and raised here.","ja":"三越の包装紙「華ひらく」をデザインした画家・猪熊弦一郎はここで生まれ育った"},{"k":"brand","zh":"冷凍烏龍麵大廠加卜吉（今 TableMark）起家於觀音寺港邊的一家海產加工小店","en":"Frozen-udon giant Katokichi (now TableMark) began as a small seafood processor by the port of Kanonji.","ja":"冷凍うどん大手の加ト吉（現テーブルマーク）は、観音寺の港近くの水産加工店から始まった"},{"k":"brand","zh":"東部有一座以手套產業為主的城市，國內手套生產占比約九成","en":"A city in the east of this prefecture makes about 90% of Japan's domestically produced gloves.","ja":"東部のある市は手袋産業が主力で、国内生産シェアは約9割"},{"k":"record","zh":"1928 年野網和三郎在引田的安戶池成功養殖青魽，是世界首次鹹水魚養殖事業化","en":"In 1928 Wasaburo Noami farmed yellowtail at Atoike pond, the world's first commercial saltwater fish farm.","ja":"1928年、野網和三郎が引田の安戸池でハマチ養殖を事業化し、鹹水魚では世界初とされる"},{"k":"history","zh":"江戶時代以鹽、棉、砂糖並稱「三白」，砂糖多作為獻給幕府的貢品","en":"In the Edo period its 'three whites' were salt, cotton and sugar, and much of the sugar went to the shogunate.","ja":"江戸時代は塩・木綿・砂糖が「三白」と呼ばれ、砂糖は幕府への献上品に多く使われた"},{"k":"history","zh":"明治初年曾被併入愛媛縣，1888 年 12 月 3 日才再度設縣，大致形成現在的縣域","en":"Once merged into Ehime, this prefecture was re-established on December 3, 1888, with roughly today's borders.","ja":"明治初期に愛媛県へ合併されたが、1888年12月3日に再び置かれ、ほぼ現在の県域になった"},{"k":"life","zh":"寶可夢「呆呆獸」被任命為這裡的觀光宣傳團成員","en":"The Pokemon Slowpoke has been appointed a member of this prefecture's tourism PR team.","ja":"ポケモンのヤドンが、ここの観光PR団の一員に任命されている"},{"k":"symbol","zh":"縣樹與縣花都是橄欖，縣鳥是小杜鵑（ホトトギス）","en":"Its prefectural tree and flower are both the olive, and its bird is the lesser cuckoo.","ja":"県の木と県の花はどちらもオリーブ、県の鳥はホトトギス"},{"k":"history","zh":"後來被奉為學問之神的菅原道真，曾在這裡擔任國司","en":"Sugawara no Michizane, later worshipped as the god of learning, once served as provincial governor here.","ja":"のちに学問の神とされる菅原道真は、かつてここの国司を務めた"},{"k":"record","zh":"縣廳所在地的中央商店街，據稱擁有日本最長的拱廊","en":"The central shopping street of the prefectural capital is said to have the longest arcade in Japan.","ja":"県庁所在地の中央商店街は、日本一長いアーケードを持つとされる"}],
"JP-38":[{"k":"symbol","zh":"吉祥物「みきゃん」是橘子小狗，因為縣的形狀像奔跑的狗","en":"Its mascot Mikyan is an orange-dog, partly because the prefecture is shaped like a running dog.","ja":"マスコット「みきゃん」はみかんと犬。県の形が走る犬に似るのも理由。"},{"k":"origin","zh":"名字來自《古事記》中的女神名，是全國唯一以神名命名的縣","en":"Its name comes from a goddess in the Kojiki, making it the only prefecture named after a deity.","ja":"名前は『古事記』の女神の名で、神名を付けた全国唯一の県。"},{"k":"record","zh":"今治市的吉祥物「巴里桑」拿下 2012 年吉祥物大賽冠軍","en":"Imabari's mascot Barysan won the 2012 Yuru-chara Grand Prix.","ja":"今治市のバリィさんはゆるキャラグランプリ2012で優勝した。"},{"k":"work","zh":"日劇《東京愛情故事》結局，女主角把手帕綁在梅津寺站的欄杆上","en":"In the finale of Tokyo Love Story, Rika ties her handkerchief to the fence at Baishinji Station here.","ja":"『東京ラブストーリー』最終回、リカが梅津寺駅の柵にハンカチを結んだ。"},{"k":"work","zh":"道後溫泉本館是《神隱少女》湯屋的原型之一","en":"Dogo Onsen's main building is one of the models for the bathhouse in Spirited Away.","ja":"道後温泉本館は『千と千尋の神隠し』の油屋のモデルのひとつ。"},{"k":"work","zh":"《坂上之雲》的三位主角秋山兄弟與正岡子規都出身這裡","en":"The three heroes of Clouds Above the Hill, the Akiyama brothers and Masaoka Shiki, came from here.","ja":"『坂の上の雲』の主人公、秋山兄弟と正岡子規はここの出身。"},{"k":"festival","zh":"新居濱太鼓祭的太鼓台重約 2 噸，要 200 多人一起扛","en":"At the Niihama Taiko Festival, 2-ton drum floats are hoisted by more than 200 bearers.","ja":"新居浜太鼓祭りの太鼓台は重さ約2トン、200人以上で担ぐ。"},{"k":"life","zh":"宴會遊戲「野球拳」是這裡的伊予鐵棒球隊 1924 年在客場比賽後的宴會上首創的","en":"The party game yakyuken was invented in 1924 by a baseball team from here, at a banquet after an away game.","ja":"宴会芸「野球拳」は1924年、ここの伊予鉄野球部が遠征試合後の懇親会で始めたもの。"},{"k":"people","zh":"八幡濱出身的二宮忠八看烏鴉滑翔得到靈感，1893 年做出飛行器模型，比萊特兄弟首飛早十年","en":"Inspired by gliding crows, Chuhachi Ninomiya built a flying-machine model in 1893, a decade before the Wrights flew.","ja":"八幡浜生まれの二宮忠八はカラスの滑空に着想し、ライト兄弟より10年早い1893年に飛行器の模型を作った"},{"k":"people","zh":"1891 年大津事件中，頂住政府壓力守住司法獨立的法官兒島惟謙出身宇和島","en":"Kojima Iken, the judge who upheld judicial independence in the 1891 Otsu Incident, was born in Uwajima.","ja":"1891年の大津事件で司法権の独立を守った「護法の神様」児島惟謙は宇和島の生まれ"},{"k":"people","zh":"以氣候模型預測全球暖化、2021 年獲諾貝爾物理學獎的真鍋淑郎出身這裡","en":"Syukuro Manabe, who won the 2021 Nobel Prize in Physics for climate modeling, was born here.","ja":"気候モデルで2021年のノーベル物理学賞を受けた真鍋淑郎はここの出身"},{"k":"history","zh":"平安時代的藤原純友以宇和海的日振島為據點，率千餘艘船橫行周邊海域","en":"In the 10th century, Fujiwara no Sumitomo used Hiburijima island as his base, commanding over 1,000 ships.","ja":"平安時代の藤原純友は日振島を根城に、千艘以上の船を操って周辺の海を荒らした"},{"k":"history","zh":"伊達政宗的長子秀宗 1614 年受封宇和島十萬石，與仙台並稱「西國的伊達」","en":"Date Hidemune, eldest son of Date Masamune, was granted Uwajima in 1614, founding a western Date house.","ja":"伊達政宗の長子・秀宗が1614年に宇和島10万石を与えられ、「西国の伊達」が生まれた"},{"k":"history","zh":"號稱「日本最大海賊」的村上海賊以能島等島嶼為據點，向過往船隻收通行費、保障航行安全","en":"The Murakami pirates, 'Japan's largest pirates', were based on islands here and charged ships tolls for safe passage.","ja":"「日本最大の海賊」村上海賊は能島などを拠点に、通行料を払った船の安全を保障した"},{"k":"record","zh":"大三島的大山祇神社收藏了全國國寶與重要文化財級甲冑的約四成","en":"Oyamazumi Shrine on Omishima holds about 40% of Japan's armor designated as national treasures or cultural properties.","ja":"大三島の大山祇神社は、国宝・重要文化財に指定された甲冑の約4割を所蔵する"},{"k":"record","zh":"來島海峽大橋是世界第一座三連吊橋，全長約 4.1 公里","en":"The Kurushima Kaikyo Bridge, about 4.1 km long, was the world's first triple suspension bridge.","ja":"来島海峡大橋は世界初の3連吊橋で、全長は約4.1km"},{"k":"festival","zh":"西條祭中，伊曾乃神社一社就奉納超過 80 台山車，是單一神社祭典的全國最多","en":"At the Saijo Festival, Isono Shrine alone receives over 80 danjiri floats, the most for any single shrine in Japan.","ja":"西条祭りでは伊曽乃神社だけで80台を超えるだんじりが奉納され、一社の祭礼として全国最多"},{"k":"festival","zh":"宇和島 7 月的和靈大祭上，竹架身軀、牛頭造型的山車「牛鬼」搖頭擺尾遊街","en":"At Uwajima's July Warei festival, 'ushi-oni' floats with bull-like heads swing and twist through the streets.","ja":"宇和島の7月の和霊大祭では、竹組みの胴に頭を付けた山車「牛鬼」が首を振って練り歩く"},{"k":"life","zh":"當地相信讓「牛鬼」咬一下孩子的頭會變聰明，扛手休息時大人會把孩子帶過去","en":"Locals believe a child whose head is 'bitten' by an ushi-oni float will grow up smarter.","ja":"牛鬼に子どもの頭をかんでもらうと賢くなるといわれ、休憩中に子や孫を連れてくる人もいる"},{"k":"legend","zh":"神話說大國主命用海底管道把大分的溫泉引來，救活病倒的少彥名命，祂高興得在石上跳舞","en":"Myth says Okuninushi piped hot water undersea from Oita to revive the ailing Sukunahikona, who then danced on a stone.","ja":"大国主命が速見の湯を海底の管で引いて病の少彦名命を治し、少彦名命は喜んで石の上で踊ったという"},{"k":"history","zh":"據《風土記》逸文記載，聖德太子 596 年曾來這裡的溫泉療養","en":"Prince Shotoku is recorded as visiting the hot springs here in 596 to recuperate.","ja":"596年に聖徳太子が病気療養のためここの温泉に滞在したと風土記逸文に記されている"},{"k":"nature","zh":"佐田岬半島長約 40 公里、最窄處僅 0.8 公里，號稱日本最細長的半島","en":"Sadamisaki Peninsula, about 40 km long and only 0.8 km wide at its narrowest, is called Japan's slenderest.","ja":"佐田岬半島は長さ約40km、最も狭い所は幅0.8kmで、日本一細長い半島とされる"},{"k":"nature","zh":"宇和島遊子水荷浦的梯田在陡坡上疊起六十多段石牆，一路延伸到海拔 90 公尺","en":"The Yusu Mizugaura terraced fields near Uwajima climb over 60 stone-walled steps up to 90 m above the sea.","ja":"宇和島の遊子水荷浦の段畑は、60段以上の石垣が海抜90mの山上まで続く"},{"k":"symbol","zh":"縣獸是 2012 年被宣告滅絕的日本水獺","en":"Its prefectural animal is the Japanese river otter, declared extinct in 2012.","ja":"県の獣は、2012年に絶滅種とされたニホンカワウソ"},{"k":"symbol","zh":"縣魚是真鯛，縣鳥是日本歌鴝（コマドリ）","en":"Its prefectural fish is the red sea bream and its bird is the Japanese robin.","ja":"県の魚はマダイ、県の鳥はコマドリ"},{"k":"brand","zh":"1952 年上市的橘子汁「ポンジュース」，取名自希望成為「日本第一（NIPPON-ICHI）」","en":"Pom Juice, launched in 1952, was named in hope it would become Japan's number one (Nippon-ichi) juice.","ja":"1952年発売のポンジュースは、「ニッポンイチ」のジュースになるようにと名付けられた"},{"k":"life","zh":"「打開水龍頭會流出橘子汁」原是關於這裡的玩笑，後來真的做成水龍頭放在機場","en":"The joke that orange juice flows from taps here came true when a juice faucet was set up at the airport.","ja":"「蛇口からみかんジュースが出る」という冗談は、本当に蛇口が作られ空港などに設置された"},{"k":"brand","zh":"衛生紙品牌「elleair」的大王製紙，總公司設在這裡的四國中央市","en":"Daio Paper, maker of the elleair tissue brand, is headquartered in Shikokuchuo here.","ja":"「エリエール」の大王製紙は、ここの四国中央市に本社を置く"},{"k":"brand","zh":"砥部燒起源於用磨刀石的碎屑燒瓷，特色是厚實乳白瓷上的藍色紋樣","en":"Tobe ware began as porcelain made from whetstone scraps, known for thick milky-white bodies with blue designs.","ja":"砥部焼は砥石くずを使って始まった磁器で、厚手の乳白色の地に藍色の模様が特徴"},{"k":"sport","zh":"1969 年夏季甲子園決賽，這裡的一所商業高校與三澤高校延長 18 局平手，隔天重賽才奪冠","en":"In the 1969 summer Koshien final, a school from here drew over 18 innings with Misawa, then won the replay.","ja":"1969年夏の甲子園決勝で、ここの商業高校が三沢と延長18回引き分け、翌日の再試合で優勝した"},{"k":"food","zh":"越往南部走，味噌和醬油越甜，外地人甚至戲稱為「砂糖醬油」","en":"The farther south you go here, the sweeter the miso and soy sauce, which outsiders tease as 'sugar soy sauce'.","ja":"県南部へ行くほど味噌や醤油が甘くなり、他県の人には「砂糖醤油」と言われることもある"},{"k":"life","zh":"流傳的比喻：拿到 100 萬日圓，東部人拿去做生意、中部人靠利息過溫泉生活、南部人一晚花光","en":"Local joke: given a million yen, easterners invest it, central folk live on interest, southerners blow it in a night.","ja":"100万円を手にしたら東部は商売に、中部は利息で温泉暮らし、南部は一晩で使い切る、という例え話がある"},{"k":"record","zh":"1888 年這裡的私鐵在三津與縣廳所在地之間開通，是四國第一條鐵路","en":"A private railway opened here in 1888 between Mitsu and the prefectural capital, the first railway on Shikoku.","ja":"1888年、ここの私鉄が三津と県庁所在地の間に開業し、四国初の鉄道となった"}],
"JP-39":[{"k":"symbol","zh":"縣鳥是八色鳥","en":"Its prefectural bird is the fairy pitta.","ja":"県の鳥はヤイロチョウ。"},{"k":"people","zh":"《麵包超人》作者柳瀨嵩在這裡長大，當地有麵包超人博物館","en":"Anpanman creator Takashi Yanase grew up here, home to the Anpanman Museum.","ja":"アンパンマンのやなせたかしはここで育ち、記念館がある。"},{"k":"work","zh":"吉卜力動畫《聽見濤聲》以這裡為舞台","en":"Studio Ghibli's Ocean Waves is set here.","ja":"ジブリ作品『海がきこえる』の舞台。"},{"k":"festival","zh":"「どろめ祭」比賽一口氣喝乾大杯清酒，男生要喝 1.8 公升","en":"At the Dorome Festival, contestants race to down huge cups of sake: 1.8 liters for men.","ja":"どろめ祭りでは男性1升、女性5合の酒を一気飲みして速さを競う。"},{"k":"origin","zh":"城址夾在兩河間常淹水，原名「河中」，後來改成同音的吉祥字","en":"The flood-prone castle site between two rivers was first named 'amid the rivers', later rewritten with luckier characters.","ja":"城地は川に挟まれ洪水が多く「河中山」と呼ばれ、のち同音の字に改めた。"},{"k":"record","zh":"1934 年室戶颱風登陸時氣壓 911.6 hPa，日本本土觀測史上最低","en":"The 1934 Muroto Typhoon made landfall at 911.6 hPa, the lowest ever recorded on Japan's main islands.","ja":"室戸台風は上陸時911.6hPa、本土上陸台風で観測史上最低。"},{"k":"life","zh":"週日街市從 1690 年延續至今，約 300 個攤位綿延約 1 公里","en":"Its Sunday street market has run since 1690, with about 300 stalls stretching some 1 km.","ja":"日曜市は1690年から続き、約300店が約1kmにわたって並ぶ。"},{"k":"people","zh":"統一四國的戰國大名長宗我部元親，小時候文靜白皙被笑稱「姬若子」，初陣後改被讚為「鬼若子」","en":"Warlord Chosokabe Motochika was mocked as a pale, shy 'princess boy' until his first battle earned him 'demon boy'.","ja":"四国を統一した長宗我部元親は幼い頃「姫若子」と揶揄されたが、初陣の活躍で「鬼若子」と称えられた"},{"k":"history","zh":"1596 年西班牙船聖費利佩號漂到這裡被拖進浦戶灣，事件被視為二十六聖人殉教的導火線","en":"In 1596 the Spanish galleon San Felipe drifted ashore here, an event linked to the martyrdom of the 26 Saints.","ja":"1596年、スペイン船サン＝フェリペ号が漂着して浦戸湾に曳航され、二十六聖人殉教のきっかけとされる"},{"k":"history","zh":"1867 年這裡的前藩主山內容堂向將軍遞出建白書，直接促成「大政奉還」","en":"In 1867 Yamauchi Yodo of this domain petitioned the shogun, directly prompting the return of power to the emperor.","ja":"1867年、ここの山内容堂が提出した建白書が大政奉還の直接のきっかけとなった"},{"k":"work","zh":"紀貫之卸任這裡的國司返京時，假扮成女性用假名寫下旅途，是日本最早的日記文學之一","en":"Ki no Tsurayuki, ending his term as governor here, wrote one of Japan's earliest diaries while posing as a woman.","ja":"ここの国司の任を終えた紀貫之は、女性を装い仮名で帰京の旅を記し、最初期の日記文学となった"},{"k":"record","zh":"2013 年 8 月 12 日四萬十市江川崎測得 41.0℃，是當時日本觀測史上最高溫","en":"On August 12, 2013, Ekawasaki in Shimanto hit 41.0 C, Japan's highest temperature on record at the time.","ja":"2013年8月12日、四万十市江川崎で当時の日本最高気温41.0℃を観測した"},{"k":"record","zh":"1948 年這裡的縣立圖書館開辦日本第一個汽車巡迴圖書館","en":"In 1948 the prefectural library here launched Japan's first mobile library by car.","ja":"1948年、ここの県立図書館が日本初の移動図書館（自動車文庫）を始めた"},{"k":"life","zh":"1949 至 1956 年這裡的公立高中全面免試入學，市區還曾用抽籤決定入學者","en":"From 1949 to 1956 its public high schools took everyone without exams; some city schools even chose by lottery.","ja":"1949〜1956年は公立高校が無試験の全入制で、市内では抽選で入学者を決めた時期もある"},{"k":"nature","zh":"仁淀川的深潭與瀑布藍得出奇，被稱為「仁淀藍」，2010 年水質全國第一","en":"The Niyodo River's pools are so blue they're called 'Niyodo Blue'; it ranked first in Japan for water quality in 2010.","ja":"仁淀川の青く澄んだ淵は「仁淀ブルー」と呼ばれ、2010年に水質全国1位となった"},{"k":"nature","zh":"日本三大鐘乳洞之一的龍河洞，有一個彌生土器被鐘乳石包住的「神之壺」","en":"Ryugado Cave, one of Japan's three great limestone caves, has a Yayoi pot fused into the rock, the 'God's Pot'.","ja":"日本三大鍾乳洞の龍河洞には、弥生土器が石灰華に取り込まれた「神の壺」がある"},{"k":"nature","zh":"室戶一帶因地震隆起形成層層海階，2011 年獲認定為世界地質公園","en":"Lifted by earthquakes into marine terraces, the Muroto area became a UNESCO Global Geopark in 2011.","ja":"地震による隆起で海成段丘ができた室戸は、2011年に世界ジオパークに認定された"},{"k":"nature","zh":"魚梁瀨杉林名列日本三大美林，魚梁瀨杉也是縣樹","en":"Yanase cedar forests rank among Japan's three most beautiful forests, and the cedar is the prefectural tree.","ja":"魚梁瀬杉は日本三大美林の一つで、県の木にもなっている"},{"k":"symbol","zh":"特別天然紀念物「尾長雞」源自這裡，公雞尾羽不換毛，曾有長達 13 公尺的紀錄","en":"The Onagadori long-tailed chicken comes from here; roosters never molt their tails, once reaching 13 m.","ja":"特別天然記念物のオナガドリはここ原産で、尾羽が抜け替わらず13mに達した記録がある"},{"k":"symbol","zh":"以四國犬和獒犬、鬥牛犬等西洋犬交配出的大型鬥犬，被指定為這裡的縣天然紀念物","en":"A huge fighting dog bred from the Shikoku dog, mastiffs and bulldogs is a prefectural natural monument here.","ja":"四国犬にマスティフやブルドッグを交配した大型の闘犬は、ここの県天然記念物に指定されている"},{"k":"symbol","zh":"縣花是楊梅（ヤマモモ），縣魚是鰹魚","en":"Its prefectural flower is the bayberry (yamamomo), and its fish is the skipjack tuna.","ja":"県の花はヤマモモ、県の魚はカツオ"},{"k":"food","zh":"酒宴上用陀螺決定喝哪種「可杯」：天狗鼻杯、嘴巴有洞的火男杯，非喝乾不能放下","en":"At banquets a spinning top picks your 'bekuhai' cup, a goblin nose or holed mask that can't be set down until empty.","ja":"宴席ではコマで「可杯」を選び、天狗やひょっとこの杯は飲み干すまで下に置けない"},{"k":"food","zh":"須崎市的「鍋燒拉麵」用砂鍋煮雞骨醬油湯，起源是戰後為了外送保溫","en":"Susaki's nabeyaki ramen comes boiling in a clay pot, a style born from keeping delivery orders hot after the war.","ja":"須崎市の鍋焼きラーメンは土鍋で煮立てる鶏ガラ醤油味で、戦後の出前の保温が始まり"},{"k":"food","zh":"這裡會把海鱔（裸胸鯙）做成炙燒「たたき」來吃","en":"Locals here eat moray eel, seared and served as tataki.","ja":"ここではウツボをたたきにして食べる"},{"k":"festival","zh":"每年 7 月赤岡的「繪金祭」，入夜後在燭光下展示畫師繪金血腥驚悚的戲劇屏風畫","en":"Each July, Akaoka's Ekin Festival shows the painter Ekin's gory theater screens by candlelight at night.","ja":"毎年7月の赤岡の絵金祭りでは、絵師・絵金の血みどろの芝居絵屏風を夜にろうそくの灯で飾る"},{"k":"people","zh":"相傳說出「天災總在人們遺忘時來臨」的物理學家寺田寅彥在這裡長大","en":"Physicist Torahiko Terada, credited with 'disasters strike when people forget them', grew up here.","ja":"「天災は忘れた頃にやってくる」の言葉で知られる物理学者・寺田寅彦はここで育った"},{"k":"legend","zh":"傳說被長宗我部元親逼死的吉良親實與家臣化為「七人御先」，要殺一人才有一人能成佛","en":"Legend says Kira Chikazane and his retainers, forced to die, became the 'Seven Misaki', ghosts who must kill to rest.","ja":"長宗我部元親に切腹させられた吉良親実らの怨霊が、一人取り殺すと一人成仏する「七人ミサキ」になったという"},{"k":"legend","zh":"河邊妖怪「シバテン」像毛茸茸的小孩，會找人比相撲，一整晚纏著不放","en":"The riverbank yokai Shibaten, a hairy child-like imp, challenges people to sumo and makes them wrestle all night.","ja":"川辺に出る妖怪シバテンは毛深い子どものような姿で、人に相撲を挑み一晩中とらせる"},{"k":"life","zh":"播磨屋橋又小又是水泥造，與札幌時計台並列「日本三大令人失望景點」","en":"Harimaya Bridge, small and concrete, ranks with Sapporo's clock tower among Japan's three most disappointing sights.","ja":"はりまや橋は札幌時計台などと並ぶ「日本三大がっかり名所」の一つ"},{"k":"work","zh":"民謠〈夜來節〉的由來，是竹林寺和尚與修鍋匠女兒在播磨屋橋一帶的戀愛故事","en":"The folk song Yosakoi-bushi grew from a love story of a Chikurin-ji monk and a tinker's daughter near Harimaya Bridge.","ja":"よさこい節は、竹林寺の僧と鋳掛屋の娘の恋という、はりまや橋ゆかりの話がもとになっている"},{"k":"sport","zh":"1992 年夏季甲子園，這裡的明德義塾對星稜的松井秀喜五打席全部保送，引發全國爭議","en":"In 1992, a school from here walked slugger Hideki Matsui five straight times at Koshien, causing a national uproar.","ja":"1992年夏の甲子園で、ここの明徳義塾が星稜・松井秀喜を5打席連続敬遠し社会問題になった"},{"k":"brand","zh":"縣民零嘴「ミレービスケット」用炒豆子的鍋子油炸，因此有獨特風味","en":"Mire Biscuits, the local favorite snack, get their flavor from being fried in pans used for roasting beans.","ja":"県民のおやつ「ミレービスケット」は豆を煎る鍋で揚げるのが独特の風味の秘密"}],
"JP-40":[{"k":"sport","zh":"職棒鷹隊 1989 年從大阪搬到這裡","en":"The Hawks pro baseball team moved here from Osaka in 1989.","ja":"ホークスは1989年に大阪から本拠地を移してきた。"},{"k":"people","zh":"藝人塔摩利的故鄉","en":"Hometown of TV host Tamori.","ja":"タモリの出身地。"},{"k":"people","zh":"《鬼滅之刃》作者吾峠呼世晴的故鄉","en":"Home of Koyoharu Gotouge, creator of Demon Slayer.","ja":"『鬼滅の刃』の作者・吾峠呼世晴の出身地。"},{"k":"festival","zh":"「博多咚打鼓」的起源是 1179 年開始的博多松囃子","en":"Hakata Dontaku traces its origin to the Hakata matsubayashi parade begun in 1179.","ja":"博多どんたくの起源は1179年に始まった博多松囃子。"},{"k":"origin","zh":"黑田長政以祖先故鄉備前（今岡山縣）的地名替城下町命名","en":"Kuroda Nagamasa named his castle town after his ancestral home in Bizen, in today's Okayama.","ja":"黒田長政が一族ゆかりの備前国の地名を城下町に付けた。"},{"k":"life","zh":"博多的承天寺立有「烏龍麵、蕎麥麵發祥地」石碑","en":"Jotenji temple in Hakata has a monument naming it the birthplace of udon and soba.","ja":"博多の承天寺に、うどん・そば発祥の碑がある。"},{"k":"record","zh":"夜間路邊攤「屋台」的數量日本第一","en":"It has more yatai street food stalls than anywhere else in Japan.","ja":"屋台の数が日本一。"},{"k":"life","zh":"機場離市中心超近，搭地鐵只要幾分鐘","en":"Its airport is so close to downtown that the subway gets you there in minutes.","ja":"空港が都心から近く、地下鉄で数分。"},{"k":"history","zh":"527 年筑紫君磐井起兵反抗大和朝廷，八女的岩戶山古墳被認為是他的墓","en":"In 527 the local ruler Iwai rebelled against the Yamato court; his tomb is thought to be Iwatoyama Kofun in Yame.","ja":"527年、筑紫君磐井が大和朝廷に反旗を翻し、八女の岩戸山古墳が磐井の墓とされる"},{"k":"history","zh":"663 年白村江之戰慘敗後，朝廷在這裡築起「水城」等防禦工事保護大宰府","en":"After the defeat at Baekgang in 663, the court built the Mizuki earthwork and other defenses here to guard Dazaifu.","ja":"663年の白村江の敗戦後、大宰府を守るため水城などの防衛施設が築かれた"},{"k":"legend","zh":"傳說菅原道真被貶時，家中梅樹一夜之間從京都飛到他身邊，成了天滿宮前的「飛梅」","en":"Legend says Michizane's beloved plum tree flew overnight from Kyoto to join him in exile, the 'Flying Plum'.","ja":"菅原道真を慕った梅が一夜で京から飛んできたという「飛梅」が、天満宮の本殿前にある"},{"k":"origin","zh":"日本年號「令和」出自《萬葉集》中大伴旅人在太宰府宅邸舉辦「梅花宴」的序文","en":"Japan's era name Reiwa comes from a Manyoshu preface on a plum blossom banquet at Otomo no Tabito's Dazaifu home.","ja":"元号「令和」の出典は、大伴旅人の大宰府の邸宅で開かれた「梅花の宴」を詠んだ万葉集の序文"},{"k":"brand","zh":"衛浴大廠 TOTO 1917 年在北九州小倉創立，1980 年推出免治馬桶座「Washlet」","en":"TOTO was founded in Kokura, Kitakyushu in 1917, and launched its Washlet bidet seat in 1980.","ja":"TOTOは1917年に北九州・小倉で創立し、1980年にウォシュレットを発売した"},{"k":"brand","zh":"小方塊巧克力「チロルチョコ」起源於田川市的松尾製菓","en":"Tirol Choco, the tiny square chocolates, originated with Matsuo Seika in Tagawa.","ja":"チロルチョコは田川市の松尾製菓が起源"},{"k":"brand","zh":"工業機器人大廠安川電機 1915 年創立，總部設在北九州","en":"Yaskawa Electric, a major industrial robot maker, was founded in 1915 and is based in Kitakyushu.","ja":"産業用ロボット大手の安川電機は1915年創業で、北九州に本社を置く"},{"k":"brand","zh":"日本三大絣之一的久留米絣，據說是江戶後期一名 12 歲少女井上傳所創","en":"Kurume kasuri, one of Japan's three great ikat fabrics, is said to have been created by 12-year-old Den Inoue.","ja":"日本三大絣の久留米絣は、江戸後期に12歳の少女・井上伝が創始したとされる"},{"k":"food","zh":"吃完麵後再單點一份麵的「替玉」，據說起源於長濱的「元祖長濱屋」","en":"Kaedama, ordering just extra noodles for your leftover ramen broth, is said to have started at Ganso Nagahamaya.","ja":"麺だけを追加注文する「替え玉」は、長浜の「元祖長浜屋」が発祥とされる"},{"k":"food","zh":"把咖哩倒進砂鍋放進烤箱焗烤的「烤咖哩」，起源於昭和 30 年代門司港的一家和食店","en":"Baked curry, curry browned in an oven like a gratin, began at a Mojiko restaurant in the late 1950s to early 1960s.","ja":"カレーを土鍋に入れオーブンで焼く「焼きカレー」は、昭和30年代の門司港の和食店が発祥"},{"k":"festival","zh":"戶畑祇園大山笠白天掛旗幟，入夜後變身為掛滿 309 盞燈籠、高約 10 公尺的金字塔","en":"Tobata's Gion Oyamagasa floats turn at night into 10 m pyramids lit by 309 lanterns.","ja":"戸畑祇園大山笠は夜になると309個の提灯を付けた高さ約10mのピラミッド形に変わる"},{"k":"festival","zh":"筥崎宮的放生會讀作「ほうじょうや」，9 月有約 500 家攤販，名物是一吹就響的玻璃玩具","en":"Hakozaki Shrine's Hojoya fair each September has about 500 stalls, famed for glass toys that pop when blown.","ja":"筥崎宮の放生会（ほうじょうや）は9月に約500軒の露店が並び、吹くと鳴るガラス玩具「チャンポン」が名物"},{"k":"work","zh":"漫畫《妙廚老爹》的舞台在這裡，主角荒岩一味是「金丸產業」的上班族","en":"The manga Cooking Papa is set here, following Kazumi Araiwa, an office worker at Kanemaru Sangyo.","ja":"漫画『クッキングパパ』はここが舞台で、主人公・荒岩一味は金丸産業の会社員"},{"k":"work","zh":"長谷川町子在這裡的百道海岸散步時，想到用海產替角色命名，《海螺小姐》首先連載於當地晚報","en":"Machiko Hasegawa dreamed up Sazae-san's seafood names on a beach here; the strip debuted in a local evening paper.","ja":"長谷川町子は百道の海岸を散歩中に登場人物を海産物の名にすることを思いつき、『サザエさん』は地元の夕刊紙で始まった"},{"k":"people","zh":"《銀河鐵道 999》、《宇宙戰艦大和號》的漫畫家松本零士出身久留米","en":"Leiji Matsumoto, creator of Galaxy Express 999 and Space Battleship Yamato, was born in Kurume.","ja":"『銀河鉄道999』『宇宙戦艦ヤマト』の漫画家・松本零士は久留米の出身"},{"k":"sport","zh":"以這裡為根據地的西鐵獅隊在 1956 至 1958 年連續三年拿下日本一，後來球隊遷往埼玉","en":"The Nishitetsu Lions, then based here, won three straight Japan Series titles from 1956 to 1958.","ja":"ここを本拠地とした西鉄ライオンズは1956〜58年に日本シリーズ3連覇、のちに球団は埼玉へ移った"},{"k":"sport","zh":"大相撲每年 11 月的本場所在這裡舉行，1957 年升格為正式本場所","en":"Grand sumo's November tournament is held here; it became an official honbasho in 1957.","ja":"大相撲の11月場所はここで開かれ、1957年に本場所となった"},{"k":"nature","zh":"北九州的平尾台與秋吉台、四國喀斯特並列日本三大喀斯特台地","en":"Hiraodai in Kitakyushu is one of Japan's three great karst plateaus, alongside Akiyoshidai.","ja":"北九州の平尾台は、秋吉台・四国カルストと並ぶ日本三大カルスト"},{"k":"symbol","zh":"北九州的曾根潮間帶是瀨戶內海規模最大的海埔地，也是瀕危物種鱟的棲地","en":"Sone tidal flat in Kitakyushu, the largest on the Seto Inland Sea, is a habitat of the endangered horseshoe crab.","ja":"北九州の曽根干潟は瀬戸内海最大規模の干潟で、カブトガニの生息地"},{"k":"work","zh":"盆舞名曲〈炭坑節〉發源於田川，歌裡的煙囪據說就是三井田川礦場保留至今的雙煙囪","en":"The Bon dance standard Tanko Bushi came from Tagawa; its chimneys are said to be the mine's twin stacks still standing.","ja":"盆踊りの定番「炭坑節」は田川発祥で、歌の煙突は今も残る三井田川鉱業所の二本煙突とされる"},{"k":"legend","zh":"已封閉的舊犬鳴隧道是知名靈異地點，相關都市傳說還被拍成恐怖片《犬鳴村》","en":"The sealed Old Inunaki Tunnel is a notorious haunted spot whose legends inspired the horror film Howling Village.","ja":"閉鎖された旧犬鳴トンネルは有名な心霊スポットで、都市伝説は映画『犬鳴村』になった"},{"k":"symbol","zh":"縣花是梅花，縣鳥是樹鶯，正好湊成「梅與鶯」","en":"The prefectural flower is the plum blossom and the bird is the bush warbler, a classic pairing.","ja":"県の花はウメ、県の鳥はウグイスで、「梅に鶯」の取り合わせ"},{"k":"history","zh":"1873 年米價高漲引發竹槍暴動，連縣廳都被暴民燒毀","en":"In 1873 soaring rice prices sparked a bamboo-spear uprising that burned down the prefectural office.","ja":"1873年、米価高騰を背景にした竹槍一揆で県庁が焼き討ちされた"}],
"JP-41":[{"k":"symbol","zh":"縣鳥是喜鵲，當地也叫「勝鴉（カチガラス）」","en":"Its prefectural bird is the magpie, locally called kachigarasu.","ja":"県の鳥はカササギ（カチガラス）。"},{"k":"origin","zh":"縣名據說源自《風土記》中因大樟樹而被稱為「榮之國」的傳說","en":"The name is said to derive from the 'land of prosperity' in a Fudoki legend about a great camphor tree.","ja":"県名は『風土記』の楠の伝説にある「栄の国」に由来するとされる。"},{"k":"people","zh":"固力果創辦人江崎利一出身這裡，從當地牡蠣的肝醣得到靈感","en":"Glico founder Riichi Ezaki was born here and got his idea from glycogen in local oysters.","ja":"グリコ創業者・江崎利一の出身地。牡蠣のグリコーゲンが発想源。"},{"k":"work","zh":"有部動畫講殭屍少女組成偶像團體，為了讓這個縣更出名","en":"In one anime, zombie girls form an idol group to make this prefecture better known.","ja":"ゾンビの少女たちがご当地アイドルとして県を盛り上げるアニメの舞台。"},{"k":"work","zh":"藝人塙（はなわ）靠自嘲家鄉的同名歌曲登上紅白","en":"Comedian Hanawa reached NHK's Kohaku with a self-mocking song named after this prefecture.","ja":"はなわは自虐的な同名の歌でNHK紅白に出場した。"},{"k":"festival","zh":"唐津宮日祭有 14 台漆製曳山，包括一條巨大的紅鯛魚","en":"Karatsu Kunchi features 14 lacquered floats, including a giant red sea bream.","ja":"唐津くんちには巨大な鯛など乾漆の曳山が14台ある。"},{"k":"record","zh":"全國唯一兩個鄰縣彼此不相接的縣，福岡往長崎一定要經過這裡","en":"It's the only prefecture whose neighbors don't touch each other, so Fukuoka–Nagasaki trips pass through it.","ja":"隣の2県同士が接しない唯一の県で、福岡と長崎の行き来は必ず通る。"},{"k":"people","zh":"幕末明治的鍋島直正、佐野常民等七位偉人被稱為「七賢人」","en":"Seven Meiji-era greats, including Nabeshima Naomasa and Sano Tsunetami, are honored here as the 'Seven Sages'.","ja":"鍋島直正・佐野常民ら幕末明治の偉人7人は「七賢人」と呼ばれる。"},{"k":"history","zh":"「所謂武士道，就是看透死亡」出自這裡的藩士山本常朝口述的《葉隱》","en":"'The way of the samurai is found in death' comes from Hagakure, dictated by a samurai of this domain.","ja":"「武士道と云ふは死ぬ事と見付けたり」は、ここの藩士・山本常朝が語った『葉隠』の一節"},{"k":"legend","zh":"江戶時代流傳的「鍋島化貓騷動」，據說源自鍋島家與龍造寺家之間的恩怨","en":"The Nabeshima ghost-cat tale is said to stem from the clan's feud with the Ryuzoji family.","ja":"鍋島藩の化け猫騒動は、鍋島氏と龍造寺氏の確執から生まれた話ともいわれる"},{"k":"legend","zh":"傳說松浦佐用姬在鏡山揮動披巾送別出征的戀人，最後因悲傷化為石頭","en":"Legend says Matsura Sayohime waved her scarf from Mt. Kagami as her lover sailed to war, then turned to stone.","ja":"松浦佐用姫は鏡山から領巾を振って出征する恋人を見送り、悲しみのあまり石になったと伝わる"},{"k":"legend","zh":"傳說徐福在金立山找到植物「フロフキ」，當地說這名字是「不老不死」的轉音","en":"Legend says Xu Fu found a herb on Mt. Kinryu whose local name is said to come from 'never age, never die'.","ja":"金立山には徐福が見つけたという植物「フロフキ」が自生し、名は「不老不死」の訛りともいう"},{"k":"festival","zh":"1985 年起每年初夏在有明海泥灘上舉行「ガタリンピック」，選手踩泥板滑行、騎車過窄板","en":"Since 1985 the Gatalympics have been held each early summer on Ariake Sea mudflats, with mud-sled races.","ja":"1985年から毎年初夏、有明海の干潟で潟スキー競走などの「ガタリンピック」が開かれる"},{"k":"people","zh":"設計東京車站與日本銀行總行的建築師辰野金吾出身唐津","en":"Kingo Tatsuno, architect of Tokyo Station and the Bank of Japan head office, was born in Karatsu.","ja":"東京駅や日本銀行本店を設計した建築家・辰野金吾は唐津の出身"},{"k":"people","zh":"《海螺小姐》作者長谷川町子 1920 年出生在這裡的多久","en":"Machiko Hasegawa, creator of Sazae-san, was born in Taku here in 1920.","ja":"『サザエさん』の作者・長谷川町子は1920年にここの多久で生まれた"},{"k":"brand","zh":"森永製菓創辦人森永太一郎出身伊萬里，在美國學會做西點後回國創業","en":"Taichiro Morinaga, who founded Morinaga confectionery after learning candy-making in America, was born in Imari.","ja":"森永製菓の創業者・森永太一郎は伊万里の出身で、アメリカで洋菓子作りを学んだ"},{"k":"brand","zh":"撒隆巴斯的久光製藥總部在鳥栖，1934 年推出撒隆巴斯貼布","en":"Hisamitsu, maker of Salonpas pain patches, is based in Tosu and launched Salonpas in 1934.","ja":"サロンパスの久光製薬は鳥栖に本社を置き、1934年にサロンパスを発売した"},{"k":"record","zh":"1850 年這裡的藩建成日本第一座實用反射爐，隔年鑄出日本第一門鐵製大砲","en":"This domain built Japan's first working reverberatory furnace in 1850 and cast Japan's first iron cannon in 1851.","ja":"ここの藩は1850年に日本初の実用反射炉を築き、翌年日本で初めて鉄製大砲を鋳造した"},{"k":"record","zh":"三重津海軍所據說在 1865 年造出日本第一艘國產實用蒸汽船「凌風丸」","en":"The Mietsu naval yard is said to have completed Japan's first practical home-built steamship, Ryofu Maru, in 1865.","ja":"三重津海軍所では1865年に国産初の実用蒸気船「凌風丸」が完成したといわれる"},{"k":"history","zh":"唐津的菜畑遺跡挖出約 2900 年前的水田遺構，被視為日本最古老的水稻耕作遺址","en":"The Nabatake site in Karatsu yielded rice paddies about 2,900 years old, seen as Japan's oldest wet-rice site.","ja":"唐津の菜畑遺跡では約2900年前の水田跡が見つかり、日本最古の水稲耕作遺跡とされる"},{"k":"sport","zh":"2007 年夏季甲子園，這裡的一所公立高中在決賽靠逆轉滿貫全壘打奪冠，被稱為「GABAI 旋風」","en":"In 2007 a public school from here won summer Koshien on a comeback grand slam in the final, the 'Gabai Whirlwind'.","ja":"2007年夏の甲子園で、ここの公立高校が決勝の逆転満塁本塁打で優勝し「がばい旋風」と呼ばれた"},{"k":"work","zh":"動畫《YURI!!! on ICE》主角勇利的故鄉「長谷津」以唐津為舞台原型","en":"Yuri's hometown of Hasetsu in the anime Yuri!!! on Ice is modeled on Karatsu.","ja":"アニメ『ユーリ!!! on ICE』の主人公・勇利の故郷「長谷津」は唐津がモデル"},{"k":"origin","zh":"《魏志倭人傳》記載的「末盧國」多被認為在唐津一帶，「松浦」的地名可能就源自它","en":"The Wei Zhi chronicle's land of Mappo is placed near Karatsu, and may be the origin of the local name Matsura.","ja":"『魏志倭人伝』の末盧国は唐津付近とする説が多く、「松浦」の地名の由来ともいわれる"},{"k":"origin","zh":"傳說神功皇后在這裡泡溫泉時高興地說「啊，好開心（うれしの）」，成了嬉野的地名","en":"Legend says Empress Jingu exclaimed with delight at the spring here, giving Ureshino its name.","ja":"神功皇后が湯に喜んで声を上げたことが嬉野の名の由来という伝説がある"},{"k":"life","zh":"鳥栖東部和基山町曾是對馬藩的飛地，至今仍說著與周邊不同的「田代方言」","en":"Eastern Tosu and Kiyama were once an exclave of the Tsushima domain and still speak a distinct Tashiro dialect.","ja":"鳥栖市東部や基山町はかつて対馬藩の飛び地で、今も田代弁が話される"},{"k":"life","zh":"這裡地名的「町」基本上都讀「ちょう」，只有江北町讀「まち」","en":"Every town name with 町 here is read 'cho', except Kohoku, which reads it 'machi'.","ja":"ここでは「町」を「ちょう」と読むのが基本だが、江北町だけは「まち」"},{"k":"food","zh":"嬉野溫泉的名物是用溫泉水煮的「溫泉湯豆腐」","en":"Ureshino's specialty is yudofu, tofu simmered in the hot-spring water itself.","ja":"嬉野温泉の名物は温泉水で煮る「温泉湯どうふ」"},{"k":"food","zh":"江戶時代砂糖沿長崎街道運入，沿線製菓業因此發達，這條路被稱為「砂糖之路」","en":"In the Edo era sugar flowed in along the Nagasaki Kaido, the 'Sugar Road', fostering a confectionery industry here.","ja":"江戸時代、長崎街道（シュガーロード）を通じて砂糖が流通し、製菓業が発展した"},{"k":"food","zh":"有明海沿岸自古就吃彈塗魚、長相怪異的「ワラスボ」和招潮蟹","en":"Along the Ariake Sea, people have long eaten mudskippers, the eerie-looking warasubo goby and fiddler crabs.","ja":"有明海沿岸ではムツゴロウやワラスボ、シオマネキが昔から郷土料理として食べられてきた"},{"k":"nature","zh":"唐津的七釜是玄武岩柱狀節理上的海蝕洞，七個洞口深度都超過 50 公尺","en":"Nanatsugama in Karatsu is a row of seven sea caves in columnar basalt, each over 50 m deep.","ja":"唐津の七ツ釜は柱状節理の玄武岩にできた海食洞で、7つの洞はいずれも奥行き50m以上"},{"k":"symbol","zh":"縣樹是樟樹；武雄神社的神木大樟推估樹齡 3000 年，樹洞裡還供奉著天神","en":"Its prefectural tree is the camphor; Takeo Shrine's 3,000-year-old sacred camphor has a shrine in its hollow.","ja":"県の木はクスノキで、樹齢3000年とされる武雄神社の大楠の空洞には天神様が祀られている"},{"k":"life","zh":"俗話說「○○人走過的地方連薺菜都不長」，據說源自藩政時代的節儉氣質","en":"A saying claims not even weeds grow where people from here have passed, said to reflect their thrifty domain days.","ja":"「○○もんの通ったあとにはぺんぺん草も生えん」という言い回しは、藩時代の倹約家気質に由来するとされる"},{"k":"history","zh":"1871 年舊肥前國被拆成兩縣，這裡一度叫做「伊萬里縣」","en":"When old Hizen province was split in two in 1871, this prefecture was briefly called Imari Prefecture.","ja":"1871年に旧肥前国が二分され、ここは一時「伊万里県」と呼ばれた"}],
"JP-42":[{"k":"people","zh":"歌手、演員福山雅治的故鄉","en":"Hometown of singer-actor Masaharu Fukuyama.","ja":"福山雅治の出身地。"},{"k":"work","zh":"漫畫《元氣囝仔》講書法家被送到這裡的五島列島生活","en":"In the manga Barakamon, a calligrapher is sent to live on the Goto Islands here.","ja":"漫画『ばらかもん』は書道家が五島列島で暮らす物語。"},{"k":"work","zh":"電影《007：空降危機》反派的廢墟島「死城」，原型是這裡的軍艦島","en":"The villain's ruined island 'Dead City' in Skyfall was modeled on Hashima (Battleship Island) here.","ja":"映画『007 スカイフォール』の廃墟の島は端島（軍艦島）がモデル。"},{"k":"festival","zh":"宮日祭的招牌是「龍踊」，觀眾會喊「もってこーい」要求安可","en":"Kunchi's highlight is the dragon dance, with crowds shouting 'motte koi!' for an encore.","ja":"くんちの代表的な演し物は龍踊り。アンコールの掛け声は「もってこーい」。"},{"k":"origin","zh":"地名主流說法來自鎌倉時代一個御家人家族的姓氏","en":"The main theory says the name comes from the surname of a Kamakura-era warrior family.","ja":"地名は鎌倉時代の御家人一族の名に由来するとの説が主流。"},{"k":"sport","zh":"源自中國福建的龍舟競賽「ペーロン」，江戶時代就在這裡舉行","en":"Peron dragon-boat racing, from Fujian in China, has been held here since the Edo period.","ja":"福建由来の龍舟競漕「ペーロン」が江戸時代から行われている。"},{"k":"record","zh":"日本第一座保齡球館 1861 年開在這裡，6 月 22 日因此定為保齡球日","en":"Japan's first bowling alley opened here in 1861; Bowling Day, June 22, marks the date.","ja":"1861年に日本初のボウリング場が開業、6月22日は「ボウリングの日」。"},{"k":"record","zh":"壹岐的遺址出土了日本最古老的貓骨","en":"Japan's oldest cat bones were excavated from a site on Iki island here.","ja":"壱岐のカラカミ遺跡から日本最古のネコの骨が出土した。"},{"k":"people","zh":"鄭成功 1624 年生於平戶，母親是日本人田川松，幼名福松","en":"Koxinga was born in Hirado in 1624 to a Japanese mother, Tagawa Matsu; his childhood name was Fukumatsu.","ja":"鄭成功は1624年に平戸で生まれ、母は日本人の田川マツ、幼名は福松"},{"k":"work","zh":"普契尼歌劇《蝴蝶夫人》的故事發生在這裡，日本藝妓苦等離去的美國軍官","en":"Puccini's opera Madama Butterfly is set here, where a geisha waits for her departed American officer.","ja":"プッチーニのオペラ『蝶々夫人』はここが舞台で、芸者が去った米国士官を待ち続ける"},{"k":"work","zh":"在這裡出生的石黑一雄，首部小說《群山淡景》以戰後的這座城市為背景","en":"Kazuo Ishiguro, born here, set his first novel A Pale View of Hills in the postwar city.","ja":"ここ生まれのカズオ・イシグロは、デビュー作『遠い山なみの光』で戦後のこの街を描いた"},{"k":"work","zh":"漫畫《坂道上的阿波羅》以 1966 年的佐世保為舞台，描寫少年們因爵士樂結緣","en":"The manga Kids on the Slope is set in Sasebo in 1966, where teenagers bond over jazz.","ja":"漫画『坂道のアポロン』は1966年の佐世保が舞台で、少年たちがジャズでつながる"},{"k":"food","zh":"融合和、華、蘭風味的「卓袱料理」，大家圍著圓桌分食，第一道是鯛魚清湯","en":"Shippoku cuisine blends Japanese, Chinese and Dutch styles, shared at a round table starting with sea bream soup.","ja":"和華蘭の卓袱料理は円卓を囲んで大皿を取り分け、鯛の吸い物「御鰭」から始まる"},{"k":"food","zh":"「土耳其飯」把炒飯、義大利麵和炸豬排裝在同一盤，名字由來眾說紛紜","en":"'Turkish rice' piles pilaf, spaghetti and a pork cutlet on one plate; nobody is sure why it's called Turkish.","ja":"ピラフ・スパゲティ・豚カツを一皿に盛る「トルコライス」は、名前の由来に諸説ある"},{"k":"festival","zh":"8 月 15 日傍晚的「精靈流」，遺族推著裝飾過的精靈船上街，鞭炮聲震天","en":"On the evening of August 15, families parade decorated spirit boats through the streets amid deafening firecrackers.","ja":"8月15日夕方の精霊流しでは、遺族が飾った精霊船を引いて練り歩き、爆竹が鳴り響く"},{"k":"festival","zh":"1987 年起，春節期間市區掛起約 1 萬 5 千盞中國燈籠，還有清朝皇帝遊行","en":"Since 1987, about 15,000 Chinese lanterns light up the city at Lunar New Year, with an emperor parade.","ja":"1987年から春節の時期に約1万5千個の中国提灯が街を彩り、皇帝パレードも行われる"},{"k":"symbol","zh":"對馬山貓推估約 10 萬年前從亞洲大陸來到對馬，1971 年被指定為國家天然紀念物","en":"The Tsushima leopard cat is thought to have come from the Asian mainland about 100,000 years ago.","ja":"ツシマヤマネコは約10万年前に大陸から対馬へ渡ったと推定され、1971年に国の天然記念物となった"},{"k":"people","zh":"日本最早的職業攝影師之一上野彥馬，1862 年在這裡開設照相館，拍過許多幕末志士","en":"Ueno Hikoma, one of Japan's first professional photographers, opened his studio here in 1862.","ja":"日本最初期の職業写真師・上野彦馬は1862年にここで写真館を開き、幕末の志士を撮った"},{"k":"people","zh":"荷蘭語通譯出身的本木昌造生於這裡，被視為日本活版印刷的先驅","en":"Motoki Shozo, a Dutch interpreter born here, is known as a pioneer of movable-type printing in Japan.","ja":"ここ生まれのオランダ通詞・本木昌造は、日本の活版印刷の先駆者として知られる"},{"k":"history","zh":"坂本龍馬等人 1865 年組成「龜山社中」，後來改名為海援隊","en":"Sakamoto Ryoma and allies formed the Kameyama Shachu here in 1865, later renamed the Kaientai.","ja":"1865年、坂本龍馬らが亀山社中を結成し、のちに海援隊となった"},{"k":"history","zh":"1582 年天正遣歐少年使節從這裡的港口出發，前往歐洲","en":"In 1582 the Tensho embassy of four Japanese boys set sail for Europe from the port here.","ja":"1582年、天正遣欧少年使節がここの港から出発した"},{"k":"history","zh":"1597 年 26 名天主教徒在西坂被處死，史稱「日本二十六聖人」","en":"In 1597, 26 Catholics were executed on Nishizaka hill here, later known as the Twenty-Six Martyrs.","ja":"1597年、西坂で26人のカトリック信者が処刑された（日本二十六聖人）"},{"k":"history","zh":"大村純忠成為日本第一位天主教大名，1571 年起這裡發展成貿易港","en":"Omura Sumitada became Japan's first Christian daimyo, and the port here opened to trade in 1571.","ja":"大村純忠は初のキリシタン大名となり、1571年にここが貿易港となった"},{"k":"record","zh":"雲仙所在的雲仙天草國立公園，是日本最早的國立公園","en":"Unzen-Amakusa, the park covering Mt. Unzen, was Japan's first national park.","ja":"雲仙を擁する雲仙天草国立公園は日本で最初の国立公園"},{"k":"record","zh":"島原半島是日本第一個世界地質公園","en":"The Shimabara Peninsula was Japan's first Global Geopark.","ja":"島原半島は国内第1号の世界ジオパーク"},{"k":"life","zh":"這裡從來沒有出現過任何一座滑雪場","en":"There has never been a single ski resort here.","ja":"ここにはスキー場が一度も存在したことがない"},{"k":"nature","zh":"境內沒有任何一處離海岸線超過 15 公里","en":"No point here is more than 15 km from the coastline.","ja":"県内には海岸線から15km以上離れた地点がない"},{"k":"life","zh":"境內的高速公路既沒有服務區，也沒有系統交流道","en":"The expressways here have neither a service area nor a junction.","ja":"県内の高速道路にはサービスエリアもジャンクションもない"},{"k":"history","zh":"壹岐的原之辻遺跡被認為就是《魏志倭人傳》記載的「一支國」","en":"Harunotsuji on Iki island is believed to be Ikikoku, a kingdom recorded in the Chinese Wei Zhi chronicle.","ja":"壱岐の原の辻遺跡は『魏志倭人伝』の「一支国」とみられ、特別史跡に指定されている"},{"k":"history","zh":"1550 年葡萄牙船首度駛入平戶","en":"A Portuguese ship first called at Hirado in 1550.","ja":"1550年、ポルトガル船が平戸に来航した"},{"k":"history","zh":"二戰日本海軍戰艦「武藏」是在這裡建造的","en":"The WWII battleship Musashi was built here.","ja":"戦艦武蔵はここで建造された"},{"k":"nature","zh":"境內最高峰是「平成新山」（1483 公尺），比原本的普賢岳（1359 公尺）還高","en":"Its highest peak is Heisei Shinzan (1,483 m), taller than the older Fugendake (1,359 m).","ja":"県内最高峰は平成新山（1483m）で、雲仙普賢岳（1359m）より高い"},{"k":"sport","zh":"2009 年春季甲子園由清峰高中奪冠，是這裡學校第一次拿下甲子園全國冠軍","en":"In 2009 Seiho High School won spring Koshien, the first national title for any school from here.","ja":"2009年春の選抜で清峰高校が優勝し、県勢初の甲子園優勝となった"},{"k":"brand","zh":"電視購物「Japanet Takata」由平戶相機店家族的高田明創立，總部在佐世保","en":"TV shopping giant Japanet Takata grew out of a family camera shop in Hirado and is based in Sasebo.","ja":"テレビ通販のジャパネットたかたは平戸のカメラ店から独立して生まれ、佐世保に本社を置く"},{"k":"legend","zh":"對馬的和多都美神社相傳是山幸彥與豐玉姬相遇的龍宮，大潮滿潮時海水漫到社殿旁","en":"Watatsumi Shrine on Tsushima is said to be where Yamasachihiko met Princess Toyotama of the sea palace.","ja":"対馬の和多都美神社は山幸彦が豊玉姫と出会った地とされ、満潮時は海水が社殿近くまで迫る"}],
"JP-43":[{"k":"people","zh":"《航海王》作者尾田榮一郎的故鄉，地震後以魯夫名義捐 8 億日圓","en":"Home of One Piece creator Eiichiro Oda, who donated ¥800 million in Luffy's name after the earthquake.","ja":"『ONE PIECE』の尾田栄一郎の出身地。地震後ルフィ名義で8億円を寄付。"},{"k":"people","zh":"宮本武藏晚年在這裡的靈巖洞寫下《五輪書》","en":"Miyamoto Musashi wrote The Book of Five Rings in Reigando cave here late in life.","ja":"宮本武蔵は晩年、霊巌洞にこもって『五輪書』を著した。"},{"k":"work","zh":"漫畫《妖怪聯絡簿》大量描繪作者家鄉人吉的風景","en":"Natsume's Book of Friends draws heavily on the scenery of Hitoyoshi, the author's hometown.","ja":"『夏目友人帳』には作者の地元・人吉の風景が多く描かれる。"},{"k":"festival","zh":"山鹿燈籠祭中，女性頭頂金色燈籠，上千人一起跳舞","en":"At the Yamaga Lantern Festival, a thousand women dance with golden lanterns on their heads.","ja":"山鹿灯籠まつりでは女性が金灯籠を頭に載せ、千人で踊る。"},{"k":"origin","zh":"加藤清正嫌原地名第一個字含「畏」不吉，改成了猛獸的字","en":"Kato Kiyomasa disliked that the name's first character contained 'fear', so he swapped in an animal's character.","ja":"加藤清正は地名の一字目に「畏」が含まれるのを嫌い、獣の字に改めた。"},{"k":"record","zh":"西瓜產量全國第一","en":"It grows more watermelons than any other prefecture.","ja":"スイカの生産量が全国1位。"},{"k":"record","zh":"釋迦院參道石階共 3333 階，號稱日本第一","en":"The 3,333 stone steps up to Shakain temple are billed as Japan's longest stairway.","ja":"釈迦院の参道は3333段で、日本一の石段とされる。"},{"k":"symbol","zh":"縣魚是斑節蝦（車蝦）","en":"Its prefectural fish is the kuruma prawn.","ja":"県の魚はクルマエビ。"},{"k":"people","zh":"細菌學之父北里柴三郎出身這裡的小國町，也是新版千圓鈔上的人物","en":"Kitasato Shibasaburo, father of Japanese bacteriology and face of the new 1,000-yen note, was born here.","ja":"新千円札の肖像・北里柴三郎は、○○の小国町の出身。"},{"k":"people","zh":"夏目漱石與小泉八雲都曾在這裡的第五高等學校教英文","en":"Both Natsume Soseki and Lafcadio Hearn taught English at the Fifth Higher School here.","ja":"夏目漱石と小泉八雲は、ともに○○の第五高等学校で英語を教えた。"},{"k":"people","zh":"在水俁長大的德富蘇峰，花了 34 年寫完全 100 卷的《近世日本國民史》","en":"Tokutomi Soho, raised in Minamata here, spent 34 years writing his 100-volume history of early modern Japan.","ja":"水俣で育った徳富蘇峰は、全100巻の『近世日本国民史』を34年かけて完成させた。"},{"k":"sport","zh":"「打擊之神」川上哲治出身這裡的人吉，後來當總教練帶巨人隊九連霸","en":"Kawakami Tetsuharu, the 'God of Batting', came from Hitoyoshi here and later led the Giants to nine straight titles.","ja":"「打撃の神様」川上哲治は○○の人吉出身で、監督として巨人をV9に導いた。"},{"k":"work","zh":"夏目漱石《草枕》裡的「那古井溫泉」，原型是這裡玉名的小天溫泉","en":"The hot spring in Natsume Soseki's novel Kusamakura is modeled on Oama Onsen in Tamana here.","ja":"漱石『草枕』の「那古井温泉」のモデルは、○○の玉名市にある小天温泉。"},{"k":"festival","zh":"八代妙見祭的遊行有龜身蛇頭的神獸「龜蛇」，2016 年列入聯合國非遺","en":"The Yatsushiro Myoken Festival parade features 'Game', a turtle-snake beast; it joined UNESCO's list in 2016.","ja":"八代妙見祭の行列には亀と蛇が合体した「亀蛇（ガメ）」が登場し、2016年にユネスコ無形文化遺産に。"},{"k":"record","zh":"阿蘇神社的樓門號稱日本三大樓門之一，2016 年地震全倒，2023 年重建完成","en":"Aso Shrine's tower gate, one of Japan's three great gates, collapsed in the 2016 quake and was rebuilt by 2023.","ja":"日本三大楼門の一つ阿蘇神社の楼門は、2016年の地震で倒壊し、2023年に復旧した。"},{"k":"record","zh":"1854 年完工的石拱輸水橋通潤橋，2023 年成為第一座被指定為國寶的土木構造物","en":"Tsujun Bridge, an 1854 stone aqueduct, became Japan's first civil-engineering National Treasure in 2023.","ja":"1854年完成の石造アーチ水路橋・通潤橋は、2023年に土木構造物として初めて国宝となった。"},{"k":"symbol","zh":"山茶、芍藥、花菖蒲、牽牛花、菊、茶梅合稱「肥後六花」，是這裡培育的名花","en":"The 'Six Flowers of Higo', camellia, peony, iris, morning glory, chrysanthemum and sasanqua, were bred here.","ja":"椿・芍薬・花菖蒲・朝顔・菊・山茶花の「肥後六花」は、○○で育てられた園芸花。"},{"k":"life","zh":"方言「あとぜき」是「進出後隨手關門」，很多學校門上都貼著這張提醒","en":"Local dialect 'atozeki' means 'close the door behind you', and school doors here often carry signs saying it.","ja":"出入りの後に戸を閉める「あとぜき」は方言で、学校の戸によく貼り紙がある。"},{"k":"life","zh":"形容人帥氣的方言「むしゃんよか」，語源是「武者風範好」","en":"Locals call a good-looking person 'mushan yoka', from a phrase praising a fine warrior's bearing.","ja":"かっこいいことを「むしゃんよか」と言い、「武者ぶりが良い」が語源とされる。"},{"k":"life","zh":"這裡人的頑固性格叫「肥後もっこす」，和土佐、津輕並稱日本三大頑固","en":"The stubborn local temperament, 'Higo mokkosu', ranks among Japan's three great stubborn types.","ja":"頑固な気質「肥後もっこす」は、土佐いごっそう・津軽じょっぱりと並ぶ日本三大頑固。"},{"k":"food","zh":"把燙過的蔥捲成一團沾醋味噌吃的「一文字ぐるぐる」，據說源自 1782 年的節約令","en":"'Hitomoji guruguru', scallions coiled and dipped in vinegared miso, is said to date from a 1782 frugality order.","ja":"ネギを巻いて酢味噌で食べる「一文字のぐるぐる」は、1782年の藩の倹約令から生まれたという。"},{"k":"food","zh":"這裡的豚骨拉麵會加炸蒜片和黑色焦蒜油，味道比博多拉麵溫和","en":"Pork-bone ramen here is topped with fried garlic chips and black garlic oil, making it mellower than Hakata ramen.","ja":"○○ラーメンは揚げニンニクやマー油を加え、博多ラーメンよりまろやかな味わい。"},{"k":"history","zh":"1876 年反對廢刀令的士族「敬神黨」約 170 人在這裡起兵，史稱神風連之亂","en":"In 1876 about 170 ex-samurai of the Keishinto rose here against the sword ban, known as the Shinpuren Rebellion.","ja":"1876年、廃刀令に反発した士族「敬神党」約170人が挙兵した神風連の乱の舞台。"},{"k":"history","zh":"1632 年細川忠利接手改易的加藤家領地，入城時把加藤清正的牌位放在隊伍最前面","en":"Taking over in 1632, Hosokawa Tadatoshi led his entry procession with Kato Kiyomasa's memorial tablet.","ja":"1632年に入国した細川忠利は、行列の先頭に加藤清正の位牌を掲げたという。"},{"k":"history","zh":"1592 年耶穌會在這裡的天草，用活字印出羅馬字版的《平家物語》","en":"In 1592 Jesuits in Amakusa here printed The Tale of the Heike in romanized Japanese with movable type.","ja":"1592年、イエズス会が○○の天草でローマ字の『平家物語』を活字印刷した。"},{"k":"history","zh":"1910 年山鹿商家集資蓋的劇場八千代座，旋轉舞台的軌道是德國克虜伯製","en":"Yachiyoza, a 1910 theater funded by Yamaga merchants, has a revolving stage on rails made by Germany's Krupp.","ja":"1910年に山鹿の旦那衆が建てた芝居小屋・八千代座の廻り舞台は、ドイツ・クルップ社製のレール。"},{"k":"nature","zh":"日本三大急流之一的球磨川，穿過人吉盆地注入八代海","en":"The Kuma River, one of Japan's three swiftest rivers, flows through the Hitoyoshi Basin into the Yatsushiro Sea.","ja":"日本三大急流の一つ球磨川は、人吉盆地を抜けて八代海に注ぐ。"},{"k":"nature","zh":"八代海在舊曆八月一日前後，會出現被稱為「不知火」的神祕海上火光","en":"Around the first day of the 8th lunar month, mysterious lights called shiranui appear over the Yatsushiro Sea.","ja":"旧暦8月1日前後、八代海の沖に蜃気楼の一種「不知火」が現れる。"},{"k":"brand","zh":"在中國展店特別多的味千拉麵發源於這裡，創辦人是台灣出身的客家人","en":"Ajisen Ramen, hugely popular in China, started here; its founder was a Hakka from Taiwan.","ja":"中国で多数展開する味千ラーメンは○○発祥で、創業者は台湾出身の客家人。"},{"k":"legend","zh":"1846 年在這裡海上現身的妖怪「阿瑪比埃」，交代疫病流行時要把牠的畫像給人看","en":"Amabie, the yokai that rose from the sea here in 1846, said to show people its picture when plague spread.","ja":"1846年、○○の海に現れたアマビエは、疫病が流行したら自分の姿を描いて見せよと告げた。"},{"k":"legend","zh":"傳說河童首領「九千坊」率九千部下作亂，加藤清正召集猴子把牠們制伏","en":"Legend says kappa chief Kusenbo and his 9,000 followers ran riot until Kato Kiyomasa sent monkeys after them.","ja":"河童の大将・九千坊が暴れた際、加藤清正は猿を集めて退治させたという。"}],
"JP-44":[{"k":"symbol","zh":"縣花和縣樹都是「豐後梅」","en":"Both its prefectural flower and tree are the Bungo plum.","ja":"県の花と木はどちらも豊後梅。"},{"k":"people","zh":"《進擊的巨人》作者諫山創出身這裡的日田","en":"Attack on Titan creator Hajime Isayama is from Hita here.","ja":"『進撃の巨人』の諫山創は日田市出身。"},{"k":"people","zh":"AKB48 總選舉拿過 4 次第一的指原莉乃出身這裡","en":"Rino Sashihara, four-time winner of the AKB48 general election, is from here.","ja":"AKB48総選挙で4度1位の指原莉乃の出身地。"},{"k":"sport","zh":"日本輪椅籃球與輪椅馬拉松的發源地","en":"The birthplace of wheelchair basketball and wheelchair marathons in Japan.","ja":"日本の車いすバスケットボールと車いすマラソン発祥の地。"},{"k":"festival","zh":"ケベス祭中，戴怪面具的人衝進燃燒的蕨堆，把火星灑向人群","en":"At the Kebesu Festival, a masked figure charges into burning fern piles and scatters sparks on onlookers.","ja":"ケベス祭では奇妙な面のケベスが燃えるシダに突入し、火の粉を散らす。"},{"k":"origin","zh":"《風土記》說景行天皇讚嘆此地廣大，命名為「碩田國」","en":"In the Fudoki, Emperor Keiko marveled at how vast the land was and named it the 'land of great fields'.","ja":"『豊後国風土記』で景行天皇が広さに感嘆し「碩田国」と名付けた。"},{"k":"record","zh":"九重「夢」大吊橋離水面 173 公尺，是日本最高的步行專用橋","en":"The Kokonoe Yume suspension bridge, 173 m above the water, is Japan's highest pedestrian bridge.","ja":"九重“夢”大吊橋は水面から173m、歩行者専用橋で日本一高い。"},{"k":"record","zh":"再生能源自給率是全國都道府縣最高","en":"It has the highest renewable-energy self-sufficiency of any prefecture.","ja":"自然エネルギー自給率が全国の都道府県で最も高い。"},{"k":"sport","zh":"大相撲至今無人打破的 69 連勝紀錄保持者、橫綱雙葉山出身這裡的宇佐","en":"Futabayama, the yokozuna whose 69-bout winning streak still stands, was born in Usa here.","ja":"大相撲69連勝の記録を持つ横綱・双葉山は、○○の宇佐出身。"},{"k":"people","zh":"主譯《解體新書》的前野良澤是這裡中津藩的藩醫，藩主稱他「蘭學怪物」","en":"Maeno Ryotaku, chief translator of Kaitai Shinsho, was a doctor of the Nakatsu domain here.","ja":"『解体新書』の中心的翻訳者・前野良沢は中津藩医で、号「蘭化」は藩主の評から。"},{"k":"people","zh":"日俄戰爭中為尋找部下而戰死的廣瀨武夫出身竹田，成為日本第一位「軍神」","en":"Hirose Takeo of Taketa here died searching for a missing subordinate in 1904 and became Japan's first 'war god'.","ja":"部下の杉野を探して戦死した広瀬武夫は竹田出身で、最初の「軍神」とされた。"},{"k":"history","zh":"黑田官兵衛 1588 年開始興建的中津城，護城河引進海水，是日本三大水城之一","en":"Nakatsu Castle, begun by Kuroda Kanbei in 1588, has seawater moats and is one of Japan's three great water castles.","ja":"黒田官兵衛が1588年に築き始めた中津城は、堀に海水を引く日本三大水城の一つ。"},{"k":"festival","zh":"國東半島的「修正鬼會」中，手持火把的鬼不是惡鬼，而是祖先的化身","en":"In the Shujo Onie fire rites of the Kunisaki Peninsula, the torch-bearing demons are ancestors, not evil.","ja":"国東半島の修正鬼会で松明を持つ鬼は、悪鬼ではなく祖先の化身とされる。"},{"k":"festival","zh":"仿京都祇園祭的日田祇園祭，從 1714 年起拉山鉾遊行，2016 年列入聯合國非遺","en":"Hita's Gion Festival, modeled on Kyoto's, has paraded floats since 1714 and joined UNESCO's list in 2016.","ja":"京都を手本にした日田祇園祭は1714年から山鉾を曳き、2016年にユネスコ無形文化遺産に。"},{"k":"origin","zh":"據《豐後國風土記》，古名「豐國」來自白鳥飛來變成年糕、再化成上千株芋頭的祥瑞","en":"Its local Fudoki says the old name Toyo-no-kuni came from a white bird that turned into rice cakes, then taro.","ja":"『豊後国風土記』は、白鳥が餅になり、さらに数千株の芋になった瑞兆から「豊国」と名付けたと記す。"},{"k":"symbol","zh":"1952 年市長為了解決猴子吃農作物，乾脆在高崎山餵食野猴、開成動物園","en":"In 1952 a mayor here solved crop raids by feeding the wild monkeys of Mt. Takasaki, creating a monkey park.","ja":"1952年、市長が畑を荒らす野生ザルを餌付けし、高崎山自然動物園が生まれた。"},{"k":"record","zh":"九重連山的中岳海拔 1791 公尺，是九州本島的最高峰","en":"Nakadake in the Kuju Mountains, 1,791 m, is the highest peak on Kyushu's main island.","ja":"九重連山の中岳（1791m）は九州本土の最高峰。"},{"k":"nature","zh":"九重山中海拔 1303 公尺的法華院溫泉，是九州位置最高的溫泉，最後一段只能步行","en":"Hokkein Onsen, 1,303 m up in the Kuju Mountains, is Kyushu's highest hot spring and reached only on foot.","ja":"標高1303mの法華院温泉は九州で最も高所にある温泉で、最後は歩いて向かう。"},{"k":"record","zh":"1557 年傳教士阿爾梅達在這裡的府內，開設日本第一家引進西洋醫學的醫院","en":"In 1557 Luis de Almeida opened Japan's first hospital practicing Western medicine in Funai here.","ja":"1557年、アルメイダが府内に西洋医学を取り入れた日本初の病院を開いた。"},{"k":"history","zh":"769 年宇佐八幡的神諭差點讓僧人道鏡當上天皇，和氣清麻呂帶回新神諭才擋下","en":"In 769 an oracle from Usa Hachiman nearly made the monk Dokyo emperor until Wake no Kiyomaro brought a new one.","ja":"769年、宇佐八幡の神託で道鏡が皇位に就きかけ、和気清麻呂の持ち帰った神託で阻まれた。"},{"k":"life","zh":"全國約四萬四千座八幡宮的總本宮在這裡，參拜方式是「二禮四拍手一禮」","en":"Head of some 44,000 Hachiman shrines, the shrine here is worshipped with two bows, four claps and one bow.","ja":"全国約4万4千の八幡宮の総本宮では、「二礼四拍手一礼」で参拝する。"},{"k":"life","zh":"別府由各町內會自己經營的共同浴場據說有好幾百處，是居民日常泡湯的地方","en":"Beppu has hundreds of neighborhood-run communal baths, part of residents' daily life.","ja":"別府には町内会が運営する共同温泉が数百あるといわれ、住民の日常の湯になっている。"},{"k":"food","zh":"麵糰扯成扁麵、撒黃豆粉和糖的點心「やせうま」，名字傳說來自奶媽「八瀨」","en":"Yaseuma, flat noodles dusted with sweet soybean flour, is said to be named after a nursemaid called Yase.","ja":"きな粉をまぶした平麺のおやつ「やせうま」は、乳母「八瀬」にねだった言葉が由来という。"},{"k":"food","zh":"臼杵以梔子染黃的「黃飯」代替昂貴的紅豆飯，相傳源自藩的節約令","en":"In Usuki here, gardenia-dyed yellow rice replaced costly red-bean rice, reportedly under a frugality order.","ja":"臼杵では藩の倹約令で、赤飯の代わりにクチナシで炊いた「黄飯」を作ったという。"},{"k":"food","zh":"鐵輪溫泉的旅館有用溫泉蒸氣煮菜的「地獄釜」，湯治客自己蒸食物","en":"Inns at Kannawa Onsen have 'hell ovens' where guests steam their own food over hot spring vapor.","ja":"鉄輪温泉の貸間旅館には温泉の蒸気で調理する「地獄釜」があり、湯治客が自炊する。"},{"k":"food","zh":"被稱為「炸雞聖地」的中津，炸雞文化據說和戰後從滿洲撤回的人重現中國雞料理有關","en":"Nakatsu, the 'holy land of karaage', owes its fried chicken partly to repatriates recreating Chinese dishes.","ja":"「からあげの聖地」中津の唐揚げは、旧満州からの引揚者が中国の鶏料理を再現したのが一因とされる。"},{"k":"nature","zh":"寬 120 公尺的原尻瀑布突然出現在平坦的田園中，有「東洋的尼加拉瀑布」之稱","en":"Harajiri Falls, 120 m wide, appears suddenly amid flat farmland and is called the 'Niagara of the Orient'.","ja":"田園の中に突然現れる幅120mの原尻の滝は「東洋のナイアガラ」と呼ばれる。"},{"k":"nature","zh":"姬島觀音崎的黑曜石是國家天然紀念物，遷徙的大絹斑蝶也會在島上停留","en":"Himeshima's obsidian outcrop is a natural monument, and migrating Asagi-madara butterflies rest there.","ja":"姫島の観音崎の黒曜石は天然記念物で、渡りをするアサギマダラも立ち寄る。"},{"k":"brand","zh":"被稱為「下町的拿破崙」的麥燒酎 iichiko，產自這裡的宇佐","en":"Iichiko, the barley shochu nicknamed 'the Napoleon of downtown', is made in Usa here.","ja":"「下町のナポレオン」と呼ばれる麦焼酎いいちこは、○○の宇佐で造られる。"},{"k":"legend","zh":"傳說燒炭的小五郎娶了貴族女子成為富豪「真名野長者」，臼杵石佛也和他有關","en":"Legend says charcoal burner Kogoro wed a noblewoman and became the rich Manano Choja, tied to the Usuki Buddhas.","ja":"炭焼小五郎が姫と結ばれ大富豪「真名野長者」となった伝説は、臼杵石仏の由来とも伝わる。"},{"k":"legend","zh":"《古事記》說伊邪那岐與伊邪那美生下的第 12 座島，就是這裡的姬島","en":"The Kojiki counts Himeshima here as the twelfth island born to the gods Izanagi and Izanami.","ja":"『古事記』で、姫島はイザナギとイザナミが生んだ12番目の島とされる。"}],
"JP-45":[{"k":"symbol","zh":"縣樹是加那利海棗（フェニックス）","en":"Its prefectural tree is the Canary Island date palm, known as 'phoenix'.","ja":"県の木はフェニックス。"},{"k":"people","zh":"前知事東國原英夫，原是北野武的大弟子「そのまんま東」","en":"Former governor Hideo Higashikokubaru was once comedian Sonomanma Higashi, Beat Takeshi's top disciple.","ja":"元知事の東国原英夫は、ビートたけしの一番弟子「そのまんま東」。"},{"k":"sport","zh":"老虎伍茲曾在這裡舉辦的鄧祿普鳳凰賽連續兩年奪冠","en":"Tiger Woods won back-to-back titles at the Dunlop Phoenix golf tournament held here.","ja":"タイガー・ウッズはここで開かれるダンロップフェニックスで連覇した。"},{"k":"festival","zh":"高千穗夜神樂在民家通宵演出 33 段，跳到隔天早上","en":"Takachiho's night kagura performs 33 dances all night in private homes, ending the next morning.","ja":"高千穂の夜神楽は民家で三十三番を夜通し舞い、翌朝まで続く。"},{"k":"record","zh":"小黃瓜產量全國第一","en":"It produces more cucumbers than any other prefecture.","ja":"キュウリの生産量が全国1位。"},{"k":"record","zh":"肉雞（白肉雞）產量全國第一","en":"It raises the most broiler chickens of any prefecture.","ja":"ブロイラーの生産が全国1位。"},{"k":"record","zh":"擁有日本最南端的天然滑雪場","en":"It has Japan's southernmost natural-snow ski area.","ja":"日本最南端の天然スキー場がある。"},{"k":"record","zh":"蘿蔔乾（切り干し大根）產量全國第一","en":"It produces more dried shredded daikon than any other prefecture.","ja":"切り干し大根の生産量が全国1位。"},{"k":"people","zh":"愛酒、一生四處旅行的歌人若山牧水，出身這裡的日向","en":"Wakayama Bokusui, the wandering tanka poet who loved travel and sake, was born in Hyuga here.","ja":"旅と酒を愛した歌人・若山牧水は、○○の日向市の出身。"},{"k":"people","zh":"天正遣歐少年使節的首席正使伊東滿所，生於這裡的都於郡城","en":"Ito Mancio, chief envoy of the 1582 Tensho embassy to Europe, was born at Tonokori Castle here.","ja":"天正遣欧少年使節の主席正使・伊東マンショは、○○の都於郡城で生まれた。"},{"k":"work","zh":"1965 年 NHK 晨間劇《たまゆら》（川端康成原作）介紹了青島等地，讓這裡的觀光廣為人知","en":"NHK's 1965 morning drama Tamayura, by Kawabata Yasunari, showcased Aoshima and spread the area's fame.","ja":"1965年の朝ドラ『たまゆら』（川端康成原作）で青島などが紹介され、観光地として広まった。"},{"k":"history","zh":"1960 年島津久永、貴子夫婦來這裡度蜜月，帶起一波觀光熱潮","en":"A 1960 honeymoon here by Shimazu Hisanaga and Princess Takako sparked a tourism boom.","ja":"1960年の島津久永・貴子夫妻の新婚旅行をきっかけに、観光ブームが起きた。"},{"k":"festival","zh":"傳說神武天皇提早在清晨出航，居民挨家喊「起來！」，美美津因此有「起來祭」","en":"Legend says villagers shouted 'Wake up!' when Emperor Jimmu sailed at dawn, recalled in Mimitsu's Okiyo Festival.","ja":"神武天皇の早朝の船出で「起きよ」と呼び回った伝承から、美々津で「おきよ祭り」が開かれる。"},{"k":"food","zh":"神武天皇急著出航來不及做麻糬，居民把紅豆和糯米一起搗，成了美美津名產「出航糰子」","en":"Too rushed to make mochi for Jimmu's departure, Mimitsu folk pounded beans and rice together: 'ofunade dango'.","ja":"急な船出で餅が作れず、小豆と餅米を一緒について渡したのが美々津名物「お船出団子」。"},{"k":"origin","zh":"古國名據說來自景行天皇說這片土地「正對著日出的方向」","en":"Its old province name is said to come from Emperor Keiko remarking that the land faces the rising sun.","ja":"旧国名は、景行天皇がこの地は日の出る方に向いていると言ったことに由来するという。"},{"k":"symbol","zh":"1953 年幸島一隻小母猴開始洗番薯，首次讓學者提出動物也有「文化」","en":"In 1953 a young monkey on Kojima began washing sweet potatoes, the first case cited as animal 'culture'.","ja":"1953年、幸島の子ザルが芋を洗い始め、動物にも文化があるという説が初めて出された。"},{"k":"record","zh":"西都原古墳群的男狹穗塚長 175 公尺，是日本最大的帆立貝形古墳","en":"Osahozuka at the Saitobaru tumuli, 175 m long, is Japan's largest scallop-shaped burial mound.","ja":"西都原古墳群の男狭穂塚（175m）は、日本最大の帆立貝形古墳。"},{"k":"legend","zh":"西都原古墳群的「鬼窟古墳」，傳說是鬼在一夜之間堆成的","en":"Legend says the Oni-no-Iwaya tomb at Saitobaru was built by an ogre in a single night.","ja":"西都原古墳群の鬼の窟古墳は、鬼が一夜で築いたと伝わる。"},{"k":"nature","zh":"綾町 1967 年拒絕砍伐，保住日本最大級的照葉樹林，全町列為聯合國生物圈保護區","en":"In 1967 Aya town refused logging, saving one of Japan's largest evergreen forests, now a UNESCO biosphere reserve.","ja":"綾町は1967年に伐採計画を拒み、日本最大級の照葉樹林を守った。町全体がユネスコエコパーク。"},{"k":"food","zh":"生菜、鮮蝦加美乃滋的「生菜卷」壽司，是 1966 年這裡的壽司店為不愛吃菜的平尾昌晃發明","en":"The lettuce-shrimp-mayo sushi roll was invented here in 1966 for composer Hirao Masaaki, who disliked vegetables.","ja":"レタスとエビ、マヨネーズのレタス巻きは、1966年に野菜嫌いの平尾昌晃のため考案された。"},{"k":"food","zh":"江戶時代在這裡偶然發現的柑橘「日向夏」，內層白皮不苦，習慣連白皮一起吃","en":"Hyuganatsu, a citrus found here by chance in the Edo period, is eaten together with its non-bitter white pith.","ja":"江戸時代に偶然見つかった日向夏は、白い内皮に苦味がなく一緒に食べられる。"},{"k":"legend","zh":"高千穗的天岩戶神社，以神話中天照大神躲藏的岩洞為神體","en":"Amano-Iwato Shrine in Takachiho worships the cave where the sun goddess Amaterasu hid in myth.","ja":"高千穂の天岩戸神社は、天照大神が隠れた天岩屋とされる岩窟を御神体とする。"},{"k":"life","zh":"高千穗天安河原堆滿祈願的小石塔，但戰前照片裡沒有，是戰後才流行起來的","en":"Amano-Yasukawara riverbed is covered with wish-stone piles, a custom that arose only after the war.","ja":"天安河原の願掛けの石積みは戦前の写真にはなく、戦後に広まった風習とされる。"},{"k":"history","zh":"民俗學家柳田國男在椎葉村調查狩獵習俗，寫成 1909 年的《後狩詞記》","en":"Folklorist Yanagita Kunio's fieldwork in Shiiba village here led to his 1909 book on hunting lore.","ja":"柳田國男は椎葉村での調査をもとに『後狩詞記』（1909年）を著した。"},{"k":"life","zh":"深山裡的椎葉村，是日本唯一仍延續傳統燒墾農業的地方","en":"Shiiba village here is the only place in Japan where traditional slash-and-burn farming continues.","ja":"椎葉村は、伝統的な焼畑農業が続く日本で唯一の地域。"},{"k":"legend","zh":"椎葉村流傳壇之浦戰敗後，平家殘黨逃進山裡隱居的傳說","en":"Shiiba village is said to have been settled by Heike survivors fleeing after the Battle of Dan-no-ura.","ja":"椎葉村には、壇ノ浦の戦いの後に平家の落人が隠れ住んだという伝承がある。"},{"k":"brand","zh":"人氣芋燒酎「黑霧島」的霧島酒造，總部在這裡的都城","en":"Kirishima Shuzo, maker of the popular sweet potato shochu Kuro Kirishima, is based in Miyakonojo here.","ja":"芋焼酎「黒霧島」の霧島酒造は、○○の都城市に本社を置く。"},{"k":"history","zh":"1877 年西鄉軍在延岡被包圍，從可愛岳突破官軍防線撤退","en":"In 1877 Saigo's encircled army broke through government lines on Mt. Enodake near Nobeoka here.","ja":"1877年、延岡で包囲された西郷軍は可愛岳を突破して退却した。"},{"k":"history","zh":"1578 年島津軍在這裡的耳川之戰大敗豐後大友軍","en":"At the Battle of Mimikawa here in 1578, the Shimazu crushed the Otomo army of Bungo.","ja":"1578年の耳川の戦いで、島津軍が大友軍を破った。"},{"k":"nature","zh":"周長很短的青島上長滿蒲葵林，被列為特別天然紀念物","en":"Tiny Aoshima island is covered in Chinese fan palm groves, a Special Natural Monument.","ja":"小さな青島はビロウの群落に覆われ、特別天然記念物に指定されている。"},{"k":"life","zh":"這裡的男性被形容為「いもがらぼくと」：外表剛強、內心溫和好相處","en":"Local men are stereotyped as 'imogara bokuto': impressive-looking but soft-hearted inside.","ja":"○○の男性気質は、見かけは立派でも中身は優しい「いもがらぼくと」と言われる。"},{"k":"life","zh":"這裡對守時很隨性，遲到也互相包容，被稱為「日向時間」","en":"A relaxed local attitude to punctuality, with lateness forgiven, is called 'Hyuga time'.","ja":"時間におおらかで遅刻も許し合う気風を「日向時間」と呼ぶ。"}],
"JP-46":[{"k":"symbol","zh":"縣鳥是琉璃色的松鴉「ルリカケス」","en":"Its prefectural bird is Lidth's jay, a lapis-blue jay.","ja":"県の鳥はルリカケス。"},{"k":"people","zh":"歌手長渕剛 2004 年在櫻島辦通宵演唱會，吸引約 7.5 萬人","en":"Singer Tsuyoshi Nagabuchi drew about 75,000 people to an all-night concert on Sakurajima in 2004.","ja":"長渕剛は2004年に桜島でオールナイトライブを開き、約7万5千人を集めた。"},{"k":"work","zh":"NHK 大河劇《篤姬》，主角出身島津家分家今和泉家","en":"NHK's taiga drama Atsuhime follows a heroine from the Imaizumi branch of the Shimazu clan.","ja":"大河ドラマ『篤姫』の主人公は島津家の分家・今和泉家の出身。"},{"k":"sport","zh":"劍術流派「示現流」講求第一刀定勝負，練習時對著木樁連砍","en":"The Jigen-ryu sword school stakes all on the first strike and trains by hacking at upright posts.","ja":"剣術・示現流は「二の太刀要らず」、立木打ちで稽古する。"},{"k":"festival","zh":"除夕夜來訪神「トシドン」挨家訓誡小孩，列入聯合國非遺","en":"On New Year's Eve, the visiting deity Toshidon scolds children door to door; it's UNESCO-listed.","ja":"大晦日に来訪神トシドンが家々で子どもを戒める。ユネスコ無形文化遺産。"},{"k":"origin","zh":"縣名據說來自霧島市的同名神宮","en":"The name is said to come from a shrine of the same name in Kirishima.","ja":"県名は霧島市にある同名の神宮に由来するとされる。"},{"k":"record","zh":"出水平原是日本最大的鶴群越冬地","en":"The Izumi plain is Japan's largest wintering ground for cranes.","ja":"出水は日本最大のツルの越冬地。"},{"k":"life","zh":"火山灰落得多時，公所會發「克灰袋」讓居民裝灰","en":"When volcanic ash piles up, local offices hand out special 'kokuhai' bags for residents to bag it.","ja":"降灰が多いと役所から克灰袋が配られ、灰を詰めて出す。"},{"k":"people","zh":"日本海海戰擊敗波羅的海艦隊、人稱「東方納爾遜」的東鄉平八郎出身這裡","en":"Admiral Togo Heihachiro, the 'Nelson of the East' who beat Russia's Baltic Fleet, was born here.","ja":"日本海海戦でバルチック艦隊を破った「東洋のネルソン」東郷平八郎は○○出身。"},{"k":"record","zh":"東鄉平八郎 1926 年登上《時代》雜誌封面，是第一位上封面的日本人","en":"Admiral Togo, born here, was the first Japanese person on the cover of Time magazine, in 1926.","ja":"○○出身の東郷平八郎は1926年、日本人として初めて『タイム』誌の表紙を飾った。"},{"k":"record","zh":"幕末藩主島津齊彬的照片，被認為是現存最古老的日本人拍攝照片","en":"A photo of lord Shimazu Nariakira is considered the oldest known photograph taken by a Japanese person.","ja":"藩主・島津斉彬の写真は、日本人が撮影した現存最古の写真とされる。"},{"k":"history","zh":"1865 年森有禮等 19 名薩摩藩使節與留學生從羽島出航前往英國","en":"In 1865, 19 Satsuma envoys and students, including Mori Arinori, sailed for Britain from Hashima here.","ja":"1865年、森有礼ら薩摩藩の使節・留学生19人が羽島から英国へ向け出航した。"},{"k":"sport","zh":"德之島鬥牛文化盛行，歷史超過四百年","en":"Tokunoshima here has a bullfighting tradition stretching back more than 400 years.","ja":"徳之島では闘牛が盛んで、400年以上の歴史があるとされる。"},{"k":"work","zh":"屋久島白谷雲水峽長滿青苔的森林，是《魔法公主》森林的原型","en":"The mossy forest of Shiratani Unsuikyo on Yakushima is a model for the forest in Princess Mononoke.","ja":"屋久島・白谷雲水峡の苔むす森は『もののけ姫』の森のモデルとされる。"},{"k":"work","zh":"007 電影《雷霆谷》的海女漁村戲，是在這裡的坊津秋目拍攝","en":"The Bond film You Only Live Twice shot its Ama fishing-village scenes at Akime in Bonotsu here.","ja":"映画『007は二度死ぬ』の海女の村の場面は、○○の坊津町秋目で撮影された。"},{"k":"festival","zh":"夏天神社寺院掛滿手繪紙燈籠的「六月燈」，源自島津光久重建觀音堂時點燈","en":"Summer Rokugatsudo festivals fill shrines here with painted paper lanterns, begun by lord Shimazu Mitsuhisa.","ja":"夏の「六月灯」は社寺に絵灯籠が並ぶ祭りで、島津光久が観音堂再建時に灯籠を灯したのが始まり。"},{"k":"festival","zh":"惡石島的來訪神「ボゼ」戴著怪面具，用長棒把紅泥抹到人身上驅邪","en":"On Akusekijima, masked Boze spirits chase people and smear red mud on them to drive away evil.","ja":"悪石島の来訪神ボゼは、マラ棒の先の赤い泥を人々に擦りつけて悪霊を祓う。"},{"k":"symbol","zh":"奄美黑兔只住在奄美大島和德之島，1921 年成為日本第一種被指定為天然紀念物的動物","en":"The Amami rabbit lives only on Amami Oshima and Tokunoshima; in 1921 it became Japan's first animal natural monument.","ja":"アマミノクロウサギは奄美大島と徳之島だけに住み、1921年に動物で初めて天然記念物に。"},{"k":"record","zh":"1993 年屋久島和白神山地一起成為日本最早的世界自然遺產","en":"In 1993 Yakushima, together with Shirakami-Sanchi, became Japan's first natural World Heritage Sites.","ja":"屋久島は1993年、白神山地とともに日本初の世界自然遺産に登録された。"},{"k":"nature","zh":"屋久島的宮之浦岳海拔 1936 公尺，是整個九州的最高峰","en":"Miyanouradake on Yakushima, 1,936 m, is the highest mountain in all of Kyushu.","ja":"屋久島の宮之浦岳（1936m）は九州の最高峰。"},{"k":"history","zh":"1863 年英國艦隊因生麥事件和這裡交戰，戰後雙方反而變得親近","en":"In 1863 British warships fought the domain here over the Namamugi Incident; afterwards the two sides grew close.","ja":"1863年、生麦事件をめぐり英国艦隊と交戦した薩英戦争。戦後は一転して英国と接近した。"},{"k":"history","zh":"1609 年約三千兵從山川出航征服琉球，並把奄美群島納為直轄地","en":"In 1609 about 3,000 troops sailed from Yamakawa here to subdue Ryukyu, taking the Amami Islands as direct territory.","ja":"1609年、約3000の兵が山川から琉球へ侵攻し、奄美群島を直轄地にした。"},{"k":"food","zh":"「酒壽司」不用醋，而是用當地的灰持酒調味飯，再壓製發酵","en":"Sakezushi here uses local ash-preserved sake instead of vinegar, layered and pressed to ferment.","ja":"酒寿司は酢の代わりに地酒（灰持酒）で飯を味付けし、押して発酵させる。"},{"k":"food","zh":"奄美的「雞飯」是在飯上鋪雞絲、蛋絲，再淋上全雞熬的高湯","en":"Amami's keihan is rice topped with shredded chicken and egg, then doused with whole-chicken broth.","ja":"奄美の鶏飯は、ご飯に鶏や錦糸卵をのせ、丸鶏のスープをかけて食べる。"},{"k":"brand","zh":"溫州蜜柑其實起源於這裡的長島，所以英文叫 Satsuma","en":"The satsuma mandarin actually originated on Nagashima here, hence its English name.","ja":"温州みかんの原産地は○○の長島とされ、英語では「サツマ」と呼ばれる。"},{"k":"brand","zh":"以色彩漸層「暈色」為特色的雕花玻璃薩摩切子，明治初年失傳，1985 年左右才復刻","en":"Satsuma kiriko cut glass, known for 'bokashi' color gradation, died out in early Meiji and was revived around 1985.","ja":"色の「ぼかし」が特徴の薩摩切子は、明治初期に途絶え1985年ごろ復刻された。"},{"k":"legend","zh":"1978 年二十多人同時在池田湖目擊水怪 Issie，真面目可能是大鰻魚","en":"In 1978 over 20 people saw 'Issie', a monster in Lake Ikeda; giant eels are the likely culprit.","ja":"1978年、池田湖で20人以上が怪獣イッシーを同時に目撃。正体は大ウナギ説が有力。"},{"k":"legend","zh":"奄美的妖怪「ケンムン」住在榕樹上，愛相撲、怕章魚","en":"Amami's yokai Kenmun lives in banyan trees, loves sumo and fears octopus.","ja":"奄美の妖怪ケンムンはガジュマルに住み、相撲好きでタコが苦手。"},{"k":"nature","zh":"外形對稱的開聞岳被稱為「薩摩富士」，特攻機南飛前把它當作告別的山","en":"Symmetrical Mt. Kaimon, the 'Satsuma Fuji', served as a farewell landmark for kamikaze pilots heading south.","ja":"円錐形の開聞岳は「薩摩富士」と呼ばれ、特攻機が別れを告げた山とされる。"}],
"JP-47":[{"k":"symbol","zh":"縣鳥是野口啄木鳥（ノグチゲラ）","en":"Its prefectural bird is Pryer's woodpecker.","ja":"県の鳥はノグチゲラ。"},{"k":"people","zh":"歌后安室奈美惠出身這裡，從當地的演藝學校起步","en":"Pop star Namie Amuro comes from here and got her start at a local actors' school.","ja":"安室奈美恵の出身地。地元のアクターズスクールから羽ばたいた。"},{"k":"sport","zh":"拳王具志堅用高出身石垣島，衛冕 13 次是日本男子紀錄","en":"Boxer Yoko Gushiken, from Ishigaki, made 13 title defenses, a record for Japanese male champions.","ja":"石垣島出身の具志堅用高は13度防衛、日本男子世界王者の最多記録。"},{"k":"work","zh":"NHK 晨間劇《ちゅらさん》女主角在八重山的小濱島長大","en":"In NHK's morning drama Churasan, the heroine grows up on Kohama Island in the Yaeyama Islands.","ja":"朝ドラ『ちゅらさん』のヒロインは八重山の小浜島育ち。"},{"k":"festival","zh":"大綱挽的稻草繩曾獲金氏認證為世界最大，現在長 200 公尺、重 40 噸","en":"Its giant tug-of-war rope, once certified by Guinness as the world's largest, is now 200 m long and 40 tons.","ja":"大綱挽の綱はギネス認定の世界最大の綱で、今は全長200m・重さ40トン。"},{"k":"origin","zh":"奈良時代記載鑑真東渡的書中，把這裡寫作「阿兒奈波」","en":"An 8th-century account of the monk Jianzhen's voyage to Japan records it as 'Akonaha'.","ja":"奈良時代の『唐大和上東征伝』に「阿児奈波」として登場する。"},{"k":"record","zh":"全國唯一沒有一級河川的縣","en":"It's the only prefecture with no Class A (first-class) river.","ja":"全国で唯一、一級河川がない県。"},{"k":"life","zh":"因為長年缺水，許多住家屋頂上都裝著水塔","en":"Because of past water shortages, many homes have water tanks on their roofs.","ja":"水不足の歴史から、屋根に給水タンクを置く家が多い。"},{"k":"people","zh":"1429 年尚巴志統一北山、中山、南山三國，建立第一個統一王朝","en":"In 1429 Sho Hashi united the three kingdoms of Hokuzan, Chuzan and Nanzan into one realm.","ja":"1429年、尚巴志が北山・中山・南山の三山を統一した。"},{"k":"sport","zh":"1922 年船越義珍到東京介紹唐手，從此留下來在本土傳授","en":"In 1922 Funakoshi Gichin introduced karate in Tokyo and stayed on to teach it on the mainland.","ja":"1922年、富名腰（船越）義珍が東京で唐手を紹介し、そのまま本土で指導を始めた。"},{"k":"sport","zh":"空手道源自這裡的「手（ティー）」，原寫作「唐手」，1936 年才決定改成「空手」","en":"Karate grew from the local art 'te'; it was written 'Chinese hand' until a 1936 decision to use 'empty hand'.","ja":"空手は琉球の「手（ティー）」が起源で、1936年の座談会で「唐手」から「空手」へ改められた。"},{"k":"work","zh":"THE BOOM 的〈島唄〉，是宮澤和史參觀姬百合和平祈念資料館後寫的","en":"The Boom's song Shima Uta was written after Miyazawa Kazufumi visited the Himeyuri Peace Museum here.","ja":"THE BOOMの「島唄」は、宮沢和史がひめゆり平和祈念資料館を訪れて書いた曲。"},{"k":"work","zh":"唱這裡的〈島唄〉翻唱版，2002 年成為阿根廷世足代表隊的主題曲","en":"A cover of Shima Uta, a song about this place, became Argentina's 2002 World Cup team theme.","ja":"この地を歌った「島唄」のカバーは、2002年にアルゼンチン代表のW杯テーマ曲に選ばれた。"},{"k":"festival","zh":"盂蘭盆時青年會打著大鼓沿街跳「エイサー」，迎送祖先的靈魂","en":"During Obon, youth groups here parade through the streets drumming and dancing Eisa for ancestral spirits.","ja":"お盆には青年会が太鼓を打ち鳴らしてエイサーを踊り、地域を練り歩く。"},{"k":"festival","zh":"舊曆五月四日在那霸、糸滿等地舉行划龍舟競賽「ハーリー」，祈求航海平安與豐漁","en":"On the 4th day of the 5th lunar month, Haari boat races in Naha and Itoman pray for safe seas and good catches.","ja":"旧暦5月4日、那覇や糸満で航海安全と豊漁を祈る爬竜船競漕「ハーリー」が行われる。"},{"k":"life","zh":"清明時節全家族去掃墓，掃完就在墓前一起野餐，稱為「シーミー」","en":"At Shimii (Qingming), families clean ancestral tombs and then share a meal in front of them.","ja":"清明祭（シーミー）では親族が墓を掃除し、墓前で一緒に食事をする。"},{"k":"origin","zh":"古稱的由來，可追溯到中國《隋書》記載的「流求」","en":"Its old name traces back to 'Liuqiu', a land recorded in China's Book of Sui.","ja":"旧名は、中国の『隋書』に記された「流求」に由来するとされる。"},{"k":"symbol","zh":"幾乎不會飛的山原秧雞（ヤンバルクイナ），1981 年才被記載為新種","en":"The Yanbaru kuina, a nearly flightless rail found only in the north here, was described as a new species in 1981.","ja":"ほとんど飛べないヤンバルクイナは、1981年に新種として記載された。"},{"k":"symbol","zh":"只棲息在慶良間群島的「慶良間鹿」，部分島上的族群是天然紀念物","en":"Kerama deer live only in the Kerama Islands, and some of their island populations are natural monuments.","ja":"慶良間諸島だけに住むケラマジカは、一部の島の個体群が天然記念物。"},{"k":"record","zh":"波照間島是日本最南端的有人島，可以看到南十字星","en":"Hateruma is Japan's southernmost inhabited island, where the Southern Cross can be seen.","ja":"波照間島は日本最南端の有人島で、南十字星が見える。"},{"k":"record","zh":"南城的洞窟出土約兩萬三千年前的貝製魚鉤，被視為世界最古老的魚鉤","en":"A cave in Nanjo here yielded a 23,000-year-old shell fishhook, considered the world's oldest.","ja":"南城市のサキタリ洞から、世界最古とされる約2万3千年前の貝製釣り針が出土。"},{"k":"history","zh":"6 月 23 日「慰靈之日」是這裡獨有的休假日，源自二戰守軍司令官自盡那天","en":"June 23, Memorial Day, is a local holiday here marking the day the WWII garrison commander took his life.","ja":"6月23日の「慰霊の日」は県の休日で、第32軍司令官・牛島満らが自決した日とされる。"},{"k":"life","zh":"T 字路口盡頭常立著「石敢當」，因為魔物只會直走，撞上就會碎掉","en":"Stones carved 'ishiganto' stand at T-junctions here, since evil spirits move straight and shatter on them.","ja":"T字路の突き当たりの石敢當は、まっすぐしか進めない魔物マジムンを砕くためという。"},{"k":"life","zh":"王國時代平民不准蓋瓦屋頂，屋頂上的風獅爺到明治以後才普及","en":"Commoners were banned from tile roofs under the old kingdom, so rooftop shisa spread only after the Meiji era.","ja":"王国時代は庶民の瓦葺きが禁じられ、屋根のシーサーは明治以降に広まった。"},{"k":"legend","zh":"八重瀨的富盛石獅是最古老的村落風獅爺，面向被認為會引發火災的山","en":"The Tomori shisa in Yaese, the oldest village guardian lion, faces a hill blamed for causing fires.","ja":"八重瀬町の富盛の石彫大獅子は最古の村落シーサーで、火災をもたらす山に向けて置かれた。"},{"k":"legend","zh":"住在老榕樹上的紅髮妖精「キジムナー」，愛吃魚的左眼、怕章魚","en":"Kijimuna, red-haired sprites of old banyan trees, love fish's left eyes and fear octopus.","ja":"ガジュマルの古木に住むキジムナーは、魚の左目が好物でタコが苦手。"},{"k":"legend","zh":"波照間島流傳島民為了逃避人頭稅，乘船去找傳說中「南波照間島」的故事","en":"Legend tells of Hateruma islanders sailing off to a mythical 'Southern Hateruma' to escape the poll tax.","ja":"波照間島には、人頭税から逃れて幻の「南波照間島」を目指した島民の伝説が残る。"},{"k":"food","zh":"把塔可餅餡料鋪在白飯上的「塔可飯」，1984 年左右誕生於美軍基地旁的金武町","en":"Taco rice, taco fillings over white rice, was born around 1984 in Kin, outside a US Marine base.","ja":"タコスの具をご飯にのせたタコライスは、1984年ごろ米軍基地前の金武町で生まれた。"},{"k":"brand","zh":"日本只有這裡有美式速食 A&W，1963 年美國統治時期開出第一家","en":"The only A&W restaurants in Japan are here; the first opened in 1963 under US rule.","ja":"日本でA&Wがあるのはここだけで、米国統治下の1963年に1号店が開いた。"},{"k":"brand","zh":"戰後物資匱乏，工匠熔化美軍丟棄的可樂、啤酒瓶，做出帶氣泡的琉球玻璃","en":"Postwar artisans here melted cola and beer bottles discarded by US bases, creating bubbly Ryukyu glass.","ja":"琉球ガラスは戦後、米軍が捨てたコーラやビールの瓶を溶かして作ったのが始まり。"},{"k":"brand","zh":"1957 年在名護創立的啤酒廠，品牌名 Orion 是向民眾懸賞公募選出的","en":"The Orion beer brand, from a brewery founded in Nago in 1957, was chosen through a public naming contest.","ja":"1957年に名護で創業したオリオンビールの名は、県民からの懸賞公募で決まった。"},{"k":"nature","zh":"石垣島白保的藍珊瑚群落被評為北半球最大，還讓新機場計畫從海上改到陸地","en":"Shiraho reef on Ishigaki has the Northern Hemisphere's largest blue coral colony, which pushed an airport onto land.","ja":"石垣島白保のアオサンゴ群落は北半球最大とされ、新空港計画を海上から陸上へ移させた。"}]};
